#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start a single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000 // +/-4.096V range
#define CONFIG_DR_128SPS 0x0080  // 128 SPS data rate
#define CONFIG_MODE_SINGLE 0x0100  // Single-shot mode

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_ads1115();
int read_ads1115(int16_t *value);
float convert_to_current(int16_t raw_value);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the ADS1115
int init_ads1115() {
    // Configure the ADS1115 for single-shot mode, AIN0 single-ended, +/-4.096V, 128 SPS
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_DR_128SPS | CONFIG_MODE_SINGLE;

    // Write the configuration to the ADS1115
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;       // LSB

    int result = i2cWriteI2CBlockData(i2c_handle, ADS1115_REG_CONFIG, buf + 1, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115: %d\n", result);
        return -1;
    }

    return 0;
}

// Read the conversion result from the ADS1115
int read_ads1115(int16_t *value) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *value = (buf[0] << 8) | buf[1];

    return 0;
}

// Convert the raw ADC value to current in amperes
float convert_to_current(int16_t raw_value) {
    // Assuming a 40mV/A sensitivity and a mid-supply of 2.5V
    float current = (float)raw_value * 40.0 / 32768.0 - 2.5;
    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the ADS1115
    if (init_ads1115() != 0) {
        fprintf(stderr, "ADS1115 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t raw_value;
    float current;
    while (!terminate) {
        // Read the conversion result
        if (read_ads1115(&raw_value) == 0) {
            // Convert the raw value to current
            current = convert_to_current(raw_value);

            // Print the current to the console
            printf("Current: %.4f A\n", current);
        } else {
            fprintf(stderr, "Failed to read current\n");
        }

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close the I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

