    FLAME_SENSOR_GPIO,
    BUZZER_GPIO,
    I2C_BUS,
    ADS1115_ADDR,
    CONFIG_REG,
    CONVERSION_REG,
    BUZZER_DURATION,
    DEBOUNCE_DELAY
};

