    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.flame_gpio, PI_INPUT);
    gpioSetPullUpDown(config.flame_gpio, PI_PUD_UP); // Enable pull-up resistor
    gpioSetMode(config.buzzer_gpio, PI_OUTPUT);
    deactivate_buzzer(); // Ensure buzzer is off initially

    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ads1115_addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Function to configure ADS1115
int configure_ads1115() {
    // Configure for single-shot mode, gain +/-4.096V, 128 SPS
    char config_data[3];
    config_data[0] = config.config_reg;
    config_data[1] = 0x40; // Single-shot mode
    config_data[2] = 0xC2; // +/-4.096V, 128 SPS

    int result = i2cWriteDevice(i2c_handle, config_data, 3);
    if (result != 0) {
        fprintf(stderr, "ADS1115 configuration failed: %d\n", result);
        return 1;
    }
    return 0;
}

// Function to read temperature from ADS1115
int read_temperature() {
    char config_data[3];
    config_data[0] = config.config_reg;
    config_data[1] = 0x83; // Start single conversion
    config_data[2] = 0xC2; // +/-4.096V, 128 SPS

    int result = i2cWriteDevice(i2c_handle, config_data, 3);
    if (result != 0) {
        fprintf(stderr, "ADS1115 start conversion failed: %d\n", result);
        return -1; // Indicate error
    }

    gpioDelay(10); // Wait for conversion (adjust as needed)

    char conversion_data[2];
    result = i2cReadDevice(i2c_handle, conversion_data, 2);
    if (result != 2) {
        fprintf(stderr, "ADS1115 read conversion failed: %d\n", result);
        return -1; // Indicate error
    }

    int16_t raw_value = (conversion_data[0] << 8) | conversion_data[1];

    // Convert raw value to voltage (assuming +/-4.096V range)
    float voltage = (float)raw_value * 4.096 / 32768.0;

    // Convert voltage to temperature (Celsius)
    float temperature = (voltage - 2.5) / 0.01;

    return (int)temperature;
}

