    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register callback function for flame sensor
    gpioSetAlertFuncEx(config.flame_gpio, flame_detected_callback, NULL);

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int temperature = read_temperature();
        if (temperature != -1) {
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Temperature: %d°C", temperature);
            log_event(log_message);

            if (temperature > 60) {
                log_event("Temperature above 60°C!");
            }
        } else {
            log_event("Failed to read temperature.");
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    deactivate_buzzer();
    gpioSetAlertFuncEx(config.flame_gpio, NULL, NULL); // Disable callback
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

