#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip4" // Or "gpiochip0"
#define GPIO_PIN 18
#define SENSOR_SENSITIVITY 100.0 // mV/A
#define CURRENT_THRESHOLD 5.0 // A
#define LOG_FILE "current_log.txt"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(uint8_t tx_buf[3], uint8_t rx_buf[3]);
int read_mcp3008(int channel);
float adc_to_current(int adc_value);
void control_fan(float current);
void log_data(float current);
void signal_handler(int sig);
int initialize_gpio();
void cleanup_gpio();

// SPI transfer function
int spi_transfer(uint8_t tx_buf[3], uint8_t rx_buf[3]) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(tx_buf, rx_buf) != 0) {
        fprintf(stderr, "Failed to read MCP3008 channel %d\n", channel);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to current
float adc_to_current(int adc_value) {
    // Assuming VREF = 3.3V
    float voltage = (float)adc_value * 3.3 / 1024.0;
    float current = voltage / SENSOR_SENSITIVITY;
    return current;
}

// Function to control the cooling fan
void control_fan(float current) {
    if (current > CURRENT_THRESHOLD) {
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Failed to set GPIO HIGH");
        }
    } else {
        if (gpiod_line_set_value(gpio_line, 0) < 0) {
            perror("Failed to set GPIO LOW");
        }
    }
}

// Function to log data to file
void log_data(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize GPIO
int initialize_gpio() {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "current_sensor", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0); // Turn off fan
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    int adc_value;
    float current;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                SENSOR_SENSITIVITY = atof(optarg);
                break;
            case 't':
                CURRENT_THRESHOLD = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup_gpio();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup_gpio();
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value from channel 0
        adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to current
        current = adc_to_current(adc_value);

        // Control the cooling fan
        control_fan(current);

        // Log the data
        log_data(current);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup_gpio();
    close(spi_fd);
    fclose(log_file);
    return 0;
}

