        return -1;
    }

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0); // Turn off fan
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    int adc_value;
    float current;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                SENSOR_SENSITIVITY = atof(optarg);
                break;
            case 't':
                CURRENT_THRESHOLD = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup_gpio();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup_gpio();
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value from channel 0
        adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to current
        current = adc_to_current(adc_value);

        // Control the cooling fan
        control_fan(current);

        // Log the data
        log_data(current);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup_gpio();
    close(spi_fd);
    fclose(log_file);
    return 0;
}

