int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
int read_temperature();
float convert_to_temperature(int adc_value);
int log_data(int flame_detected, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to read the temperature from the MCP3008
int read_temperature() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message to read from MCP3008 channel 0
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | TEMPERATURE_CHANNEL) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

