#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define sensor-specific constants
#define I2C_BUS 1
#define SENSOR_ADDRESS 0x48 // Replace with the actual I2C address
#define CO_REGISTER 0x00
#define NO2_REGISTER 0x02
#define SCALE_FACTOR 0.1 // Example scale factor, adjust based on datasheet
#define ALERT_THRESHOLD 25.0

// Global variables
int i2c_handle;
FILE *co_log_file;
FILE *alert_log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co_value;
    uint16_t no2_value;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
float calculate_co_ppm(uint16_t raw_value);
void log_co_data(float co_ppm);
void log_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the MICS-4514
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[4];

    // Read CO and NO2 values from the sensor registers
    int bytes_read = i2cReadI2CBlockData(i2c_handle, CO_REGISTER, buffer, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        data.co_value = 0; // Set to 0 to avoid using uninitialized data
        data.no2_value = 0;
        return data;
    }

    // Combine the two bytes to form the 16-bit values
    data.co_value = (buffer[0] << 8) | buffer[1];
    data.no2_value = (buffer[2] << 8) | buffer[3];

    return data;
}

// Calculate CO level in PPM
float calculate_co_ppm(uint16_t raw_value) {
    return (float)raw_value * SCALE_FACTOR;
}

// Log CO data to a file
void log_co_data(float co_ppm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(co_log_file, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f PPM\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fflush(co_log_file); // Ensure data is written to disk immediately
}

// Log alert to a file
void log_alert(float co_ppm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(alert_log_file, "%d-%02d-%02d %02d:%02d:%02d, ALERT: CO level exceeds threshold (%.2f PPM)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fflush(alert_log_file);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (co_log_file != NULL) {
        fclose(co_log_file);
    }
    if (alert_log_file != NULL) {
        fclose(alert_log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    co_log_file = fopen("co_log.txt", "a");
    if (co_log_file == NULL) {
        fprintf(stderr, "Error opening co_log.txt\n");
        gpioTerminate();
        return 1;
    }

    alert_log_file = fopen("alert_log.txt", "a");
    if (alert_log_file == NULL) {
        fprintf(stderr, "Error opening alert_log.txt\n");
        fclose(co_log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t sensor_data = read_sensor_data();

        // Calculate CO level
        float co_ppm = calculate_co_ppm(sensor_data.co_value);

        // Log CO data
        log_co_data(co_ppm);

        // Check for alert condition
        if (co_ppm > ALERT_THRESHOLD) {
            log_alert(co_ppm);
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

