#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE) // microseconds
#define MIC1_SENSITIVITY -38.0 // dB/Pa
#define MIC2_SENSITIVITY -38.0 // dB/Pa
#define REFERENCE_PRESSURE 20e-6 // Pa
#define LOG_FILE "audio_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int16_t data;
    time_t timestamp;
} MicrophoneData;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_microphone_data(int handle, int16_t *data);
double convert_to_db(int16_t raw_data, double sensitivity, double reference_pressure);
double calculate_average_db(double db1, double db2);
int log_data(FILE *fp, double db_average);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initializes the I2C interface
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Reads data from the microphone
int read_microphone_data(int handle, int16_t *data) {
    char buf[2];
    int result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *data = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Converts raw data to sound pressure level in dB
double convert_to_db(int16_t raw_data, double sensitivity, double reference_pressure) {
    double pressure = (double)raw_data * (sensitivity / 100.0) + reference_pressure; // Scale raw data to Pa
    double db = 20 * log10(pressure / REFERENCE_PRESSURE);
    return db;
}

// Calculates the average sound pressure level in dB
