#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL_0 0
#define SPI_CHANNEL_1 1
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 27
#define RMS_THRESHOLD 0.7
#define SAMPLE_WINDOW_MS 100
#define NUM_SAMPLES 100
#define CSV_FILE "audio_events.csv"

// Global variables
int spi_handle_0 = -1;
int spi_handle_1 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi(int channel);
int read_adc(int spi_handle, int channel);
double calculate_rms(int16_t *samples, int num_samples);
void normalize_rms(double rms1, double rms2, double *normalized_rms1, double *normalized_rms2);
void control_led(int gpio, int state);
void log_data(FILE *fp, double rms1, double rms2);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int spi_channel_0;
    int spi_channel_1;
    int led_gpio;
    double rms_threshold;
    int sample_window_ms;
    int num_samples;
    char csv_file[64];
} Config;

// Function to initialize SPI
int initialize_spi(int channel) {
    int handle = spiOpen(channel, SPI_SPEED, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// Function to read ADC value from MCP3008
int read_adc(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS value
double calculate_rms(int16_t *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to normalize RMS values
void normalize_rms(double rms1, double rms2, double *normalized_rms1, double *normalized_rms2) {
    *normalized_rms1 = rms1 / 32768.0; // Assuming 16-bit ADC
    *normalized_rms2 = rms2 / 32768.0;
}

// Function to control LED
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Function to log data to CSV file
void log_data(FILE *fp, double rms1, double rms2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.4f,%.4f\n", timestamp, rms1, rms2);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_handle_0 = initialize_spi(SPI_CHANNEL_0);
    if (spi_handle_0 < 0) {
        gpioTerminate();
        return 1;
    }

    spi_handle_1 = initialize_spi(SPI_CHANNEL_1);
    if (spi_handle_1 < 0) {
        spiClose(spi_handle_0);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", CSV_FILE);
        spiClose(spi_handle_0);
        spiClose(spi_handle_1);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1 RMS,Mic2 RMS\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t mic1_samples[NUM_SAMPLES];
        int16_t mic2_samples[NUM_SAMPLES];

        // Sample microphone 1
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int adc_value = read_adc(spi_handle_0, 0); // Channel 0
            if (adc_value < 0) {
                fprintf(stderr, "Error reading ADC from channel 0\n");
                break; // Exit loop on error
            }
            mic1_samples[i] = (int16_t)adc_value;
            gpioDelay(1); // 1 ms delay
        }

        // Sample microphone 2
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int adc_value = read_adc(spi_handle_1, 0); // Channel 0
            if (adc_value < 0) {
                fprintf(stderr, "Error reading ADC from channel 0\n");
                break; // Exit loop on error
            }
            mic2_samples[i] = (int16_t)adc_value;
            gpioDelay(1); // 1 ms delay
        }

        // Calculate RMS values
        double rms1 = calculate_rms(mic1_samples, NUM_SAMPLES);
        double rms2 = calculate_rms(mic2_samples, NUM_SAMPLES);

        // Normalize RMS values
        double normalized_rms1, normalized_rms2;
        normalize_rms(rms1, rms2, &normalized_rms1, &normalized_rms2);

        // Check if RMS values exceed threshold
        if (normalized_rms1 > RMS_THRESHOLD || normalized_rms2 > RMS_THRESHOLD) {
            control_led(LED_GPIO, 1); // Turn on LED
            gpioDelay(500);           // Wait 500 ms
            control_led(LED_GPIO, 0); // Turn off LED
        }

        // Log data
        log_data(log_file, normalized_rms1, normalized_rms2);

        gpioDelay(SAMPLE_WINDOW_MS); // Delay for 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle_0);
    spiClose(spi_handle_1);
    fclose(log_file);
    control_led(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

