        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the ADS1115 for single-ended A0, 4.096V range, 128 SPS
int configure_ads1115() {
    // Configuration register settings:
    // 1. Start single conversion (bit 15)
    // 2. AIN0 (bit 12-11)
    // 3. +/- 4.096V range (bit 10-9)
    // 4. 128 SPS (bit 8-7)
    // 5. Single-shot mode (bit 6)
    // 6. Disable comparator (bit 5)
    // 7. Disable comparatorlatching (bit 4)
    // 8. Disable comparator polarity (bit 3)
    // 9. Disable comparator mode (bit 2)
    // 10. Disable comparator window (bit 1)
    // 11. Disable comparator alert/RDY pin (bit 0)
    uint16_t config_value = 0x4083; // Start single conversion, AIN0, +/- 4.096V, 128 SPS

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;       // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Read raw ADC value from the ADS1115
int read_ads1115(int16_t *raw_value) {
    char buf[1];
    buf[0] = CONVERSION_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "I2C write (conversion register select) failed: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    *raw_value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Convert raw ADC value to current in Amperes
float convert_to_current(int16_t raw_value) {
    // Assuming 0.5V to 4.5V range, 0-100A
    float voltage = (float)raw_value * 4.096 / 32768.0; // Assuming 16-bit ADC
    float current = voltage / 0.5;
    return current;
}

// Add a new value to the circular buffer
void add_to_buffer(CircularBuffer *buffer, float value) {
    buffer->buffer[buffer->head] = value;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i];
    }
    return sum / buffer->count;
}

