#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)
#define MOISTURE_1_CHANNEL 0
#define MOISTURE_2_CHANNEL 1
#define LOG_FILE "moisture_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int channel;
    int adc_value;
    float moisture_percentage;
} sensor_data_t;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float map_adc_to_moisture(int adc_value);
int log_data(sensor_data_t sensor1, sensor_data_t sensor2);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;           // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Map ADC value to moisture percentage (0-100%)
float map_adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Log data to CSV file
int log_data(sensor_data_t sensor1, sensor_data_t sensor2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
