#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define CURRENT_THRESHOLD 10.0
#define LOG_FILE "current_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *motor_shutdown_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
int log_current(float current);
int overcurrent_check(float current);
void motor_shutdown(void);
void motor_startup(void);
void signal_handler(int sig);
int setup(void);
void cleanup(void);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1024.0;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    return (voltage - 0.05) / 0.1;
}

// Function to log current reading to file
int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current_in_Amperes\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to check for overcurrent condition
int overcurrent_check(float current) {
    return (current > CURRENT_THRESHOLD) ? 1 : 0;
}

// Function to shutdown the motor
void motor_shutdown(void) {
    if (motor_shutdown_line != NULL) {
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "current_monitor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        config.flags = 0;

        if (gpiod_line_request(motor_shutdown_line, &config, 0) < 0) {
            perror("Failed to request motor shutdown line");
            return;
        }

        if (gpiod_line_set_value(motor_shutdown_line, 0) < 0) {
            perror("Failed to set motor shutdown line LOW");
        }

        printf("Motor shutdown initiated.\n");
    }
}

// Function to startup the motor
void motor_startup(void) {
    if (motor_shutdown_line != NULL) {
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "current_monitor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        config.flags = 0;

        if (gpiod_line_request(motor_shutdown_line, &config, 0) < 0) {
            perror("Failed to request motor shutdown line");
            return;
        }

        if (gpiod_line_set_value(motor_shutdown_line, 1) < 0) {
            perror("Failed to set motor shutdown line HIGH");
        }

        printf("Motor startup initiated.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

// Setup function
int setup(void) {
    // Initialize gpiod
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    motor_shutdown_line = gpiod_chip_get_line(gpio_chip, MOTOR_SHUTDOWN_PIN);
    if (!motor_shutdown_line) {
        perror("Failed to get motor shutdown line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Configure bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Configure max speed hz
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed hz");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Release GPIO line
    if (motor_shutdown_line != NULL) {
        gpiod_line_release(motor_shutdown_line);
    }

    // Close GPIO chip
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup
    if (setup() < 0) {
        fprintf(stderr, "Setup failed. Exiting.\n");
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to current
        float current = voltage_to_current(voltage);

        // Log current reading
        if (log_current(current) < 0) {
            fprintf(stderr, "Failed to log current reading. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
        }

        // Check for overcurrent condition
        if (overcurrent_check(current)) {
            printf("Overcurrent detected! Current: %.2f A\n", current);
            motor_shutdown();
        } else {
            motor_startup();
        }

        // Wait for 1 second
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    printf("Current monitoring stopped.\n");
    return 0;
}

