// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    time_t timestamp;
    float pressure_kPa;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_pressure(int handle, uint16_t *raw_pressure);
float convert_pressure(uint16_t raw_pressure);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure from the sensor
int read_pressure(int handle, uint16_t *raw_pressure) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }

    *raw_pressure = (buf[0] << 8) | buf[1];
    return 0;
}

