                retry++;
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read pressure after %d retries\n", RETRY_COUNT);
            // Optionally, add a retry-on-failure strategy here
            continue; // Skip to the next iteration
        }

        pressure_kPa = convert_pressure(raw_pressure);
        data.timestamp = time(NULL);
        data.pressure_kPa = pressure_kPa;

        if (log_data(log_file, data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Pressure: %.2f kPa\n", pressure_kPa);

        gpioDelay(1000000); // 1 second delay (1000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

