#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 105.0
#define NTC_A 10.0
#define NTC_B 0.01
#define NTC_C 0.000001

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_ads1115();
int read_ads1115(int16_t *pressure, int16_t *temperature);
float convert_pressure(int16_t adc_value);
float convert_temperature(int16_t adc_value);
void control_led(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

int main() {
    sensor_data_t sensor_data;
    int16_t raw_pressure, raw_temperature;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        fprintf(stderr, "Failed to configure ADS1115. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_ads1115(&raw_pressure, &raw_temperature) == 0) {
            // Convert sensor data
            sensor_data.pressure = convert_pressure(raw_pressure);
            sensor_data.temperature = convert_temperature(raw_temperature);

            // Display sensor data
            printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", sensor_data.pressure, sensor_data.temperature);

            // Control LED
            control_led(sensor_data.pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure ADS1115 for single-ended AIN0 and AIN1, 2/3 gain, 128 SPS
int configure_ads1115() {
    // Configuration register settings
    uint16_t config = 0x4003; // Single-ended AIN0, +/- 6.144V, 128 SPS, Continuous conversion

    // Write configuration to the ADS1115
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;       // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register: %d\n", result);
        return 1;
    }

    return 0;
}

// Read pressure and temperature data from ADS1115
int read_ads1115(int16_t *pressure, int16_t *temperature) {
    char buf[2];
    char read_buf[2];
    int retries = 3;

    // Read pressure data
    buf[0] = ADS1115_CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register for pressure.\n");
        return 1;
    }
    gpioDelay(10); // Wait for conversion (adjust as needed)

    while (retries > 0) {
        if (i2cReadDevice(i2c_handle, read_buf, 2) == 2) {
            *pressure = (read_buf[0] << 8) | read_buf[1];
            break; // Success
        } else {
            fprintf(stderr, "Failed to read pressure data (attempt %d).\n", 4 - retries);
            gpioDelay(10); // Wait before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read pressure data after multiple retries.\n");
        return 1;
    }

    // Read temperature data
    buf[0] = ADS1115_CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register for temperature.\n");
        return 1;
    }
    gpioDelay(10); // Wait for conversion (adjust as needed)

    retries = 3;
    while (retries > 0) {
        if (i2cReadDevice(i2c_handle, read_buf, 2) == 2) {
            *temperature = (read_buf[0] << 8) | read_buf[1];
            break; // Success
        } else {
            fprintf(stderr, "Failed to read temperature data (attempt %d).\n", 4 - retries);
            gpioDelay(10); // Wait before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read temperature data after multiple retries.\n");
        return 1;
    }

    return 0;
}

// Convert raw ADC value to pressure (kPa)
float convert_pressure(int16_t adc_value) {
    // Assuming 0V = 0 kPa, 5V = 400 kPa
    return (float)adc_value * (400.0 / 32767.0);
}

// Convert raw ADC value to temperature (°C) using a simplified NTC approximation
float convert_temperature(int16_t adc_value) {
    // Assuming 1V = 0°C, 2V = 100°C
    float voltage = (float)adc_value * (5.0 / 32767.0);
    return NTC_A * pow(voltage, -1.0 / (NTC_B + NTC_C * voltage));
}

// Control the warning LED based on pressure
void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    // Turn off LED
    gpioWrite(GPIO_LED, 0);

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();
}

