#define MCP3008_CHANNEL 0
#define VREF 3.3
#define ZERO_CURRENT_VOLTAGE 1.65
#define SENSITIVITY 66.0 // mV/A
#define OVERCURRENT_THRESHOLD 10.0 // A
#define GPIO_SHUTDOWN 27
#define LOG_FILE "current_log.txt"

// Global variables
