        if (current > OVERCURRENT_THRESHOLD) {
            gpioWrite(GPIO_SHUTDOWN, 1); // Set GPIO HIGH to shutdown motor
        } else {
            gpioWrite(GPIO_SHUTDOWN, 0); // Set GPIO LOW to allow motor to run
        }

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

