#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define VREF 3.3
#define SENSITIVITY 0.1
#define OFFSET 0.5
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    float vref;
    float sensitivity;
    float offset;
    float min_pressure;
    float max_pressure;
    char *log_file;
} config_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int configure_ads1115(int handle);
int read_ads1115(int handle, int16_t *raw_value);
float convert_to_voltage(int16_t raw_value, float vref);
float convert_to_pressure(float voltage, float sensitivity, float offset);
int validate_pressure(float pressure);
int log_pressure(float pressure, const char *filename);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Configures the ADS1115 for single-ended AIN0, 4.096V range, 128 SPS, and single-shot mode
int configure_ads1115(int handle) {
    // Configuration register settings:
    // 1. Start single conversion (bit 15)
    // 2. Single-ended AIN0 (bits 12-11)
    // 3. +/- 4.096V range (bits 10-9)
    // 4. 128 SPS (bits 8-5)
    // 5. Single-shot mode (bit 4)
    // 6. Disable comparator (bit 3)
    // 7. Disable comparatorlatching (bit 2)
    // 8. Disable comparator polarity (bit 1)
    // 9. Disable comparator enable (bit 0)
    uint16_t config_value = 0x4083; // Start single conversion, AIN0, +/- 4.096V, 128 SPS, single-shot

    int result = i2cWriteWordData(handle, CONFIG_REG, config_value);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Reads the conversion result from the ADS1115
int read_ads1115(int handle, int16_t *raw_value) {
    int result = i2cReadWordData(handle, CONVERSION_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading from conversion register: %d\n", result);
        return -1;
    }
    *raw_value = (int16_t)result;
    return 0;
}

// Converts the raw ADC value to a voltage
float convert_to_voltage(int16_t raw_value, float vref) {
    return (float)raw_value * vref / 32768.0;
}

// Converts the voltage to a pressure in kPa using a linear transfer function
float convert_to_pressure(float voltage, float sensitivity, float offset) {
    return (voltage - offset) / sensitivity;
}

// Validates the pressure reading
int validate_pressure(float pressure) {
    if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
        fprintf(stderr, "Error: Pressure out of range: %.2f kPa\n", pressure);
        return -1;
    }
    return 0;
}

// Logs the pressure reading to a file with ISO-8601 timestamp
int log_pressure(float pressure, const char *filename) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", filename);
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

int main() {
    // Configuration
    config_t config = {
        .i2c_bus = I2C_BUS,
        .ads1115_address = ADS1115_ADDR,
        .vref = VREF,
        .sensitivity = SENSITIVITY,
        .offset = OFFSET,
        .min_pressure = MIN_PRESSURE,
        .max_pressure = MAX_PRESSURE,
        .log_file = LOG_FILE
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(config.i2c_bus, config.ads1115_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        float voltage, pressure;

        // Read ADC value
        if (read_ads1115(i2c_handle, &raw_value) == 0) {
            // Convert to voltage
            voltage = convert_to_voltage(raw_value, config.vref);

            // Convert to pressure
            pressure = convert_to_pressure(voltage, config.sensitivity, config.offset);

            // Validate pressure
            if (validate_pressure(pressure) == 0) {
                // Log pressure
                if (log_pressure(pressure, config.log_file) != 0) {
                    fprintf(stderr, "Error logging pressure\n");
                }
                printf("Pressure: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Error reading pressure\n");
        }

        // Delay for 1 second
        gpioDelay(1000); // pigpioDelay takes milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Pressure monitoring stopped.\n");

    return 0;
}

