#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3208 channel connected to HIH-4602-A
#define HUMIDITY_THRESHOLD 80.0
#define EMAIL_RECIPIENT "recipient@example.com"
#define LOG_FILE "humidity_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float humidity;
    float temperature;
} SensorData;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3208 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3208 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate relative humidity
float calculate_humidity(int adc_value) {
    float vout = (float)adc_value / 1023.0 * 5.0; // Assuming 5.0V reference
    float rh = (vout - 0.824) / 0.0315;
    if (rh < 0.0) rh = 0.0;
    if (rh > 100.0) rh = 100.0;
    return rh;
}

// Function to calculate temperature (using Beta parameter)
float calculate_temperature(int adc_value) {
    float vout = (float)adc_value / 1023.0 * 5.0; // Assuming 5.0V reference
    float r0 = 10000.0; // 10kΩ
    float beta = 3950.0; // Beta parameter for HIH-4602-A
    float temperature = (vout - 0.7) * beta / (0.0315 * r0);
    return temperature;
}

// Function to log data to file
void log_data(float humidity, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send email alert
void send_email_alert(float humidity) {
    char command[256];
    snprintf(command, sizeof(command), "echo \"Humidity exceeds threshold: %.2f%%\" | ssmtp %s", humidity, EMAIL_RECIPIENT);
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error executing ssmtp command\n");
    } else if (WIFEXITED(result) && WEXITSTATUS(result) != 0) {
        fprintf(stderr, "ssmtp command failed with exit status %d\n", WEXITSTATUS(result));
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(adc_value);
        float temperature = calculate_temperature(adc_value);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold and send email alert
        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        sleep(5); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    printf("Humidity monitoring stopped.\n");
    return 0;
}

