FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3208(int channel);
float convert_to_voltage(int adc_value);
float convert_to_celsius(float voltage);
int log_temperature(float temperature);
void signal_handler(int signal);
