#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define LOG_FILE "impact_log.txt"
#define IMPACT_THRESHOLD 2.0 // g
#define SENSITIVITY 300.0   // mV/g
#define VREF 3.3            // V

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_g(int adc_value);
void log_data(float x, float y, float z);
void check_impact(float x, float y, float z);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed with code: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to g
float adc_to_g(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0;
    float acceleration = (voltage - 1.65) / SENSITIVITY;
    return acceleration;
}

// Function to log data to file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to check for impact
void check_impact(float x, float y, float z) {
    float magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude > IMPACT_THRESHOLD) {
        fprintf(log_file, "IMPACT DETECTED\n");
        fflush(log_file);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        // Read ADC values
        int adc_x = read_mcp3008(0);
        int adc_y = read_mcp3008(1);
        int adc_z = read_mcp3008(2);

        if (adc_x == -1 || adc_y == -1 || adc_z == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to g
        float x = adc_to_g(adc_x);
        float y = adc_to_g(adc_y);
        float z = adc_to_g(adc_z);

        // Log data
        log_data(x, y, z);

        // Check for impact
        check_impact(x, y, z);

        // Delay for 100 Hz (10 ms)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

