#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define GAIN_FACTOR 0.5 // Adjust this value to control gain
#define SAMPLE_RATE 16000 // 16 kHz
#define NUM_SAMPLES 1024 // Number of samples to read

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data
typedef struct {
    int16_t left;
    int16_t right;
} AudioData;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
AudioData sample_audio();
AudioData apply_gain(AudioData data, float gain);
AudioData subtract_audio(AudioData left, AudioData right);
void output_csv(AudioData data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Sample audio data from microphones
AudioData sample_audio() {
    AudioData data;
    int left_adc = read_mcp3008(MCP3008_CHANNEL_0);
    int right_adc = read_mcp3008(MCP3008_CHANNEL_1);

    if (left_adc < 0 || right_adc < 0) {
        fprintf(stderr, "Error reading ADC values\n");
        data.left = 0; // Set to 0 to avoid garbage output
        data.right = 0;
        return data;
    }

    // Convert ADC values to signed 16-bit integers (assuming 12-bit ADC)
    data.left = (int16_t)((left_adc & 0x0FFF) << 4); // Shift right by 4 bits
    data.right = (int16_t)((right_adc & 0x0FFF) << 4);

    return data;
}

// Apply gain to audio data
AudioData apply_gain(AudioData data, float gain) {
    AudioData output;
    output.left = (int16_t)(data.left * gain);
    output.right = (int16_t)(data.right * gain);
    return output;
}

// Subtract audio data
AudioData subtract_audio(AudioData left, AudioData right) {
    AudioData output;
    output.left = left.left - right.left;
    output.right = left.right - right.right;
    return output;
}

// Output audio data to CSV format
void output_csv(AudioData data) {
    printf("%d,%d\n", data.left, data.right);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <gain_factor>\n", argv[0]);
        return 1;
    }

    float gain_factor = atof(argv[1]);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Audio noise cancellation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Sample audio
        AudioData audio_data = sample_audio();

        // Apply gain
        AudioData gain_data = apply_gain(audio_data, gain_factor);

        // Subtract audio
        AudioData noise_cancellation_data = subtract_audio(audio_data, gain_data);

        // Output CSV
        output_csv(noise_cancellation_data);

        // Delay for a short period
        gpioDelay(1000000 / SAMPLE_RATE); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

