#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define FLAME_THRESHOLD 1.0 // Volts
#define TEMPERATURE_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define RETRY_COUNT 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_temperature(float voltage);
float compensate_voltage(float voltage, float temperature);
void control_buzzer(int state);
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value = -1; // Initialize to an invalid value
    int retries = 0;

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    spi_tx_buf[2] = 0x00; // Dummy byte

    while (retries < RETRY_COUNT) {
        if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) == 0) {
            // Extract ADC value (10 bits)
            adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d). Retrying...\n", retries + 1);
            fprintf(log_file, "SPI transfer failed (attempt %d). Retrying...\n", retries + 1);
            fflush(log_file);
            gpioDelay(10000); // 10ms delay before retrying
            retries++;
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries. Returning -1.\n", RETRY_COUNT);
    fprintf(log_file, "SPI transfer failed after %d retries. Returning -1.\n", RETRY_COUNT);
    fflush(log_file);
    return -1; // Indicate failure
}

// Function to convert voltage to temperature (Celsius)
float voltage_to_temperature(float voltage) {
    // Linear approximation: 0V = 25°C, 3.3V = 100°C
    return (voltage - 0.5) * 100.0;
}

// Function to compensate voltage for temperature
float compensate_voltage(float voltage, float temperature) {
    // Simple linear compensation: voltage = voltage + (temperature - 25.0) * 0.001
    return voltage + (temperature - 25.0) * 0.001;
}

// Function to control the buzzer
void control_buzzer(int state) {
    gpioWrite(BUZZER_GPIO, state);
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int raw_adc = read_mcp3008(0); // Channel 0
        if (raw_adc < 0) {
            fprintf(stderr, "Failed to read ADC value. Skipping iteration.\n");
            fprintf(log_file, "Failed to read ADC value. Skipping iteration.\n");
            fflush(log_file);
            gpioDelay(500000); // 500ms delay
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (float)raw_adc / 1023.0 * 3.3;

        // Read ambient temperature from file
        FILE *temp_file = fopen(TEMPERATURE_FILE, "r");
        if (temp_file == NULL) {
            fprintf(stderr, "Failed to open temperature file. Using default temperature: 25.0\n");
            fprintf(log_file, "Failed to open temperature file. Using default temperature: 25.0\n");
            fflush(log_file);
            float temperature = 25.0;
        } else {
            if (fscanf(temp_file, "%f", &temperature) != 1) {
                fprintf(stderr, "Failed to read temperature from file. Using default temperature: 25.0\n");
                fprintf(log_file, "Failed to read temperature from file. Using default temperature: 25.0\n");
                fflush(log_file);
                temperature = 25.0;
            }
            fclose(temp_file);
        }

        // Compensate voltage
        float compensated_voltage = compensate_voltage(voltage, temperature);

        // Check for flame detection
        int flame_detected = (compensated_voltage > FLAME_THRESHOLD);

        // Control buzzer
        control_buzzer(flame_detected);

        // Log data
        log_data(raw_adc, voltage, compensated_voltage, temperature, flame_detected);

        // Wait 500ms
        gpioDelay(500000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_buzzer(0); // Turn off buzzer
    spiClose(spi_handle); // Close SPI channel
    fclose(log_file); // Close log file
    gpioTerminate(); // Terminate pigpio

    printf("Exiting.\n");
    return 0;
}

