// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75
#define WATER_LEVEL_THRESHOLD_LOW 70
#define WATER_LEVEL_HYSTERESIS 5
#define JSON_FILE "water_levels.json"
#define LOG_FILE "water_level_log.txt"

// Global variables
