#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75
#define WATER_LEVEL_THRESHOLD_LOW 70
#define WATER_LEVEL_HYSTERESIS 5
#define JSON_FILE "water_levels.json"
#define LOG_FILE "water_level_log.txt"

// Global variables
int spi_handle;
FILE *json_file;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_percentage(int adc_value);
int log_data(float water_level);
void control_led(float water_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Padding

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to water level percentage
float convert_to_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    return (float)adc_value / 1023.0 * 100.0;
}

// Function to log data to JSON file
int log_data(float water_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char json_string[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    // Format JSON string
    snprintf(json_string, sizeof(json_string), "{\"timestamp\": \"%s.%03ld\", \"water_level\": %.2f}\n", timestamp, (long)(timeinfo->tm_nsec / 1000000), water_level);

    // Write to JSON file
    if (fputs(json_string, json_file) == EOF) {
        fprintf(stderr, "Error: Failed to write to JSON file\n");
        return -1;
    }

    // Flush the buffer to ensure data is written immediately
    fflush(json_file);

    return 0;
}

// Function to control LED based on water level
void control_led(float water_level) {
    if (water_level > WATER_LEVEL_THRESHOLD_HIGH) {
        gpioWrite(LED_GPIO, 1); // Turn LED ON
    } else if (water_level < WATER_LEVEL_THRESHOLD_LOW - WATER_LEVEL_HYSTERESIS) {
        gpioWrite(LED_GPIO, 0); // Turn LED OFF
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

