        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, skipping this iteration\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Convert to water level percentage
        float water_level = convert_to_percentage(adc_value);
        if (water_level < 0) {
            fprintf(stderr, "Error: Failed to convert ADC value to water level, skipping this iteration\n");
