        if (log_data(water_level) != 0) {
            fprintf(stderr, "Error: Failed to log data, skipping this iteration\n");
        }

        // Control LED
        control_led(water_level);

        // Print water level to console
        printf("Water level: %.2f%%\n", water_level);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

