#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration structure
typedef struct {
    int spi_channel;
    int adc_channel;
    int min_raw_value;
    int max_raw_value;
    int moisture_threshold;
    int logging_frequency;
    char *recipient_email;
    char *msmtp_config_file;
} Config;

// Global variables
int spi_handle;
FILE *log_file;
Config config;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int raw_value, int min_raw, int max_raw);
int log_data(float moisture_percent);
int send_email_alert(float moisture_percent);
void signal_handler(int signal);
int initialize(Config *config);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int raw_value, int min_raw, int max_raw) {
    if (min_raw == max_raw) {
        return 0.0; // Avoid division by zero
    }
    return 100.0 - ((float)(raw_value - min_raw) / (float)(max_raw - min_raw)) * 100.0;
}

// Function to log data to file
int log_data(float moisture_percent) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percent);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to send email alert using msmtp
int send_email_alert(float moisture_percent) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    char command[256];
    snprintf(command, sizeof(command), "echo \"Subject: Plant Moisture Alert\n\nTimestamp: %s\nMoisture: %.2f%%\" | msmtp -t -f %s", timestamp, moisture_percent, config.msmtp_config_file);

    FILE *pipe = popen(command, "r");
    if (pipe == NULL) {
        fprintf(stderr, "Error: Failed to execute msmtp command\n");
        return -1;
    }

    int status = pclose(pipe);
    if (status != 0) {
        fprintf(stderr, "Error: msmtp command failed with status %d\n", status);
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize(Config *config) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config->spi_channel, 500000, 0); // Channel, Baud rate, Flags
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen("plant_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Default configuration
    config.spi_channel = 0;
    config.adc_channel = 0;
    config.min_raw_value = 300;
    config.max_raw_value = 700;
    config.moisture_threshold = 30;
    config.logging_frequency = 60;
    config.recipient_email = "recipient@example.com";
    config.msmtp_config_file = "/etc/msmtprc";

    // Parse command-line arguments
    if (argc > 1) {
        config.spi_channel = atoi(argv[1]);
    }
    if (argc > 2) {
        config.adc_channel = atoi(argv[2]);
    }
    if (argc > 3) {
        config.min_raw_value = atoi(argv[3]);
    }
    if (argc > 4) {
        config.max_raw_value = atoi(argv[4]);
    }
    if (argc > 5) {
        config.moisture_threshold = atoi(argv[5]);
    }
    if (argc > 6) {
        config.logging_frequency = atoi(argv[6]);
    }
    if (argc > 7) {
        config.recipient_email = argv[7];
    }
    if (argc > 8) {
        config.msmtp_config_file = argv[8];
    }

    // Initialize
    if (initialize(&config) != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Plant monitoring started. Logging to plant_data.txt, sending email alerts to %s, logging frequency: %d seconds\n", config.recipient_email, config.logging_frequency);

    // Main loop
    while (!terminate) {
        int raw_value = read_mcp3008(config.adc_channel);
        if (raw_value >= 0) {
            float moisture_percent = calculate_moisture_percentage(raw_value, config.min_raw_value, config.max_raw_value);

            if (log_data(moisture_percent) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }

            if (moisture_percent < config.moisture_threshold) {
                if (send_email_alert(moisture_percent) != 0) {
                    fprintf(stderr, "Error: Failed to send email alert\n");
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        sleep(config.logging_frequency);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

