    spi_fd = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);
        if (moisture_percentage < 0) {
            fprintf(stderr, "Error: Failed to calculate moisture percentage\n");
            continue; // Skip to the next iteration
        }

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Log data to console
        printf("[%s] ADC Value: %d, Moisture: %.2f%%\n", asctime(timeinfo), adc_value, moisture_percentage);

        // Wait for 5 seconds
        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness and to avoid compiler warnings.
    spiClose(spi_fd);
    gpioTerminate();
    return 0;
}

