#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700
#define LOG_FILE "soil_moisture.log"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor calibration data
typedef struct {
    int min_adc_value;
    int max_adc_value;
} sensor_calibration_t;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture_percentage(int adc_value, sensor_calibration_t calibration);
void log_data(float moisture_percentage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the pigpio library and SPI interface
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_fd < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_fd);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_fd);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Reads the ADC value from the specified channel of the MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_fd, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Converts the ADC value to a moisture percentage using calibration constants
float convert_to_moisture_percentage(int adc_value, sensor_calibration_t calibration) {
    if (adc_value < calibration.min_adc_value) {
        return 0.0;
    } else if (adc_value > calibration.max_adc_value) {
        return 100.0;
    } else {
        return 100.0 - ((float)(adc_value - calibration.min_adc_value) / (float)(calibration.max_adc_value - calibration.min_adc_value)) * 100.0;
    }
}

// Logs the current timestamp and moisture percentage to the log file
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %.2f%%\n", timestamp, moisture_percentage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleans up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        spiClose(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    sensor_calibration_t calibration = {MIN_ADC_VALUE, MAX_ADC_VALUE};

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float moisture_percentage = convert_to_moisture_percentage(adc_value, calibration);
            log_data(moisture_percentage);
            printf("Moisture: %.2f%%\n", moisture_percentage);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

