    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = MCP3008_START_BIT;
    tx_buffer[1] = (MCP3008_SINGLE_ENDED_MODE | (channel << 4));
    tx_buffer[2] = MCP3008_DONT_CARE;

    // Transfer SPI data
    int result = spiXfer(spi_fd, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate error
