// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define NUM_SENSORS 4
#define SAMPLE_INTERVAL_SEC 1
#define CSV_FILE "environmental_data.csv"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *spi_cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float voltage_to_temperature(int adc_value);
float voltage_to_humidity(int adc_value);
int log_data(float temperatures[], float humidities[]);
void signal_handler(int sig);
void cleanup(void);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize SPI
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float voltage_to_temperature(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to convert ADC value to humidity (%RH)
float voltage_to_humidity(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float humidity = (voltage - 0.25) * 100.0;
    return humidity;
}

// Function to log data to CSV file
int log_data(float temperatures[], float humidities[]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp,
            temperatures[0], humidities[0],
            temperatures[1], humidities[1]);
    fflush(log_file); // Ensure data is written to disk immediately

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp,
            temperatures[2], humidities[2],
            temperatures[3], humidities[3]);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    printf("Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    if (spi_cs_line != NULL) {
        gpiod_line_release(spi_cs_line);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    spi_cs_line = gpiod_chip_get_line(gpio_chip, 8); // CE0
    if (!spi_cs_line) {
        perror("Error getting SPI CS line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(spi_cs_line, "spi_cs", 0) < 0) {
        perror("Error requesting SPI CS line as output");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Sensor1_Temperature,Sensor1_Humidity,Sensor2_Temperature,Sensor2_Humidity,Sensor3_Temperature,Sensor3_Humidity,Sensor4_Temperature,Sensor4_Humidity\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data[NUM_SENSORS];
        int adc_values[NUM_SENSORS];

        // Read ADC values from each sensor
        for (int i = 0; i < NUM_SENSORS; i++) {
            adc_values[i] = read_mcp3008(i);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Error reading ADC value from sensor %d\n", i);
                // Attempt to recover by setting to a default value
                adc_values[i] = 0; // Or some other error value
            }
        }

        // Convert ADC values to temperature and humidity
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_data[i].temperature = voltage_to_temperature(adc_values[i]);
            sensor_data[i].humidity = voltage_to_humidity(adc_values[i]);
        }

        // Log data
        if (log_data(sensor_data[0].temperature, sensor_data[0].humidity,
                    sensor_data[1].temperature, sensor_data[1].humidity,
                    sensor_data[2].temperature, sensor_data[2].humidity,
                    sensor_data[3].temperature, sensor_data[3].humidity) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

