#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 300
#define MOISTURE_THRESHOLD_HIGH 600
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer entries
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

// Circular buffer
LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_data(int moisture_level, int pump_state);
void print_log_buffer();
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Function to log data to the circular buffer
void log_data(int moisture_level, int pump_state) {
    time(&log_buffer[buffer_index].timestamp);
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the log buffer
void print_log_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index - BUFFER_SIZE + i + BUFFER_SIZE) % BUFFER_SIZE; // Corrected index calculation
        struct tm *timeinfo = localtime(&log_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Moisture: %d, Pump: %s\n", timestamp_str, log_buffer[index].moisture_level,
               log_buffer[index].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Initialize pump to OFF state
    control_pump(0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read moisture level
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            continue; // Skip to the next iteration
        }

        // Control pump based on moisture level
        int pump_state = (moisture_level < MOISTURE_THRESHOLD_LOW) ? 1 : 0;
        control_pump(pump_state);

        // Log data
        log_data(moisture_level, pump_state);

        // Print log buffer every 5 seconds
        time_t current_time;
        time(&current_time);
        if (difftime(current_time, last_print_time) >= SAMPLE_INTERVAL_SEC) {
            print_log_buffer();
            last_print_time = current_time;
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

