    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Initialize pump to OFF state
    control_pump(0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read moisture level
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            continue; // Skip to the next iteration
        }

        // Control pump based on moisture level
        int pump_state = (moisture_level < MOISTURE_THRESHOLD_LOW) ? 1 : 0;
        control_pump(pump_state);

        // Log data
        log_data(moisture_level, pump_state);

        // Print log buffer every 5 seconds
        time_t current_time;
        time(&current_time);
        if (difftime(current_time, last_print_time) >= SAMPLE_INTERVAL_SEC) {
            print_log_buffer();
            last_print_time = current_time;
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

