// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define VREF 3.3
#define LOG_FILE "analog_log.csv"
#define RETRY_COUNT 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_voltage(int adc_value);
int log_data(int channel, float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    int result;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
        if (result == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Function to calculate voltage from ADC value
float calculate_voltage(int adc_value) {
    return (adc_value / 1023.0) * VREF;
}

// Function to log data to CSV file
int log_data(int channel, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
    }

    fprintf(log_file, "%s,%d,%.3f\n", timestamp, channel, voltage);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values from channels 0, 1, and 2
        int adc_value0 = read_mcp3008(0);
        int adc_value1 = read_mcp3008(1);
        int adc_value2 = read_mcp3008(2);

        // Calculate voltages
        float voltage0 = calculate_voltage(adc_value0);
        float voltage1 = calculate_voltage(adc_value1);
        float voltage2 = calculate_voltage(adc_value2);

        // Log data
        if (log_data(0, voltage0) != 0) {
            fprintf(stderr, "Error: Failed to log data for channel 0\n");
        }
        if (log_data(1, voltage1) != 0) {
            fprintf(stderr, "Error: Failed to log data for channel 1\n");
        }
        if (log_data(2, voltage2) != 0) {
            fprintf(stderr, "Error: Failed to log data for channel 2\n");
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close SPI channel and log file
    spiClose(spi_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

