#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define RELAY_GPIO 17
#define DOOR_SENSOR_GPIO 27
#define LOG_FILE "/var/log/door_events.log"
#define SAMPLE_SIZE 10
#define POLL_INTERVAL_MS 200
#define THRESHOLD_PERCENT 80
#define RELEASE_DURATION_S 3

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_word(int fd, uint8_t reg, uint16_t value);
int read_distance(int fd);
int calibrate_distance(int fd, int samples);
int check_threshold(int distance, int threshold);
void control_relay(int gpio, int state);
int read_reed_sensor(int gpio);
void log_event(const char *message);
void signal_handler(int signal);

// I2C read word function
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select)");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("I2C read");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// I2C write word function
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

// Read distance from ADS1115
int read_distance(int fd) {
    int raw_value = i2c_read_word(fd, CONVERSION_REG);
    if (raw_value < 0) {
        log_event("Error reading distance from ADS1115");
        return -1; // Indicate error
    }
    // Convert raw value to distance (example conversion, adjust as needed)
    // This is a placeholder; replace with actual conversion formula
    // from the GP2Y0A21YK0F datasheet.
    // Example: distance = (raw_value / 32768.0) * 100.0; // 100cm range
    // Adjust the scaling factor based on your sensor's characteristics.
    return (int)(raw_value * 0.01); // Example scaling
}

// Calibrate distance sensor
int calibrate_distance(int fd, int samples) {
    int sum = 0;
    for (int i = 0; i < samples; i++) {
        int distance = read_distance(fd);
        if (distance < 0) {
            log_event("Error during calibration, skipping sample");
            return -1; // Indicate error
        }
        sum += distance;
        gpioDelay(50); // Small delay between samples
    }
    return sum / samples;
}

// Check if distance is below threshold
int check_threshold(int distance, int threshold) {
    return (distance < threshold) ? 1 : 0;
}

// Control relay
void control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Read reed sensor
int read_reed_sensor(int gpio) {
    return gpioRead(gpio);
}

// Log event
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, terminating...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115 for single-ended A0, +/- 4.096V, 128 SPS
    uint16_t config = 0x4083; // Single-ended A0, +/- 4.096V, 128 SPS, Start single conversion
    if (i2c_write_word(i2c_fd, CONFIG_REG, config) < 0) {
        log_event("Failed to configure ADS1115");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetMode(DOOR_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(DOOR_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Calibrate distance sensor
    int baseline_distance = calibrate_distance(i2c_fd, SAMPLE_SIZE);
    if (baseline_distance < 0) {
        log_event("Failed to calibrate distance sensor");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    char log_buffer[100];
    snprintf(log_buffer, sizeof(log_buffer), "Baseline distance: %d cm", baseline_distance);
    log_event(log_buffer);

    // Set initial relay state to OFF
    control_relay(RELAY_GPIO, 0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        int distance = read_distance(i2c_fd);
        if (distance < 0) {
            log_event("Error reading distance, skipping poll");
            gpioDelay(POLL_INTERVAL_MS);
            continue;
        }

        // Check threshold
        int threshold_exceeded = check_threshold(distance, baseline_distance * (THRESHOLD_PERCENT / 100.0));

        // Control relay
        if (threshold_exceeded) {
            control_relay(RELAY_GPIO, 1); // Energize relay
            log_event("Threshold exceeded, releasing door lock");
            gpioDelay(RELEASE_DURATION_S * 1000); // Wait for release duration
            control_relay(RELAY_GPIO, 0); // De-energize relay
            log_event("Door lock released");

            // Read reed sensor
            int reed_state = read_reed_sensor(DOOR_SENSOR_GPIO);
            if (reed_state == 0) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }

        gpioDelay(POLL_INTERVAL_MS);
    }

    // Cleanup
    control_relay(RELAY_GPIO, 0); // Ensure relay is OFF
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

