        if (sensor1_value != -1 && sensor2_value != -1 && sensor3_value != -1) {
            log_data(sensor1_value, sensor2_value, sensor3_value);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

