#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define EMA_ALPHA 0.1
#define THRESHOLD_PERCENTAGE 20.0
#define LOG_FILE "/var/log/sound_events.log"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    double ema_alpha;
    double threshold_percentage;
    char *log_file;
} Config;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
double calculate_ema(double new_value, double ema_value, double alpha);
int detect_peak(double ema_value, double threshold_percentage);
int log_event(double ema_value);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate exponential moving average
double calculate_ema(double new_value, double ema_value, double alpha) {
    return alpha * new_value + (1 - alpha) * ema_value;
}

// Detect peak based on EMA value and threshold
int detect_peak(double ema_value, double threshold_percentage) {
    double threshold = ema_value * (1 + threshold_percentage / 100.0);
    return (ema_value > threshold) ? 1 : 0;
}

