// PCF8591 I2C address
#define PCF8591_ADDR 0x48

// I2C bus number (usually 1 on Raspberry Pi)
#define I2C_BUS 1

// I2C file descriptor
int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, PCF8591_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read AIN0 (single-ended, channel 0)
        char buf[1];
        buf[0] = 0x40; // Control byte for single-ended mode, channel 0
        if (i2cWriteDevice(i2c_fd, buf, 1) != 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        gpioDelay(10000); // 10ms delay

        if (i2cReadDevice(i2c_fd, buf, 1) != 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Print the sample value
        printf("AIN0: %d\n", buf[0]);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

