#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define GPIO_SHUTDOWN 27
#define SAMPLE_RATE_HZ 1
#define BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500.0
#define VREF 3.3
#define SENSITIVITY 1.4 // mV/Gauss
#define ZERO_FIELD_OUTPUT 2.5 // V

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_gauss(int16_t raw_value);
void add_to_buffer(CircularBuffer *buffer, float value);
float calculate_average(CircularBuffer *buffer);
void shutdown_motor();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Initialize the circular buffer
void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *buffer, float value) {
    buffer->buffer[buffer->head] = value;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i];
    }
    return sum / buffer->count;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        log_message(LOG_ERR, "Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char config[3];
    char buffer[2];

    // Configure ADS1115 for single-ended AIN0, 4.096V range, single-shot mode
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC2; // Single-shot mode, AIN0, +/- 4.096V, 128 SPS
    config[2] = 0x83; // Start single conversion

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        log_message(LOG_ERR, "Failed to write to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10); // 10 ms

    // Read the conversion result
    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        log_message(LOG_ERR, "Failed to read from I2C device");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Convert raw ADC value to magnetic field strength in Gauss
float convert_to_gauss(int16_t raw_value) {
    float voltage = (float)raw_value * VREF / 32768.0;
    float gauss = (voltage - ZERO_FIELD_OUTPUT) / SENSITIVITY;
    return gauss;
}

// Shutdown the motor
void shutdown_motor() {
    gpioWrite(GPIO_SHUTDOWN, 1); // Set GPIO HIGH
    log_message(LOG_INFO, "Motor shutdown triggered");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    terminate = 1;
}

// Log messages with timestamps
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(priority, "%s: %s", timestamp, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0); // Ensure it starts LOW

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer gauss_buffer;
    init_buffer(&gauss_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message(LOG_INFO, "Program started");

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            float gauss = convert_to_gauss(raw_value);

            // Add to circular buffer
            add_to_buffer(&gauss_buffer, gauss);

            // Calculate rolling average
            float average_gauss = calculate_average(&gauss_buffer);

            // Log reading
            char log_message_buffer[100];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "Raw: %d, Gauss: %.2f, Average: %.2f", raw_value, gauss, average_gauss);
            log_message(LOG_INFO, log_message_buffer);

            // Check threshold and shutdown motor
            if (average_gauss > THRESHOLD_GAUSS) {
                shutdown_motor();
            }
        } else {
            log_message(LOG_ERR, "Failed to read sensor data");
        }

        gpioDelay(1000 / SAMPLE_RATE_HZ); // Delay for 1000 ms / SAMPLE_RATE_HZ
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_SHUTDOWN, 0); // Ensure GPIO is LOW
    gpioTerminate();
    closelog();

    return 0;
}

