// Function to map ADC value to rainfall intensity level
int map_adc_to_intensity(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1;
    }

    // Linear mapping: 0-1023 -> 0-10
    int intensity_level = (int)(((float)adc_value / 1023.0) * (RAIN_INTENSITY_MAX - RAIN_INTENSITY_MIN) + RAIN_INTENSITY_MIN);

    return intensity_level;
}

// Function to log data to console
void log_data(int adc_value, int intensity_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] ADC Value: %d, Intensity Level: %d\n", timestamp, adc_value, intensity_level);
}

