    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value. Retrying in 1 second.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Map ADC value to rainfall intensity level
        int intensity_level = map_adc_to_intensity(adc_value);
        if (intensity_level < 0) {
            fprintf(stderr, "Error: Failed to map ADC value to intensity level. Retrying in 1 second.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Log data
        log_data(adc_value, intensity_level);

        // Check if rain is detected
        if (intensity_level >= RAIN_THRESHOLD) {
            printf("Rain detected!\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close SPI channel and terminate pigpio library
    spiClose(spi_handle);
    gpioTerminate();

    printf("Rain sensor monitoring stopped.\n");

    return 0;
}

