#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_ads1115();
int read_ads1115();
double convert_to_gauss(int raw_value);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional, but good practice)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int config_register;
    int conversion_register;
    int led_gpio;
    double threshold;
} Config;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure ADS1115 for single-ended AIN0, +/- 4.096V, single-shot mode
int configure_ads1115() {
    // Configuration register settings:
    // 1. Start single conversion (bit 15)
    // 2. Set gain (bits 12-11) to +/- 4.096V (00)
    // 3. Set single-ended input (bits 10-9) to AIN0 (00)
    // 4. Set comparator mode (bits 8-7) to non-latching (00)
    // 5. Set comparator polarity (bits 6-5) to active low (00)
    // 6. Set comparator threshold (bits 4-0) to 0 (default)
    // 7. Disable comparator (bit 3)
    // 8. Disable interrupts (bit 2)
    // 9. Set data ready bit (bit 1) to high (default)
    // 10. Set conversion mode (bit 0) to single-shot (0)
    unsigned short config_value = 0xC283; // Single-shot, +/- 4.096V, AIN0

    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, config_value);
    if (result < 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Read raw ADC value from ADS1115
