#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CLIENT_ID "soil_monitor"
#define PUMP_ON_COMMAND "pump_on"
#define PUMP_OFF_COMMAND "pump_off"

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_moisture(int adc_value);
void control_pump(int pump_state);
void publish_moisture(float moisture);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to moisture percentage
float adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_WARNING, "ADC value out of range: %d", adc_value);
        return -1.0; // Indicate sensor-absent
    }

    // Linear mapping: 0 ADC = 100% moisture, 1023 ADC = 0% moisture
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(int pump_state) {
    gpioWrite(PUMP_GPIO, pump_state);
    syslog(LOG_INFO, "Pump set to %s", pump_state ? "ON" : "OFF");
}

// Function to publish moisture reading to MQTT broker
void publish_moisture(float moisture) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%.2f", moisture);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(ret));
    }
}

// MQTT connect callback function
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_BROKER, MQTT_PORT);
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_strerror(result));
    }
}

// MQTT message callback function
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, (char *)message->payload);

        if (strcmp(message->topic, MQTT_TOPIC) == 0) {
            if (strcmp((char *)message->payload, PUMP_ON_COMMAND) == 0) {
                control_pump(1); // Turn pump ON
            } else if (strcmp((char *)message->payload, PUMP_OFF_COMMAND) == 0) {
                control_pump(0); // Turn pump OFF
            }
        }
    } else {
        syslog(LOG_INFO, "Received empty message on topic %s", message->topic);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0); // Ensure pump is initially off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT new failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read moisture sensor
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            syslog(LOG_WARNING, "Failed to read moisture sensor");
            sleep(60); // Wait before retrying
            continue;
        }

        float moisture = adc_to_moisture(adc_value);
        if (moisture < 0) {
            syslog(LOG_WARNING, "Sensor-absent or out-of-range reading");
            sleep(60); // Wait before retrying
            continue;
        }

        // Control pump based on moisture level
        if (moisture < MOISTURE_THRESHOLD_LOW) {
            control_pump(1); // Turn pump ON
        } else if (moisture > MOISTURE_THRESHOLD_HIGH) {
            control_pump(0); // Turn pump OFF
        }

        // Publish moisture reading
        publish_moisture(moisture);

        // Wait 60 seconds
        sleep(60);
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    control_pump(0); // Ensure pump is off on exit
    gpioTerminate();
    closelog();

    return 0;
}

