#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0
#define VALVE_GPIO 17
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"
#define SENSOR_COUNT 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float average_sensor_readings(int sensor_values[], int num_sensors);
int map_to_valve_position(float average_reading);
void set_valve_position(int valve_position);
void log_data(int sensor_values[], float average_reading, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate the average of sensor readings
float average_sensor_readings(int sensor_values[], int num_sensors) {
    float sum = 0.0;
    int valid_readings = 0;

    for (int i = 0; i < num_sensors; i++) {
        if (sensor_values[i] >= 0) { // Check for valid reading
            sum += sensor_values[i];
            valid_readings++;
        }
    }

    if (valid_readings > 0) {
        return sum / valid_readings;
    } else {
        return -1.0; // Indicate no valid readings
    }
}

// Function to map the average reading to a valve position (0-100%)
int map_to_valve_position(float average_reading) {
    if (average_reading < 0) {
        return 0; // No valid readings, so return 0
    }

    // Invert the reading (0 is wet, 1023 is dry)
    int inverted_reading = 1023 - (int)average_reading;

    // Map the inverted reading to the valve position range (0-100%)
    int valve_position = (int)(((float)inverted_reading / 1023.0) * 100.0);

    // Clamp the valve position to the range 0-100%
    if (valve_position < 0) {
        valve_position = 0;
    } else if (valve_position > 100) {
        valve_position = 100;
    }

    return valve_position;
}

// Function to set the valve position using PWM
void set_valve_position(int valve_position) {
    // Calculate the duty cycle (0-100%)
    int duty_cycle = (int)(((float)valve_position / 100.0) * PWM_RANGE);

    // Set the PWM duty cycle
    gpioPWM(VALVE_GPIO, duty_cycle);
}

// Function to log data to a file
void log_data(int sensor_values[], float average_reading, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ", timestamp);
    for (int i = 0; i < SENSOR_COUNT; i++) {
        fprintf(log_file, "%d, ", sensor_values[i]);
    }
    fprintf(log_file, "%.2f, %d\n", average_reading, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set valve GPIO as output
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int sensor_values[SENSOR_COUNT];
        float average_reading;
        int valve_position;

        // Read sensor values
        for (int i = 0; i < SENSOR_COUNT; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error: Failed to read sensor %d\n", i);
                // Skip to the next sensor, but continue with other sensors
                sensor_values[i] = 0; // Assign a default value
            }
        }

        // Calculate average reading
        average_reading = average_sensor_readings(sensor_values, SENSOR_COUNT);

        // Map to valve position
        if (average_reading >= 0) {
            valve_position = map_to_valve_position(average_reading);
        } else {
            valve_position = 0; // No valid readings, set to 0
        }

        // Set valve position
        set_valve_position(valve_position);

        // Log data
        log_data(sensor_values, average_reading, valve_position);

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    set_valve_position(0); // Close the valve
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

