#define RETRY_COUNT 5
#define RETRY_DELAY_MS 10
#define SLEEP_DURATION_S 5

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int spi_flags;
