#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define LDR_CHANNEL 0
#define PWM_PERIOD 1000000 // 1 ms
#define PWM_RANGE 1000000   // 1 ms
#define MIN_DISTANCE 2.0   // cm
#define MAX_DISTANCE 400.0  // cm
#define MIN_FREQUENCY 220.0 // Hz
#define MAX_FREQUENCY 880.0 // Hz
#define MIN_VOLUME 0.0
#define MAX_VOLUME 1.0
#define CONFIG_FILE "theremin_config.txt"
#define LOG_FILE "theremin_log.txt"

// Global variables
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *trigger_line, *echo_line, *pwm_line;
static int spi_fd;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Calibration data
static float distance_to_frequency_offset = 0.0;
static float distance_to_frequency_scale = 1.0;
static float ldr_to_volume_offset = 0.0;
static float ldr_to_volume_scale = 1.0;

// Function prototypes
int init_gpio();
int init_spi();
int read_ldr();
float calculate_distance(unsigned int pulse_width);
float calculate_frequency(float distance);
float calculate_volume(int ldr_value);
void set_pwm_frequency(float frequency);
void set_pwm_duty_cycle(float volume);
void trigger_sensor();
void echo_callback(struct gpiod_line *line, unsigned int value, void *user_data);
void signal_handler(int sig);
int load_calibration_data();
int save_calibration_data();

// Helper function to write to a file
int write_to_file(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening file for writing");
        return -1;
    }
    if (write(fd, value, strlen(value)) < 0) {
        perror("Error writing to file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Helper function to read from a file
int read_from_file(const char *path, char *buffer, size_t buffer_size) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Error opening file for reading");
        return -1;
    }
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read < 0) {
        perror("Error reading from file");
        close(fd);
        return -1;
    }
    buffer[bytes_read] = '\0';
    close(fd);
    return 0;
}

int main() {
    // Initialize signal handling
    signal(SIGINT, signal_handler);

    // Load calibration data
    if (load_calibration_data() != 0) {
        fprintf(stderr, "Failed to load calibration data. Using default values.\n");
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize PWM
    if (set_pwm_frequency(440.0) != 0) {
        fprintf(stderr, "PWM frequency initialization failed.\n");
        close(spi_fd);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read LDR value
        int ldr_value = read_ldr();
        if (ldr_value < 0) {
            fprintf(stderr, "Error reading LDR value.\n");
            continue; // Skip to the next iteration
        }

        // Calculate distance
        unsigned int pulse_width = trigger_sensor();
        if (pulse_width == 0) {
            fprintf(stderr, "Error reading distance.\n");
            continue; // Skip to the next iteration
        }
        float distance = calculate_distance(pulse_width);

        // Calculate frequency
        float frequency = calculate_frequency(distance);

        // Calculate volume
        float volume = calculate_volume(ldr_value);

        // Set PWM frequency and duty cycle
        set_pwm_frequency(frequency);
        set_pwm_duty_cycle(volume);

        // Log data
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);
        fprintf(log_file, "%s, Distance: %.2f cm, Frequency: %.2f Hz, Volume: %.2f\n", timestamp, distance, frequency, volume);
        fflush(log_file); // Ensure data is written to file immediately

        // Delay
        usleep(10000); // 10 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_pwm_frequency(0.0); // Stop PWM
    set_pwm_duty_cycle(0.0); // Stop PWM
    close(spi_fd);
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(pwm_line);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);

    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(gpio_chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(gpio_chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    pwm_line = gpiod_chip_get_line(gpio_chip, PWM_PIN);
    if (!pwm_line) {
        perror("Error getting PWM line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Set trigger line as output
    if (gpiod_line_request_output(trigger_line, "theremin", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Set echo line as input with callback
    if (gpiod_line_request_input(echo_line, "theremin") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "theremin";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0;

    if (gpiod_line_request_config(echo_line, &config) < 0) {
        perror("Error requesting echo line config");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Set PWM line as output
    if (gpiod_line_request_output(pwm_line, "theremin", 0) < 0) {
        perror("Error requesting PWM line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Initialize SPI
int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
