void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Shutting down...\n", signal);
    terminate = 1;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    spiClose(spi_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from MQ-135 sensor
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            // Attempt to re-initialize SPI
            spiClose(spi_handle);
            if (initialize_spi() != 0) {
                fprintf(stderr, "Error: Failed to re-initialize SPI\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Convert ADC value to AQI
        float aqi = adc_to_aqi(adc_value);

        // Control the ventilation fan
        control_fan(aqi);

        // Log the data
        log_data(aqi);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Air quality monitoring stopped.\n");
    return 0;
}

