#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define MCP3008_CHANNEL 0
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define LOG_FILE "alcohol_log.txt"
#define ALCOHOL_THRESHOLD 50.0
#define SOBER_THRESHOLD 20.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int spi_handle;
int udp_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
char* classify_alcohol_level(float ppm);
int send_udp_message(const char *message);
void log_message(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int adc_value = -1; // Initialize to an invalid value
    int retries = 0;

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (channel << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    while (retries < RETRY_COUNT) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value
            adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
            return adc_value;
        } else {
            log_message("SPI transfer failed. Retrying...");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    log_message("SPI transfer failed after multiple retries.");
    return -1; // Indicate failure
}

// Function to convert ADC value to PPM
float adc_to_ppm(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        log_message("Invalid ADC value.");
        return -1.0; // Indicate error
    }
    return (adc_value * 0.5) - 10.0;
}

// Function to classify alcohol level
char* classify_alcohol_level(float ppm) {
    if (ppm > ALCOHOL_THRESHOLD) {
        return "Alcohol detected! Limit exceeded.";
    } else if (ppm < SOBER_THRESHOLD) {
        return "Sobriety confirmed.";
    } else {
        return "Alcohol level within acceptable range.";
    }
}

// Function to send UDP message
int send_udp_message(const char *message) {
    struct sockaddr_in server_addr;

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        log_message("Invalid server IP address.");
        return -1;
    }

    if (sendto(udp_socket, message, strlen(message), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        log_message("Failed to send UDP message.");
        return -1;
    }

    return 0;
}

// Function to log messages
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
    printf("%s: %s\n", timestamp, message); // Also print to console
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Signal received, terminating...");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        log_message("SPI open failed");
        gpioTerminate();
        return -1;
    }

    // Open UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        log_message("Socket creation failed");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_message("Failed to open log file");
        close(udp_socket);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Initialization complete");
    return 0;
}

// Cleanup function
void cleanup() {
    log_message("Cleaning up...");

    // Close SPI channel
    spiClose(spi_handle);

    // Close UDP socket
    close(udp_socket);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    log_message("Cleanup complete");
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            log_message("Failed to read ADC value.");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to PPM
        float ppm = adc_to_ppm(adc_value);
        if (ppm < 0) {
            log_message("Failed to convert ADC value to PPM.");
            continue; // Skip to the next iteration
        }

        // Classify alcohol level
        char *alcohol_level = classify_alcohol_level(ppm);

        // Log message
        char log_message_buffer[100];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "ADC Value: %d, PPM: %.2f, Alcohol Level: %s", adc_value, ppm, alcohol_level);
        log_message(log_message_buffer);

        // Send UDP message
        if (send_udp_message(log_message_buffer) != 0) {
            log_message("Failed to send UDP message.");
        }

        // Wait for 1 second
        gpioDelay(1000 * 1000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

