#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 Configuration
#define MCP3008_CS 8

// Potentiometer Channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Speed Limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Motion Profile Parameters
#define ACCELERATION_TIME 2.0 // seconds
#define DECELERATION_TIME 2.0 // seconds
#define PAUSE_TIME 5.0        // seconds

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int read_mcp3008(int channel);
float map_adc_to_speed(int adc_value);
void set_motor_speed(int motor_enable, int motor_direction, int speed);
void move_forward(int motor1_enable, int motor1_direction, int motor2_enable, int motor2_direction, float speed1, float speed2);
void move_backward(int motor1_enable, int motor1_direction, int motor2_enable, int motor2_direction, float speed1, float speed2);
void pause(float seconds);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;           // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    gpioWrite(MCP3008_CS, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map ADC value to speed factor
float map_adc_to_speed(int adc_value) {
    // Logarithmic mapping
    float speed_factor = MIN_SPEED + (float)(adc_value - 0) * (MAX_SPEED - MIN_SPEED) / 1023.0;
    return speed_factor;
}

// Function to set motor speed using pigpio
void set_motor_speed(int motor_enable, int motor_direction, int speed) {
    if (speed < 0 || speed > 255) {
        fprintf(stderr, "Error: Invalid speed value: %d\n", speed);
        return;
    }

    gpioPWM(motor_enable, speed);
    gpioWrite(motor_direction, speed > 0 ? 1 : 0); // Set direction based on speed
}

// Function to move motors forward
void move_forward(int motor1_enable, int motor1_direction, int motor2_enable, int motor2_direction, float speed1, float speed2) {
    set_motor_speed(motor1_enable, motor1_direction, (int)speed1);
    set_motor_speed(motor2_enable, motor2_direction, (int)speed2);
}

// Function to move motors backward
void move_backward(int motor1_enable, int motor1_direction, int motor2_enable, int motor2_direction, float speed1, float speed2) {
    set_motor_speed(motor1_enable, motor1_direction, (int)speed2);
    set_motor_speed(motor2_enable, motor2_direction, (int)speed1);
}

// Function to pause for a specified time
void pause(float seconds) {
    gpioDelay(seconds * 1000000); // pigpioDelay takes microseconds
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);
    gpioSetMode(MCP3008_CS, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM range for motor speed control
    gpioSetPWMrange(MOTOR1_ENABLE, 255);
    gpioSetPWMrange(MOTOR2_ENABLE, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int adc_value1 = read_mcp3008(POT1_CHANNEL);
        int adc_value2 = read_mcp3008(POT2_CHANNEL);

        if (adc_value1 == -1 || adc_value2 == -1) {
            fprintf(stderr, "Error: Failed to read ADC values. Retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Map ADC values to speed factors
        float speed1 = map_adc_to_speed(adc_value1);
        float speed2 = map_adc_to_speed(adc_value2);

        // Move motors forward
        move_forward(MOTOR1_ENABLE, MOTOR1_DIRECTION, MOTOR2_ENABLE, MOTOR2_DIRECTION, speed1, speed2);

        // Pause
        pause(PAUSE_TIME);

        // Move motors backward
        move_backward(MOTOR1_ENABLE, MOTOR1_DIRECTION, MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2, speed1);

        // Pause
        pause(PAUSE_TIME);
    }

    // Stop motors
    set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, 0);
    set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, 0);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

