#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <stdbool.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define SAMPLE_RATE_HZ 1000
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE_HZ)
#define LOG_FILE "audio_log.txt"
#define CS_GPIO 8

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int mode, int bits_per_word, int speed);
int spi_transfer(int fd, uint8_t tx_buf[3], uint8_t rx_buf[3]);
int read_adc(int fd, int channel);
void log_data(FILE *fp, uint64_t timestamp_ns, int raw_adc_value);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, int mode, int bits_per_word, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_buf[1];
    mode_buf[0] = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_buf) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_per_word_buf[1];
    bits_per_word_buf[0] = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word_buf) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed_buf[1];
    speed_buf[0] = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_buf) < 0) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t tx_buf[3], uint8_t rx_buf[3]) {
    struct spi_ioc_transfer transfer[1];

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// ADC reading function
int read_adc(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    if (spi_transfer(fd, tx_buf, rx_buf) < 0) {
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Data logging function
void log_data(FILE *fp, uint64_t timestamp_ns, int raw_adc_value) {
    fprintf(fp, "%llu|%d\n", timestamp_ns, raw_adc_value);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int sig) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_release(gpio_chip);
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    // Request GPIO8 as output
    cs_line = gpiod_chip_get_line(gpio_chip, CS_GPIO);
    if (!cs_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "audio_sampler", 0) < 0) {
        perror("Error requesting GPIO line as output");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_PERIOD_NS;

    while (!terminate) {
        // Set CS low
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("Error setting CS low");
            break;
        }

        // Read ADC value
        int raw_adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (raw_adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Get timestamp
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
            perror("Error getting timestamp");
            break;
        }
        uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;

        // Log data
        log_data(log_file, timestamp_ns, raw_adc_value);

        // Set CS high
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Error setting CS high");
            break;
        }

        // Sleep for the sample period
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

