    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    // Request GPIO8 as output
    cs_line = gpiod_chip_get_line(gpio_chip, CS_GPIO);
    if (!cs_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "audio_sampler", 0) < 0) {
        perror("Error requesting GPIO line as output");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_PERIOD_NS;

    while (!terminate) {
        // Set CS low
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("Error setting CS low");
            break;
        }

        // Read ADC value
        int raw_adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (raw_adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Get timestamp
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
            perror("Error getting timestamp");
            break;
        }
        uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;

        // Log data
        log_data(log_file, timestamp_ns, raw_adc_value);

        // Set CS high
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Error setting CS high");
            break;
        }

        // Sleep for the sample period
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

