#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

// ADXL335 Register Addresses
#define ADXL335_REG_DEVID_AD 0x00
#define ADXL335_REG_THRESH_TAP 0x1D
#define ADXL335_REG_OFSX 0x1E
#define ADXL335_REG_OFSY 0x1F
#define ADXL335_REG_OFSZ 0x20
#define ADXL335_REG_DUR 0x21
#define ADXL335_REG_LATENT 0x22
#define ADXL335_REG_WINDOW 0x23
#define ADXL335_REG_THRESH_ACT 0x24
#define ADXL335_REG_TIME_ACT 0x25
#define ADXL335_REG_THRESH_INACT 0x26
#define ADXL335_REG_TIME_INACT 0x27
#define ADXL335_REG_ACT_INACT_CTL 0x28
#define ADXL335_REG_THRESH_FF 0x29
#define ADXL335_REG_TIME_FF 0x2A
#define ADXL335_REG_TAP_AXES 0x2B
#define ADXL335_REG_ACT_TAP_STATUS 0x2C
#define ADXL335_REG_BW_RATE 0x2C
#define ADXL335_REG_POWER_CTL 0x2D
#define ADXL335_REG_INT_ENABLE 0x2E
#define ADXL335_REG_INT_MAP 0x2F
#define ADXL335_REG_INT_SOURCE 0x30
#define ADXL335_REG_DATA_FORMAT 0x31
#define ADXL335_REG_DATAX0 0x32
#define ADXL335_REG_DATAX1 0x33
#define ADXL335_REG_DATAY0 0x34
#define ADXL335_REG_DATAY1 0x35
#define ADXL335_REG_DATAZ0 0x36
#define ADXL335_REG_DATAZ1 0x37

// MCP3008 Register Addresses
#define MCP3008_REG_START 0x01
#define MCP3008_REG_SINGLE_ENDED 0x01

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// GPIO Configuration
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman Filter Parameters
float Q = 0.01; // Process noise covariance
float R = 0.1;  // Measurement noise covariance
float P = 1.0;  // Initial error covariance
float x = 0.0;  // Estimate
float K = 0.0;  // Kalman gain

// Function Prototypes
int spi_read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_acceleration(float voltage);
float kalman_filter(float measurement);
void signal_handler(int signal);

// SPI Read ADC Function
int spi_read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = MCP3008_REG_START | (channel << 4);
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// ADC to Voltage Conversion Function
float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1024.0;
}

// Voltage to Acceleration Conversion Function
float voltage_to_acceleration(float voltage) {
    return (voltage - 1.5) / 0.3;
}

// Kalman Filter Function
float kalman_filter(float measurement) {
    // Prediction step
    x = x; // No prediction needed for the first iteration
    P = P + Q;

    // Update step
    K = P / (P + R);
    x = x + K * (measurement - x);
    P = (1 - K) * P;

    return x;
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008 initially

    gpioSetMode(MOSI_PIN, PI_OUTPUT);
    gpioSetMode(MISO_PIN, PI_INPUT);
    gpioSetMode(SCLK_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int adc_x = spi_read_adc(0);
        int adc_y = spi_read_adc(1);
        int adc_z = spi_read_adc(2);

        if (adc_x == -1 || adc_y == -1 || adc_z == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to voltages
        float voltage_x = adc_to_voltage(adc_x);
        float voltage_y = adc_to_voltage(adc_y);
        float voltage_z = adc_to_voltage(adc_z);

        // Convert voltages to accelerations
        float acceleration_x = voltage_to_acceleration(voltage_x);
        float acceleration_y = voltage_to_acceleration(voltage_y);
        float acceleration_z = voltage_to_acceleration(voltage_z);

        // Apply Kalman filter
        float filtered_acceleration_x = kalman_filter(acceleration_x);
        float filtered_acceleration_y = kalman_filter(acceleration_y);
        float filtered_acceleration_z = kalman_filter(acceleration_z);

        // Print filtered acceleration values
        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", filtered_acceleration_x, filtered_acceleration_y, filtered_acceleration_z);

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

