#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>
#include <pigpio.h>

// Configuration
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60 // seconds

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
void signal_handler(int signum);
int connect_mqtt(struct mosquitto **mosq);
int subscribe_mqtt(struct mosquitto *mosq);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json(const char *json_string, int *led_state);
void set_led(int led_state);
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
        printf("Received signal %d, shutting down...\n", signum);
    }
}

// Connect to MQTT broker
int connect_mqtt(struct mosquitto **mosq) {
    int rc;

    *mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!*mosq) {
        log_error("Error: Out of memory.");
        return 1;
    }

    mosquitto_connect_callback_set(*mosq, NULL);
    mosquitto_disconnect_callback_set(*mosq, NULL);
    mosquitto_message_callback_set(*mosq, message_callback);

    rc = mosquitto_connect(*mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Error: Could not connect to MQTT broker.");
        mosquitto_destroy(*mosq);
        *mosq = NULL;
        return 1;
    }

    return 0;
}

// Subscribe to MQTT topic
int subscribe_mqtt(struct mosquitto *mosq) {
    int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Error: Could not subscribe to MQTT topic.");
        return 1;
    }
    return 0;
}

// Message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        int led_state;
        if (parse_json((char *)message->payload, &led_state) == 0) {
            set_led(led_state);
        } else {
            log_error("Error: Invalid JSON payload.");
        }
    } else {
        log_error("Error: Empty message received.");
    }
}

// Parse JSON payload
int parse_json(const char *json_string, int *led_state) {
    cJSON *root = cJSON_Parse(json_string);
    if (root == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            fprintf(stderr, "Error before: %s\n", error_ptr);
        }
        return 1;
    }

    cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(root, "led_state");
    if (!cJSON_IsBool(led_state_json)) {
        log_error("Error: 'led_state' is not a boolean.");
        cJSON_Delete(root);
        return 1;
    }

    *led_state = led_state_json->valueint;

    cJSON_Delete(root);
    return 0;
}

// Set LED state
void set_led(int led_state) {
    gpioWrite(GPIO_PIN, led_state);
    printf("LED set to %s\n", led_state ? "ON" : "OFF");
}

// Log error messages with timestamps
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

int main() {
    int rc;
    int reconnect_delay = 1; // Initial delay in seconds

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure LED is off on startup

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Connect to MQTT broker
    if (connect_mqtt(&mosq) != 0) {
        gpioTerminate();
        return 1;
    }

    // Subscribe to MQTT topic
    if (subscribe_mqtt(mosq) != 0) {
        mosquitto_destroy(mosq);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        rc = mosquitto_loop(mosq, -1, 1); // Non-blocking loop with a timeout
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Error: MQTT loop error.");
            sleep(reconnect_delay);
            reconnect_delay *= 2; // Exponential backoff
            if (reconnect_delay > MAX_RECONNECT_DELAY) {
                reconnect_delay = MAX_RECONNECT_DELAY;
            }
            if (connect_mqtt(&mosq) != 0) {
                running = 0; // Exit loop if reconnection fails
            }
            if (subscribe_mqtt(mosq) != 0) {
                running = 0; // Exit loop if reconnection fails
            }
        }
    }

    // Cleanup
    printf("Cleaning up...\n");
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

