#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Define constants
#define SOUND_THRESHOLD 0 // KY-038 outputs LOW when sound is detected
#define ALARM_DURATION 1 // Alarm duration in seconds

// Global variable for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to control the alarm LED
void control_alarm_led(int state) {
    gpioWrite(ALARM_LED_PIN, state);
}

// Function to blink the alarm LED
void blink_alarm_led() {
    control_alarm_led(1); // Turn LED on
    gpioDelay(1000);       // Wait for 1 second
    control_alarm_led(0); // Turn LED off
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();

        printf("Sound level: %d\n", sound_level);

        if (sound_level == SOUND_THRESHOLD) {
            printf("Sound detected! Blinking alarm LED.\n");
            blink_alarm_led();
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Clean up GPIO resources before exiting
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

