#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define SHUTDOWN_COMMAND "sudo shutdown -h now"

static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s: %s\n", timestamp, message);
    free(timestamp); // Free the allocated memory

    if (fclose(fp) != 0) {
        perror("Failed to close log file");
        return -1;
    }
    return 0;
}

// Function to execute the shutdown command
int execute_shutdown() {
    int result = system(SHUTDOWN_COMMAND);
    if (result == -1) {
        perror("Failed to execute shutdown command");
        return -1;
    }
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for falling-edge event detection
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "vibration-monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0; // No special flags

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(line, -1, &event); // Wait indefinitely

        if (ret < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            perror("Failed to wait for event");
            break;
        }

        if (ret > 0) {
            // Event occurred
            if (event.type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                printf("Vibration detected! Shutting down...\n");

                // Log the event
                if (log_message("Vibration detected! Shutting down...") != 0) {
                    fprintf(stderr, "Failed to log message.\n");
                }

                // Execute the shutdown command
                if (execute_shutdown() != 0) {
                    fprintf(stderr, "Failed to execute shutdown command.\n");
                }

                // Release the GPIO line
                gpiod_line_release(line);

                // Close the GPIO chip
                gpiod_chip_close(chip);

                // Exit the program
                break;
            }
        }
    }

    // Release the GPIO line and close the GPIO chip before exiting
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Vibration monitoring stopped.\n");

    return 0;
}

