#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define LM35_OUTPUT_VOLTAGE 10.0
#define TEMPERATURE_SCALE (LM35_OUTPUT_VOLTAGE / 1000.0)
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer temp_buffer;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_temperature(int adc_value);
void add_to_buffer(float temperature);
float get_average_temperature();
void log_temperature(float temperature);
void save_buffer_to_file();
void signal_handler(int signal);
void initialize_circular_buffer(CircularBuffer *cb);

// Initialize circular buffer
void initialize_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode + channel number
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Convert ADC value to temperature
float convert_to_temperature(int adc_value) {
    float voltage = (adc_value * VREF) / 1024.0;
    float temperature = voltage * TEMPERATURE_SCALE;
    return temperature;
}

// Add temperature to circular buffer
void add_to_buffer(float temperature) {
    temp_buffer.buffer[temp_buffer.head] = temperature;
    temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
    if (temp_buffer.count < BUFFER_SIZE) {
        temp_buffer.count++;
    }
}

// Get average temperature from circular buffer
float get_average_temperature() {
    if (temp_buffer.count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < temp_buffer.count; i++) {
        sum += temp_buffer.buffer[i];
    }
    return sum / temp_buffer.count;
}

// Log temperature to console
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

