        // Save buffer to file
        save_buffer_to_file();

        // Wait 5 seconds
        sleep(5);
    }

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

