#include <wiringPiSPI.h>

// Constants
#define BH1750_ADDR 0x23
#define MCP3008_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "environmental_log.txt"
#define SLEEP_INTERVAL 1 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
int read_mcp3008(int spi_channel, int channel);
void log_data(int light_level, int sound_level);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read light level from BH1750 sensor
int read_bh1750(int i2c_handle) {
    int lux;
    unsigned char config[1] = {0x10}; // Continuous high-resolution mode

    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to BH1750\n");
        return -1;
    }

    gpioDelay(200); // Wait for measurement (at least 180ms)

    unsigned char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from BH1750\n");
        return -1;
    }

    lux = (data[0] << 8) | data[1];
    return lux;
}

// Function to read sound level from MCP3008 ADC
int read_mcp3008(int spi_channel, int channel) {
    unsigned char spi_data[3];
    int adc_value;

    // Construct SPI message
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    spi_data[2] = 0x00; // Don't care

    wiringPiSPIDataRW(spi_channel, spi_data, 3);

    // Extract ADC value (10 bits)
    adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return adc_value;
}

// Function to log data to file
void log_data(int light_level, int sound_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Light: %d lux, Sound: %d\n", timestamp, light_level, sound_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Environmental monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int light_level = read_bh1750(i2c_handle);
        int sound_level = read_mcp3008(SPI_CHANNEL, MCP3008_CHANNEL);

        if (light_level != -1 && sound_level != -1) {
            log_data(light_level, sound_level);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        sleep(SLEEP_INTERVAL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Environmental monitoring stopped.\n");

    return 0;
}

