#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"
#define POTENTIOMETER_GPIO 18
#define POTENTIOMETER_MIN_VALUE 0
#define POTENTIOMETER_MAX_VALUE 1023
#define POTENTIOMETER_MIN_THRESHOLD 0
#define POTENTIOMETER_MAX_THRESHOLD 1023

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the GPIO chip
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_PIN);
    if (!*line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_input(*line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO_PIN, strerror(errno));
        gpiod_line_release(*line);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to read the potentiometer value
int read_potentiometer(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to convert the potentiometer value to a flame detection threshold
int convert_potentiometer_to_threshold(int potentiometer_value) {
    return POTENTIOMETER_MIN_THRESHOLD + (int)(((float)(potentiometer_value - POTENTIOMETER_MIN_VALUE) / (POTENTIOMETER_MAX_VALUE - POTENTIOMETER_MIN_VALUE)) * (POTENTIOMETER_MAX_THRESHOLD - POTENTIOMETER_MIN_THRESHOLD));
}

// Function to log the flame event to a file
int log_flame_event(FILE *log_file, int pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d,%d\n", timestamp, pin, state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to print an alarm message to stdout
void print_alarm_message(int pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - ALARM: Flame detected on GPIO %d (State: %s)\n", timestamp, pin, state ? "HIGH" : "LOW");
}

int main() {
    int flame_threshold;
    int flame_detected;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &line) < 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read the flame sensor value
        flame_detected = read_flame_sensor(line);
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting...\n");
            break;
        }

        // Read the potentiometer value
        int potentiometer_value = read_potentiometer(line);
        if (potentiometer_value < 0) {
            fprintf(stderr, "Error reading potentiometer, exiting...\n");
            break;
        }

        // Convert the potentiometer value to a flame detection threshold
        flame_threshold = convert_potentiometer_to_threshold(potentiometer_value);

        // Log the flame event
        if (log_flame_event(log_file, GPIO_PIN, flame_detected) < 0) {
            fprintf(stderr, "Error logging flame event, exiting...\n");
            break;
        }

        // Check if flame is detected
        if (flame_detected == 0) { // Assuming LOW indicates flame
            print_alarm_message(GPIO_PIN, flame_detected);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

