#define SPI_BAUD 500000
#define MCP3008_CHANNEL 0
#define DAC_ADDRESS 0x62
#define VREF 3.3
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 0.5 // seconds

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_temperature(float voltage);
int dac_write(int voltage);
void log_data(int adc_value, float temperature, float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to convert voltage to temperature in Celsius
float voltage_to_temperature(float voltage) {
    return (voltage - 0.5) * 100.0;
}

// Function to write to MCP4725 DAC
int dac_write(int voltage) {
    if (voltage < 0 || voltage > 4095) {
        fprintf(stderr, "Error: Invalid DAC voltage: %d\n", voltage);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct I2C message (MCP4725 datasheet)
    tx_buffer[0] = 0x40; // Write command
    tx_buffer[1] = (voltage >> 4) & 0xFF; // MSB of DAC value
    tx_buffer[2] = voltage & 0x0F; // LSB of DAC value

    if (i2cWriteDevice(i2c_handle, tx_buffer, 3) != 0) {
