#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Function prototypes
int initialize_gpio();
void activate_relay(int pin);
void deactivate_relay(int pin);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop to activate and deactivate relays sequentially
    while (program_running) {
        // Activate relay 1
        activate_relay(RELAY1_PIN);
        sleep(1);

        // Deactivate relay 1
        deactivate_relay(RELAY1_PIN);
        sleep(1);

        // Activate relay 2
        activate_relay(RELAY2_PIN);
        sleep(1);

        // Deactivate relay 2
        deactivate_relay(RELAY2_PIN);
        sleep(1);

        // Activate relay 3
        activate_relay(RELAY3_PIN);
        sleep(1);

        // Deactivate relay 3
        deactivate_relay(RELAY3_PIN);
        sleep(1);

        // Activate relay 4
        activate_relay(RELAY4_PIN);
        sleep(1);

        // Deactivate relay 4
        deactivate_relay(RELAY4_PIN);
        sleep(1);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    printf("Program terminated gracefully.\n");
    return 0;
}

