#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_ENA_PIN 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define rain level thresholds
#define RAIN_THRESHOLD_HIGH 5
#define RAIN_THRESHOLD_LOW 3

// Define motor control parameters
#define MOTOR_FORWARD_SPEED 150
#define MOTOR_REVERSE_SPEED 150
#define MOTOR_FORWARD_DURATION 3 // seconds
#define MOTOR_REVERSE_DURATION 3 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
int map_adc_to_rain_level(int adc_value);
void close_window();
void open_window();
void stop_motor();
void log_rain_reading(int rain_level);
void signal_handler(int signal);

// Function to read the rain sensor value from MCP3008
int read_rain_sensor() {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message (MCP3008 single-ended read)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | SPI_CHANNEL) << 4; // Single-ended, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map ADC value to rain level (0-10)
int map_adc_to_rain_level(int adc_value) {
    // Ensure ADC value is within the valid range
    if (adc_value < 0) {
        adc_value = 0;
    } else if (adc_value > 1023) {
        adc_value = 1023;
    }

    // Map ADC value to rain level (0-10)
    return 10 - (int)(((float)adc_value / 1023.0) * 10.0);
}

// Function to close the window
void close_window() {
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_ENA_PIN, MOTOR_FORWARD_SPEED);
    printf("Closing window...\n");
    sleep(MOTOR_FORWARD_DURATION);
    stop_motor();
    printf("Window closed.\n");
}

// Function to open the window
void open_window() {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 1);
    gpioPWM(MOTOR_ENA_PIN, MOTOR_REVERSE_SPEED);
    printf("Opening window...\n");
    sleep(MOTOR_REVERSE_DURATION);
    stop_motor();
    printf("Window opened.\n");
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_ENA_PIN, 0);
    printf("Motor stopped.\n");
}

// Function to log rain reading to file
void log_rain_reading(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM range for motor control
    gpioSetPWMrange(MOTOR_ENA_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read rain sensor value
        int adc_value = read_rain_sensor();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading rain sensor, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Map ADC value to rain level
        int rain_level = map_adc_to_rain_level(adc_value);

        // Log rain reading
        log_rain_reading(rain_level);

        // Check rain level and control window
        if (rain_level >= RAIN_THRESHOLD_HIGH) {
            close_window();
        } else if (rain_level <= RAIN_THRESHOLD_LOW) {
            open_window();
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    stop_motor();
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

