        // Check rain level and control window
        if (rain_level >= RAIN_THRESHOLD_HIGH) {
            close_window();
        } else if (rain_level <= RAIN_THRESHOLD_LOW) {
            open_window();
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    stop_motor();
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

