#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_DATA_PIN 26
#define LED_PIN 16

// Define AGC parameters
#define AGC_THRESHOLD 0.7
#define AGC_WINDOW_SIZE 10
#define AGC_DELAY 50 // milliseconds

// Define debounce parameters
#define DEBOUNCE_DELAY 50 // milliseconds

// Global variables
static volatile int running = 1;
static int adc_value = 0;
static int adc_history[AGC_WINDOW_SIZE] = {0};
static int adc_history_index = 0;
static int led_state = 0; // 0 = off, 1 = on
static struct timespec debounce_start_time;

// Function prototypes
int initialize_gpio();
int read_adc();
float calculate_agc();
void control_led(int state);
void log_detection();
void debounce_delay();
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(MIC_DATA_PIN, PI_INPUT); // Set microphone data pin as input
    gpioSetMode(LED_PIN, PI_OUTPUT);    // Set LED pin as output
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Read ADC value using bit-banging
int read_adc() {
    int count = 0;
    int i;

    gpioSetMode(MIC_DATA_PIN, PI_OUTPUT); // Ensure data pin is output
    gpioWrite(MIC_DATA_PIN, 0); // Set low initially
    gpioDelay(1); // Small delay

    gpioSetMode(MIC_DATA_PIN, PI_INPUT); // Set data pin as input

    // Read 10 bits of data
    for (i = 0; i < 10; i++) {
        gpioWrite(MIC_DATA_PIN, 1); // Set high
        gpioDelay(1); // Small delay
        count = count << 1;
        if (gpioRead(MIC_DATA_PIN)) {
            count++;
        }
        gpioWrite(MIC_DATA_PIN, 0); // Set low
        gpioDelay(1); // Small delay
    }

    return count;
}

// Calculate AGC
float calculate_agc() {
    float sum = 0.0;
    int i;

    // Update AGC history
    adc_history[adc_history_index] = adc_value;
    adc_history_index = (adc_history_index + 1) % AGC_WINDOW_SIZE;

    // Calculate sum of ADC values in the window
    for (i = 0; i < AGC_WINDOW_SIZE; i++) {
        sum += adc_history[i];
    }

    // Calculate average ADC value
    float average_adc = sum / AGC_WINDOW_SIZE;

    // Calculate AGC threshold
    float agc_threshold = average_adc * AGC_THRESHOLD;

    return agc_threshold;
}

// Control LED state
void control_led(int state) {
    if (state != led_state) {
        gpioWrite(LED_PIN, state);
        led_state = state;
    }
}

// Log detection event
void log_detection() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Clap detected!\n", timestamp);
}

// Debounce delay
void debounce_delay() {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = DEBOUNCE_DELAY * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&ts, NULL);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Clap detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read ADC value
        adc_value = read_adc();

        // Calculate AGC threshold
        float agc_threshold = calculate_agc();

        // Check if clap is detected
        if (adc_value > agc_threshold) {
            // Check if LED is off
            if (led_state == 0) {
                // Turn on LED
                control_led(1);

                // Log detection
                log_detection();

                // Debounce delay
                debounce_delay();

                // Turn off LED
                control_led(0);
            }
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return 0;
}

