#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define LED_PIN 27

// Define constants
#define A 26.0
#define B -6.0
#define DISTANCE_THRESHOLD 200.0
#define LOG_FILE "distance_log.txt"

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
float voltage_to_distance(float voltage);
void log_distance(float distance);
void feeder_control(float distance);
void signal_handler(int signal);

// Function to export a GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int len;
    FILE *fp;

    fp = fopen("/sys/class/gpio/export", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int len;
    FILE *fp;

    fp = fopen("/sys/class/gpio/unexport", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s", direction) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to read the value of a GPIO pin
int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (fread(value_str, 1, 3, fp) < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return atoi(value_str);
}

// Function to convert voltage to distance (mm)
float voltage_to_distance(float voltage) {
    return A / voltage + B;
}

// Function to log the distance to a file
void log_distance(float distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Distance: %.2f mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, distance);

    fclose(fp);
}

// Function to control the feeder based on distance
void feeder_control(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pins
    if (gpio_export(SENSOR_PIN) < 0 || gpio_export(LED_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO pins. Exiting.\n");
        return 1;
    }

    // Set GPIO directions
    if (gpio_set_direction(SENSOR_PIN, "in") < 0 || gpio_set_direction(LED_PIN, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO directions. Exiting.\n");
        gpio_unexport(SENSOR_PIN);
        gpio_unexport(LED_PIN);
        return 1;
    }

    printf("Distance sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor value
        int sensor_value = gpio_read(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Convert sensor value to voltage (0V for LOW, 3.3V for HIGH)
        float voltage = (float)sensor_value * 3.3;

        // Convert voltage to distance
        float distance = voltage_to_distance(voltage);

        // Log the distance
        log_distance(distance);

        // Control the feeder
        feeder_control(distance);

        // Delay for 100 milliseconds
        usleep(100000); // 100 milliseconds
    }

    // Unexport GPIO pins before exiting
    gpio_unexport(SENSOR_PIN);
    gpio_unexport(LED_PIN);

    printf("Distance sensor monitoring stopped.\n");

    return 0;
}

