// SPI transfer function
int spi_transfer(int channel) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    gpioWrite(CS_GPIO, 0); // Assert CS low
    int result = spiXfer(spi_fd, tx_buf, rx_buf, 3);
    gpioWrite(CS_GPIO, 1); // Deassert CS high

    if (result != 0) {
