        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
            continue;
        }

        // Convert ADC value to voltage
