    return ((float)adc_value / ADC_RESOLUTION) * VREF;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    return (voltage - MLX91209_OFFSET) / MLX91209_SENSITIVITY;
}

// Function to log current reading to file
int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error: wiringPi initialisation failed.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "Error: SPI initialisation failed.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC value.\n");
            continue; // Skip to the next iteration
        }

        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage);

        if (log_current(current) != 0) {
            fprintf(stderr, "Error: Failed to log current.\n");
        }

        printf("Current: %.2f A\n", current);

        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_fd != -1) {
        // No specific SPI cleanup function in wiringPi, but good practice to set to -1
        spi_fd = -1;
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

