#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 5.0
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float vref;
    char *log_file;
    int sample_interval_ms;
} Config;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_current(int raw_code);
void log_current(float current);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3];
    unsigned char rx[3];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx[2] = 0x00;

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int raw_code = ((rx[1] & 0x03) << 8) | rx[2];
    return raw_code;
}

// Function to convert voltage to current
float voltage_to_current(int raw_code) {
    float voltage = (float)raw_code * VREF / 1023.0;
    float current = (voltage - 2.5) * (50.0 / 2.5);
    return current;
}

// Function to log current to file
void log_current(float current) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s %.2f A\n", timestamp, current);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Current sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read raw ADC value
        int raw_code = read_mcp3008(MCP3008_CHANNEL);
        if (raw_code < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Convert to voltage and current
        float voltage = (float)raw_code * VREF / 1023.0;
        float current = (voltage - 2.5) * (50.0 / 2.5);

        // Check for out-of-range voltage
        if (voltage < 0 || voltage > 5) {
            fprintf(stderr, "Warning: Voltage out of range: %.2f V\n", voltage);
        }

        // Log current
        log_current(current);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("Current sensor logging stopped.\n");

