    while (!terminate) {
        // Read raw ADC value
        int raw_code = read_mcp3008(MCP3008_CHANNEL);
        if (raw_code < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Convert to voltage and current
        float voltage = (float)raw_code * VREF / 1023.0;
        float current = (voltage - 2.5) * (50.0 / 2.5);

