#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to debounce the sensor readings
int debounce_sensor(int gpio_pin) {
    int count = 0;
    for (int i = 0; i < 5; i++) {
        int value = read_sensor(gpio_pin);
        if (value < 0) {
            return -1; // Indicate an error
        }
        if (value == 0) { // Assuming LOW indicates object present
            count++;
        }
        gpioDelay(2000); // 2 ms delay
    }
    return (count >= 3) ? 0 : 1; // Return 0 if majority of samples indicate object present
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = debounce_sensor(SENSOR1_GPIO);
        int sensor2_value = debounce_sensor(SENSOR2_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values. Exiting.\n");
            break;
        }

        // Log sensor states
        printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_value, sensor2_value);

        // Check for simultaneous object detection
        if (sensor1_value == 0 && sensor2_value == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

