#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pigpio.h>

// Configuration
#define PIR_GPIO 17
#define DEBOUNCE_DELAY_MS 200
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define ISO_8601_FORMAT "%Y%m%dT%H%M%SZ"
#define IMAGE_DIR "/home/pi/security_cam/"
#define LOG_FILE "/var/log/security_cam.log"

// Global variables
static volatile int running = 1;
static int pigpio_initialized = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int capture_image(const char *filename);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    pigpio_initialized = 1;

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    syslog(LOG_INFO, "GPIO initialized successfully");
    return 0;
}

// Read the PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_GPIO);
}

// Capture an image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width %d --height %d --iso 8601 --timeout 1000", filename, IMAGE_WIDTH, IMAGE_HEIGHT);

    syslog(LOG_INFO, "Executing libcamera-still: %s", command);

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        int status = execlp("sh", "sh", "-c", command, (char *)NULL);
        if (status == -1) {
            syslog(LOG_ERR, "execlp failed");
            exit(EXIT_FAILURE);
        }
    } else if (pid > 0) {
        // Parent process
        int wait_status;
        waitpid(pid, &wait_status, 0);

        if (WIFEXITED(wait_status)) {
            int exit_status = WEXITSTATUS(wait_status);
            if (exit_status == 0) {
                syslog(LOG_INFO, "Image captured successfully");
                return 0;
            } else {
                syslog(LOG_ERR, "libcamera-still exited with status %d", exit_status);
                return -1;
            }
        } else {
            syslog(LOG_ERR, "libcamera-still exited abnormally");
            return -1;
        }
    } else {
        syslog(LOG_ERR, "fork failed");
        return -1;
    }
}

// Log an event to syslog
int log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");

    if (pigpio_initialized) {
        gpioTerminate();
        syslog(LOG_INFO, "pigpio terminated");
    }

    closelog();
}

int main() {
    // Open syslog
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_event("System started");

    int last_state = 0; // 0 = no motion, 1 = motion

    // Main loop
    while (running) {
        int current_state = read_pir_sensor();

        if (current_state != last_state) {
            // Motion detected
            if (current_state == 1) {
                time_t rawtime;
                struct tm *timeinfo;
                char filename[256];

                time(&rawtime);
                timeinfo = localtime(&rawtime);

                strftime(filename, sizeof(filename), IMAGE_DIR "%Y%m%d_%H%M%S.jpg", timeinfo);

                if (capture_image(filename) == 0) {
                    char log_message[256];
                    snprintf(log_message, sizeof(log_message), "Motion detected, captured image: %s", filename);
                    log_event(log_message);
                } else {
                    log_event("Failed to capture image");
                }
            }

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // pigpioDelay takes microseconds
            last_state = current_state;
        }

        gpioDelay(50 * 1000); // Check every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

