int save_frame(const unsigned char *frame_data, int frame_number) {
    FILE *fp = fopen("image_0000.pgm", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
    fwrite(frame_data, 1, IMAGE_SIZE, fp);
    fclose(fp);

