    if (rename("image_0000.pgm", filename) != 0) {
        fprintf(stderr, "Error renaming file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to unmap the buffer
void unmap_buffer() {
    if (buffer != NULL) {
        munmap(buffer, buf.length);
        buffer = NULL;
    }
}

// Function to close the device
void close_device() {
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        }
        close(fd);
        fd = -1;
    }
}

int main(int argc, char *argv[]) {
    const char *device_name = DEVICE_NAME;

    // Parse command-line arguments
    if (argc > 1) {
        device_name = argv[1];
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the device
    if (init_device(device_name) < 0) {
        return 1;
    }

    int frame_number = 0;

    // Main loop
    while (!stop_flag) {
        unsigned char *frame_data;
        if (capture_frame(&frame_data) == 0) {
            if (save_frame(frame_data, frame_number) == 0) {
                frame_number++;
                printf("Captured frame %d\n", frame_number);
            } else {
                fprintf(stderr, "Failed to save frame %d\n", frame_number);
            }
        } else {
            fprintf(stderr, "Failed to capture frame\n");
        }
    }

    // Clean up resources
    unmap_buffer();
    close_device();

    return 0;
}

