        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            cleanup();
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        cleanup();
        return -1;
    }

    return 0;
}

// Capture a frame from the camera
frame_t capture_frame() {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("select() error");
        frame_t empty_frame = {NULL, 0};
        return empty_frame;
    } else if (r == 0) {
        fprintf(stderr, "select() timeout\n");
        frame_t empty_frame = {NULL, 0};
        return empty_frame;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        frame_t empty_frame = {NULL, 0};
        return empty_frame;
    }

    frame_t frame = {buffer, buffer_size};

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        frame_t empty_frame = {NULL, 0};
        return empty_frame;
    }

    return frame;
}

// Log the timestamp of the captured frame to a file
void log_timestamp(frame_t frame) {
    struct timespec ts;
