    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return -1;
    }

    buffer_count = req.count;

    for (i = 0; i < buffer_count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            cleanup();
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            cleanup();
            return -1;
        }
    }

    for (i = 0; i < buffer_count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            cleanup();
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        cleanup();
        return -1;
    }

    return 0;
}

// Initialize UDP socket
int init_udp_socket(const char *ip_address, int port) {
    int socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        perror("Error creating socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip_address, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(socket_fd);
        return -1;
    }

    return socket_fd;
}

// Capture a frame from the camera
int capture_frame(void **frame_data, size_t *frame_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    *frame_data = buffers[buf.index].start;
    *frame_size = buffers[buf.index].length;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Send a UDP packet
int send_udp_packet(int socket_fd, const void *data, size_t data_size) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        return -1;
    }

    ssize_t bytes_sent = sendto(socket_fd, data, data_size, 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
    if (bytes_sent < 0) {
        perror("Error sending data");
        return -1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("Error stopping stream");
        }

        for (int i = 0; i < buffer_count; ++i) {
            if (munmap(buffers[i].start, buffers[i].length) < 0) {
                perror("Error unmapping buffer");
            }
        }

        if (buffers) {
            free(buffers);
        }

        close(fd);
    }

    if (server_ip) {
        free(server_ip);
    }

    if (server_port) {
        close(server_port);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    server_ip = strdup(argv[1]);
    server_port = atoi(argv[2]);

    if (!server_ip || server_port <= 0) {
        fprintf(stderr, "Invalid server IP or port\n");
        cleanup();
        return 1;
    }

    if (init_v4l2() < 0) {
        fprintf(stderr, "V4L2 initialization failed\n");
        cleanup();
        return 1;
    }

    int socket_fd = init_udp_socket(server_ip, server_port);
    if (socket_fd < 0) {
        fprintf(stderr, "UDP socket initialization failed\n");
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    void *frame_data = NULL;
    size_t frame_size = 0;
    int frame_index = 0;
    int fragment_index = 0;
    int total_fragments = 0;
    int retries = 0;

    while (!stop_flag) {
        if (capture_frame(&frame_data, &frame_size) == 0) {
            total_fragments = frame_size / UDP_FRAGMENT_SIZE;
            if (frame_size % UDP_FRAGMENT_SIZE != 0) {
                total_fragments++;
            }

            for (int i = 0; i < total_fragments; ++i) {
                struct udp_header header;
                header.frame_index = frame_index;
                header.fragment_index = i;
                header.total_fragments = total_fragments;
                header.payload_size = (i == total_fragments - 1) ? (frame_size % UDP_FRAGMENT_SIZE) : UDP_FRAGMENT_SIZE;

                if (send_udp_packet(socket_fd, &header, sizeof(header)) < 0) {
                    fprintf(stderr, "Failed to send UDP header, retrying...\n");
                    retries = 0; // Reset retry count on failure
                    while (retries < MAX_RETRIES && !stop_flag) {
                        retries++;
                        usleep(10000); // Wait 10ms before retrying
                        if (send_udp_packet(socket_fd, &header, sizeof(header)) < 0) {
                            fprintf(stderr, "Failed to send UDP header after retry, continuing...\n");
                        } else {
                            break; // Exit retry loop on success
                        }
                    }
                    if (stop_flag) break; // Exit loop if signal received
                }

                if (send_udp_packet(socket_fd, frame_data + i * UDP_FRAGMENT_SIZE, header.payload_size) < 0) {
                    fprintf(stderr, "Failed to send UDP payload, retrying...\n");
                    retries = 0; // Reset retry count on failure
                    while (retries < MAX_RETRIES && !stop_flag) {
                        retries++;
                        usleep(10000); // Wait 10ms before retrying
                        if (send_udp_packet(socket_fd, frame_data + i * UDP_FRAGMENT_SIZE, header.payload_size) < 0) {
                            fprintf(stderr, "Failed to send UDP payload after retry, continuing...\n");
                        } else {
                            break; // Exit retry loop on success
                        }
                    }
                    if (stop_flag) break; // Exit loop if signal received
                }
            }

            frame_index++;
            fragment_index = 0; // Reset fragment index after sending all fragments for a frame
        } else {
            fprintf(stderr, "Failed to capture frame, retrying...\n");
            retries = 0; // Reset retry count on failure
            while (retries < MAX_RETRIES && !stop_flag) {
                retries++;
                usleep(10000); // Wait 10ms before retrying
                if (capture_frame(&frame_data, &frame_size) < 0) {
                    fprintf(stderr, "Failed to capture frame after retry, continuing...\n");
                } else {
                    break; // Exit retry loop on success
                }
            }
            if (stop_flag) break; // Exit loop if signal received
        }
    }

    cleanup();
    return 0;
}

