    };

    // Main loop
    while (!stop_flag) {
        // Read a frame
        if (read_frame(rgb_frame) < 0) {
            fprintf(stderr, "Error reading frame\n");
            break;
        }

        // Apply box blur filter
        rgb24_pixel_t blurred_pixel = apply_kernel(rgb_frame, WIDTH, HEIGHT, KERNEL_RADIUS, kernel);

        // Save the blurred image as JPEG
        char filename[256];
        time_t rawtime;
        struct tm *timeinfo;

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(filename, sizeof(filename), OUTPUT_FILENAME_FORMAT, timeinfo);

        if (save_jpeg(rgb_frame, WIDTH, HEIGHT, filename, QUALITY) < 0) {
            fprintf(stderr, "Error saving JPEG\n");
        }

        // Wait for 2 seconds
        struct timespec ts;
        ts.tv_sec = 2;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

