            perror("VIDIOC_QUERYCAP");
        }
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to enumerate frame sizes
int enumerate_frame_sizes(const char *device_name, struct v4l2_frmsizeenum *fsize) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        handle_error("Failed to open device");
    }

    fsize->index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, fsize) == 0) {
        printf("Frame size: %dx%d\n", fsize->frmsize.width, fsize->frmsize.height);
        fsize->index++;
    }

    if (errno != EINVAL) {
        perror("VIDIOC_ENUM_FRAMESIZES");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to enumerate frame intervals
int enumerate_frame_intervals(const char *device_name, struct v4l2_frmivalenum *finterval) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        handle_error("Failed to open device");
    }

    finterval->index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, finterval) == 0) {
        printf("Frame interval: %d/%d\n", finterval->frmival.numerator, finterval->frmival.denominator);
        finterval->index++;
    }

    if (errno != EINVAL) {
        perror("VIDIOC_ENUM_FRAMEINTERVALS");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to query autofocus support
int query_autofocus_support(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        handle_error("Failed to open device");
    }

    struct v4l2_control ctrl;
    ctrl.id = V4L2_CID_FOCUS_AUTO;
    ctrl.value = 0; // Initial value

    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        if (errno == EINVAL) {
            printf("Autofocus control is not supported\n");
        } else {
            perror("VIDIOC_QUERYCTRL");
        }
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum fsize;
    struct v4l2_frmivalenum finterval;

    // Query camera capabilities
    if (query_camera_capabilities(DEVICE_NAME, &cap) < 0) {
        return EXIT_FAILURE;
    }

    printf("Device name: %s\n", cap.card);
    printf("Driver: %s\n", cap.driver);
    printf("Version: %d.%d.%d\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("Capabilities: 0x%08X\n", cap.capabilities);

    // Enumerate frame sizes
    if (enumerate_frame_sizes(DEVICE_NAME, &fsize) < 0) {
        return EXIT_FAILURE;
    }

    // Enumerate frame intervals
    if (enumerate_frame_intervals(DEVICE_NAME, &finterval) < 0) {
        return EXIT_FAILURE;
    }

    // Query autofocus support
    if (query_autofocus_support(DEVICE_NAME) < 0) {
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

