#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define center position for servos (microseconds)
#define CENTER_POSITION 1500

// Define increment/decrement step (microseconds)
#define STEP_SIZE 10

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the pan servo position
void set_pan_servo_position(int position) {
    gpioServo(PAN_SERVO_PIN, position);
}

// Function to set the tilt servo position
void set_tilt_servo_position(int position) {
    gpioServo(TILT_SERVO_PIN, position);
}

// Function to increment the pan servo position
void increment_pan_servo_position() {
    int current_position = gpioGetServoPulsewidth(PAN_SERVO_PIN);
    if (current_position < 2000) {
        current_position += STEP_SIZE;
        if (current_position > 2000) {
            current_position = 2000;
        }
        set_pan_servo_position(current_position);
    }
}

// Function to decrement the pan servo position
void decrement_pan_servo_position() {
    int current_position = gpioGetServoPulsewidth(PAN_SERVO_PIN);
    if (current_position > 1000) {
        current_position -= STEP_SIZE;
        if (current_position < 1000) {
            current_position = 1000;
        }
        set_pan_servo_position(current_position);
    }
}

// Function to increment the tilt servo position
void increment_tilt_servo_position() {
    int current_position = gpioGetServoPulsewidth(TILT_SERVO_PIN);
    if (current_position < 2000) {
        current_position += STEP_SIZE;
        if (current_position > 2000) {
            current_position = 2000;
        }
        set_tilt_servo_position(current_position);
    }
}

// Function to decrement the tilt servo position
void decrement_tilt_servo_position() {
    int current_position = gpioGetServoPulsewidth(TILT_SERVO_PIN);
    if (current_position > 1000) {
        current_position -= STEP_SIZE;
        if (current_position < 1000) {
            current_position = 1000;
        }
        set_tilt_servo_position(current_position);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency for both servos
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set initial servo positions
    set_pan_servo_position(CENTER_POSITION);
    set_tilt_servo_position(CENTER_POSITION);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Camera pan-tilt system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for button presses
        if (gpioRead(UP_BUTTON_PIN) == 0) {
            increment_tilt_servo_position();
            gpioDelay(50000); // 50ms delay
        }
        if (gpioRead(DOWN_BUTTON_PIN) == 0) {
            decrement_tilt_servo_position();
            gpioDelay(50000); // 50ms delay
        }
        if (gpioRead(LEFT_BUTTON_PIN) == 0) {
            increment_pan_servo_position();
            gpioDelay(50000); // 50ms delay
        }
        if (gpioRead(RIGHT_BUTTON_PIN) == 0) {
            decrement_pan_servo_position();
            gpioDelay(50000); // 50ms delay
        }

        gpioDelay(10000); // 10ms delay
    }

    // Stop PWM on both servos
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

