#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <curl/curl.h>
#include <errno.h>

// Configuration
#define PIR_GPIO 17
#define DEBOUNCE_DELAY 2 // seconds
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 8080
#define CAPTURE_DIR "motion_captures"
#define CAPTURE_COMMAND "libcamera-still -o %s/motion_%Y%m%d_%H%M%S_%06ld.jpg --width 640 --height 480 --quality 85"
#define JSON_BUFFER_SIZE 256

// Global variables
static volatile int running = 1;
static int pir_state = 0; // 0 = no motion, 1 = motion
static time_t last_motion_time = 0;
static char json_payload[JSON_BUFFER_SIZE];
static int sockfd = -1;

// Structure to hold libcurl write callback data
typedef struct {
    char *memory;
    size_t size;
} MemoryStruct;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int read_pir_sensor();
int capture_image();
int format_json(time_t timestamp, int motion_status, int gpio_pin);
int send_http_request(const char *json_payload);
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_GPIO);
}

// Capture image using libcamera-still
int capture_image() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char filename[256];
    snprintf(filename, sizeof(filename), "%s/motion_%Y%m%d_%H%M%S_%06ld.jpg", CAPTURE_DIR, tstruct->tm_year + 1900, tstruct->tm_mon + 1, tstruct->tm_mday, tstruct->tm_hour, tstruct->tm_min, tstruct->tm_sec, now);

    char command[512];
    snprintf(command, sizeof(command), CAPTURE_COMMAND, CAPTURE_DIR, tstruct->tm_year + 1900, tstruct->tm_mon + 1, tstruct->tm_mday, tstruct->tm_hour, tstruct->tm_min, tstruct->tm_sec, now);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing libcamera-still: %s\n", strerror(errno));
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Format JSON payload
int format_json(time_t timestamp, int motion_status, int gpio_pin) {
    struct tm *tstruct = localtime(&timestamp);
    char timestamp_str[32];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", tstruct);

    snprintf(json_payload, JSON_BUFFER_SIZE, "{\"filename\": \"%s\", \"timestamp\": \"%s.%06ld\", \"motion_status\": %d, \"gpio_pin\": %d}",
             timestamp_str, timestamp_str, timestamp % 1000000, motion_status, gpio_pin);

    return 0;
}

// Send HTTP request using libcurl
int send_http_request(const char *json_payload) {
    CURL *curl;
    CURLcode res;
    MemoryStruct chunk;

    chunk.memory = malloc(1);
    chunk.size = 0;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://%s:%d/upload", SERVER_IP, SERVER_PORT);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code != 200) {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
            }
        }

        curl_easy_cleanup(curl);
        free(chunk.memory);
    }
    curl_global_cleanup();

    return (res == CURLE_OK) ? 0 : -1;
}

// libcurl write callback function
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if (ptr == NULL) {
        fprintf(stderr, "realloc() failed\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

// Cleanup resources before exiting
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (sockfd != -1) {
        close(sockfd);
    }
    gpioTerminate();
    curl_global_cleanup();
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    SERVER_IP = argv[1];
    SERVER_PORT = atoi(argv[2]);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Create capture directory if it doesn't exist
    if (mkdir(CAPTURE_DIR, 0777) == -1 && errno != EEXIST) {
        fprintf(stderr, "Error creating capture directory: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        cleanup();
        return 1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error connecting to server: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(stderr, "Connected to server: %s:%d\n", SERVER_IP, SERVER_PORT);

    // Main loop
    while (running) {
        int current_pir_state = read_pir_sensor();

        if (current_pir_state == 1 && pir_state == 0) {
            // Motion detected
            time_t now = time(NULL);
            if (difftime(now, last_motion_time) >= DEBOUNCE_DELAY) {
                fprintf(stderr, "Motion detected!\n");

                // Capture image
                if (capture_image() == 0) {
                    fprintf(stderr, "Image captured successfully.\n");

                    // Format JSON payload
                    format_json(now, 1, PIR_GPIO);
                    fprintf(stderr, "JSON payload: %s\n", json_payload);

                    // Send HTTP request
                    if (send_http_request(json_payload) == 0) {
                        fprintf(stderr, "HTTP request sent successfully.\n");
                    } else {
                        fprintf(stderr, "HTTP request failed.\n");
                    }
                } else {
                    fprintf(stderr, "Image capture failed.\n");
                }

                last_motion_time = now;
            }
        } else if (current_pir_state == 0 && pir_state == 1) {
            // No motion
            time_t now = time(NULL);
            if (difftime(now, last_motion_time) >= DEBOUNCE_DELAY) {
                fprintf(stderr, "No motion detected.\n");

                // Format JSON payload
                format_json(now, 0, PIR_GPIO);
                fprintf(stderr, "JSON payload: %s\n", json_payload);

                // Send HTTP request
                if (send_http_request(json_payload) == 0) {
                    fprintf(stderr, "HTTP request sent successfully.\n");
                } else {
                    fprintf(stderr, "HTTP request failed.\n");
                }

                last_motion_time = now;
            }
        }

        pir_state = current_pir_state;
        gpioDelay(100); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

