// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_MS 50
#define IMAGE_DIR "/home/pi/images/"
#define LOG_FILE "/home/pi/motion_capture.log"
#define SERVER_IP "192.168.1.100"
#define SERVER_PORT 5000
#define MAX_RETRIES 3

// Global variables
static volatile int running = 1;
static int socket_fd = -1;

// Function prototypes
int read_pir_sensor(int gpio_pin);
int capture_image(const char *filename);
int send_image_to_server(const char *filename);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the PIR sensor value with debouncing
int read_pir_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    gpioDelay(DEBOUNCE_MS * 1000); // Debounce in microseconds
    return value;
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", filename);
    int status = system(command);
    if (status == -1) {
        perror("system() failed");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

// Function to send the image to the server using UDP
int send_image_to_server(const char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        perror("Failed to open image file for sending");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        fclose(fp);
        return -1;
    }

    char buffer[4096];
    ssize_t bytes_read;
    int retries = 0;

    while ((bytes_read = fread(buffer, 1, sizeof(buffer), fp)) > 0 && retries < MAX_RETRIES) {
        ssize_t bytes_sent = sendto(socket_fd, buffer, bytes_read, 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
        if (bytes_sent < 0) {
            perror("sendto() failed");
            retries++;
            gpioDelay(100 * 1000); // Exponential backoff
        } else {
            break; // Success
        }
    }

    fclose(fp);
    if (bytes_read == 0) {
        fprintf(stderr, "Failed to send all data after %d retries\n", MAX_RETRIES);
        return -1;
    }

    return 0;
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Release GPIO resources
    gpioTerminate();

    // Close socket
    if (socket_fd != -1) {
        close(socket_fd);
    }

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

