    while (running) {
        if (read_pir_sensor(GPIO_PIN) == 1) {
            // Motion detected
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            char filename[256];
            snprintf(filename, sizeof(filename), "%s%d%02d%02d_%02d%02d%02d_mmm.jpg", IMAGE_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

            printf("Motion detected! Capturing image: %s\n", filename);
            log_event("Motion detected");

            if (capture_image(filename) == 0) {
                printf("Image captured successfully.\n");
                log_event("Image captured successfully");

                if (send_image_to_server(filename) == 0) {
                    printf("Image sent to server successfully.\n");
                    log_event("Image sent to server successfully");
                } else {
                    fprintf(stderr, "Failed to send image to server.\n");
                    log_event("Failed to send image to server");
                }
            } else {
                fprintf(stderr, "Failed to capture image.\n");
                log_event("Failed to capture image");
            }

            gpioDelay(1000 * 1000); // Debounce delay
        }
        gpioDelay(100 * 1000); // Check every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    close(socket_fd);

    return 0;
}

