#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FORMAT V4L2_PIX_FMT_YUYV
#define FIELD V4L2_FIELD_NONE
#define BUFFER_COUNT 1
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define FRAME_SIZE (WIDTH * HEIGHT * 2)

static int fd = -1;
static struct v4l2_buffer buf;
static struct v4l2_format fmt;
static struct v4l2_requestbuffers req;
static unsigned char *buffer = NULL;
static volatile sig_atomic_t stop_flag = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping...\n");
    stop_flag = 1;
}

// Function to initialize the V4L2 device
int init_device() {
    struct v4l2_capability cap;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = FORMAT;
    fmt.fmt.pix.field = FIELD;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return -1;
    }

    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return -1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(buffer, buf.length);
        close(fd);
        return -1;
    }

    return 0;
}

// Function to capture a single frame
int capture_frame() {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout occurred\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to crop the YUYV frame
int crop_frame(unsigned char *yuyv_frame, unsigned char *cropped_frame, int width, int height) {
    int i, j;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            // Copy YUYV macroblock (Y0, U, Y1, V)
            cropped_frame[i * width * 2 + j * 2] = yuyv_frame[i * width * 2 + j * 2];
            cropped_frame[i * width * 2 + j * 2 + 1] = yuyv_frame[i * width * 2 + j * 2 + 1];
        }
    }

    return 0;
}

// Function to save the cropped frame to a file
int save_frame(unsigned char *cropped_frame, int width, int height, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(cropped_frame, 1, width * height * 2, fp);
    if (bytes_written != width * height * 2) {
        fprintf(stderr, "Error writing to file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to uninitialize the V4L2 device
void uninit_device() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
    }

    if (munmap(buffer, buf.length) < 0) {
        perror("Error unmapping buffer");
    }

    close(fd);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_device() < 0) {
        fprintf(stderr, "Device initialization failed\n");
        return EXIT_FAILURE;
    }

    unsigned char *yuyv_frame = buffer;
    unsigned char *cropped_frame = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (cropped_frame == NULL) {
        perror("Error allocating memory for cropped frame");
        uninit_device();
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        if (capture_frame() < 0) {
            fprintf(stderr, "Frame capture failed\n");
            break;
        }

        if (crop_frame(yuyv_frame, cropped_frame, WIDTH, HEIGHT) < 0) {
            fprintf(stderr, "Frame cropping failed\n");
            break;
        }

        if (save_frame(cropped_frame, CROP_WIDTH, CROP_HEIGHT, "cropped.yuv") < 0) {
            fprintf(stderr, "Frame saving failed\n");
            break;
        }

        printf("Frame saved as cropped.yuv\n");
    }

    free(cropped_frame);
    uninit_device();

    return EXIT_SUCCESS;
}

