#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define neutral position angles (90 degrees)
#define PAN_NEUTRAL 90
#define TILT_NEUTRAL 90

// Define increment and decrement steps (5 degrees)
#define PAN_INCREMENT 5
#define TILT_INCREMENT 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the pan angle
int set_pan_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Pan angle out of range (0-180): %d\n", angle);
        return -1; // Indicate error
    }

    // Calculate pulse width (500-2500 us)
    int pulse_width = 500 + (int)((float)angle / 180.0 * 2000.0);

    // Set PWM duty cycle for pan servo
    gpioPWM(PAN_GPIO, pulse_width);

    return 0; // Indicate success
}

// Function to set the tilt angle
int set_tilt_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Tilt angle out of range (0-180): %d\n", angle);
        return -1; // Indicate error
    }

    // Calculate pulse width (500-2500 us)
    int pulse_width = 500 + (int)((float)angle / 180.0 * 2000.0);

    // Set PWM duty cycle for tilt servo
    gpioPWM(TILT_GPIO, pulse_width);

    return 0; // Indicate success
}

// Function to move the camera in a specific direction
int move_camera(int pan_increment, int tilt_increment) {
    int current_pan_angle = PAN_NEUTRAL;
    int current_tilt_angle = TILT_NEUTRAL;

    // Move pan
    current_pan_angle += pan_increment;
    if (set_pan_angle(current_pan_angle) != 0) {
        fprintf(stderr, "Error setting pan angle.\n");
        return -1;
    }
    gpioDelay(100); // Delay for 100ms

    // Move tilt
    current_tilt_angle += tilt_increment;
    if (set_tilt_angle(current_tilt_angle) != 0) {
        fprintf(stderr, "Error setting tilt angle.\n");
        return -1;
    }
    gpioDelay(100); // Delay for 100ms

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with error code
    }

    // Set GPIO modes for pan and tilt servos
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency for pan and tilt servos
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    // Set PWM range for pan and tilt servos
    gpioSetPWMrange(PAN_GPIO, PWM_RANGE);
    gpioSetPWMrange(TILT_GPIO, PWM_RANGE);

    // Set initial pan and tilt angles
    if (set_pan_angle(PAN_NEUTRAL) != 0 || set_tilt_angle(TILT_NEUTRAL) != 0) {
        fprintf(stderr, "Error setting initial pan and tilt angles.\n");
        gpioTerminate(); // Terminate pigpio
        return 1; // Exit with error code
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    char input;
    while (program_running) {
        printf("Enter a direction (u, d, l, r, q): ");
        input = getchar();

        // Clear the input buffer
        while (getchar() != '\n');

        switch (input) {
            case 'u': // Move up
                if (move_camera(0, TILT_INCREMENT) != 0) {
                    fprintf(stderr, "Error moving camera up.\n");
                }
                break;
            case 'd': // Move down
                if (move_camera(0, -TILT_INCREMENT) != 0) {
                    fprintf(stderr, "Error moving camera down.\n");
                }
                break;
            case 'l': // Move left
                if (move_camera(-PAN_INCREMENT, 0) != 0) {
                    fprintf(stderr, "Error moving camera left.\n");
                }
                break;
            case 'r': // Move right
                if (move_camera(PAN_INCREMENT, 0) != 0) {
                    fprintf(stderr, "Error moving camera right.\n");
                }
                break;
            case 'q': // Quit
                printf("Exiting...\n");
                break;
            default:
                printf("Invalid input. Please enter a valid direction.\n");
                break;
        }
    }

    // Set both servos to the neutral position before exiting
    set_pan_angle(PAN_NEUTRAL);
    set_tilt_angle(TILT_NEUTRAL);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

