int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SSD1306
    if (init_ssd1306() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU usage
        FILE *fp = fopen("/proc/stat", "r");
        if (fp == NULL) {
            fprintf(stderr, "Error opening /proc/stat\n");
            display_text(0, 0, "ERROR");
            display_text(0, 8, "CPU");
            display_text(0, 16, "USAGE");
            display_text(0, 24, "ERROR");
            display_text(0, 32, "TEMP");
            display_text(0, 40, "ERROR");
            display_text(0, 48, "ERROR");
            display_text(0, 56, "ERROR");
        } else {
            int user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
            if (fscanf(fp, "cpu  %d %d %d %d %d %d %d %d %d %d", &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
                fprintf(stderr, "Error reading /proc/stat\n");
                display_text(0, 0, "ERROR");
                display_text(0, 8, "CPU");
                display_text(0, 16, "USAGE");
                display_text(0, 24, "ERROR");
                display_text(0, 32, "TEMP");
                display_text(0, 40, "ERROR");
                display_text(0, 48, "ERROR");
                display_text(0, 56, "ERROR");
            } else {
                float total_idle = idle + iowait;
                float total_non_idle = user + nice + system + irq + softirq + steal;
                float total_cpu = total_idle + total_non_idle;
                float cpu_usage = 100.0 - ((total_idle / total_cpu) * 100.0);

                // Read temperature
                FILE *fp_temp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
                if (fp_temp == NULL) {
                    fprintf(stderr, "Error opening /sys/class/thermal/thermal_zone0/temp\n");
                    display_text(0, 0, "ERROR");
                    display_text(0, 8, "CPU");
                    display_text(0, 16, "USAGE");
                    display_text(0, 24, "TEMP");
                    display_text(0, 32, "ERROR");
                    display_text(0, 40, "ERROR");
                    display_text(0, 48, "ERROR");
                    display_text(0, 56, "ERROR");
                } else {
                    int temp_milli_celsius;
                    if (fscanf(fp_temp, "%d", &temp_milli_celsius) != 1) {
                        fprintf(stderr, "Error reading /sys/class/thermal/thermal_zone0/temp\n");
                        display_text(0, 0, "ERROR");
                        display_text(0, 8, "CPU");
                        display_text(0, 16, "USAGE");
                        display_text(0, 24, "TEMP");
                        display_text(0, 32, "ERROR");
                        display_text(0, 40, "ERROR");
                        display_text(0, 48, "ERROR");
                        display_text(0, 56, "ERROR");
                    } else {
                        float temperature = (float)temp_milli_celsius / 1000.0;

                        // Display data
                        display_cpu_usage(0, 0, cpu_usage);
                        display_temperature(0, 32, temperature);
                        display_text(0, 0, "CPU");
                        display_text(0, 8, "USAGE");
                        display_text(0, 16, "TEMP");
                    }
                    fclose(fp_temp);
                }
            }
            fclose(fp);
        }

        // Update display
