#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17
#define LCD_I2C_ADDR 0x27

// Define LCD dimensions
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Define pulse counting variables
volatile int pulse_count = 0;
volatile int last_tick = 0;

// Define calibration factor (pulses per liter)
#define CALIBRATION_FACTOR 450.0

// Define LCD I2C handle
int lcd_handle;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
double calculate_flow_rate(int pulse_count);
void display_flow_rate(double flow_rate);
void display_volume(double volume);
void signal_handler(int signal);

// Structure to hold LCD configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int lcd_width;
    int lcd_height;
} lcd_config_t;

// Function to initialize the LCD
int lcd_init(lcd_config_t config) {
    lcd_handle = i2cOpen(config.i2c_bus, config.i2c_address, 0);
    if (lcd_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", lcd_handle);
        return -1;
    }

    // Initialize LCD (4-bit mode)
    i2cWriteByteData(lcd_handle, 0x00, 0x33); // Initialize
    i2cWriteByteData(lcd_handle, 0x00, 0x32); // Initialize
    i2cWriteByteData(lcd_handle, 0x00, 0x28); // 4-bit mode, 2 lines, 5x8 font
    i2cWriteByteData(lcd_handle, 0x00, 0x0C); // Display on, cursor off, blink off
    i2cWriteByteData(lcd_handle, 0x00, 0x06); // Increment cursor, no shift
    i2cWriteByteData(lcd_handle, 0x00, 0x01); // Clear display
    gpioDelay(2); // Delay for clear display to complete

    return 0;
}

// Function to display text on the LCD
void lcd_display_text(int row, int col, const char *text) {
    if (row == 0) {
        i2cWriteByteData(lcd_handle, 0x00, 0x80 + col); // Set cursor position for first line
    } else {
        i2cWriteByteData(lcd_handle, 0x00, 0xC0 + col); // Set cursor position for second line
    }

    for (int i = 0; text[i] != '\0'; i++) {
        i2cWriteByteData(lcd_handle, 0x40, text[i]); // Send character to LCD
    }
}

// Function to clear the LCD
void lcd_clear() {
    i2cWriteByteData(lcd_handle, 0x00, 0x01); // Clear display
    gpioDelay(2); // Delay for clear display to complete
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    // Set up interrupt callback for rising edge detection
    gpioSetAlertFuncEx(FLOW_SENSOR_PIN, pulse_callback, NULL);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    lcd_config_t lcd_config = {
        .i2c_bus = 1,
        .i2c_address = LCD_I2C_ADDR,
        .lcd_width = LCD_WIDTH,
        .lcd_height = LCD_HEIGHT
    };

    // Initialize LCD
    if (lcd_init(lcd_config) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Calculate flow rate
        double flow_rate = calculate_flow_rate(pulse_count);

        // Display flow rate on LCD
        char flow_rate_str[20];
        snprintf(flow_rate_str, sizeof(flow_rate_str), "Flow Rate: %.2f LPM", flow_rate);
        lcd_display_text(0, 0, flow_rate_str);

        // Display volume on LCD
        double volume = (double)pulse_count / CALIBRATION_FACTOR;
        char volume_str[20];
        snprintf(volume_str, sizeof(volume_str), "Volume: %.2f L", volume);
        lcd_display_text(1, 0, volume_str);

        // Wait for 1 second
        gpioDelay(1000);

        // Reset pulse count
        pulse_count = 0;
    }

    return 0;
}

// Callback function for pulse detection
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge detected
        int current_tick = tick;
        int pulse_duration = current_tick - last_tick;
        last_tick = current_tick;

        // Debounce: Check if the pulse duration is within a reasonable range
        if (pulse_duration > 0 && pulse_duration < 1000) { // 1ms debounce
            pulse_count++;
        }
    }
}

// Function to calculate flow rate
double calculate_flow_rate(int pulse_count) {
    return (double)pulse_count / CALIBRATION_FACTOR * 60.0;
}

// Function to display flow rate on LCD
void display_flow_rate(double flow_rate) {
    char flow_rate_str[20];
    snprintf(flow_rate_str, sizeof(flow_rate_str), "Flow Rate: %.2f LPM", flow_rate);
    lcd_display_text(0, 0, flow_rate_str);
}

// Function to display volume on LCD
void display_volume(double volume) {
    char volume_str[20];
    snprintf(volume_str, sizeof(volume_str), "Volume: %.2f L", volume);
    lcd_display_text(1, 0, volume_str);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable interrupt callback
    gpioSetAlertFuncEx(FLOW_SENSOR_PIN, NULL, NULL);

    // Close I2C connection
    i2cClose(lcd_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

