    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);

    lcd_clear();
    lcd_send_command(0x80); // Set cursor to first line
    lcd_send_data(buffer[0]);
    lcd_send_data(buffer[1]);
    lcd_send_data(buffer[2]);
    lcd_send_data(buffer[3]);
    lcd_send_data(buffer[4]);
    lcd_send_data(buffer[5]);
    lcd_send_data(buffer[6]);
    lcd_send_data(buffer[7]);
    lcd_send_data(buffer[8]);
    lcd_send_data(buffer[9]);
    lcd_send_data(buffer[10]);
    lcd_send_data(buffer[11]);
    lcd_send_data(buffer[12]);
    lcd_send_data(buffer[13]);
    lcd_send_data(buffer[14]);
    lcd_send_data(buffer[15]);
}

// LCD initialization function
void lcd_init() {
    gpioDelay(5000); // Wait for LCD to power up
    lcd_send_command(0x33); // Initialize
    lcd_send_command(0x32); // Initialize
    lcd_send_command(0x06); // Increment cursor
    lcd_send_command(0x0C); // Display on, cursor off, blink off
    lcd_send_command(0x28); // 4-bit mode, 2 lines, 5x8 font
    lcd_clear();
}

// LCD send command function
void lcd_send_command(unsigned char command) {
    unsigned char data_u, data_l;
    data_u = command & 0xF0;
    data_l = (command << 4) & 0xF0;

    gpioWrite(LCD_RS, 0); // RS = 0 for command
    gpioWrite(LCD_EN, 1); // Enable high
    gpioWrite(LCD_D4, (data_u >> 4) & 0x01);
    gpioWrite(LCD_D5, (data_u >> 5) & 0x01);
    gpioWrite(LCD_D6, (data_u >> 6) & 0x01);
    gpioWrite(LCD_D7, (data_u >> 7) & 0x01);
    gpioDelay(1); // Delay for command execution
    gpioWrite(LCD_EN, 0); // Enable low

    gpioWrite(LCD_EN, 1); // Enable high
    gpioWrite(LCD_D4, data_l & 0x01);
    gpioWrite(LCD_D5, (data_l >> 1) & 0x01);
    gpioWrite(LCD_D6, (data_l >> 2) & 0x01);
    gpioWrite(LCD_D7, (data_l >> 3) & 0x01);
    gpioDelay(1); // Delay for command execution
    gpioWrite(LCD_EN, 0); // Enable low
}

// LCD send data function
void lcd_send_data(unsigned char data) {
    unsigned char data_u, data_l;
    data_u = data & 0xF0;
    data_l = (data << 4) & 0xF0;

    gpioWrite(LCD_RS, 1); // RS = 1 for data
    gpioWrite(LCD_EN, 1); // Enable high
    gpioWrite(LCD_D4, (data_u >> 4) & 0x01);
    gpioWrite(LCD_D5, (data_u >> 5) & 0x01);
    gpioWrite(LCD_D6, (data_u >> 6) & 0x01);
    gpioWrite(LCD_D7, (data_u >> 7) & 0x01);
    gpioDelay(1); // Delay for data execution
    gpioWrite(LCD_EN, 0); // Enable low

    gpioWrite(LCD_EN, 1); // Enable high
    gpioWrite(LCD_D4, data_l & 0x01);
    gpioWrite(LCD_D5, (data_l >> 1) & 0x01);
    gpioWrite(LCD_D6, (data_l >> 2) & 0x01);
    gpioWrite(LCD_D7, (data_l >> 3) & 0x01);
    gpioDelay(1); // Delay for data execution
    gpioWrite(LCD_EN, 0); // Enable low
}

// LCD clear function
void lcd_clear() {
    lcd_send_command(0x01); // Clear display
    gpioDelay(2); // Delay for clear command execution
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-up/down resistor (optional, depending on sensor)
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set alert function for rising edge detection
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_handle = i2cOpen(1, LCD_I2C_ADDR, 0); // Bus 1, address 0x27, no flags
    if (lcd_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", lcd_handle);
        gpioTerminate();
        return 1;
    }
    lcd_init();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pulse_count, PULSES_PER_LITER);

        // Display flow rate
        display_flow_rate(flow_rate);

        // Reset pulse count
        pulse_count = 0;

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable alert function
    i2cClose(lcd_handle); // Close I2C device
    gpioTerminate(); // Terminate pigpio

    printf("Water flow monitoring stopped.\n");

    return 0;
}

