#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for rows and columns
const int rowPins[] = {17, 18, 27, 22, 23, 24, 25, 4};
const int colPins[] = {5, 6, 12, 13, 19, 16, 26, 20};
const int numRows = 8;
const int numCols = 8;

// Global variable to track program termination
volatile sig_atomic_t programRunning = 1;

// Signal handler for SIGINT (Ctrl+C)
void signalHandler(int signum) {
    programRunning = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to initialize GPIO pins
int initializeGPIO() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set row pins as outputs
    for (int i = 0; i < numRows; i++) {
        gpioSetMode(rowPins[i], PI_OUTPUT);
        gpioWrite(rowPins[i], 1); // Set row pins HIGH initially
    }

    // Set column pins as outputs
    for (int i = 0; i < numCols; i++) {
        gpioSetMode(colPins[i], PI_OUTPUT);
        gpioWrite(colPins[i], 1); // Set column pins HIGH initially
    }

    return 0;
}

// Function to light an LED (common-anode)
void lightLED(int row, int col) {
    gpioWrite(rowPins[row], 0); // Turn on the row (LOW)
    gpioWrite(colPins[col], 0); // Turn on the column (LOW)
}

// Function to clear an LED (common-anode)
void clearLED(int row, int col) {
    gpioWrite(rowPins[row], 1); // Turn off the row (HIGH)
    gpioWrite(colPins[col], 1); // Turn off the column (HIGH)
}

// Function to scan the display (left-to-right)
void scanDisplayLeftToRight() {
    for (int row = 0; row < numRows; row++) {
        for (int col = 0; col < numCols; col++) {
            lightLED(row, col);
            gpioDelay(800); // Delay for 800 microseconds
            clearLED(row, col);
        }
    }
}

// Function to scan the display (right-to-left)
void scanDisplayRightToLeft() {
    for (int row = 0; row < numRows; row++) {
        for (int col = numCols - 1; col >= 0; col--) {
            lightLED(row, col);
            gpioDelay(800); // Delay for 800 microseconds
            clearLED(row, col);
        }
    }
}

// Function to cleanup GPIO pins
void cleanupGPIO() {
    // Turn off all LEDs
    for (int row = 0; row < numRows; row++) {
        for (int col = 0; col < numCols; col++) {
            clearLED(row, col);
        }
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signalHandler);

    // Initialize GPIO
    if (initializeGPIO() != 0) {
        return 1;
    }

    fprintf(stderr, "Scan display animation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (programRunning) {
        scanDisplayLeftToRight();
        scanDisplayRightToLeft();
    }

    // Cleanup GPIO before exiting
    cleanupGPIO();

    return 0;
}

