void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set row pins as outputs
    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpioSetMode(ROW_PINS[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set row pin %d as output\n", ROW_PINS[i]);
            gpioTerminate();
            return -1;
        }
    }

    // Set column pins as outputs
    for (int i = 0; i < NUM_COLS; i++) {
        if (gpioSetMode(COL_PINS[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set column pin %d as output\n", COL_PINS[i]);
            gpioTerminate();
            return -1;
        }
        gpioWrite(COL_PINS[i], 1); // Ensure column cathodes are initially HIGH
    }

    return 0;
}

