    // Set all row pins LOW
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioWrite(ROW_PINS[i], 0);
    }

    // Set the corresponding column cathode LOW
    gpioWrite(COL_PINS[column], 0);

    // Delay for 150 ms
    gpioDelay(150000); // 150 ms = 150000 microseconds

    // Clear the column cathode
    gpioWrite(COL_PINS[column], 1);

    // Set all row pins HIGH
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioWrite(ROW_PINS[i], 1);
    }
}

