#define VL53L3CX_REG_RANGING_MEASUREMENT_DATA 0x0014
#define VL53L3CX_REG_START_STOP_CONTROL 0x0000

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    int i2c_address;
    int i2c_bus;
} sensor_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the VL53L3CX sensor
int init_vl53l3cx(int i2c_handle) {
    // Example initialization sequence (Refer to VL53L3CX datasheet for complete sequence)
    // This is a placeholder - replace with actual initialization commands
    // based on the VL53L3CX datasheet.
    char init_data[] = {0x00, 0x01}; // Example initialization data
    int result = i2cWriteDevice(i2c_handle, init_data, sizeof(init_data));
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L3CX: %d\n", result);
        return -1;
    }

    // Verify sensor model ID (Example - Replace with actual verification)
    char model_id_reg = VL53L3CX_REG_IDENTIFICATION_MODEL_ID;
    char model_id_data[2];
    result = i2cWriteDevice(i2c_handle, &model_id_reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L3CX model ID register: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, model_id_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L3CX model ID register: %d\n", result);
        return -1;
    }

    uint16_t model_id = (model_id_data[0] << 8) | model_id_data[1];
    printf("VL53L3CX Model ID: 0x%04X\n", model_id);

    // Start continuous ranging (Example - Replace with actual start command)
    char start_ranging_cmd = VL53L3CX_REG_START_STOP_CONTROL;
    char start_ranging_data[] = {0x01}; // Start ranging
    result = i2cWriteDevice(i2c_handle, &start_ranging_cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L3CX start ranging register: %d\n", result);
        return -1;
    }
    result = i2cWriteDevice(i2c_handle, start_ranging_data, sizeof(start_ranging_data));
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L3CX start ranging data: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read distance measurements from the VL53L3CX sensor
int read_distance(int i2c_handle, uint16_t *distance) {
    char range_data_reg = VL53L3CX_REG_RANGING_MEASUREMENT_DATA;
    char range_data[2];
    int result = i2cWriteDevice(i2c_handle, &range_data_reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L3CX range data register: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, range_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L3CX range data register: %d\n", result);
        return -1;
    }

    *distance = (range_data[0] << 8) | range_data[1];
    return 0;
}

// Function to get the current timestamp in ISO 8601 format
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time
    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L3CX sensor
    if (init_vl53l3cx(i2c_handle) != 0) {
        fprintf(stderr, "VL53L3CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            char timestamp[30];
            get_timestamp(timestamp);
            printf("%s Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

