#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75031_ADDR 0x4C

// Define the register address for the distance data
#define DISTANCE_REG 0x0D

// Define the log file name
#define LOG_FILE "depth_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_distance(int *distance);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the I2C interface
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read the distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading distance: %d\n", bytes_read);
        return -1;
    }

    // Convert the two bytes to a 16-bit integer (big-endian)
    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to log the data to a CSV file
int log_data(sensor_data_t data) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&data.timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp_str, data.distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize the I2C interface
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        int distance;
        sensor_data_t data;

        // Read the distance from the sensor
        if (read_distance(&distance) == 0) {
            // Get the current timestamp
            data.timestamp = time(NULL);
            data.distance = distance;

            // Log the data
            if (log_data(data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            // Log an error row
            data.timestamp = time(NULL);
            data.distance = -1; // Indicate an error
            if (log_data(data) != 0) {
                fprintf(stderr, "Error logging error data\n");
            }
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

