#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0 0x24
#define REG_COMMAND 0x18

// Command register values
#define CMD_RESET 0x01
#define CMD_ALS_FORCE 0x06
#define CMD_PS1_FORCE 0x07

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *ambient_light, int *proximity);
void log_data(int ambient_light, int proximity);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int als_rate;
    int ps1_rate;
} sensor_config_t;

// Global configuration
sensor_config_t config = {10, 10}; // Default values

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int ambient_light, proximity;
    while (1) {
        // Read sensor data
        if (read_sensor_data(&ambient_light, &proximity) == 0) {
            // Log the data
            log_data(ambient_light, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            // Log the error
            log_data(-1, -1); // Indicate error
        }

        // Wait 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    return 0;
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    // Check Part ID
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART ID: %d\n", part_id);
        return 1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        return 1;
    }

    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        return 1;
    }
    gpioDelay(10000); // Wait for reset to complete (10ms)

    // Configure ALS and PS1 rates
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_ALS_FORCE) < 0) {
        fprintf(stderr, "Failed to set ALS force mode\n");
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_PS1_FORCE) < 0) {
        fprintf(stderr, "Failed to set PS1 force mode\n");
        return 1;
    }

    // Set ALS and PS1 rates
    if (i2cWriteByteData(i2c_handle, 0x08, config.als_rate) < 0) {
        fprintf(stderr, "Failed to set ALS rate\n");
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, 0x09, config.ps1_rate) < 0) {
        fprintf(stderr, "Failed to set PS1 rate\n");
        return 1;
    }

    return 0;
}

// Function to read ambient light and proximity data from the sensor
int read_sensor_data(int *ambient_light, int *proximity) {
    int als_low, als_high, ps1_low, ps1_high;

    // Read ALS data
    als_low = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
    als_high = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0 + 1);
    if (als_low < 0 || als_high < 0) {
        fprintf(stderr, "Failed to read ALS data\n");
        return 1;
    }
    *ambient_light = (als_high << 8) | als_low;

    // Read PS1 data
    ps1_low = i2cReadByteData(i2c_handle, REG_PS1_DATA0);
    ps1_high = i2cReadByteData(i2c_handle, REG_PS1_DATA0 + 1);
    if (ps1_low < 0 || ps1_high < 0) {
        fprintf(stderr, "Failed to read PS1 data\n");
        return 1;
    }
    *proximity = (ps1_high << 8) | ps1_low;

    return 0;
}

// Function to log data to a file
void log_data(int ambient_light, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Write data to log file
    fprintf(log_file, "%s, Ambient Light: %d, Proximity: %d\n", timestamp, ambient_light, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Cleaning up...\n");

    // Close I2C connection
    i2cClose(i2c_handle);

    // Flush and close log file
    fflush(log_file);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

