#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define REG_PART_ID 0x00
#define REG_HW_KEY 0x07
#define REG_CHLIST 0x4F
#define REG_MEASRATE0 0x08
#define REG_MEASRATE1 0x09
#define REG_COMMAND 0x30
#define REG_PS1_DATA0 0x18
#define REG_PS1_DATA1 0x19
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int si1145_init();
int read_register(int handle, uint8_t reg, uint8_t *value);
int write_register(int handle, uint8_t reg, uint8_t value);
int read_proximity(int handle);
int read_ambient_light(int handle);
char* get_iso8601_timestamp();
void log_data(const char *timestamp, int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize the Si1145 sensor
int si1145_init() {
    uint8_t part_id;

    // Check Part ID
    if (read_register(i2c_handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error reading PART_ID register\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Write HW_KEY
    if (write_register(i2c_handle, REG_HW_KEY, 0x17) != 0) {
        fprintf(stderr, "Error writing HW_KEY register\n");
        return -1;
    }

    // Enable PS1 and ALS_VIS channels
    if (write_register(i2c_handle, REG_CHLIST, 0x03) != 0) {
        fprintf(stderr, "Error writing CHLIST register\n");
        return -1;
    }

    // Configure measurement rates (example values)
    if (write_register(i2c_handle, REG_MEASRATE0, 0x0A) != 0) {
        fprintf(stderr, "Error writing MEASRATE0 register\n");
        return -1;
    }
    if (write_register(i2c_handle, REG_MEASRATE1, 0x00) != 0) {
        fprintf(stderr, "Error writing MEASRATE1 register\n");
        return -1;
    }

    return 0;
}

// Read a single byte from a register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Write a single byte to a register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read proximity data from the sensor
int read_proximity(int handle) {
    uint8_t data0, data1;

    if (read_register(handle, REG_PS1_DATA0, &data0) != 0) {
        return -1;
    }
    if (read_register(handle, REG_PS1_DATA1, &data1) != 0) {
        return -1;
    }

    return (data1 << 8) | data0;
}

// Read ambient light data from the sensor
int read_ambient_light(int handle) {
    uint8_t data0, data1;

    if (read_register(handle, REG_ALS_VIS_DATA0, &data0) != 0) {
        return -1;
    }
    if (read_register(handle, REG_ALS_VIS_DATA1, &data1) != 0) {
        return -1;
    }

    return (data1 << 8) | data0;
}

// Get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[20]; //YYYY-MM-DDTHH:MM:SSZ\0

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

// Log data to a CSV file
void log_data(const char *timestamp, int proximity, int ambient_light) {
    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1145 sensor
    if (si1145_init() != 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Proximity,Ambient Light\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        int proximity = read_proximity(i2c_handle);
        int ambient_light = read_ambient_light(i2c_handle);

        if (proximity >= 0 && ambient_light >= 0) {
            // Get timestamp
            char *timestamp = get_iso8601_timestamp();

            // Log the data
            log_data(timestamp, proximity, ambient_light);

            printf("Timestamp: %s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

