#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// APDS9960 I2C address
#define APDS9960_I2C_ADDR 0x39

// APDS9960 register addresses
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATAL 0x9C
#define APDS9960_PDATAH 0x9D

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int apds9960_init();
int apds9960_read_raw_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity);
int apds9960_read_proximity();
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the APDS9960 sensor
int apds9960_init() {
    // Check sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, APDS9960_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0xAB) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Enable all sensors (PON, AEN, ALSEN)
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Set ATIME (ATIME = 100ms)
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Set WTIME (WTIME = 2.4ms)
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6) < 0) {
        fprintf(stderr, "Error writing to WTIME register\n");
        return -1;
    }

    // Set PPULSE (PPULSE = 4 pulses)
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) {
        fprintf(stderr, "Error writing to PPULSE register\n");
        return -1;
    }

    // Set CONTROL (GAIN = 1x, GTIME = 2.4ms)
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error writing to CONTROL register\n");
        return -1;
    }

    // Set CONFIG2 (CONFIG2 = Gain = 1x)
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG2 register\n");
        return -1;
    }

    return 0;
}

// Read raw RGBC data from the APDS9960 sensor
int apds9960_read_raw_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    int cdatal, cdatah, rdatal, rdatah, gdatal, gdatah, bdatal, bdatah, pdatal, pdatah;

    cdatal = i2cReadByteData(i2c_handle, APDS9960_CDATAL);
    cdatah = i2cReadByteData(i2c_handle, APDS9960_CDATAH);
    rdatal = i2cReadByteData(i2c_handle, APDS9960_RDATAL);
    rdatah = i2cReadByteData(i2c_handle, APDS9960_RDATAH);
    gdatal = i2cReadByteData(i2c_handle, APDS9960_GDATAL);
    gdatah = i2cReadByteData(i2c_handle, APDS9960_GDATAH);
    bdatal = i2cReadByteData(i2c_handle, APDS9960_BDATAL);
    bdatah = i2cReadByteData(i2c_handle, APDS9960_BDATAH);
    pdatal = i2cReadByteData(i2c_handle, APDS9960_PDATAL);
    pdatah = i2cReadByteData(i2c_handle, APDS9960_PDATAH);

    if (cdatal < 0 || cdatah < 0 || rdatal < 0 || rdatah < 0 || gdatal < 0 || gdatah < 0 || bdatal < 0 || bdatah < 0 || pdatal < 0 || pdatah < 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *red = (uint16_t)((rdatah << 8) | rdatal);
    *green = (uint16_t)((gdatah << 8) | gdatal);
    *blue = (uint16_t)((bdatah << 8) | bdatal);
    *proximity = (uint8_t)pdatah;

    return 0;
}

// Read the proximity value from the APDS9960 sensor
int apds9960_read_proximity() {
    int proximity = i2cReadByteData(i2c_handle, APDS9960_PDATAH);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }
    return proximity;
}

// Log data to a CSV file
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize APDS9960 sensor
    if (apds9960_init() < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, green, blue;
    uint8_t proximity;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (apds9960_read_raw_data(&red, &green, &blue, &proximity) == 0) {
            // Log data if proximity exceeds threshold
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, re-initializing...\n");
            // Attempt to re-initialize the sensor
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait 1 second before re-opening
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (apds9960_init() < 0) {
                    fprintf(stderr, "APDS9960 re-initialisation failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(100); // Delay 100ms
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

