#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x5A
#define PART_ID_REG 0x00
#define MEAS_RATE0_REG 0x08
#define COMMAND_REG 0x47
#define PS_DATA0_REG 0x24
#define PS_DATA1_REG 0x25
#define CSV_FILE "heartrate.csv"

// Global variables
int i2c_fd;
FILE *csv_file;
volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c();
int read_register(uint8_t reg);
int write_register(uint8_t reg, uint8_t value);
int read_proximity_data(uint16_t *proximity);
int calculate_bpm(uint16_t proximity);
int log_data(uint16_t proximity, int bpm);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read a single byte from a register
int read_register(uint8_t reg) {
    int result = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Write a single byte to a register
int write_register(uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Read proximity data from the sensor
int read_proximity_data(uint16_t *proximity) {
    int low = read_register(PS_DATA0_REG);
