int read_distance(int handle) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(handle, DISTANCE_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", bytes_read);
        return -1;
    }

    // Combine the two bytes into a 16-bit integer
    int distance = (buf[0] << 8) | buf[1];
    return distance;
}

// Logs the distance to a file
void log_distance(FILE *file, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(file, "%s, %d\n", timestamp, distance);
    fflush(file); // Ensure data is written to disk immediately
}

// Prints the distance to the console
void print_distance(int distance) {
    printf("%d\n", distance);
}

