    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger a measurement
        if (i2cWriteByteData(i2c_handle, DISTANCE_REG, 0x01) != 0) {
            fprintf(stderr, "Error triggering measurement\n");
            log_distance(log_file, -1); // Log error
            print_distance(-1);
