        gpioDelay(50000); // 50 ms = 50000 microseconds

        // Read the distance
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            // Log the distance
            log_distance(log_file, distance);

            // Print the distance
            print_distance(distance);
        } else {
            fprintf(stderr, "Error reading distance, skipping logging\n");
        }
    }

    // Close I2C and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

