    char init_data[] = {0x10, 0x01, 0x02, 0x03}; // Example initialization data
    int result = i2cWriteI2CBlockData(i2c_handle, 0x11, init_data, sizeof(init_data)); // Example register and data
    if (result < 0) {
        fprintf(stderr, "Error writing to sensor: %d\n", result);
        return -1;
    }

    return 0;
}

