        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int distance = read_distance();
        if (distance >= 0) {
            log_distance(distance);
            if (distance < threshold) {
                control_led(1); // Turn on LED
            } else {
                control_led(0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }

        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

