    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Distance: %d mm\n", s, distance);
    fclose(fp);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default: %d mm\n", DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int distance = read_distance();
        if (distance >= 0) {
            log_distance(distance);
            if (distance < threshold) {
                control_led(1); // Turn on LED
            } else {
                control_led(0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }

        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

