#define SAMPLE_DELAY_MS 100
#define LOG_FILE "intrusion_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
