int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Write a command to the sensor
int write_command(uint8_t command) {
    uint8_t buffer[2];
    buffer[0] = command;
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Error writing command to sensor");
        return -1;
    }
    return 0;
}

// Read a response from the sensor
int read_response(uint8_t *response, int length) {
    if (read(i2c_fd, response, length) != length) {
        perror("Error reading response from sensor");
        return -1;
    }
    return 0;
}

// Process the response data (check header, convert to distance)
sensor_data_t process_response(const uint8_t *response) {
    sensor_data_t data;
    data.distance = (response[11] << 8) | response[12];
    return data;
