            write_command(MEASUREMENT_COMMAND_3) != 0 ||
            write_command(MEASUREMENT_COMMAND_4) != 0) {
            fprintf(stderr, "Error requesting measurement, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Wait for a short period (at least 10ms)
        usleep(10000); // 10ms

        // Read the response
        if (read_response(response, RESPONSE_FRAME_LENGTH) != 0) {
            fprintf(stderr, "Error reading response, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Validate the response header
        if (response[0] != SENSOR_ADDRESS) {
            fprintf(stderr, "Invalid response header: 0x%02X\n", response[0]);
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Process the response data
        distance = process_response(response);

        // Sample the sensor 10 times
        for (i = 0; i < 10; i++) {
            // Read the response
            if (read_response(response, RESPONSE_FRAME_LENGTH) != 0) {
                fprintf(stderr, "Error reading response, retrying...\n");
                usleep(100000); // Wait 100ms before retrying
                break; // Exit the inner loop if read fails
            }

            // Validate the response header
            if (response[0] != SENSOR_ADDRESS) {
                fprintf(stderr, "Invalid response header: 0x%02X\n", response[0]);
                usleep(100000); // Wait 100ms before retrying
                break; // Exit the inner loop if header is invalid
            }

            // Process the response data
            distance = process_response(response);

            // Calculate the average distance
            uint16_t sum = 0;
            for (int j = 0; j < 10; j++) {
                sum += distance.distance;
            }
            uint16_t average_distance = sum / 10;

            // Log the intrusion if the average distance is below the threshold
            if (average_distance < DISTANCE_THRESHOLD) {
                log_intrusion(distance);
            }
        }

        // Delay before the next sample
        usleep(SAMPLE_DELAY_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Intrusion detection system stopped.\n");
    return 0;
}

