#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C

// Define the distance register address
#define DISTANCE_REG 0x00

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    // Set the slave address
    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read the distance from the MLX75030 sensor
int read_distance(int fd) {
    uint8_t buffer[2];
    ssize_t bytes_read = read(fd, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t distance = (buffer[1] << 8) | buffer[0];

    // Convert the raw value to millimetres (0.125 mm per count)
    return (int)(distance * 0.125);
}

int main() {
    // Register the signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    printf("MLX75030 Distance Sensor Reader\n");

    // Main loop to read and log the distance
    while (1) {
        int distance = read_distance(i2c_fd);

        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        // Wait for 500 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500 * 1000 * 1000; // 500 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

