#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define OPT3101_ADDR 0x44

// Define register addresses (replace with actual values from datasheet)
#define OPT3101_REG_DISTANCE_MSB 0x00
#define OPT3101_REG_DISTANCE_LSB 0x01
#define OPT3101_REG_AMBIENT_MSB 0x02
#define OPT3101_REG_AMBIENT_LSB 0x03
#define OPT3101_REG_ERROR_FLAGS 0x04
#define OPT3101_REG_CONFIG 0x05

// Global variables for I2C handle and program termination
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    uint16_t ambient_light;
    uint8_t error_flags;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the OPT3101 sensor
int init_opt3101() {
    // Example configuration: Continuous mode, 100 Hz, gain 1
    // Replace with actual configuration from datasheet
    char config_data[2] = {OPT3101_REG_CONFIG, 0x01}; // Example: Continuous mode
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to OPT3101 config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Extract distance data
    data->distance = (buffer[0] << 8) | buffer[1];

    // Extract ambient light data
    data->ambient_light = (buffer[2] << 8) | buffer[3];

    // Extract error flags
    data->error_flags = buffer[4];

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OPT3101 sensor
    if (init_opt3101() != 0) {
        fprintf(stderr, "OPT3101 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Print sensor data
            printf("Distance: %u mm, Ambient Light: %u lux, Error Flags: 0x%02X\n",
                   sensor_data.distance, sensor_data.ambient_light, sensor_data.error_flags);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 500 milliseconds
        gpioDelay(500000); // pigpio's delay function
    }

    // Close I2C connection and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

