#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 200000      // 200 ms timeout in microseconds

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;
volatile int running = 1;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, unsigned int tick);
float calculate_distance(unsigned int pulse_width);
void log_distance(float distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioTerminate();
    exit(0);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 0; // Reset echo_received flag
    } else if (level == 0 && echo_received == 0) {
        end_tick = tick;
        echo_received = 1; // Set echo_received flag
    }
}

// Function to calculate distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    if (pulse_width <= 0 || pulse_width > TIMEOUT_US) {
        return -1.0; // Indicate invalid pulse width
    }
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

// Function to log distance with timestamp
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (distance >= 0) {
        printf("[%s] Distance: %.2f cm\n", timestamp, distance);
    } else {
        printf("[%s] Invalid pulse width: %u us\n", timestamp, pulse_width);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-up/down resistor on echo pin (optional, depends on sensor wiring)
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_UP);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_sensor();

        // Wait for echo to be received with timeout
        int timeout = 0;
        while (echo_received == 0 && timeout < TIMEOUT_US) {
            gpioDelay(1); // Small delay to prevent busy-waiting
            timeout++;
        }

        if (echo_received == 0) {
            fprintf(stderr, "Timeout waiting for echo\n");
            log_distance(-1.0); // Log timeout error
        } else {
            // Calculate pulse width
            unsigned int pulse_width = end_tick - start_tick;

            // Calculate distance
            float distance = calculate_distance(pulse_width);

            // Log distance
            log_distance(distance);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

