// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize UART
int initialize_uart(const char *device, int baud_rate) {
    int handle = serOpen(device, baud_rate, 0); // 0 for default flags
    if (handle < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }
    return handle;
}

// Read radar data from UART
int read_radar_data(int uart_handle, RadarData *data) {
    char buffer[FRAME_SIZE];
    int bytes_read = serRead(uart_handle, buffer, FRAME_SIZE);

    if (bytes_read != FRAME_SIZE) {
        fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
        return -1;
    }

    // Check for magic word header
    if (buffer[0] != 0x02 || buffer[1] != 0x01 || buffer[2] != 0x04 || buffer[3] != 0x03 ||
        buffer[4] != 0x06 || buffer[5] != 0x05 || buffer[6] != 0x08 || buffer[7] != 0x07) {
        fprintf(stderr, "Invalid frame header\n");
        return -1;
    }

    // Convert raw data to range profile
    for (int i = 0; i < 64; i++) {
        data->range_profile[i] = (int16_t)((buffer[8 + 2 * i] << 8) | buffer[9 + 2 * i]);
    }

    return 0;
}

// Calculate distance from range profile
float calculate_distance(const RadarData *data) {
    // Simple distance calculation (replace with a more sophisticated algorithm)
    // This is a placeholder; a real implementation would involve more complex
