    float max_distance = 0.0;
    for (int i = 0; i < 64; i++) {
        if (data->range_profile[i] > max_distance) {
            max_distance = data->range_profile[i];
        }
    }
    return max_distance * 0.0486; // meters
}

// Trigger alert by setting GPIO pin HIGH for 2 seconds
void trigger_alert(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO HIGH
    gpioDelay(2000);       // Wait for 2 seconds
    gpioWrite(gpio_pin, 0); // Set GPIO LOW
}

// Log intrusion event to file
void log_intrusion(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
}

