    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize UART
    uart_handle = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    RadarData radar_data;
    float distance;

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read radar data
        if (read_radar_data(uart_handle, &radar_data) == 0) {
            // Calculate distance
            distance = calculate_distance(&radar_data);

            // Check for intrusion
            if (distance < DISTANCE_THRESHOLD) {
                printf("Intrusion detected! Distance: %.2f meters\n", distance);
                trigger_alert(GPIO_LED);
                log_intrusion(distance);
            }
        } else {
            fprintf(stderr, "Error reading radar data. Retrying...\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

