#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define DISTANCE_HIGH_REG 0x31
#define DISTANCE_LOW_REG 0x32
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
int log_distance(int distance);
void trigger_alert(int distance);
void signal_handler(int signal);

// Structure for sensor configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int distance_high_reg;
    int distance_low_reg;
    int gpio_pin;
    float distance_threshold;
    int sample_interval_ms;
} sensor_config_t;

// Function to initialize the sensor
int initialize_sensor() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_HIGH_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to log distance to a file
int log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Distance: %d cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to trigger an alert if the distance is below the threshold
void trigger_alert(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
        gpioDelay(1000);        // Wait for 1 second
        gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure it starts LOW

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Sensor initialized and logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int distance;
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            trigger_alert(distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

