#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x007
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x078
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L1X_REG_SYSTEM__INTERRUPT_CLEAR 0x014

// Distance thresholds (mm)
#define STOP_THRESHOLD 300
#define APPROACH_THRESHOLD 300
#define SLOW_THRESHOLD 600
#define CLEAR_THRESHOLD 1200

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void log_distance(int distance);
void print_message(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Check sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Error writing to reset register\n");
        return -1;
    }
    gpioDelay(2); // Wait for reset to complete

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error writing to mode start register\n");
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int *distance) {
    int range_status;
    int distance_mm;

    // Poll for data ready
    int timeout = 100; // 100 ms timeout
    while (timeout > 0) {
        range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS);
        if (range_status < 0) {
            fprintf(stderr, "Error reading interrupt status\n");
            return -1;
        }
        if (range_status & 0x01) {
            break; // Data ready
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }

    // Read distance
    distance_mm = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance_mm < 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    // Clear interrupt
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM__INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error writing to interrupt clear register\n");
        return -1;
    }

    *distance = distance_mm;
    return 0;
}

// Logging function
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("distance_log.csv", "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file\n");
            return;
        }
