#define CH201_REG_DISTANCE 0x10
#define CH201_REG_CONFIG 0x11

// GPIO pin for LED
#define LED_PIN 18

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_ch201();
int read_distance(uint16_t *distance);
float map_distance_to_frequency(uint16_t distance);
void blink_led(float frequency);
void log_data(uint16_t distance, float frequency);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the CH201 sensor
int init_ch201() {
    // Example configuration: Set continuous mode, 10 Hz sampling rate
    // Refer to the CH201 datasheet for the correct register and value
    char config_data[2] = {CH201_REG_CONFIG, 0x01}; // Example value, check datasheet
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read distance from the CH201 sensor
int read_distance(uint16_t *distance) {
    char reg = CH201_REG_DISTANCE;
    char buffer[2];
    int result;

    result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to distance register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

