float map_distance_to_frequency(uint16_t distance) {
    // Linear mapping: 50 mm -> 10 Hz, 500 mm -> 1 Hz
    float frequency = 10.0 + (float)(distance - 50) / (500.0 - 50.0) * 9.0;
    // Clamp frequency to 1 Hz and 10 Hz
    if (frequency < 1.0) frequency = 1.0;
    if (frequency > 10.0) frequency = 10.0;
    return frequency;
}

