    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a measurement on the MLX75030
int trigger_measurement() {
    char buf[1];
    buf[0] = TRIGGER_MEASUREMENT_CMD;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // 10 ms delay
    return 0;
}

// Read distance data from the MLX75030
int read_distance(int *distance_cm) {
    char buf[1];
    char read_buf[2];
    int result;

    buf[0] = READ_DISTANCE_CMD;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write read command: %d\n", result);
        return -1;
    }

    gpioDelay(10000); // 10 ms delay

    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read distance data: %d\n", result);
        return -1;
    }

    *distance_cm = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Log data to a CSV file
int log_data(sensor_data_t data) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&data.timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp_str, data.distance_cm);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data;
        int distance_cm;
        int retry;

        // Trigger measurement
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (trigger_measurement() == 0) {
                break; // Success
            }
            fprintf(stderr, "Retrying trigger measurement (%d/%d)...\n", retry + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retry++;
        }
        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to trigger measurement after %d retries\n", RETRY_COUNT);
            continue; // Skip to the next iteration
        }

        // Read distance
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_distance(&distance_cm) == 0) {
                break; // Success
            }
            fprintf(stderr, "Retrying read distance (%d/%d)...\n", retry + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retry++;
        }
        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read distance after %d retries\n", RETRY_COUNT);
            continue; // Skip to the next iteration
        }

        // Get timestamp
        data.timestamp = time(NULL);
        data.distance_cm = distance_cm;

        // Log data
        if (log_data(data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

