// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables for sensor states
static volatile int sensor1_state = 1; // Initialize to HIGH (no obstacle)
static volatile int sensor2_state = 1; // Initialize to HIGH (no obstacle)

// File pointer for the log file
static FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
void log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
    int debounced_state = gpioRead(gpio_pin);

    if (debounced_state != current_state) {
        return current_state; // Return the debounced state
    } else {
        return debounced_state; // Return the original state if debouncing fails
    }
}

