    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Open the log file in append mode
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read sensor 1
        int sensor1_value = read_sensor(SENSOR_1_GPIO);

        // Check for state change and log event
        if (sensor1_value == 0 && sensor1_state == 1) {
            log_event(1, "DETECTED");
            sensor1_state = 0; // Update state
        } else if (sensor1_value == 1 && sensor1_state == 0) {
            log_event(1, "CLEARED");
            sensor1_state = 1; // Update state
        }

        // Read sensor 2
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        // Check for state change and log event
        if (sensor2_value == 0 && sensor2_state == 1) {
            log_event(2, "DETECTED");
            sensor2_state = 0; // Update state
        } else if (sensor2_value == 1 && sensor2_state == 0) {
            log_event(2, "CLEARED");
            sensor2_state = 1; // Update state
        }

        gpioDelay(10 * 1000); // Poll every 10 milliseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness and to avoid compiler warnings.
    fclose(log_file);
    gpioTerminate();
    return 0;
}

