#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x49

// Define the register addresses
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    int distance_mm;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *bus);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int read_distance(int fd);
sensor_data_t get_sensor_data(int distance_mm);
int log_data(sensor_data_t data);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Open the I2C bus
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    // Set the slave address
    if (ioctl(fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", CH101_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Write a byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02x: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read a byte from an I2C register
int i2c_read_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C register 0x%02x: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Read multiple bytes from an I2C register
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading from I2C register 0x%02x: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read the distance from the sensor
int read_distance(int fd) {
    uint8_t buf[2];

    // Trigger a single range measurement
    if (i2c_write_byte(fd, MEAS_TRIGGER, 0x01) != 0) {
        fprintf(stderr, "Error triggering range measurement\n");
        return -1;
    }

    // Wait for the measurement to complete (data ready bit)
    int timeout = 0;
    while (1) {
        int status = i2c_read_byte(fd, MEAS_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading MEAS_STATUS\n");
            return -1;
        }

        if (status & 0x01) {
            break; // Data ready
        }

        usleep(1000); // Wait 1 ms
        timeout++;
        if (timeout > 50) { // Timeout after 50 ms
            fprintf(stderr, "Timeout waiting for data ready\n");
            return -1;
        }
    }

    // Read the distance data
    if (i2c_read_bytes(fd, DIST_HIGH, buf, 2) != 0) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    // Combine the high and low bytes
    int distance_mm = (buf[0] << 8) | buf[1];
    return distance_mm;
}

// Get the current timestamp in ISO 8601 format
sensor_data_t get_sensor_data(int distance_mm) {
    sensor_data_t data;
    time(&data.timestamp);
    data.distance_mm = distance_mm;
    return data;
}

// Log the data to a CSV file
int log_data(sensor_data_t data) {
    struct tm *tm_info;
    char timestamp[30];

    tm_info = localtime(&data.timestamp);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s,%d\n", timestamp, data.distance_mm);
    fclose(log_file);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read the distance from the sensor
        int distance_mm = read_distance(i2c_fd);
        if (distance_mm >= 0) {
            // Get the sensor data
            sensor_data_t data = get_sensor_data(distance_mm);

            // Log the data
            if (log_data(data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            printf("Distance: %d mm\n", distance_mm);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        // Wait for 500 ms
        usleep(500000); // 500 ms = 500000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

