#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the register address for distance measurement
#define DISTANCE_REG 0x00

// Global variables for I2C handle and pigpio initialization status
int i2c_handle = -1;
int pigpio_initialized = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_distance(int handle);
void log_distance(int distance);
void cleanup();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int distance;
    long timestamp_ms;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Initializes the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    pigpio_initialized = 1;
    return 0;
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads the distance from the MLX75030 sensor
int read_distance(int handle) {
    char buf[2];
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, DISTANCE_REG, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit distance value
            int distance = (buf[0] << 8) | buf[1];
            return distance;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10); // Wait 10ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries\n");
    return -1; // Indicate failure
}

// Logs the distance to the console with a timestamp
void log_distance(int distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    printf("Distance: %d mm, Timestamp: %ld ms\n", distance, timestamp_ms);
}

// Cleans up resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (pigpio_initialized) {
        gpioTerminate();
    }
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }

        gpioDelay(100); // Wait 100ms
    }

    return 0;
}

