#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses
#define VL53L4CX_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L4CX_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L4CX_REG_SYSRANGE_START 0x0040
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L4CX_REG_INTERRUPT_STATUS 0x0046

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    int i2c_address;
    int i2c_bus;
} sensor_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the VL53L4CX sensor
int init_vl53l4cx(int i2c_handle) {
    // Check sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, VL53L4CX_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L4CX_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Function to read distance from the VL53L4CX sensor
int read_distance(int i2c_handle) {
    int high_byte, low_byte;

    high_byte = i2cReadByteData(i2c_handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (high_byte < 0) {
        fprintf(stderr, "Error reading high byte\n");
        return -1;
    }

    low_byte = i2cReadByteData(i2c_handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1);
    if (low_byte < 0) {
        fprintf(stderr, "Error reading low byte\n");
        return -1;
    }

    return (high_byte << 8) | low_byte;
}

// Function to get the current timestamp in microseconds
void get_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    sprintf(timestamp, "%ld.%06ld", ts.tv_sec, ts.tv_nsec / 1000);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (init_vl53l4cx(i2c_handle) < 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            // Get timestamp
            char timestamp[30];
            get_timestamp(timestamp);

            // Log distance
            printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds

        // Check interrupt status
        int interrupt_status = i2cReadByteData(i2c_handle, VL53L4CX_REG_INTERRUPT_STATUS);
        if (interrupt_status < 0) {
            fprintf(stderr, "Error reading interrupt status\n");
        } else {
            if (interrupt_status & 0x01) {
                // Clear interrupt by writing 1 to the register
                if (i2cWriteByteData(i2c_handle, VL53L4CX_REG_INTERRUPT_STATUS, 0x01) < 0) {
                    fprintf(stderr, "Error clearing interrupt\n");
                }
            }
        }
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

