int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (init_vl53l4cx(i2c_handle) < 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            // Get timestamp
            char timestamp[30];
            get_timestamp(timestamp);

            // Log distance
            printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds

        // Check interrupt status
        int interrupt_status = i2cReadByteData(i2c_handle, VL53L4CX_REG_INTERRUPT_STATUS);
        if (interrupt_status < 0) {
            fprintf(stderr, "Error reading interrupt status\n");
        } else {
            if (interrupt_status & 0x01) {
                // Clear interrupt by writing 1 to the register
                if (i2cWriteByteData(i2c_handle, VL53L4CX_REG_INTERRUPT_STATUS, 0x01) < 0) {
                    fprintf(stderr, "Error clearing interrupt\n");
                }
            }
        }
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

