#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50 ms timeout in microseconds
#define LOG_FILE "sensor_data.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulseWidth);
int mapDistanceToAngle(float distance);
void setServoAngle(int angle);
void logData(float distance, int angle);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    setServoAngle(0); // Stop the servo
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long pulseIn(int pin, int level, int timeout) {
    long start = 0, end = 0;

    // Wait for the pulse to start
    int count = 0;
    while (gpioRead(pin) != level) {
        if (count++ > timeout) return -1; // Timeout
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    start = gpioTick();

    // Wait for the pulse to end
    count = 0;
    while (gpioRead(pin) == level) {
        if (count++ > timeout) return -1; // Timeout
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    end = gpioTick();

    return end - start;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) return -1.0; // Indicate error
    return (pulseWidth * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map distance to servo angle
int mapDistanceToAngle(float distance) {
    if (distance < 2.0) return -90; // Closest
    if (distance > 400.0) return 90;  // Farthest
    return (int)(((distance - 2.0) / (400.0 - 2.0)) * 180.0); // Linear mapping
}

// Function to set the servo angle
void setServoAngle(int angle) {
    if (angle < -90 || angle > 90) {
        fprintf(stderr, "Error: Invalid servo angle. Angle must be between -90 and 90.\n");
        return;
    }

    // Calculate pulse width based on angle (SG90 servo)
    int pulseWidth = 1000 + (angle * 2000 / 180); // 1000 us for 0 degrees, 2000 us for 180 degrees

    gpioServo(SERVO_PIN, pulseWidth);
}

// Function to log data to a file
void logData(float distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %d degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        triggerSensor();
        long pulseWidth = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

        if (pulseWidth > 0) {
            float distance = calculateDistance(pulseWidth);
            int angle = mapDistanceToAngle(distance);
            setServoAngle(angle);
            logData(distance, angle);
        } else {
            fprintf(stderr, "Error: Timeout waiting for echo pulse.\n");
            logData(-1.0, -1); // Log error
        }

        gpioDelay(200); // Delay for 200 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    setServoAngle(0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

