#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ipc.h>
#include <sys/msg.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define MESSAGE_QUEUE_KEY 12345
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// VL53L1X Register Addresses (Example - Refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSRANGE_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD1 0x0097

// Global variables
int i2c_handle;
int message_queue_id;
volatile sig_atomic_t terminate = 0;

// Structure for message queue messages
typedef struct {
    long mtype;
    int distance;
} message_t;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_buzzer(int state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    int retries = 0;
    int status;

    // Check sensor ID
    while (retries < MAX_RETRIES) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
        if (status >= 0) {
            if (status == 0xEA) {
                printf("VL53L1X sensor found with model ID: 0x%02X\n", status);
                return 0; // Success
            } else {
                fprintf(stderr, "Error: Invalid sensor model ID: 0x%02X (expected 0xEA)\n", status);
            }
        } else {
            fprintf(stderr, "Error reading sensor ID (attempt %d/%d): %d\n", retries + 1, MAX_RETRIES, status);
        }
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    fprintf(stderr, "Error: Failed to initialize VL53L1X sensor after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Read the distance from the VL53L1X sensor
int read_distance() {
    int retries = 0;
    int distance = -1; // Default to -1 to indicate error
    int status;

    while (retries < MAX_RETRIES) {
        // Start ranging
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01);
        if (status < 0) {
            fprintf(stderr, "Error starting ranging (attempt %d/%d): %d\n", retries + 1, MAX_RETRIES, status);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        // Wait for data ready (bit 0 of register 0x0089)
        int data_ready = 0;
        int timeout = 100; // Timeout after 100ms
        while (!data_ready && timeout > 0) {
            status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
            if (status < 0) {
                fprintf(stderr, "Error reading data ready status (attempt %d/%d): %d\n", retries + 1, MAX_RETRIES, status);
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000);
                continue;
            }
            data_ready = (status & 0x01);
            gpioDelay(1000); // Small delay to avoid busy-waiting
            timeout--;
        }

        if (!data_ready) {
            fprintf(stderr, "Error: Data ready timeout (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        // Read distance data
        int distance_msb = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        int distance_lsb = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD1);

        if (distance_msb < 0 || distance_lsb < 0) {
            fprintf(stderr, "Error reading distance data (attempt %d/%d): %d %d\n", retries + 1, MAX_RETRIES, distance_msb, distance_lsb);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        distance = (distance_msb << 8) | distance_lsb;
        return distance;
    }

    fprintf(stderr, "Error: Failed to read distance after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Control the buzzer
void control_buzzer(int state) {
    gpioWrite(BUZZER_GPIO, state);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (message_queue_id >= 0) {
        msgctl(message_queue_id, IPC_RMID, NULL);
    }
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }

    // Configure message queue
    message_queue_id = msgget(MESSAGE_QUEUE_KEY, IPC_CREAT | 0666);
    if (message_queue_id < 0) {
        fprintf(stderr, "Error creating message queue: %d\n", message_queue_id);
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);

            // Send distance to message queue
            message_t message;
            message.mtype = 1; // Message type (can be used for filtering)
            message.distance = distance;

            if (msgsnd(message_queue_id, &message, sizeof(message) - sizeof(long), 0) == -1) {
                fprintf(stderr, "Error sending message to queue\n");
            }

            // Control buzzer based on distance
            if (distance < DISTANCE_THRESHOLD) {
                control_buzzer(1); // Turn buzzer on
            } else {
                control_buzzer(0); // Turn buzzer off
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

