// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 500000      // 500ms timeout
#define DISTANCE_THRESHOLD 30.0 // cm

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;
volatile int running = 1;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, unsigned int tick);
float calculate_distance(unsigned int pulse_width);
void control_buzzer(float distance);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();           // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1;
    } else if (level == 0 && echo_received) {
        end_tick = tick;
        echo_received = 0;
    }
}

// Function to calculate distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    if (pulse_width == 0) {
        return -1.0; // Indicate invalid reading
    }
    float time_taken = (float)pulse_width / 1000000.0; // Convert us to s
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm
    return distance;
}

// Function to control the buzzer
void control_buzzer(float distance) {
    if (distance >= 0 && distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_sensor();

        // Wait for echo to be received with timeout
        int timeout = 0;
        while (!echo_received && timeout < TIMEOUT_US) {
            gpioDelay(1); // Small delay to prevent busy-waiting
            timeout++;
        }

        if (!echo_received) {
            fprintf(stderr, "Timeout waiting for echo\n");
            continue; // Skip to the next iteration
        }

        // Calculate pulse width
        unsigned int pulse_width = end_tick - start_tick;

        // Calculate distance
        float distance = calculate_distance(pulse_width);

        if (distance < 0) {
            fprintf(stderr, "Invalid distance reading\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();

    return 0;
}

