#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 30000      // 30ms timeout
#define MIN_PULSE_WIDTH_US 100  // Minimum pulse width (100us)
#define MAX_PULSE_WIDTH_US 30000 // Maximum pulse width (30000us)

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void trigger_sensor();
int read_echo_pulse(uint32_t *rising_tick, uint32_t *falling_tick);
float calculate_distance(uint32_t rising_tick, uint32_t falling_tick);
void log_distance(float distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to read the echo pulse width
int read_echo_pulse(uint32_t *rising_tick, uint32_t *falling_tick) {
    int timeout = 0;
    uint32_t start_tick, end_tick;

    // Wait for rising edge (with timeout)
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (timeout >= TIMEOUT_US) {
        return -1; // Timeout
    }
    start_tick = gpioTick();

    // Wait for falling edge (with timeout)
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (timeout >= TIMEOUT_US) {
        return -1; // Timeout
    }
    end_tick = gpioTick();

    *rising_tick = start_tick;
    *falling_tick = end_tick;

    return 0; // Success
}

// Function to calculate the distance in centimeters
float calculate_distance(uint32_t rising_tick, uint32_t falling_tick) {
    uint32_t pulse_width = falling_tick - rising_tick;

    // Validate pulse width
    if (pulse_width < MIN_PULSE_WIDTH_US || pulse_width > MAX_PULSE_WIDTH_US) {
        return -1.0; // Invalid pulse width
    }

    // Calculate distance in centimeters
    float distance = (pulse_width * SPEED_OF_SOUND) / 2.0;
    return distance;
}

// Function to log the distance to a file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (distance >= 0) {
        fprintf(stdout, "%s Distance: %.2f cm\n", timestamp, distance);
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "%s WARNING: Invalid distance reading: %.2f cm\n", timestamp, distance);
        fprintf(log_file, "%s WARNING: Invalid distance reading: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
    }
}

int main() {
    uint32_t rising_tick, falling_tick;
    float distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_sensor();

        if (read_echo_pulse(&rising_tick, &falling_tick) == 0) {
            distance = calculate_distance(rising_tick, falling_tick);
            if (distance >= 0) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Invalid distance reading, skipping logging.\n");
            }
        } else {
            fprintf(stderr, "Timeout waiting for echo pulse.\n");
            log_distance(-1.0); // Log timeout
        }

        gpioDelay(200); // 200ms delay
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

