#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for gate control
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19

// Define I2C bus and address
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29

// Define distance threshold (in mm)
#define DISTANCE_THRESHOLD 200

// Define log file name
#define LOG_FILE "gate_events.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void control_gate(int distance);
void log_event(const char *event);
void signal_handler(int signal);

// VL53L1X register addresses (example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0014
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the VL53L1X sensor
int vl53l1x_init() {
    // Soft reset the sensor
    if (i2cWriteByteData(i2c_handle, 0x0080, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset VL53L1X\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure timing budget (example - adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, 0x0088, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write timing budget\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0089, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write timing budget\n");
        return -1;
    }

    // Start ranging (example - adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance() {
    char buffer[2];
    int distance;

    // Read the distance data (2 bytes)
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, buffer, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance data\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit distance value
    distance = (buffer[0] << 8) | buffer[1];

    return distance;
}

// Function to control the gate based on the distance
void control_gate(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        // Open the gate
        gpioWrite(GATE_OPEN_PIN, 1);
        gpioWrite(GATE_CLOSE_PIN, 0);
        log_event("Gate opened");
    } else {
        // Close the gate
        gpioWrite(GATE_OPEN_PIN, 0);
        gpioWrite(GATE_CLOSE_PIN, 1);
        log_event("Gate closed");
    }
}

// Function to log events to a file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
