#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0014
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the VL53L1X sensor
int vl53l1x_init() {
    // Soft reset the sensor
    if (i2cWriteByteData(i2c_handle, 0x0080, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset VL53L1X\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure timing budget (example - adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, 0x0088, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write timing budget\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0089, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write timing budget\n");
        return -1;
    }

    // Start ranging (example - adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    return 0;
}

