#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define LED_GPIO_17 17
#define LED_GPIO_18 18
#define LED_GPIO_27 27
#define LED_GPIO_22 22
#define PROXIMITY_THRESHOLD 50
#define POLL_INTERVAL_MS 50

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line_17 = NULL;
static struct gpiod_line *led_line_18 = NULL;
static struct gpiod_line *led_line_27 = NULL;
static struct gpiod_line *led_line_22 = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int mpr121_init(int fd);
int mpr121_read_touch_status(int fd);
void set_led_pattern(int gpio_pin, uint8_t pattern);
void log_proximity_event(int electrode_number, uint8_t touch_status);
void signal_handler(int sig);

// I2C read function
int i2c_read_register(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return buf[0];
}

// I2C write function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// MPR121 initialization function
int mpr121_init(int fd) {
    // Soft reset
    if (i2c_write_register(fd, 0x80, 0x63) != 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    usleep(10000); // Wait for reset to complete

    // Verify sensor presence
    int status = i2c_read_register(fd, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read sensor status\n");
        return -1;
    }
    if ((status & 0x01) == 0) {
        fprintf(stderr, "Error: MPR121 not present\n");
        return -1;
    }

    // Configure MPR121 (example configuration)
    if (i2c_write_register(fd, 0x5A, 0x0B) != 0) return -1; // Touch threshold
    if (i2c_write_register(fd, 0x5D, 0xC8) != 0) return -1; // Release threshold
    if (i2c_write_register(fd, 0x5E, 0x82) != 0) return -1; // Touch and release threshold
    if (i2c_write_register(fd, 0x5F, 0xB4) != 0) return -1; // Release and touch threshold

    // Enable all electrodes
    if (i2c_write_register(fd, 0x5B, 0x0C) != 0) return -1; // ELECONFIG0
    if (i2c_write_register(fd, 0x5C, 0x00) != 0) return -1; // ELECONFIG1

    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(int fd) {
    uint8_t touch_status_low = i2c_read_register(fd, 0x00);
    uint8_t touch_status_high = i2c_read_register(fd, 0x01);

    if (touch_status_low < 0 || touch_status_high < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    return (touch_status_high << 8) | touch_status_low;
}

// Set LED pattern function
void set_led_pattern(int gpio_pin, uint8_t pattern) {
    struct gpiod_line *line = NULL;
    switch (gpio_pin) {
        case LED_GPIO_17:
            line = led_line_17;
            break;
        case LED_GPIO_18:
            line = led_line_18;
            break;
