#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30 ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0      // cm

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
void trigger_sensor();
long measure_echo_pulse();
float calculate_distance(long pulse_width);
void log_distance(float distance);
void signal_handler(int sig);
void cleanup();

// Structure to hold GPIO lines
struct gpio_lines {
    struct gpiod_line *trigger;
    struct gpiod_line *echo;
};

// Function to initialize GPIO lines
struct gpio_lines init_gpio_lines() {
    struct gpio_lines lines;
    lines.trigger = NULL;
    lines.echo = NULL;
    return lines;
}

// Function to request a GPIO line as output
struct gpiod_line *request_output_line(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return NULL;
    }

    if (gpiod_line_request_output(line, "trigger", 0) < 0) {
        fprintf(stderr, "Error: Could not request output line %d\n", pin);
        gpiod_line_release(line);
        return NULL;
    }

    return line;
}

// Function to request a GPIO line as input
struct gpiod_line *request_input_line(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        return NULL;
    }

    if (gpiod_line_request_input(line, "echo") < 0) {
        fprintf(stderr, "Error: Could not request input line %d\n", pin);
        gpiod_line_release(line);
        return NULL;
    }

    return line;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    if (!trigger_line) {
        fprintf(stderr, "Error: Trigger line not initialized\n");
        return;
    }

    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Error: Could not set trigger line low\n");
        return;
    }
    usleep(5000); // 5 microseconds

    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        fprintf(stderr, "Error: Could not set trigger line high\n");
        return;
    }
    usleep(10000); // 10 microseconds

    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Error: Could not set trigger line low after pulse\n");
        return;
    }
}

