// Global variables
static volatile unsigned int pulse_start_tick = 0;
static volatile unsigned int pulse_end_tick = 0;
static volatile int pulse_width = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, unsigned int tick);
double calculate_distance(int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        pulse_start_tick = tick;
        echo_received = 1; // Set flag to indicate echo received
    } else if (level == 0 && echo_received) {
        pulse_end_tick = tick;
        pulse_width = pulse_end_tick - pulse_start_tick;
        echo_received = 0; // Reset flag after processing
    }
}

// Function to calculate distance in meters
double calculate_distance(int pulse_width) {
    if (pulse_width <= 0) {
        return -1.0; // Indicate error
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // pulse_width in microseconds
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL); // Disable ISR
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt-driven echo pin
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_sensor();
        gpioDelay(1000); // Wait 1 second
    }

    return 0;
}

