#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_SPAD_NB 0x0022
#define VL53L1X_REG_RESULT_SIGNAL_RATE 0x001E
#define VL53L1X_REG_RESULT_AMBIENT_RATE 0x001C
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// GPIO pin for trigger
#define TRIGGER_PIN 27

// I2C handle
int i2c_handle;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
int read_status(int *status);
void log_data(int distance, int status);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    closelog();
    exit(0);
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Check sensor ID
    int sensor_id;
    if (i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID) < 0) {
        syslog(LOG_ERR, "Error reading sensor ID");
        return -1;
    }
    sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id != 0xEACC) {
        syslog(LOG_ERR, "Incorrect sensor ID: 0x%02X", sensor_id);
        return -1;
    }

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, 0x0018, 0x00) < 0) { // Continuous mode
        syslog(LOG_ERR, "Error writing to continuous mode register");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0019, 0x00) < 0) { // No timeout
        syslog(LOG_ERR, "Error writing to no timeout register");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0020, 0x01) < 0) { // Start ranging
        syslog(LOG_ERR, "Error writing to start ranging register");
        return -1;
    }

    syslog(LOG_INFO, "VL53L1X sensor initialized successfully");
    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance(int *distance) {
    int range_mm = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (range_mm < 0) {
        syslog(LOG_ERR, "Error reading distance");
        return -1;
    }
    *distance = range_mm;
    return 0;
}

// Read status from the VL53L1X sensor
int read_status(int *status) {
    int status_byte = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (status_byte < 0) {
        syslog(LOG_ERR, "Error reading status");
        return -1;
    }
    *status = status_byte;
    return 0;
}

// Log data to the systemd journal
void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s, Distance: %d mm, Status: %d", timestamp, distance, status);
}

int main() {
    // Initialize syslog
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Error opening I2C device: %d", i2c_handle);
        gpioTerminate();
        closelog();
