#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 200 // mm
#define LOG_FILE "gate_log.txt"
#define RANGE_MODE 0x00
#define RANGE_START 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_gate(int distance);
void log_event(const char *message);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MODE 0x0021
#define VL53L1X_REG_RANGING_START 0x0015
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Check sensor ID
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        log_event("Error reading sensor ID");
        return -1;
    }
    if (model_id != 0xEA) {
        log_event("Incorrect sensor ID");
        return -1;
    }

    // Set ranging mode
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, RANGE_MODE) < 0) {
        log_event("Error setting ranging mode");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_START, RANGE_START) < 0) {
        log_event("Error starting ranging");
        return -1;
    }

    log_event("VL53L1X sensor initialized successfully");
    return 0;
}

// Function to read the distance from the VL53L1X sensor
int read_distance() {
    int distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        log_event("Error reading distance");
        return -1;
    }
    return distance;
}

// Function to control the gate actuator
void control_gate(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GATE_GPIO, 1); // Open gate
        log_event("Gate opened");
    } else {
        gpioWrite(GATE_GPIO, 0); // Close gate
        log_event("Gate closed");
    }
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure immediate write to file
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        log_event("VL53L1X initialization failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); // Initially close the gate

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Gate control system started");

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            control_gate(distance);
        } else {
            log_event("Failed to read distance, retrying...");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    log_event("Shutting down...");
    gpioWrite(GATE_GPIO, 0); // Ensure gate is closed on exit
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

