#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0     // cm
#define MIN_PULSE_WIDTH 500   // us
#define MAX_PULSE_WIDTH 2500  // us
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_ANGLE_MIN 0
#define SERVO_ANGLE_MAX 180
#define MOVING_AVG_SIZE 5
#define TIMEOUT_US 30000      // 30 ms timeout

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold pulse width data
typedef struct {
    uint32_t start_tick;
    uint32_t end_tick;
    int valid;
} pulse_data_t;

pulse_data_t pulse_data = {0, 0, 0};

// Moving average filter
float distance_history[MOVING_AVG_SIZE];
int history_index = 0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(uint32_t pulse_width);
float moving_average(float new_value);
float map_distance_to_angle(float distance);
int set_servo_angle(float angle);
int log_data(float distance, float angle);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_data.start_tick = tick;
        pulse_data.valid = 0; // Reset valid flag on rising edge
    } else if (level == 0) {
        pulse_data.end_tick = tick;
        pulse_data.valid = 1; // Set valid flag on falling edge
    }
}

// Function to calculate distance in centimeters
float calculate_distance(uint32_t pulse_width) {
    if (pulse_width == 0) {
        return -1.0; // Indicate invalid reading
    }
    float time_taken = (float)(pulse_width / 1000000.0); // Convert us to s
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0;
    return distance;
}

// Moving average filter function
float moving_average(float new_value) {
    distance_history[history_index] = new_value;
    history_index = (history_index + 1) % MOVING_AVG_SIZE;

    float sum = 0.0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sum += distance_history[i];
    }
    return sum / MOVING_AVG_SIZE;
}

// Function to map distance to servo angle using a logarithmic mapping
float map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return SERVO_ANGLE_MIN;
    } else if (distance > MAX_DISTANCE) {
        return SERVO_ANGLE_MAX;
    } else {
        float log_distance = log10(distance / MIN_DISTANCE);
        float log_max_angle = log10(MAX_DISTANCE / MIN_DISTANCE);
        float angle = (log_distance / log_max_angle) * (SERVO_ANGLE_MAX - SERVO_ANGLE_MIN) + SERVO_ANGLE_MIN;
        return angle;
    }
}

// Function to set the servo angle
int set_servo_angle(float angle) {
    if (angle < SERVO_ANGLE_MIN || angle > SERVO_ANGLE_MAX) {
        fprintf(stderr, "Error: Angle out of range (%.2f)\n", angle);
        return -1; // Indicate error
    }

    // Convert angle to pulse width
    float pulse_width = (angle / (SERVO_ANGLE_MAX - SERVO_ANGLE_MIN)) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH;

    // Set servo pulse width
    int result = gpioServo(SERVO_PIN, (int)pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width (%d)\n", result);
        return -1; // Indicate error
    }

    return 0; // Indicate success
}

// Function to log data to a CSV file
int log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Register alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set alert function\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_sensor();

        // Wait for echo to be valid or timeout
        int timeout_count = 0;
        while (!pulse_data.valid && timeout_count < TIMEOUT_US) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout_count++;
        }

        if (!pulse_data.valid) {
            fprintf(stderr, "Error: Echo timeout\n");
            distance_history[history_index] = -1.0; // Log invalid reading
            history_index = (history_index + 1) % MOVING_AVG_SIZE;
            float avg_distance = moving_average(-1.0);
            float angle = map_distance_to_angle(avg_distance);
            set_servo_angle(angle);
            log_data(-1.0, angle);
            gpioDelay(100); // Short delay before next measurement
            continue;
        }

        // Calculate pulse width
        uint32_t pulse_width = pulse_data.end_tick - pulse_data.start_tick;

        // Calculate distance
        float distance = calculate_distance(pulse_width);

        // Apply moving average filter
        float avg_distance = moving_average(distance);

        // Map distance to servo angle
        float angle = map_distance_to_angle(avg_distance);

        // Set servo angle
        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Error: Failed to set servo angle\n");
        }

        // Log data
        log_data(avg_distance, angle);

        // Delay
        gpioDelay(100); // 100 ms delay
    }

    // Stop servo
    set_servo_angle(90); // Set to 90 degrees

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

