#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1102_ADDR 0x60
#define PROXIMITY_REG 0x08
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
FILE *log_file;
int threshold = 1000;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_proximity();
void log_data(int proximity);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Structure for passing data to the interrupt handler
typedef struct {
    int proximity;
} interrupt_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read proximity value from Si1102
int read_proximity() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PROXIMITY_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes
    int proximity = (buf[0] << 8) | buf[1];
    return proximity;
}

// Function to log data to file
void log_data(int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity, (proximity <= threshold) ? "SAFE" : "ALERT");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    interrupt_data_t *data = (interrupt_data_t *)user_data;
    int proximity = data->proximity;

    if (proximity > threshold) {
        log_data(proximity);
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                SI1102_ADDR = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int proximity = read_proximity();
        if (proximity >= 0) {
            interrupt_data_t data = {proximity};
            interrupt_handler(GPIO_PIN, 1, 0, &data); // Trigger interrupt
        } else {
            fprintf(stderr, "Failed to read proximity, retrying...\n");
        }
        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

