#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 200.0     // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define TIMEOUT_US 200000      // 200 ms timeout in microseconds

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;
volatile int running = 1;

// Function prototypes
void trigger_sensor();
double measure_distance();
double calculate_frequency(double distance);
void set_pwm_frequency(double frequency);
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
double measure_distance() {
    trigger_sensor();

    // Wait for echo to start (with timeout)
    int timeout = TIMEOUT_US;
    while (!echo_received && timeout > 0) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout--;
    }

    if (!echo_received) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate error
    }

    echo_start_tick = gpioTick();

    // Wait for echo to end (with timeout)
    timeout = TIMEOUT_US;
    while (!echo_end_received && timeout > 0) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout--;
    }

    if (!echo_end_received) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate error
    }

    echo_end_tick = gpioTick();

    // Calculate pulse width in microseconds
    int pulse_width = echo_end_tick - echo_start_tick;

    // Calculate distance in centimeters
    double distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to calculate the frequency based on the distance
double calculate_frequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return 0.0; // Return 0Hz if distance is out of range
    }

    // Use logarithmic formula for frequency mapping
    double frequency = MIN_FREQUENCY * exp(distance / 50.0);

    // Clamp frequency to the valid range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    return frequency;
}

// Function to set the PWM frequency
void set_pwm_frequency(double frequency) {
    if (frequency > 0) {
        gpioSetPWMfrequency(PWM_PIN, (int)frequency);
        gpioPWM(PWM_PIN, 128); // 50% duty cycle
    } else {
        gpioPWM(PWM_PIN, 0); // Stop PWM if frequency is 0
    }
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            echo_start_tick = tick;
        } else if (level == 0) {
            echo_end_tick = tick;
            echo_end_received = 1;
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        double distance = measure_distance();

        if (distance > 0) {
            double frequency = calculate_frequency(distance);
            set_pwm_frequency(frequency);
        } else {
            set_pwm_frequency(0.0); // Stop PWM if distance measurement fails
        }

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();

    return 0;
}

