// Signal handler for graceful shutdown
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping buzzer and terminating pigpio...\n", signal);
    gpioHardwarePWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
