    long startTime = 0, endTime = 0;

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (high)\n");
        return -1; // Indicate timeout error
    }
    startTime = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (low)\n");
        return -1; // Indicate timeout error
    }
    endTime = gpioTick();

