    if (frequency <= 0) {
        gpioHardwarePWM(BUZZER_PIN, 0); // Stop PWM if frequency is 0
        return;
    }

    // Calculate the PWM range (adjust as needed based on your hardware)
    int range = 1000000; // 1 ms PWM range (adjust as needed)

    // Calculate the PWM duty cycle (50% for 500us on/500us off)
    int dutyCycle = (int)(range * 0.5); // 50% duty cycle

    // Set the PWM frequency
    gpioHardwarePWM(BUZZER_PIN, dutyCycle, range); // Set PWM frequency
}

