    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (adjust as needed based on your hardware)
    gpioSetPWMrange(BUZZER_PIN, 1000000); // 1 ms PWM range

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
        long pulseWidth = getPulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulseWidth);

        // Calculate the frequency
        float frequency = calculateFrequency(distance);

        // Set the buzzer frequency
        setBuzzerFrequency(frequency);

        // Print the distance and frequency
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioHardwarePWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();

    return 0;
}

