// Structure to hold sensor configuration
typedef struct {
    int i2c_address;
    int spi_channel;
    int spi_speed;
    int spi_flags;
} sensor_config_t;

// Function prototypes
int init_pigpio();
int init_i2c(int i2c_address);
int init_spi(int spi_channel, int spi_speed, int spi_flags);
int init_sensor(int i2c_handle);
int read_distance(int spi_handle, int *distance);
void log_distance(FILE *log_file, int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c(int i2c_address) {
    int handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", handle);
        return -1;
    }
    return handle;
}

// Initialize SPI communication
int init_spi(int spi_channel, int spi_speed, int spi_flags) {
    int handle = spiOpen(spi_channel, spi_speed, spi_flags);
    if (handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", handle);
        return -1;
    }
    return handle;
}

