#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x60

// Define register addresses (replace with actual values from datasheet)
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0 0x24
#define REG_PS1_DATA1 0x25

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als_visible;
    uint16_t proximity;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *bus, int addr);
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int i2c_close(int fd);
int read_sensor_data(int fd, sensor_data_t *data);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, uint16_t als_visible);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Open the I2C bus
int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read a single byte from an I2C register
int i2c_read_register(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }

    return buf[0];
}

// Write a single byte to an I2C register
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }

    return 0;
}

// Close the I2C bus
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C bus");
        return -1;
    }
    return 0;
}

// Read ambient light and proximity data from the sensor
int read_sensor_data(int fd, sensor_data_t *data) {
    int als_low, als_high, prox_low, prox_high;

    als_low = i2c_read_register(fd, REG_ALS_VIS_DATA0);
    als_high = i2c_read_register(fd, REG_ALS_VIS_DATA1);
    prox_low = i2c_read_register(fd, REG_PS1_DATA0);
    prox_high = i2c_read_register(fd, REG_PS1_DATA1);

    if (als_low < 0 || als_high < 0 || prox_low < 0 || prox_high < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    data->als_visible = (uint16_t)((als_high << 8) | als_low);
    data->proximity = (uint16_t)((prox_high << 8) | prox_low);

    return 0;
}

// Get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[20]; //YYYY-MM-DDTHH:MM:SSZ\0

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

// Log the data to a CSV file
int log_data(const char *timestamp, uint16_t als_visible) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%u\n", timestamp, als_visible);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = i2c_open(I2C_BUS, SI1175_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("proximity_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2c_close(i2c_fd);
        return 1;
