// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Open the I2C bus
int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read a single byte from an I2C register
int i2c_read_register(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }

    return buf[0];
}

// Write a single byte to an I2C register
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }

    return 0;
}

// Close the I2C bus
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C bus");
        return -1;
    }
    return 0;
}

// Read ambient light and proximity data from the sensor
int read_sensor_data(int fd, sensor_data_t *data) {
    int als_low, als_high, prox_low, prox_high;

    als_low = i2c_read_register(fd, REG_ALS_VIS_DATA0);
    als_high = i2c_read_register(fd, REG_ALS_VIS_DATA1);
    prox_low = i2c_read_register(fd, REG_PS1_DATA0);
    prox_high = i2c_read_register(fd, REG_PS1_DATA1);

    if (als_low < 0 || als_high < 0 || prox_low < 0 || prox_high < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    data->als_visible = (uint16_t)((als_high << 8) | als_low);
    data->proximity = (uint16_t)((prox_high << 8) | prox_low);

    return 0;
}

