#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_ALS_VIS_DATA1 0x23
#define SI1120_REG_PS1_DATA0 0x18
#define SI1120_REG_PS1_DATA1 0x19
#define SI1120_REG_COMMAND 0x30

// Command to reset the sensor
#define SI1120_RESET_CMD 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t proximity;
} sensor_data_t;

// Function prototypes
int init_si1120();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the Si1120 sensor
int init_si1120() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SI1120_REG_COMMAND, SI1120_RESET_CMD) != 0) {
        fprintf(stderr, "Error: Failed to reset Si1120\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Verify the part ID
    int part_id = i2cReadByteData(i2c_handle, SI1120_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: Failed to read part ID\n");
        return -1;
    }
    if (part_id != 0x41) {
        fprintf(stderr, "Error: Incorrect part ID: 0x%02X\n", part_id);
        return -1;
    }

    return 0;
}

// Read ALS and proximity data from the Si1120 sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int retries = 3;
    int status;

    while (retries > 0) {
        // Read ALS data
        int als_low = i2cReadByteData(i2c_handle, SI1120_REG_ALS_VIS_DATA0);
        int als_high = i2cReadByteData(i2c_handle, SI1120_REG_ALS_VIS_DATA1);

        if (als_low < 0 || als_high < 0) {
            fprintf(stderr, "Error: Failed to read ALS data (low/high)\n");
            gpioDelay(10);
            retries--;
            continue;
        }

        data.als = (uint16_t)((als_high << 8) | als_low);

        // Read proximity data
        int prox_low = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA0);
        int prox_high = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA1);

        if (prox_low < 0 || prox_high < 0) {
            fprintf(stderr, "Error: Failed to read proximity data (low/high)\n");
            gpioDelay(10);
            retries--;
            continue;
        }

        data.proximity = (uint16_t)((prox_high << 8) | prox_low);

        return data;
    }

    fprintf(stderr, "Error: Failed to read sensor data after multiple retries\n");
    data.als = 0; // Set to 0 to indicate error
    data.proximity = 0;
    return data;
}

// Log the sensor data to a file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, Proximity: %u\n", timestamp, data.als, data.proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

