    if (read(i2c_fd, &part_id, 1) != 1) {
        perror("Error reading part ID");
        close(i2c_fd);
        return -1;
    }

    if (part_id != 0x50) {
        fprintf(stderr, "Error: Incorrect part ID: 0x%02X\n", part_id);
        close(i2c_fd);
        return -1;
    }

    // Configure measurement rate (example: 100 Hz)
    uint8_t config_data[2] = {MEAS_RATE_REG, 0x07};
    if (write(i2c_fd, config_data, 2) != 2) {
        perror("Error writing to measurement rate register");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[4];

    // Read ambient light data
    if (read(i2c_fd, buffer, 4) != 4) {
        perror("Error reading sensor data");
        return -1;
    }

    data->ambient_light = (buffer[1] << 8) | buffer[0];
    data->proximity = (buffer[3] << 8) | buffer[2];

    return 0;
}

// Convert raw ambient light data to lux
float convert_lux(uint16_t raw_lux) {
    return (float)raw_lux * 0.1;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%u\n", timestamp, convert_lux(data.ambient_light), data.proximity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Print data to console
void print_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Lux: %.2f, Proximity: %u\n", timestamp, convert_lux(data.ambient_light), data.proximity);
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            // Print data
            print_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

