#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define DISTANCE_THRESHOLD 20.0 // cm
#define TIMEOUT_US 50000       // 50ms timeout

// Global variables
volatile unsigned int rising_edge_time = 0;
volatile unsigned int falling_edge_time = 0;
volatile int echo_received = 0;
volatile int program_running = 1;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, unsigned int tick);
float calculate_distance(unsigned int rising_edge, unsigned int falling_edge);
void control_buzzer(float distance);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        rising_edge_time = tick;
        echo_received = 1; // Set flag to indicate echo received
    } else if (level == 0 && echo_received) {
        falling_edge_time = tick;
        echo_received = 0; // Reset flag
    }
}

// Function to calculate distance in centimeters
float calculate_distance(unsigned int rising_edge, unsigned int falling_edge) {
    if (rising_edge == 0 || falling_edge == 0) {
        return -1.0; // Indicate error
    }

    unsigned int pulse_width = falling_edge - rising_edge;
    if (pulse_width > TIMEOUT_US) {
        return -1.0; // Timeout
    }

    float distance = (float)pulse_width * SPEED_OF_SOUND / 2.0;
    return distance;
}

// Function to control the buzzer
void control_buzzer(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        gpioDelay(50); // Wait for 50ms before next measurement

        if (echo_received) {
            float distance = calculate_distance(rising_edge_time, falling_edge_time);
            if (distance >= 0) {
                printf("Distance: %.2f cm\n", distance);
                control_buzzer(distance);
            } else {
                fprintf(stderr, "Error: Timeout or invalid echo pulse received.\n");
            }
        } else {
            fprintf(stderr, "Error: No echo received.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();

    return 0;
}

