#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50 ms timeout
#define MIN_DISTANCE 2.0       // Minimum measurable distance (2 cm)
#define MAX_DISTANCE 400.0      // Maximum measurable distance (400 cm)
#define MIN_PULSE_WIDTH 500   // Minimum pulse width (500 us)
#define MAX_PULSE_WIDTH 2500  // Maximum pulse width (2500 us)

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;
volatile int running = 1;

// Function prototypes
void trigger_sensor();
float measure_distance();
void set_servo_angle(float distance);
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
float measure_distance() {
    echo_received = 0; // Reset echo_received flag
    echo_start_tick = 0;
    echo_end_tick = 0;

    // Trigger the sensor
    trigger_sensor();

    // Wait for echo to start (rising edge)
    int timeout = 0;
    while (!echo_received && timeout < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }
    if (!echo_received) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate timeout error
    }
    echo_start_tick = gpioTick();

    // Wait for echo to end (falling edge)
    timeout = 0;
    while (!echo_received && timeout < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }
    if (!echo_received) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate timeout error
    }
    echo_end_tick = gpioTick();

    // Calculate pulse duration in microseconds
    int pulse_duration_us = echo_end_tick - echo_start_tick;

    // Calculate distance in centimeters
    float distance = (pulse_duration_us * 0.0343) / 2.0;

    // Validate distance
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Invalid distance reading: %.2f cm\n", distance);
        return -1.0; // Indicate invalid reading
    }

    return distance;
}

// Function to set the servo angle based on the distance
void set_servo_angle(float distance) {
    // Map distance to pulse width (0-180 degrees)
    float pulse_width = MIN_PULSE_WIDTH + (distance - MIN_DISTANCE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_DISTANCE - MIN_DISTANCE);

    // Clamp pulse width to valid range
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }

    // Set servo angle
    gpioServo(SERVO_PIN, (int)pulse_width);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            echo_start_tick = tick;
        } else if (level == 0) {
            echo_end_tick = tick;
            echo_received = 1; // Set flag to indicate echo received
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set trigger pin to low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Set servo to a safe position (90 degrees)
    gpioServo(SERVO_PIN, 1500); // 1500 us pulse width for 90 degrees
    gpioDelay(2000); // Allow servo to settle

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (running) {
        // Measure distance
        float distance = measure_distance();

        if (distance > 0) {
            // Set servo angle
            set_servo_angle(distance);

            // Print distance and angle
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, (distance - MIN_DISTANCE) * 180.0 / (MAX_DISTANCE - MIN_DISTANCE));
        } else {
            fprintf(stderr, "Error: Failed to measure distance\n");
        }

        // Delay
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();

    return 0;
}

