    // Set servo angle
    gpioServo(SERVO_PIN, (int)pulse_width);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            echo_start_tick = tick;
        } else if (level == 0) {
            echo_end_tick = tick;
            echo_received = 1; // Set flag to indicate echo received
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set trigger pin to low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Set servo to a safe position (90 degrees)
    gpioServo(SERVO_PIN, 1500); // 1500 us pulse width for 90 degrees
    gpioDelay(2000); // Allow servo to settle

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (running) {
        // Measure distance
        float distance = measure_distance();

        if (distance > 0) {
            // Set servo angle
            set_servo_angle(distance);

            // Print distance and angle
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, (distance - MIN_DISTANCE) * 180.0 / (MAX_DISTANCE - MIN_DISTANCE));
        } else {
            fprintf(stderr, "Error: Failed to measure distance\n");
        }

        // Delay
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();

    return 0;
}

