// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define MEASURE_TEMP 0xE3
#define MEASURE_HUMID 0xE5
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_handle();
int write_config_register(int handle, int config);
int read_sensor_data(int handle, int *temperature, int *humidity);
float convert_temperature(int raw_temperature);
float convert_humidity(int raw_humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C handle
int open_i2c_handle() {
    int handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write to the configuration register
int write_config_register(int handle, int config) {
    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = config;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(int handle, int *temperature, int *humidity) {
    char buf[1];
    char data[2];

    // Measure temperature
    buf[0] = TEMP_REG;
    if (i2cWriteDevice(handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write temperature register address\n");
        return -1;
    }
    gpioDelay(10); // Wait for conversion

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read temperature and humidity data\n");
        return -1;
    }

    *temperature = (data[0] << 8) | data[1];

    // Measure humidity
    buf[0] = HUMID_REG;
    if (i2cWriteDevice(handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write humidity register address\n");
        return -1;
    }
    gpioDelay(10); // Wait for conversion

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read humidity data\n");
        return -1;
    }

    *humidity = (data[0] << 8) | data[1];

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(int raw_temperature) {
    return (175.72 * raw_temperature) / 65536.0 - 46.85;
}

// Convert raw humidity to relative humidity
float convert_humidity(int raw_humidity) {
    return (125.0 * raw_humidity) / 65536.0 - 6.0;
}

// Log temperature and humidity data to the console
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C handle
    i2c_handle = open_i2c_handle();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Write to the configuration register to select the temperature sensor
    if (write_config_register(i2c_handle, MEASURE_TEMP) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int raw_temperature, raw_humidity;

        // Read sensor data
        if (read_sensor_data(i2c_handle, &raw_temperature, &raw_humidity) == 0) {
            // Convert data
            float temperature = convert_temperature(raw_temperature);
            float humidity = convert_humidity(raw_humidity);

            // Log data
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 2 seconds
        gpioDelay(2000); // pigpioDelay takes milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

