#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to stabilize

    // Configure accelerometer range to ±2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range\n");
        return -1;
    }

    // Configure gyroscope range to ±250 deg/s
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read raw sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[14];
    int result = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14);

    if (result != 14) {
        fprintf(stderr, "Error: Could not read sensor data (read %d bytes)\n", result);
        return -1;
    }

    // Combine high and low bytes for each axis
    data->accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    data->accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    data->accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    data->gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
    data->gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
    data->gyro_z = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    struct timespec sleep_time = {0, 100000000}; // 100 milliseconds

    printf("MPU-6050 data logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Print sensor data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  |  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z,
                   sensor_data.gyro_x, sensor_data.gyro_y, sensor_data.gyro_z);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying...\n");
        }

        // Sleep for 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("MPU-6050 data logging stopped.\n");

    return 0;
}

