        // Validate CRC checksums
        if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "CRC checksum error, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
