#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A

// Define the register addresses for ambient and object temperature
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07

// Global variables for I2C file descriptor and log file
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int read_temperature(int reg);
float convert_to_celsius(int raw_temp);
int log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize the I2C interface
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Read temperature data from the specified register
int read_temperature(int reg) {
    int raw_temp = i2cReadWordData(i2c_fd, reg);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature from register 0x%02X: %d\n", reg, raw_temp);
        return -1;
    }
    return raw_temp;
}

// Convert raw temperature data to Celsius
float convert_to_celsius(int raw_temp) {
    // The raw temperature is a 12-bit value, left-aligned.
    // The temperature is then multiplied by 0.02 - 256.02 degrees Celsius.
    // The temperature is then shifted right by 4 bits to get the 12-bit value.
    float temp_celsius = (float)((raw_temp >> 4) * 0.02) - 273.15;
    return temp_celsius;
}

// Log temperature data to a CSV file
int log_temperature(float ambient_temp, float object_temp) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("temperature_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp);
    fclose(log_file);
    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize the I2C interface
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to read and log temperature data
    while (1) {
        // Read ambient temperature
        int raw_ambient_temp = read_temperature(AMBIENT_TEMP_REG);
        if (raw_ambient_temp >= 0) {
            float ambient_temp = convert_to_celsius(raw_ambient_temp);

            // Read object temperature
            int raw_object_temp = read_temperature(OBJECT_TEMP_REG);
            if (raw_object_temp >= 0) {
                float object_temp = convert_to_celsius(raw_object_temp);

                // Log the temperature data
                if (log_temperature(ambient_temp, object_temp) != 0) {
                    fprintf(stderr, "Error logging temperature data.\n");
                } else {
                    printf("Ambient Temperature: %.2f °C, Object Temperature: %.2f °C\n", ambient_temp, object_temp);
                }
            } else {
                fprintf(stderr, "Error reading object temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading ambient temperature.\n");
        }

        // Wait for 5 seconds
        gpioSleep(PI_TIME_RELATIVE, 5, 0);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_fd);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

