#include <string.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_temperature(uint16_t raw_temperature);
int log_data(float temperature);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Read temperature data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buffer[6];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command");
        return -1;
    }

    gpioDelay(20); // Wait for measurement (datasheet specifies 15ms for high repeatability)

    result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        log_error("Failed to read sensor data");
        return -1;
    }

    uint16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    data->temperature = convert_temperature(raw_temperature);

    return 0;
}

// Convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return -45.0 + (175.0 * (float)raw_temperature / 65535.0);
}

