    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(error_log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(error_log_file);

    return 0;
}

