        gpioTerminate();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data.temperature);
        } else {
            log_error("Failed to read sensor data, retrying...");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

