#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define LOG_FILE "sht40_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *temperature, uint16_t *humidity);
uint8_t crc8(const uint8_t *data, int len);
sensor_data_t convert_data(uint16_t raw_temperature, uint16_t raw_humidity);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(uint16_t *temperature, uint16_t *humidity) {
    char cmd[1] = {MEASURE_HIGH_REPEATABILITY};
    char buffer[6];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for measurement (at least 10 ms)

    result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *temperature = (buffer[0] << 8) | buffer[1];
    *humidity = (buffer[3] << 8) | buffer[4];

    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw data to temperature and humidity
sensor_data_t convert_data(uint16_t raw_temperature, uint16_t raw_humidity) {
    sensor_data_t data;
    data.temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    data.humidity = 100.0 * (float)raw_humidity / 65535.0;
    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    uint16_t raw_temperature, raw_humidity;
    sensor_data_t sensor_data;
    int retry;

    printf("Smart Greenhouse Environment Monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_sensor_data(&raw_temperature, &raw_humidity) == 0) {
                // CRC validation
                uint8_t temp_data[2] = {(raw_temperature >> 8) & 0xFF, raw_temperature & 0xFF};
                uint8_t hum_data[2] = {(raw_humidity >> 8) & 0xFF, raw_humidity & 0xFF};

                if (crc8(temp_data, 2) != raw_temperature & 0xFF) {
                    fprintf(stderr, "Temperature CRC error, retry %d\n", retry + 1);
                    retry++;
                    gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                    continue;
                }

                if (crc8(hum_data, 2) != raw_humidity & 0xFF) {
                    fprintf(stderr, "Humidity CRC error, retry %d\n", retry + 1);
                    retry++;
                    gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                    continue;
                }

                // Convert data
                sensor_data = convert_data(raw_temperature, raw_humidity);

                // Log data
                log_data(sensor_data);

                printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Sensor read failed, retry %d\n", retry + 1);
                retry++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

