#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define TEMP_MEASURE_CMD 0xF3
#define HUMID_MEASURE_CMD 0xF5
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_device();
int read_sensor_data(uint8_t command, uint16_t *raw_value);
float convert_temperature(uint16_t raw_value);
float convert_humidity(uint16_t raw_value);
int log_data(float temperature, float humidity);
void print_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data with retry mechanism
int read_sensor_data(uint8_t command, uint16_t *raw_value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, command);
        if (result != 0) {
            fprintf(stderr, "I2C write failed (command 0x%02X): %s, retry %d/%d\n", command, strerror(errno), retries + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(20000); // Wait for measurement (at least 20ms)

        result = i2cReadWordData(i2c_handle, 0); // Read two bytes
        if (result < 0) {
            fprintf(stderr, "I2C read failed: %s, retry %d/%d\n", strerror(errno), retries + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_MS * 1000);
            retries++;
            continue;
        }

        *raw_value = (uint16_t)result;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_value) {
    return ((175.72 * raw_value / 65536.0) - 46.85);
}

// Convert raw humidity to relative humidity
float convert_humidity(uint16_t raw_value) {
    return ((125.0 * raw_value / 65536.0) - 6.0);
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Print data to console
void print_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temperature, humidity);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint16_t raw_temperature, raw_humidity;
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_sensor_data(TEMP_MEASURE_CMD, &raw_temperature) == 0) {
            temperature = convert_temperature(raw_temperature);
        } else {
            temperature = -999.0; // Indicate error
        }

        // Read humidity
        if (read_sensor_data(HUMID_MEASURE_CMD, &raw_humidity) == 0) {
            humidity = convert_humidity(raw_humidity);
        } else {
            humidity = -999.0; // Indicate error
        }

        // Log data
        if (temperature != -999.0 && humidity != -999.0) {
            log_data(temperature, humidity);
            print_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Skipping logging.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

