// Constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define LOG_FILE "airflow_data.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation (Sensirion CRC-8-ATM)
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP800 sensor
int read_sdp800(int fd, int16_t *pressure, int16_t *temperature, int16_t *scale_factor) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t buffer[9];
    int bytes_read;

    // Send measurement command
    if (write(fd, cmd, 2) != 2) {
        perror("Failed to write measurement command");
        return -1;
    }

    // Wait for measurement to complete (at least 45 ms)
    usleep(50000); // 50 ms

    // Read 9 bytes of data
    bytes_read = read(fd, buffer, 9);
    if (bytes_read != 9) {
        perror("Failed to read data");
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5] || crc8(buffer + 6, 2) != buffer[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Extract raw pressure, temperature, and scale factor
    *pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    *temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    *scale_factor = (int16_t)((buffer[6] << 8) | buffer[7]);

    return 0;
}

