#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASUREMENT_COMMAND 0x2C06
#define CRC8_POLYNOMIAL 0x31
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_connection();
int send_measurement_command(int handle);
int read_sensor_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc8(const uint8_t *data, int len);
float convert_to_celsius(uint16_t raw_temp);
int log_data(sensor_data_t data);
int log_error(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command to STS30
int send_measurement_command(int handle) {
    char cmd[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(handle, cmd, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from STS30
int read_sensor_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw temperature data to Celsius
float convert_to_celsius(uint16_t raw_temp) {
    return -45.0 + 175.0 * (raw_temp / 65535.0);
}

// Log data to file
int log_data(sensor_data_t data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    struct tm *tm_info = localtime(&data.timestamp);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(fp, "%s,%.2f\n", timestamp, data.temperature);
    fclose(fp);
    return 0;
}

// Log errors to file
int log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm_info = localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(fp, "%s,ERROR: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Send measurement command
        if (send_measurement_command(i2c_handle) != 0) {
            log_error("Failed to send measurement command");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        gpioDelay(15000); // Wait 15 ms for conversion

        // Read sensor data
        uint8_t data[3];
        if (read_sensor_data(i2c_handle, data, 3) != 0) {
            log_error("Failed to read sensor data");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Calculate CRC-8 checksum
        uint8_t crc = calculate_crc8(data, 2);
        if (crc != data[2]) {
            log_error("CRC checksum mismatch");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Convert raw temperature to Celsius
        uint16_t raw_temp = (data[0] << 8) | data[1];
        float temperature = convert_to_celsius(raw_temp);

        // Get current timestamp
        time_t now = time(NULL);

        // Create sensor data struct
        sensor_data_t sensor_data = {temperature, now};

        // Log data
        if (log_data(sensor_data) != 0) {
            log_error("Failed to log data");
        }

        printf("Temperature: %.2f °C\n", temperature);

        gpioDelay(5000); // Wait 5 seconds before next reading
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

