    if (crc8(pressure_data, 2) != pressure_crc) {
        fprintf(stderr, "Error: CRC check failed for pressure data\n");
        sensor_data.pressure = -999.0; // Indicate error
    } else {
        sensor_data.pressure = (float)raw_pressure / SCALE_FACTOR;
