                uint16_t raw_humidity = (buf[3] << 8) | buf[4];

                *temperature = 175.72 * raw_temperature / 65536.0 - 46.85;
                *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

                return 0; // Success
            } else {
                fprintf(stderr, "Error reading sensor data (attempt %d): %d\n", i + 1, result);
            }
        } else {
            fprintf(stderr, "Error writing to sensor (attempt %d): %d\n", i + 1, result);
        }
        gpioDelay(100); // Wait before retrying
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to add a reading to the circular buffer
void add_reading(CircularBuffer *buffer, float temperature, float humidity) {
    time(&buffer->buffer[buffer->head].timestamp);
    buffer->buffer[buffer->head].temperature = temperature;
    buffer->buffer[buffer->head].humidity = humidity;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to print the contents of the circular buffer
void print_buffer(CircularBuffer *buffer) {
    printf("\n--- Sensor Readings ---\n");
    for (int i = 0; i < buffer->count; ++i) {
        int index = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&buffer->buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp_str, buffer->buffer[index].temperature, buffer->buffer[index].humidity);
    }
    printf("--- End of Readings ---\n\n");
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else if (temperature < HUMID_THRESHOLD) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&reading_buffer);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&temperature, &humidity) == 0) {
            add_reading(&reading_buffer, temperature, humidity);
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data. Skipping fan control.\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

