// CRC-8 checksum calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to send a command to the SCD40
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Function to read data from the SCD40
int read_data(int handle, uint8_t *data, int len) {
    int result = i2cReadDevice(handle, (char *)data, len);
    if (result != len) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to process sensor data
int process_sensor_data(const uint8_t *data, sensor_data_t *sensor_data) {
    // Extract CO2, temperature, and humidity values
    sensor_data->co2 = (data[0] << 8) | data[1];
    int16_t temp_raw = (data[3] << 8) | data[4];
    int16_t hum_raw = (data[6] << 8) | data[7];

    // CRC check for CO2
    uint8_t co2_data[2] = {data[0], data[1]};
    uint8_t co2_crc = crc8(co2_data, 2);
    if (co2_crc != data[2]) {
        fprintf(stderr, "CRC check failed for CO2\n");
        return -1;
    }

    // CRC check for temperature
    uint8_t temp_data[2] = {data[3], data[4]};
    uint8_t temp_crc = crc8(temp_data, 2);
    if (temp_crc != data[5]) {
        fprintf(stderr, "CRC check failed for temperature\n");
        return -1;
    }

    // CRC check for humidity
    uint8_t hum_data[2] = {data[6], data[7]};
    uint8_t hum_crc = crc8(hum_data, 2);
    if (hum_crc != data[8]) {
        fprintf(stderr, "CRC check failed for humidity\n");
        return -1;
    }

