    if (send_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SCD40 started periodic measurement\n");

    // Main loop
    while (!terminate) {
        // Wait for data ready flag (0xE4B8)
        char data_ready_buf[2];
        data_ready_buf[0] = 0xE4;
        data_ready_buf[1] = 0xB8;
        int result = i2cWriteDevice(i2c_handle, data_ready_buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error writing data ready flag: %d\n", result);
            break; // Exit loop on error
        }
        gpioDelay(10); // Small delay to allow the sensor to respond

        // Read data (0xEC05)
        uint8_t data[9];
        if (send_command(i2c_handle, CMD_READ_MEASUREMENT) != 0) {
            fprintf(stderr, "Failed to read measurement\n");
            break; // Exit loop on error
        }
        gpioDelay(10); // Small delay to allow the sensor to respond

        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Failed to read data\n");
            break; // Exit loop on error
        }

        // Process sensor data
        sensor_data_t sensor_data;
        if (process_sensor_data(data, &sensor_data) != 0) {
            fprintf(stderr, "Failed to process sensor data\n");
            break; // Exit loop on error
        }

        // Log sensor data
        log_sensor_data(&sensor_data);

        printf("CO2: %d ppm, Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.co2, sensor_data.temperature, sensor_data.humidity);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Stop periodic measurement
    if (send_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("SCD40 stopped periodic measurement and terminated\n");

    return 0;
}

