#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define LED_GPIO 17
#define BUFFER_SIZE 20
#define CO2_THRESHOLD 1000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    time_t timestamp;
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

// Circular buffer
sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_scd40();
int start_periodic_measurement();
int get_data_ready_status();
int read_measurement(uint16_t *co2, uint16_t *temperature, uint16_t *humidity);
uint8_t crc8(const uint8_t *data, int len);
void add_to_buffer(uint16_t co2, uint16_t temperature, uint16_t humidity);
void print_buffer();
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize SCD40 sensor
int init_scd40() {
    // Start periodic measurement command
    uint8_t start_cmd[2] = {0x21, 0xB1};
    int result = i2cWriteDevice(i2c_handle, (char *)start_cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting periodic measurement: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to start
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    uint8_t start_cmd[2] = {0x21, 0xB1};
    int result = i2cWriteDevice(i2c_handle, (char *)start_cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting periodic measurement: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to start
    return 0;
}

// Get data ready status
int get_data_ready_status() {
    uint8_t status_cmd[2] = {0xE4, 0xB8};
    uint8_t status_data[2];
    int result = i2cWriteDevice(i2c_handle, (char *)status_cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing status command: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Small delay after writing the command
    result = i2cReadDevice(i2c_handle, (char *)status_data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading status data: %d\n", result);
        return -1;
    }
    return (status_data[0] & 0x01);
}

// Read measurement data
int read_measurement(uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    uint8_t read_cmd[2] = {0xEC, 0x05};
    uint8_t read_data[9];
    int result = i2cWriteDevice(i2c_handle, (char *)read_cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing read command: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Small delay after writing the command
    result = i2cReadDevice(i2c_handle, (char *)read_data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading measurement data: %d\n", result);
        return -1;
    }

    // CRC Check
    if (crc8(read_data, 2) != read_data[2] || crc8(read_data + 3, 2) != read_data[5] || crc8(read_data + 6, 2) != read_data[8]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Extract data
    *co2 = (read_data[0] << 8) | read_data[1];
    *temperature = (read_data[3] << 8) | read_data[4];
    *humidity = (read_data[6] << 8) | read_data[7];

    return 0;
}

// Add data to circular buffer
void add_to_buffer(uint16_t co2, uint16_t temperature, uint16_t humidity) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].co2 = co2;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print circular buffer contents
void print_buffer() {
    printf("\n--- Sensor Readings ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&circular_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n",
               timestamp_str, circular_buffer[index].co2, (float)circular_buffer[index].temperature / 10.0, (float)circular_buffer[index].humidity / 10.0);
    }
    printf("--- End of Readings ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SCD40 sensor
    if (init_scd40() != 0) {
        fprintf(stderr, "SCD40 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t co2, temperature, humidity;

    // Main loop
    while (!terminate) {
        // Start periodic measurement
        if (start_periodic_measurement() != 0) {
            fprintf(stderr, "Failed to start periodic measurement, retrying...\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Wait for data ready status
        int data_ready = 0;
        int timeout_count = 0;
        while (!data_ready && !terminate) {
            data_ready = get_data_ready_status();
            if (data_ready != 0) {
                fprintf(stderr, "Error getting data ready status, retrying...\n");
                gpioDelay(100); // Wait before retrying
                timeout_count++;
                if (timeout_count > 100) {
                    fprintf(stderr, "Timeout waiting for data ready status\n");
                    break;
                }
