    i2cWriteDevice(i2c_handle, (char *)stop_cmd, 2);
    gpioDelay(100); // Wait for the sensor to stop

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

