#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TMP05_PIN 4
#define PWM_FREQUENCY 1000 // 1 kHz

// Define PWM range
#define PWM_RANGE 1000000 // 1 ms

// Define log file name
#define LOG_FILE "temperature_log.txt"

// Define error log file name
#define ERROR_LOG_FILE "error_log.txt"

// Define timeout duration (in microseconds)
#define TIMEOUT_DURATION 50000 // 50 ms

// Define consecutive error threshold
#define CONSECUTIVE_ERROR_THRESHOLD 3

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;
static int consecutive_errors = 0;

// Function prototypes
int initialize_gpio();
int read_pwm_data(int gpio, int *high_time, int *total_time);
float convert_to_celsius(int high_time, int total_time);
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);

// Structure to hold PWM data
typedef struct {
    int high_time;
    int total_time;
} pwm_data_t;

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TMP05_PIN, PI_INPUT); // Set GPIO4 as input
    gpioSetPWMfrequency(TMP05_PIN, PWM_FREQUENCY); // Set PWM frequency
    gpioSetPWMrange(TMP05_PIN, PWM_RANGE); // Set PWM range

    return 0;
}

// Function to read PWM data
int read_pwm_data(int gpio, int *high_time, int *total_time) {
    struct timespec start, end;
    long long start_time, end_time;
    int timeout = 0;

    // Wait for the rising edge of the PWM signal
    while (gpioRead(gpio) == 0 && timeout < TIMEOUT_DURATION) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= TIMEOUT_DURATION) {
        return -1; // Timeout occurred
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    start_time = start.tv_sec * 1000000000LL + start.tv_nsec;

    // Wait for the falling edge of the PWM signal
    timeout = 0;
    while (gpioRead(gpio) == 1 && timeout < TIMEOUT_DURATION) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= TIMEOUT_DURATION) {
        return -1; // Timeout occurred
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    end_time = end.tv_sec * 1000000000LL + end.tv_nsec;

    *high_time = (int)(end_time - start_time);
    *total_time = (int)(end_time - start_time);

    return 0; // Success
}

// Function to convert PWM data to temperature (degrees Celsius)
float convert_to_celsius(int high_time, int total_time) {
    if (total_time == 0) {
        return -999.0; // Indicate division by zero
    }

    float temperature = 4215.0 - (2143.0 * (float)high_time / (float)total_time);

    // Validate temperature range
    if (temperature < -40.0 || temperature > 150.0) {
        return -998.0; // Indicate out-of-range temperature
    }

    return temperature;
}

// Function to log temperature to file
int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Function to log errors to file
int log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (error_log_file != NULL) {
        fprintf(error_log_file, "%s, ERROR: %s\n", timestamp, message);
        fflush(error_log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Error log file is not open.\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int high_time, total_time;
    float temperature;
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Error opening error log file: %s\n", ERROR_LOG_FILE);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        consecutive_errors = 0; // Reset consecutive errors on each iteration

        // Read PWM data
        result = read_pwm_data(TMP05_PIN, &high_time, &total_time);

        if (result == 0) {
            // Convert to temperature
            temperature = convert_to_celsius(high_time, total_time);

            // Log temperature
            if (temperature != -999.0) {
                if (log_temperature(temperature) != 0) {
                    log_error("Failed to log temperature.");
                }
            } else {
                log_error("Invalid temperature reading.");
            }
        } else {
            consecutive_errors++;
            log_error("Failed to read PWM data.");
        }

        // Check for consecutive errors
        if (consecutive_errors >= CONSECUTIVE_ERROR_THRESHOLD) {
            log_error("Sensor malfunction detected.");
            consecutive_errors = 0; // Reset after logging
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close error log file
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

