    data->temperature += SINUSOIDAL_OFFSET_TEMP * sin(2 * M_PI * time(NULL) / 3600.0);
    data->humidity += SINUSOIDAL_OFFSET_HUM * sin(2 * M_PI * time(NULL) / 3600.0);
