#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_HOLD 0xF5
#define MEASURE_HUMIDITY_HOLD 0xF3
#define MEASURE_TEMP_HOLD_CMD 0xE0
#define RESET_CMD 0xFE
#define LOG_FILE "environment.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define MAX_TIMEOUT_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *bus);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int i2c_close(int fd);
int read_sensor_data(int fd, sensor_data_t *data);
int log_data(const char *timestamp, float temperature, float humidity);
void signal_handler(int sig);
int reset_sensor(int fd);

// CRC-8 checksum calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t buf[3];
    int retries = 0;
    int delay_ms = RETRY_DELAY_MS;

    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(fd, MEASURE_TEMP_HOLD_CMD, 0) < 0) {
            fprintf(stderr, "Error writing temperature measurement command (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            continue;
        }

        usleep(10000); // Wait for measurement (datasheet specifies 10ms)

        if (i2c_read_bytes(fd, 0, buf, 3) < 0) {
            fprintf(stderr, "Error reading temperature and humidity data (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            continue;
        }

        // CRC check
        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC check failed (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            continue;
        }

        // Convert raw data
        uint16_t raw_temperature = (buf[0] << 8) | buf[1];
        uint16_t raw_humidity = (buf[2] << 8) | buf[3];

        data->temperature = 175.72 * raw_temperature / 65536.0 - 46.85;
        data->humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Log data function
int log_data(const char *timestamp, float temperature, float humidity) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Reset sensor function
int reset_sensor(int fd) {
    if (i2c_write_byte(fd, RESET_CMD, 0) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    usleep(100000); // Wait for reset to complete (datasheet specifies 100ms)
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2c_close(i2c_fd);
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log data
            if (log_data(timestamp, sensor_data.temperature, sensor_data.humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            printf("Timestamp: %s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, sensor_data.temperature, sensor_data.humidity);
        } else {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log error
            if (log_data(timestamp, -999.0, -999.0) != 0) {
                fprintf(stderr, "Error logging error\n");
            }

            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    if (i2c_close(i2c_fd) != 0) {
        fprintf(stderr, "Error closing I2C device during cleanup\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

