        i2c_close(i2c_fd);
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log data
            if (log_data(timestamp, sensor_data.temperature, sensor_data.humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            printf("Timestamp: %s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, sensor_data.temperature, sensor_data.humidity);
        } else {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log error
            if (log_data(timestamp, -999.0, -999.0) != 0) {
                fprintf(stderr, "Error logging error\n");
            }

            fprintf(stderr, "Error reading sensor data\n");
        }

