        sleep(5);
    }

    // Cleanup
    if (i2c_close(i2c_fd) != 0) {
        fprintf(stderr, "Error closing I2C device during cleanup\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

