#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASUREMENT_COMMAND 0x362F
#define SCALE_FACTOR_PRESSURE 60.0
#define SCALE_FACTOR_TEMPERATURE 200.0
#define PRESSURE_OFFSET -1000.0
#define TEMPERATURE_OFFSET -45.0
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int write_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t crc8(const uint8_t *data, int len);
sensor_data_t convert_data(uint8_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write a command to the SDP810 sensor
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the SDP810 sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    sensor_data.pressure = (float)raw_pressure / SCALE_FACTOR_PRESSURE - PRESSURE_OFFSET;
    sensor_data.temperature = (float)raw_temperature / SCALE_FACTOR_TEMPERATURE - TEMPERATURE_OFFSET;

    return sensor_data;
}

// Log data to a file
int log_data(FILE *fp, sensor_data_t data) {
    if (fwrite(&data.pressure, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing pressure to file\n");
        return -1;
    }
    if (fwrite(&data.temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing temperature to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow.dat", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Write measurement command
        if (write_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Error writing measurement command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for conversion time (adjust as needed based on sensor datasheet)
        gpioDelay(20); // 20 ms conversion time

        // Read data
        uint8_t data[9];
        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // CRC check for pressure
        if (crc8(data, 2) != data[2]) {
            fprintf(stderr, "CRC check failed for pressure\n");
            continue;
        }

        // CRC check for temperature
        if (crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "CRC check failed for temperature\n");
            continue;
        }

        // Convert data
        sensor_data_t sensor_data = convert_data(data);

        // Log data
        if (log_data(log_file, sensor_data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Print data to console
        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", sensor_data.pressure, sensor_data.temperature);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Convert seconds to milliseconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

