#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASUREMENT_COMMAND 0x3603
#define SCALE_FACTOR 60.0
#define LOG_FILE "pressure_log.txt"
#define SLEEP_DURATION_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    int16_t status;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP800 sensor
int read_sdp800(sensor_data_t *data) {
    char buf[9];
    int result;

    // Send measurement command
    result = i2cWriteWordData(i2c_handle, 0, MEASUREMENT_COMMAND);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    // Wait for conversion (45 ms)
    gpioDelay(45000); // 45 ms

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Validate CRC for pressure data
    uint8_t pressure_data[3] = {buf[0], buf[1], buf[2]};
    uint8_t pressure_crc = buf[3];
    if (crc8(pressure_data, 3) != pressure_crc) {
        fprintf(stderr, "CRC error for pressure data\n");
        return -1;
    }

    // Validate CRC for temperature data
    uint8_t temperature_data[3] = {buf[3], buf[4], buf[5]};
    uint8_t temperature_crc = buf[6];
    if (crc8(temperature_data, 3) != temperature_crc) {
        fprintf(stderr, "CRC error for temperature data\n");
        return -1;
    }

    // Validate CRC for status data
    uint8_t status_data[3] = {buf[6], buf[7], buf[8]};
    uint8_t status_crc = buf[9];
    if (crc8(status_data, 3) != status_crc) {
        fprintf(stderr, "CRC error for status data\n");
        return -1;
    }

    // Extract raw pressure and temperature values
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[3] << 8) | buf[4];

    // Convert raw values to physical units
    data->pressure = (int16_t)((float)raw_pressure / SCALE_FACTOR);
    data->temperature = raw_temperature;
    data->status = (int16_t)((buf[6] << 8) | buf[7]);

    return 0;
}

// Function to log data to a file
void log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Pressure: %.2f Pa, Temperature: %.2f C, Status: 0x%04X\n",
            timestamp, (float)data.pressure / SCALE_FACTOR, (float)data.temperature / 200.0, data.status);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sdp800(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Sleep for 5 seconds
        gpioDelay(SLEEP_DURATION_SEC * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

