#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5D

// LPS33HW register addresses
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C
#define WHO_AM_I 0x0F

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_register(int handle, uint8_t reg, uint8_t *value);
int write_register(int handle, uint8_t reg, uint8_t value);
int read_pressure(int handle, int32_t *pressure);
int read_temperature(int handle, int16_t *temperature);
void convert_pressure(int32_t raw_pressure, float *pressure);
void convert_temperature(int16_t raw_temperature, float *temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data;

        // Read pressure and temperature
        if (read_pressure(i2c_handle, &sensor_data.pressure) == 0 &&
            read_temperature(i2c_handle, &sensor_data.temperature) == 0) {
            // Convert raw data to physical units
            convert_pressure((int32_t)sensor_data.pressure, &sensor_data.pressure);
            convert_temperature((int16_t)sensor_data.temperature, &sensor_data.temperature);

            // Log the data
            log_data(sensor_data.pressure, sensor_data.temperature);
        } else {
            // Log error to file
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s, Error reading sensor data\n", timestamp);
            fflush(log_file);
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpioDelay takes milliseconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // Bus 1, address 0x5D, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Check WHO_AM_I register
    uint8_t who_am_i;
    if (read_register(i2c_handle, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        i2cClose(i2c_handle);
        return 1;
    }

    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0xB1\n", who_am_i);
        i2cClose(i2c_handle);
        return 1;
    }

    // Configure CTRL_REG1 (ODR = 10 Hz, Block Data Update, Active Mode)
    if (write_register(i2c_handle, CTRL_REG1, 0xB0) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read a single byte from an I2C register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return 1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return 1;
    }
    return 0;
}

// Read pressure data from the LPS33HW
int read_pressure(int handle, int32_t *pressure) {
    uint8_t buffer[3];
    int result = i2cReadI2CBlockData(handle, PRESS_OUT_XL, (char *)buffer, 3);
    if (result < 0) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return 1;
    }

    *pressure = (int32_t)((((uint32_t)buffer[2]) << 16) | (((uint32_t)buffer[1]) << 8) | (uint32_t)buffer[0]);
    *pressure = *pressure >> 8; // Shift right by 8 bits
    return 0;
}

// Read temperature data from the LPS33HW
int read_temperature(int handle, int16_t *temperature) {
    uint8_t buffer[2];
    int result = i2cReadI2CBlockData(handle, TEMP_OUT_L, (char *)buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return 1;
    }

    *temperature = (int16_t)((((uint16_t)buffer[1]) << 8) | (uint16_t)buffer[0]);
    return 0;
}

// Convert raw pressure data to hPa
void convert_pressure(int32_t raw_pressure, float *pressure) {
    *pressure = (float)raw_pressure / 4096.0;
}

// Convert raw temperature data to Celsius
void convert_temperature(int16_t raw_temperature, float *temperature) {
    *temperature = 42.5 + (float)raw_temperature / 480.0;
}

// Log data to file
void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

