// Constants
#define I2C_BUS 1
#define SCD30_ADDR 0x61
#define MEASUREMENT_INTERVAL 2 // seconds
#define LOG_FILE "air_quality.log"
#define CO2_THRESHOLD_LOW 800
#define CO2_THRESHOLD_MED 1199
#define CO2_THRESHOLD_HIGH 1200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int initialize_scd30();
int read_scd30_data(sensor_data_t *data);
int validate_checksum(const unsigned char *data, int len);
int log_data(const sensor_data_t *data);
void control_ventilation(float co2);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize SCD30 sensor
int initialize_scd30() {
    // Send command to start periodic measurement with ambient pressure compensation disabled
    unsigned char cmd[2] = {0x21, 0xb1};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write to SCD30\n");
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to initialize

    // Send command to set measurement interval
    cmd[0] = 0x21;
    cmd[1] = 0xb2;
    unsigned char interval[2] = {(MEASUREMENT_INTERVAL >> 8) & 0xFF, MEASUREMENT_INTERVAL & 0xFF};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write to SCD30\n");
        return -1;
    }
    if (i2cWriteDevice(i2c_handle, interval, 2) != 2) {
        fprintf(stderr, "Failed to write to SCD30\n");
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to initialize

    return 0;
}

// Read data from SCD30 sensor
int read_scd30_data(sensor_data_t *data) {
    unsigned char cmd[2] = {0x03, 0x00};
    unsigned char buffer[18];

    // Send command to read measurement
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write to SCD30\n");
        return -1;
    }

    gpioDelay(100); // Wait for measurement to complete

    // Read 18 bytes of data
    if (i2cReadDevice(i2c_handle, buffer, 18) != 18) {
        fprintf(stderr, "Failed to read from SCD30\n");
        return -1;
    }

    // Validate checksums
    if (!validate_checksum(buffer, 4) || !validate_checksum(buffer + 4, 4) || !validate_checksum(buffer + 8, 4) ||
        !validate_checksum(buffer + 12, 4) || !validate_checksum(buffer + 16, 4)) {
        fprintf(stderr, "Checksum validation failed\n");
        return -1;
    }

    // Extract CO2, temperature, and humidity
    data->co2 = (float)((buffer[0] << 8) | buffer[1]);
    data->temperature = -45 + 175 * ((float)((buffer[3] << 8) | buffer[4])) / 65535.0;
    data->humidity = 100 * ((float)((buffer[6] << 8) | buffer[7])) / 65535.0;

    return 0;
}

// Validate CRC checksum
int validate_checksum(const unsigned char *data, int len) {
    unsigned char crc = crc8(data, len - 1);
    return crc == data[len - 1];
}

// Log data to file
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data->co2, data->temperature, data->humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Control ventilation system based on CO2 level
void control_ventilation(float co2) {
    if (co2 < CO2_THRESHOLD_LOW) {
        printf("Ventilation: OFF\n");
    } else if (co2 < CO2_THRESHOLD_MED) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Initialize SCD30 sensor
    if (initialize_scd30() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_scd30_data(&sensor_data) == 0) {
            // Log data
            log_data(&sensor_data);

            // Control ventilation
            control_ventilation(sensor_data.co2);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next measurement interval
        sleep(MEASUREMENT_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

