// Constants
#define I2C_BUS 1
#define SDP32_ADDR 0x21
#define SAMPLE_INTERVAL_MS 1000
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int init_i2c();
int start_measurement();
int read_sensor_data(uint8_t *data);
uint8_t crc8(const uint8_t *data, int len);
sensor_data_t convert_data(const uint8_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Start continuous measurement
int start_measurement() {
    uint8_t cmd[2] = {0x36, 0x2F};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw data to physical units
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t raw_scale_factor = (data[6] << 8) | data[7];

    // CRC check for pressure
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Pressure CRC check failed\n");
        sensor_data.pressure_pa = -999.0; // Indicate error
    } else {
        sensor_data.pressure_pa = (float)raw_pressure / raw_scale_factor;
    }

    // CRC check for temperature
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        sensor_data.temperature_c = -999.0; // Indicate error
    } else {
        sensor_data.temperature_c = (float)raw_temperature / 200.0;
    }

    return sensor_data;
