#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// HDC1000 I2C address
#define HDC1000_ADDR 0x40

// HDC1000 register addresses
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define CONFIG_REG 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the HDC1000 sensor
int init_hdc1000() {
    // Configure the HDC1000 for temperature and humidity measurement
    // Set configuration register to 0x0000 (14-bit resolution, continuous measurement)
    char config_data[2];
    config_data[0] = CONFIG_REG;
    config_data[1] = 0x00;

    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity from the HDC1000 sensor
int read_hdc1000(float *temperature, float *humidity) {
    char temp_data[1];
    char humid_data[1];
    char buffer[4];
    int result;

    // Write temperature register pointer to the sensor
    temp_data[0] = TEMP_REG;
    result = i2cWriteDevice(i2c_handle, temp_data, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature register pointer: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 20 ms)
    gpioDelay(20000); // 20 ms

    // Read 4 bytes from the sensor
    result = i2cReadDevice(i2c_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data from sensor: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temp = (buffer[0] << 8) | buffer[1];
    uint16_t raw_humidity = (buffer[2] << 8) | buffer[3];

    *temperature = ((float)raw_temp / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, HDC1000_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC1000 sensor
    if (init_hdc1000() != 0) {
        fprintf(stderr, "HDC1000 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read temperature and humidity
        if (read_hdc1000(&temperature, &humidity) == 0) {
            // Print temperature and humidity to the console
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

