#include <string.h>

// ICP-10101 I2C address
#define ICP10101_ADDR 0x63

// ICP-10101 register addresses
#define ICP10101_REG_WHO_AM_I 0x0F
#define ICP10101_REG_RESET 0x16
#define ICP10101_REG_MEASURE 0x40
#define ICP10101_REG_COEFF_START 0x31

// Calibration coefficients
int16_t scale_factor_lut, scale_factor_h, scale_factor_p;

// I2C handle
int i2c_handle;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to read calibration coefficients from the sensor
int read_calibration_coefficients(int handle) {
    uint8_t buffer[8];
    int result = i2cReadI2CBlockData(handle, ICP10101_REG_COEFF_START, (char *)buffer, 8);
    if (result < 0) {
        fprintf(stderr, "Error reading calibration coefficients: %d\n", result);
        return -1;
    }

    scale_factor_lut = (int16_t)((buffer[1] << 8) | buffer[0]);
    scale_factor_h = (int16_t)((buffer[3] << 8) | buffer[2]);
    scale_factor_p = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to trigger a high-precision measurement
int trigger_measurement(int handle) {
    int result = write_register(handle, ICP10101_REG_MEASURE, 0x01); // Trigger measurement
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(7); // Wait for measurement to complete (7 ms)
    return 0;
}

// Function to read raw temperature and pressure data
int read_raw_data(int handle, int16_t *raw_temperature, int32_t *raw_pressure) {
    uint8_t buffer[6];
    int result = i2cReadI2CBlockData(handle, ICP10101_REG_MEASURE, (char *)buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading raw data: %d\n", result);
        return -1;
    }

    *raw_temperature = (int16_t)((buffer[0] << 8) | buffer[1]);
    *raw_pressure = (int32_t)((buffer[2] << 16) | (buffer[3] << 8) | buffer[4]);

    return 0;
}

// Function to compensate temperature
float compensate_temperature(int16_t raw_temperature, int16_t scale_factor_lut) {
    // Placeholder implementation - replace with actual formula from datasheet
    return (float)raw_temperature / 100.0; // Example: Temperature in degrees Celsius
}

// Function to compensate pressure
float compensate_pressure(int32_t raw_pressure, int16_t scale_factor_h, int16_t scale_factor_p) {
    // Placeholder implementation - replace with actual formula from datasheet
    return (float)raw_pressure / 1000.0; // Example: Pressure in Pascals
}

// Function to log data with timestamp
void log_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check WHO_AM_I register
    int who_am_i = read_register(i2c_handle, ICP10101_REG_WHO_AM_I);
    if (who_am_i < 0 || who_am_i != 0x41) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x41\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients(i2c_handle) < 0) {
        fprintf(stderr, "Error reading calibration coefficients, exiting\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int16_t raw_temperature;
        int32_t raw_pressure;

        // Trigger measurement
        if (trigger_measurement(i2c_handle) < 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Read raw data
        if (read_raw_data(i2c_handle, &raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Error reading raw data, retrying...\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Compensate temperature and pressure
        float temperature = compensate_temperature(raw_temperature, scale_factor_lut);
        float pressure = compensate_pressure(raw_pressure, scale_factor_h, scale_factor_p);

        // Log data
        log_data(temperature, pressure);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

