    }
    gpioTerminate();
    exit(0);
}

// Function to read pressure from the MLX90819 sensor
int read_pressure(int i2c_fd, float *pressure) {
    char buf[2];
    int result;

    // Trigger a measurement by writing to the pressure register (0x00)
    result = i2cWriteByteData(i2c_fd, PRESSURE_MSB_REG, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error writing to pressure register: %d\n", result);
        return -1;
    }

    // Wait for a short period for the measurement to complete (adjust as needed)
    gpioDelay(10000); // 10 ms

    // Read the pressure data from the sensor
    result = i2cReadI2CBlockData(i2c_fd, PRESSURE_MSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }

    // Combine the MSB and LSB to form the raw pressure value
    int16_t raw_pressure = (buf[0] << 8) | buf[1];

    // Convert the raw pressure value to kPa
    *pressure = (float)raw_pressure * PRESSURE_SCALE_FACTOR;

    return 0;
}

