        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to read and log pressure values
    float pressure;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    while (1) {
        // Read the pressure value
