            // Get the current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Log the pressure value with the timestamp
            printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
        } else {
            // Log an error message if reading failed
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
            fprintf(stderr, "%s Error reading pressure\n", timestamp);
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

