#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define CMD_MEASURE 0x362F
#define LOG_FILE "pressure_log.txt"
#define SLEEP_MS 45

// Global variables
int i2c_fd = -1;
FILE *log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(int fd, int16_t *pressure, int16_t *temperature) {
    uint8_t cmd[2] = {(CMD_MEASURE >> 8) & 0xFF, CMD_MEASURE & 0xFF};
    uint8_t buffer[9];

    // Send measurement command
    if (write(fd, cmd, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (at least 45 ms)
    usleep(SLEEP_MS * 1000); // Convert ms to microseconds

    // Read 9 bytes of data
    if (read(fd, buffer, 9) != 9) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Validate CRC for pressure
    if (crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "Error: CRC for pressure invalid\n");
        return -1;
    }

    // Validate CRC for temperature
    if (crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "Error: CRC for temperature invalid\n");
        return -1;
    }

    // Convert raw data to signed integers
    *pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    *temperature = (int16_t)((buffer[3] << 8) | buffer[4]);

    return 0;
}

// Function to log data to a file
int log_data(FILE *fp, int16_t pressure, int16_t temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write data to file
    if (fprintf(fp, "%s,%d,%d\n", timestamp, pressure, temperature) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    int16_t pressure, temperature;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &pressure, &temperature) == 0) {
            // Log data
            if (log_data(log_fp, pressure, temperature) != 0) {
                fprintf(stderr, "Error logging data, continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, continuing...\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

