        cleanup();
        return 1;
    }

    uint16_t raw_pressure;
    float pressure;
    int status;

    // Main loop
    while (!terminate) {
        // Read pressure data
        status = read_pressure(&raw_pressure);
        if (status == 0) {
            // Convert pressure to kPa
            pressure = convert_pressure(raw_pressure);

            // Log pressure data
            status = log_pressure(pressure);
            if (status != 0) {
                fprintf(stderr, "Error logging pressure data\n");
            }

            // Check pressure range
            if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
                fprintf(stderr, "Warning: Pressure out of range: %.2f kPa\n", pressure);
            }
        } else {
