#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENT_CLK 4
#define SENT_DATA 17

// Define SENT protocol constants
#define SYNC_PULSE_WIDTH 56 // 3 us
#define STATUS_NIBBLE 0x00
#define DATA_NIBBLE_LENGTH 3
#define CHECKSUM_NIBBLE_LENGTH 1
#define MAX_PULSES 1000 // Maximum number of pulses to read

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold SENT data
typedef struct {
    int raw_value;
    float pressure;
    int status;
} SENTData;

// Function prototypes
int initialize_gpio();
int read_sent_data(SENTData *data);
int validate_checksum(int raw_value);
float convert_raw_to_pressure(int raw_value);
void log_pressure_reading(float pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the pigpio library and sets GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENT_CLK, PI_OUTPUT);
    gpioSetMode(SENT_DATA, PI_INPUT);

    return 0;
}

// Reads data from the SENT sensor
int read_sent_data(SENTData *data) {
    int i, pulse_width, pulse_count = 0;
    int raw_data[DATA_NIBBLE_LENGTH + CHECKSUM_NIBBLE_LENGTH];

    // Wait for the synchronization pulse
    while (gpioRead(SENT_DATA) == 1 && pulse_count < MAX_PULSES) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        pulse_count++;
    }
    if (pulse_count >= MAX_PULSES) {
        fprintf(stderr, "Timeout waiting for synchronization pulse\n");
        data->status = -1; // Timeout error
        return 1;
    }

    // Read the status nibble
    gpioDelay(SYNC_PULSE_WIDTH); // Wait for the status pulse width
    pulse_width = gpioRead(SENT_DATA);
    if (pulse_width != 0) {
        fprintf(stderr, "Error: Invalid status pulse width: %d\n", pulse_width);
        data->status = -2; // Bus error
        return 1;
    }

    // Read the data nibbles
    for (i = 0; i < DATA_NIBBLE_LENGTH; i++) {
        gpioDelay(SYNC_PULSE_WIDTH); // Wait for the data pulse width
        pulse_width = gpioRead(SENT_DATA);
        if (pulse_width != 0) {
            fprintf(stderr, "Error: Invalid data pulse width: %d\n", pulse_width);
            data->status = -3; // Bus error
            return 1;
        }
        raw_data[i] = pulse_width;
    }

    // Read the checksum nibble
