#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0078125
#define DATA_FILE "greenhouse_temps.dat"

// Global variables
int i2c_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_temperature(float *temperature);
int write_data_to_file(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117 sensor
int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }

    int16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = raw_temp * TEMP_SCALE;
    return 0;
}

// Write temperature data to file
int write_data_to_file(float temperature) {
    size_t bytes_written = fwrite(&temperature, sizeof(float), 1, data_file);
    if (bytes_written != 1) {
        fprintf(stderr, "Failed to write temperature data to file\n");
        return -1;
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open data file for writing
    data_file = fopen(DATA_FILE, "wb");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        cleanup();
        return 1;
    }

    float temperature;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_temperature(&temperature) == 0) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Write data to file
            if (write_data_to_file(temperature) != 0) {
                fprintf(stderr, "Failed to write data to file, continuing...\n");
            } else {
                printf("%s Temperature: %.4f °C\n", timestamp, temperature);
            }
        } else {
            fprintf(stderr, "Failed to read temperature, continuing...\n");
        }

        // Wait for 60 seconds
        gpioSleep(PI_TIME_RELATIVE, 60, 0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

