#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define LOG_FILE "environmental_data.txt"
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int write_command(int handle, uint8_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
sensor_data_t convert_data(const uint8_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// CRC calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to write a command to the SHT40
int write_command(int handle, uint8_t command) {
    int result = i2cWriteByte(handle, command);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the SHT40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw data to temperature and humidity
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    uint16_t raw_temp = (data[0] << 8) | data[1];
    uint16_t raw_hum = (data[3] << 8) | data[4];

    sensor_data.temperature = -45.0 + 175.0 * (raw_temp / 65535.0);
    sensor_data.humidity = -6.0 + 125.0 * (raw_hum / 65535.0);

    return sensor_data;
}

// Function to log data to a file
int log_data(const sensor_data_t *data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f °C, Humidity: %.2f %%RH\n", timestamp, data->temperature, data->humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        sensor_data_t sensor_data;

        // Write measurement command
        if (write_command(i2c_handle, MEASURE_HIGH_PRECISION) != 0) {
            fprintf(stderr, "Failed to write measurement command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for conversion (at least 8.5 ms)
        gpioDelay(10); // 10 ms

        // Read 6 bytes of data
        if (read_data(i2c_handle, data, 6) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC checksums
        if (calculate_crc(data, 2) != data[2] || calculate_crc(data + 3, 2) != data[5]) {
            fprintf(stderr, "CRC checksum error\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        sensor_data = convert_data(data);

        // Log data
        if (log_data(&sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

