#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for storing temperature readings
typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

// Circular buffer
TemperatureReading temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
float read_temperature();
void store_temperature(float temperature);
void flush_buffer_to_file();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117 sensor
float read_temperature() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw data to temperature (see TMP117 datasheet)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = raw_temp * 0.0078125;

    return temperature;
}

// Store temperature reading in circular buffer
void store_temperature(float temperature) {
    time(&temperature_buffer[buffer_index].timestamp);
    temperature_buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Flush the circular buffer to a file
void flush_buffer_to_file() {
    FILE *fp = fopen("temperature_log.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open temperature_log.dat for writing\n");
        return;
    }

    size_t elements_written = fwrite(temperature_buffer, sizeof(TemperatureReading), BUFFER_SIZE, fp);
    if (elements_written != BUFFER_SIZE) {
        fprintf(stderr, "Failed to write all elements to file\n");
    }

    fclose(fp);
    printf("Temperature log flushed to temperature_log.dat\n");
}

// Cleanup resources before exiting
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("pigpio terminated and I2C closed. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            store_temperature(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping this sample.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Flush buffer to file before exiting
    flush_buffer_to_file();

    // Cleanup resources
    cleanup();

    return 0;
}

