FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SHTC3 sensor
int read_shtc3(int i2c_handle, uint8_t *data) {
    char buf[2];
    int result;

    // Send measurement command
    buf[0] = (MEASUREMENT_COMMAND >> 8) & 0xFF;
    buf[1] = MEASUREMENT_COMMAND & 0xFF;
    result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 12.4 ms)
    gpioDelay(124000); // 124 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to validate CRC8 checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return 175.0 * (float)raw_temp / 65535.0 - 45.0;
}

// Function to convert raw humidity to relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Function to log data to file
void log_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        int result;

        // Read sensor data
        result = read_shtc3(i2c_handle, data);
        if (result == 0) {
            // Validate CRC for temperature
            if (validate_crc(data, 2)) {
                // Validate CRC for humidity
                if (validate_crc(data + 3, 2)) {
                    // Convert raw data to temperature and humidity
                    uint16_t raw_temp = (data[0] << 8) | data[1];
                    uint16_t raw_humidity = (data[3] << 8) | data[4];

                    float temperature = convert_temperature(raw_temp);
                    float humidity = convert_humidity(raw_humidity);

                    // Validate temperature and humidity
                    if (temperature >= -40.0 && temperature <= 125.0 && humidity >= 0.0 && humidity <= 100.0) {
                        // Log data
                        log_data(temperature, humidity);
                    } else {
                        fprintf(stderr, "Invalid temperature or humidity reading: Temperature=%.2f, Humidity=%.2f\n", temperature, humidity);
                    }
                } else {
                    fprintf(stderr, "CRC check failed for humidity data\n");
                }
            } else {
                fprintf(stderr, "CRC check failed for temperature data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // pigpioDelay takes microseconds
    }

    // Close I2C device and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

