#define FLOW_LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_rate;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the I2C interface
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data from the HAFUHH0025PA3
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[4];
    int result;

    // Read 4 bytes from the sensor
    result = i2cReadDevice(i2c_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        data.flow_rate = -1.0; // Indicate error
        data.temperature = -100.0; // Indicate error
        return data;
    }

    // Convert raw data to SLPM and Celsius
    int16_t raw_flow = (buffer[0] << 8) | buffer[1];
    int16_t raw_temp = (buffer[2] << 8) | buffer[3];

    data.flow_rate = ((raw_flow / 16384.0) - 0.1) / 0.8 * 25.0;
    data.temperature = ((raw_temp / 4096.0) - 0.1) / 0.8 * 80.0 - 40.0;

    return data;
}

// Function to log data to a file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (data.flow_rate >= 0.0 && data.temperature >= -40.0) {
        fprintf(log_file, "%s, Flow Rate: %.2f SLPM, Temperature: %.2f °C\n", timestamp, data.flow_rate, data.temperature);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Invalid sensor data. Skipping logging.\n");
    }
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

