    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

