#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT31D_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06
#define LOG_FILE "sht31d_data.log"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int write_command(int handle, unsigned short command);
int read_data(int handle, unsigned char *data, int count);
unsigned char calculate_crc(const unsigned char *data, int nbrOfBytes);
sensor_data_t convert_data(const unsigned char *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SHT31D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write command to SHT31-D
int write_command(int handle, unsigned short command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from SHT31-D
int read_data(int handle, unsigned char *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
unsigned char calculate_crc(const unsigned char *data, int nbrOfBytes) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw data to temperature and humidity
sensor_data_t convert_data(const unsigned char *data) {
    sensor_data_t sensor_data;
    unsigned short temperature_raw = (data[0] << 8) | data[1];
    unsigned short humidity_raw = (data[3] << 8) | data[4];

    sensor_data.temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return sensor_data;
}

// Log data to file
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("SHT31-D data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        unsigned char data[6];
        int retries = 0;
        int read_success = 0;

        // Write measurement command
        if (write_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Failed to write measurement command, retrying...\n");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Wait for measurement (at least 15 ms)
        gpioDelay(20000); // 20 ms

        // Read data with retries
        while (retries < RETRY_COUNT && !read_success) {
            if (read_data(i2c_handle, data, 6) == 0) {
                read_success = 1;
            } else {
                fprintf(stderr, "Failed to read data, retrying (%d/%d)...\n", retries + 1, RETRY_COUNT);
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (!read_success) {
            fprintf(stderr, "Failed to read data after %d retries\n", RETRY_COUNT);
            // Log the error to the log file
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
            fprintf(log_file, "%s,ERROR,Failed to read data after %d retries\n", timestamp, RETRY_COUNT);
            fflush(log_file);
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC for temperature
        if (calculate_crc(data, 2) != data[2]) {
            fprintf(stderr, "Temperature CRC check failed\n");
            // Log the error to the log file
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
            fprintf(log_file, "%s,ERROR,Temperature CRC check failed\n", timestamp);
            fflush(log_file);
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC for humidity
        if (calculate_crc(data + 3, 2) != data[5]) {
            fprintf(stderr, "Humidity CRC check failed\n");
            // Log the error to the log file
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
            fprintf(log_file, "%s,ERROR,Humidity CRC check failed\n", timestamp);
            fflush(log_file);
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        sensor_data_t sensor_data = convert_data(data);

        // Log data
        if (log_data(&sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

