            // Log the error to the log file
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
            fprintf(log_file, "%s,ERROR,Temperature CRC check failed\n", timestamp);
            fflush(log_file);
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC for humidity
        if (calculate_crc(data + 3, 2) != data[5]) {
            fprintf(stderr, "Humidity CRC check failed\n");
            // Log the error to the log file
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
            fprintf(log_file, "%s,ERROR,Humidity CRC check failed\n", timestamp);
            fflush(log_file);
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        sensor_data_t sensor_data = convert_data(data);

        // Log data
        if (log_data(&sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

