#define TEMPERATURE_REG 0x0A2E
#define PRESSURE_MIN 0
#define PRESSURE_MAX 32768
#define TEMPERATURE_MIN -40.0
#define TEMPERATURE_MAX 125.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int raw_pressure;
    int raw_temperature;
    float pressure_kPa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int initialize();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the pigpio library and I2C interface
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

