        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Reads raw pressure and temperature data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buf[4];

    // Read pressure data
    if (i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2) != 2) {
        fprintf(stderr, "Failed to read pressure data\n");
        data.raw_pressure = -1; // Indicate error
    } else {
        data.raw_pressure = (buf[0] << 8) | buf[1];
    }

    // Read temperature data
    if (i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf, 2) != 2) {
        fprintf(stderr, "Failed to read temperature data\n");
        data.raw_temperature = -1; // Indicate error
    } else {
        data.raw_temperature = (buf[0] << 8) | buf[1];
    }

    return data;
}

// Converts raw pressure to kPa
float convert_pressure(int raw_pressure) {
    return (raw_pressure - PRESSURE_MIN) * (PRESSURE_MAX - PRESSURE_MIN) / (PRESSURE_MAX - PRESSURE_MIN);
}

// Converts raw temperature to Celsius
float convert_temperature(int raw_temperature) {
    return raw_temperature * 0.01 - TEMPERATURE_MIN;
}

