    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (data.raw_pressure != -1 && data.raw_temperature != -1) {
        fprintf(log_file, "%s, Raw Pressure: %d, Raw Temperature: %d, Pressure: %.2f kPa, Temperature: %.2f °C\n",
                timestamp, data.raw_pressure, data.raw_temperature, data.pressure_kPa, data.temperature_C);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(log_file, "%s, Error reading sensor data\n", timestamp);
        fflush(log_file);
    }
}

// Cleans up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("Tire Pressure Monitoring System started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        if (data.raw_pressure != -1 && data.raw_temperature != -1) {
            data.pressure_kPa = convert_pressure(data.raw_pressure);
            data.temperature_C = convert_temperature(data.raw_temperature);
            log_data(data);
        } else {
            fprintf(stderr, "Failed to read sensor data, skipping logging.\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    cleanup();
    return 0;
}

