#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define TEMP_REG 0x00
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_i2c();
float read_temperature();
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_fan(float average_temp);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read the temperature from the LM75B sensor
float read_temperature() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate an error with a very low temperature
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Extract the 9-bit temperature value (ignoring the status bits)
    raw_temp = raw_temp >> 5;

    // Convert the raw temperature to Celsius (0.5 degrees Celsius per LSB)
    float temperature = raw_temp * 0.5;

    return temperature;
}

// Control the cooling fan based on the average temperature
void control_fan(float average_temp) {
    if (average_temp > TEMP_THRESHOLD_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else if (average_temp < TEMP_THRESHOLD_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output for the fan
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize the circular buffer
    CircularBuffer temp_buffer;
    init_circular_buffer(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            // Add temperature to the circular buffer
            add_to_buffer(&temp_buffer, temperature);

            // Calculate the average temperature
            float average_temp = calculate_average(&temp_buffer);

            // Control the cooling fan
            control_fan(average_temp);

            // Print the temperature and average temperature
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temp);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping this cycle.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

