#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASUREMENT_COMMAND 0x362F
#define SCALE_FACTOR_PRESSURE 60.0
#define SCALE_FACTOR_TEMPERATURE 200.0
#define LOG_FILE "airflow.log"
#define WARNING_THRESHOLD 5.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, int16_t *pressure, int16_t *temperature, uint8_t *status) {
    char buf[9];
    int result = i2cReadDevice(i2c_handle, buf, 9);

    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // CRC validation
    if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5] || crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert raw data
    *pressure = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    *status = buf[6];

    return 0;
}

// Function to log data to a file
void log_data(FILE *log_file, int16_t pressure, int16_t temperature, uint8_t status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%d,%d,%d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, pressure, temperature, status);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to print a warning if pressure exceeds the threshold
void check_pressure_threshold(int16_t pressure) {
    if (pressure > WARNING_THRESHOLD * 1000) { // Convert Pa to Pa
        fprintf(stderr, "WARNING: Pressure exceeds threshold (%.2f Pa > %.2f Pa)\n", pressure / 1000.0, WARNING_THRESHOLD);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C),Status\n");
    }
    rewind(log_file);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t pressure, temperature;
    uint8_t status;
    while (!terminate) {
        // Send continuous measurement command
        char cmd[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
        int result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d\n", result);
            break;
        }

