#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
void control_led(float temperature);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for grouping sensor data
typedef struct {
    float temperature;
    int led_state;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STTS2004_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Read temperature from the sensor
int read_temperature(float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
        if (result == 2) {
            // Combine MSB and LSB, right-shift by 4 bits, and convert to Celsius
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            *temperature = (float)raw_temp >> 4 * 0.0625;
            return 0; // Success
        } else {
            log_error("I2C read failed");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    return -1; // Failure after retries
}

// Control the LED based on temperature
void control_led(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Log errors to stderr
void log_error(const char *message) {
    fprintf(stderr, "Error: %s (errno: %d, %s)\n", message, errno, strerror(errno));
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_temperature(&sensor_data.temperature) == 0) {
            printf("Temperature: %.2f °C\n", sensor_data.temperature);
            control_led(sensor_data.temperature);
        } else {
            log_error("Failed to read temperature, retrying...");
        }

        gpioDelay(1000 * 1000); // Delay for 1 second (1000 milliseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

