#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP800_ADDR 0x25

// Define the continuous measurement command
#define CONTINUOUS_MEASUREMENT_CMD 0x362F

// Define the scale factor data register address
#define SCALE_FACTOR_REG 0x31

// Define the number of bytes to read from the sensor
#define NUM_BYTES_TO_READ 9

// Global variables for I2C handle and program state
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t differential_pressure;
    int16_t temperature;
    int16_t scale_factor;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(uint16_t command);
int read_sensor_data(uint8_t *data);
int validate_crc8(const uint8_t *data, int len);
int convert_data(const uint8_t *data, sensor_data_t *sensor_data);
int log_data(const sensor_data_t *sensor_data);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the I2C interface
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the sensor
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read data from the sensor
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, NUM_BYTES_TO_READ);
    if (result != NUM_BYTES_TO_READ) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to validate CRC-8 checksum
int validate_crc8(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Function to convert raw data to physical units
int convert_data(const uint8_t *data, sensor_data_t *sensor_data) {
    // Extract scale factor from the last 16 bits of the scale factor register
    sensor_data->scale_factor = (int16_t)((data[6] << 8) | data[7]);

    // Extract differential pressure and temperature from the first 6 bytes
    sensor_data->differential_pressure = (int16_t)((data[0] << 8) | data[1]);
    sensor_data->temperature = (int16_t)((data[3] << 8) | data[4]);

    return 0;
}

// Function to log data to a file
int log_data(const sensor_data_t *sensor_data) {
    FILE *fp = fopen("flow_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Differential Pressure: %d Pa, Temperature: %d C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            sensor_data->differential_pressure, sensor_data->temperature);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        uint8_t data[NUM_BYTES_TO_READ];
        sensor_data_t sensor_data;

        // Send continuous measurement command
        if (send_command(CONTINUOUS_MEASUREMENT_CMD) != 0) {
            fprintf(stderr, "Failed to send continuous measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for at least 45 ms
        gpioDelay(50);

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC-8 checksums
        if (!validate_crc8(data, 2) || !validate_crc8(data + 3, 2) || !validate_crc8(data + 6, 3)) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert data to physical units
        if (convert_data(data, &sensor_data) != 0) {
            fprintf(stderr, "Failed to convert data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log data
        if (log_data(&sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

