        if (send_command(CONTINUOUS_MEASUREMENT_CMD) != 0) {
            fprintf(stderr, "Failed to send continuous measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for at least 45 ms
        gpioDelay(50);

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC-8 checksums
        if (!validate_crc8(data, 2) || !validate_crc8(data + 3, 2) || !validate_crc8(data + 6, 3)) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert data to physical units
        if (convert_data(data, &sensor_data) != 0) {
            fprintf(stderr, "Failed to convert data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log data
        if (log_data(&sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

