#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// HDC1080 I2C address
#define HDC1080_ADDR 0x40

// HDC1080 configuration register address
#define HDC1080_CONFIG_REG 0x02

// HDC1080 temperature and humidity registers
#define HDC1080_TEMP_REG 0x00
#define HDC1080_HUMID_REG 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_hdc1080();
int read_sensor_data(uint16_t *raw_temp, uint16_t *raw_humidity);
sensor_data_t convert_data(uint16_t raw_temp, uint16_t raw_humidity);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the HDC1080 sensor
int configure_hdc1080() {
    // Configure for 14-bit temperature and humidity resolution
    // Continuous measurement mode
    uint16_t config_value = 0x0000; // Default configuration
    int result = i2cWriteWordData(i2c_handle, HDC1080_CONFIG_REG, config_value);
    if (result < 0) {
        fprintf(stderr, "Failed to write to configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read raw temperature and humidity data from the sensor
int read_sensor_data(uint16_t *raw_temp, uint16_t *raw_humidity) {
    int result;

    // Trigger a measurement by writing to the temperature or humidity register
    result = i2cWriteByteData(i2c_handle, HDC1080_TEMP_REG, 0x00); // Dummy write
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 20 ms)
    gpioDelay(20000); // 20 ms

    // Read temperature data
    result = i2cReadWordData(i2c_handle, HDC1080_TEMP_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }
    *raw_temp = (uint16_t)result;

    // Read humidity data
    result = i2cReadWordData(i2c_handle, HDC1080_HUMID_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read humidity data: %d\n", result);
        return -1;
    }
    *raw_humidity = (uint16_t)result;

    return 0;
}

// Convert raw data to temperature and humidity
sensor_data_t convert_data(uint16_t raw_temp, uint16_t raw_humidity) {
    sensor_data_t data;
    data.temperature = ((float)raw_temp / 65536.0) * 165.0 - 40.0;
    data.humidity = ((float)raw_humidity / 65536.0) * 100.0;
    return data;
}

// Log data to a file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Configure HDC1080
    if (configure_hdc1080() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("enviro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint16_t raw_temp, raw_humidity;
    sensor_data_t data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_temp, &raw_humidity) == 0) {
            // Convert data
            data = convert_data(raw_temp, raw_humidity);

            // Log data
            if (log_data(data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

