#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x3615
#define LOG_FILE "hvac_pressure_log.txt"
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send the continuous measurement command
int send_measurement_command() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate CRC checksums
int validate_crc(const uint8_t *data, int len) {
    uint8_t pressure_crc = crc8(data, 2);
    uint8_t temperature_crc = crc8(data + 2, 2);
    uint8_t scale_factor_crc = crc8(data + 4, 3);

    if (pressure_crc != data[2] || temperature_crc != data[5] || scale_factor_crc != data[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }
    return 0;
}

// Function to convert raw data to pressure and temperature
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Scale factors from the datasheet
    float scale_factor_pressure = 60.0; // Pa
    float scale_factor_temperature = 200.0; // Degrees C

    sensor_data.pressure = (float)raw_pressure / scale_factor_pressure;
    sensor_data.temperature = (float)raw_temperature / scale_factor_temperature;

    return sensor_data;
}

// Function to log data to a file
void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("HVAC system monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        if (send_measurement_command() == 0) {
            gpioDelay(50); // Wait 50 ms
            if (read_sensor_data(data) == 0) {
                if (validate_crc(data, 9) == 0) {
                    sensor_data_t sensor_data = convert_data(data);
                    log_data(sensor_data.pressure, sensor_data.temperature);
                    printf("Pressure: %.2f Pa, Temperature: %.2f C\n", sensor_data.pressure, sensor_data.temperature);
                } else {
                    fprintf(stderr, "CRC validation failed, skipping logging.\n");
                }
            } else {
                fprintf(stderr, "Failed to read sensor data, skipping logging.\n");
            }
        } else {
            fprintf(stderr, "Failed to send measurement command, skipping logging.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the next sample
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("HVAC system monitoring stopped.\n");
    return 0;
}

