#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define START_PERIODIC_MEASUREMENT_CMD 0x21B1
#define STOP_PERIODIC_MEASUREMENT_CMD 0x3F86
#define BUFFER_SIZE 100
#define LOG_FILE_PATH "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define READ_INTERVAL_SEC 5
#define LOG_INTERVAL_SEC 60

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    int co2;
    float temperature;
    float humidity;
} SensorData;

// Circular buffer structure
typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;
CircularBuffer buffer;

// Function prototypes
int init_scd40();
int read_scd40_data(int *co2, float *temperature, float *humidity);
void add_to_buffer(CircularBuffer *buffer, time_t timestamp, int co2, float temperature, float humidity);
void *log_data_thread(void *arg);
void signal_handler(int signal);
unsigned char crc8(const unsigned char *data, int len);

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize the SCD40 sensor
int init_scd40() {
    char cmd[2] = {(START_PERIODIC_MEASUREMENT_CMD >> 8) & 0xFF, START_PERIODIC_MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to SCD40: %d\n", result);
        return -1;
    }
    gpioDelay(1000); // Wait for measurement to start (1 second)
    return 0;
}

// Read data from the SCD40 sensor
int read_scd40_data(int *co2, float *temperature, float *humidity) {
    char cmd[2] = {(E000 >> 8) & 0xFF, E000 & 0xFF};
    char buffer[9];
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to SCD40 for data read: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for measurement (at least 10ms)

    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from SCD40: %d\n", result);
        return -1;
    }

    // CRC Check for CO2
    if (crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "CRC check failed for CO2\n");
        return -1;
    }

    // CRC Check for Temperature
    if (crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC check failed for Temperature\n");
        return -1;
    }

    // CRC Check for Humidity
    if (crc8(buffer + 6, 2) != buffer[8]) {
        fprintf(stderr, "CRC check failed for Humidity\n");
        return -1;
    }

    // Convert data
    *co2 = (buffer[0] << 8) | buffer[1];
    *temperature = -45 + 175 * ((float)((buffer[3] << 8) | buffer[4])) / 65535.0;
    *humidity = 100 * ((float)((buffer[6] << 8) | buffer[7])) / 65535.0;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(CircularBuffer *buffer, time_t timestamp, int co2, float temperature, float humidity) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head].timestamp = timestamp;
    buffer->data[buffer->head].co2 = co2;
    buffer->data[buffer->head].temperature = temperature;
    buffer->data[buffer->head].humidity = humidity;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Thread function to log data to a CSV file
void *log_data_thread(void *arg) {
    time_t current_time;
    struct tm *time_info;
    char filename[100];
    char timestamp[30];
    FILE *fp;
    int co2, temperature, humidity;
    float co2_ppm, temperature_celsius, humidity_percent;

    while (running) {
        sleep(LOG_INTERVAL_SEC);
        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
        snprintf(filename, sizeof(filename), "%s%s.csv", LOG_FILE_PATH, timestamp);

