    time_t timestamp;
    int co2;
    float temperature;
    float humidity;
} SensorData;

// Circular buffer structure
typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

// Global variables
