void signal_handler(int signal);
unsigned char crc8(const unsigned char *data, int len);

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize the SCD40 sensor
int init_scd40() {
    char cmd[2] = {(START_PERIODIC_MEASUREMENT_CMD >> 8) & 0xFF, START_PERIODIC_MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to SCD40: %d\n", result);
        return -1;
    }
    gpioDelay(1000); // Wait for measurement to start (1 second)
    return 0;
}

// Read data from the SCD40 sensor
int read_scd40_data(int *co2, float *temperature, float *humidity) {
    char cmd[2] = {(E000 >> 8) & 0xFF, E000 & 0xFF};
    char buffer[9];
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to SCD40 for data read: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for measurement (at least 10ms)

    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from SCD40: %d\n", result);
        return -1;
    }

    // CRC Check for CO2
    if (crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "CRC check failed for CO2\n");
        return -1;
    }

    // CRC Check for Temperature
    if (crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC check failed for Temperature\n");
        return -1;
    }

    // CRC Check for Humidity
    if (crc8(buffer + 6, 2) != buffer[8]) {
        fprintf(stderr, "CRC check failed for Humidity\n");
        return -1;
    }

    // Convert data
    *co2 = (buffer[0] << 8) | buffer[1];
    *temperature = -45 + 175 * ((float)((buffer[3] << 8) | buffer[4])) / 65535.0;
