#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASUREMENT_COMMAND 0x362F
#define LOG_FILE "sdp810_log.txt"
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_Pa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
sensor_data_t convert_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send continuous measurement command
int send_measurement_command() {
    char cmd[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    gpioDelay(45000); // Wait 45 ms
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temp = (data[3] << 8) | data[4];
    uint16_t scale_factor = (data[6] << 8) | data[7];

    // CRC validation
    if (calculate_crc(data, 2) != data[2]) {
        fprintf(stderr, "CRC error for differential pressure\n");
        sensor_data.pressure_Pa = -999.0; // Indicate error
    } else if (calculate_crc(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC error for temperature\n");
        sensor_data.temperature_C = -999.0; // Indicate error
    } else if (calculate_crc(data + 6, 2) != data[8]) {
        fprintf(stderr, "CRC error for scale factor\n");
        sensor_data.pressure_Pa = -999.0; // Indicate error
        sensor_data.temperature_C = -999.0; // Indicate error
    } else {
        // Convert to physical units
        sensor_data.pressure_Pa = raw_pressure * scale_factor / 1000.0;
        sensor_data.temperature_C = -45.0 + 175.0 * raw_temp / 65535.0;
    }

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure_Pa, data.temperature_C);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t sensor_data[9];
        sensor_data_t converted_data;

        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue; // Skip to the next iteration
        }

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue; // Skip to the next iteration
        }

        // Convert data
        converted_data = convert_data(sensor_data);

        // Log data
        if (log_data(converted_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

