double convert_pressure(int16_t raw_pressure, int16_t raw_temperature);
double convert_temperature(int16_t raw_temperature);
void control_led(double pressure);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation (from ICP-10125 datasheet)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients() != 0) {
        fprintf(stderr, "Failed to read calibration coefficients. Exiting.\n");
        cleanup();
        return 1;
    }

    // Request GPIO line for LED control
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "icp10125_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return 1;
    }

    // Main loop
    int16_t raw_pressure, raw_temperature;
    double pressure, temperature;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds

    while (program_running) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement.\n");
        } else {
            // Wait for measurement to complete (adjust as needed)
            usleep(10000); // 10 ms

            // Read sensor data
            if (read_sensor_data(&raw_pressure, &raw_temperature) == 0) {
                // Convert raw data to physical units
