#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int read_temperature(int reg);
float convert_to_celsius(int raw_temp);
int log_temperature(float ambient_temp, float object_temp);
void control_fan(float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from a specific register
int read_temperature(int reg) {
    int raw_temp = i2cReadWordData(i2c_handle, reg);
    if (raw_temp < 0) {
        fprintf(stderr, "Failed to read temperature from register 0x%02X: %d\n", reg, raw_temp);
        return -1;
    }
    return raw_temp;
}

// Convert raw temperature to Celsius
float convert_to_celsius(int raw_temp) {
    return raw_temp * 0.02 - 273.15;
}

// Log temperature data to file
int log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Ambient: %.2f °C, Object: %.2f °C\n", timestamp, ambient_temp, object_temp);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Control the cooling fan based on object temperature
void control_fan(float object_temp) {
    if (object_temp > TEMP_THRESHOLD_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else if (object_temp < TEMP_THRESHOLD_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO 18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially off

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int retries = 0;
        int ambient_raw, object_raw;

        // Read ambient temperature
        while (retries < MAX_RETRIES) {
            ambient_raw = read_temperature(AMBIENT_TEMP_REG);
            if (ambient_raw >= 0) {
                break; // Success
            }
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read ambient temperature after %d retries\n", MAX_RETRIES);
            continue; // Skip to the next iteration
        }

        // Read object temperature
        retries = 0;
        while (retries < MAX_RETRIES) {
            object_raw = read_temperature(OBJECT_TEMP_REG);
            if (object_raw >= 0) {
                break; // Success
            }
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read object temperature after %d retries\n", MAX_RETRIES);
            continue; // Skip to the next iteration
        }

        // Convert raw temperatures to Celsius
        float ambient_temp = convert_to_celsius(ambient_raw);
        float object_temp = convert_to_celsius(object_raw);

        // Validate temperature readings
        if (ambient_temp < -40.0 || ambient_temp > 125.0 || object_temp < -40.0 || object_temp > 125.0) {
            fprintf(stderr, "Invalid temperature reading: Ambient = %.2f, Object = %.2f\n", ambient_temp, object_temp);
            continue; // Skip to the next iteration
        }

        // Log temperature data
        log_temperature(ambient_temp, object_temp);

        // Control the cooling fan
        control_fan(object_temp);

        // Wait for 2 seconds
        gpioDelay(2000 * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

