    int retries = 0;

    // Wait for the measurement to complete (status bit 0 is set)
    while (1) {
        int status = i2cReadByteData(i2c_handle, MEASUREMENT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading MEASUREMENT_STATUS register\n");
            return -1;
        }
        if ((status & 0x01) == 0) {
            break; // Measurement complete
        }
        gpioDelay(1); // Wait 1 ms
        retries++;
        if (retries > 50) {
            fprintf(stderr, "Timeout waiting for measurement to complete\n");
            return -1;
        }
    }

    // Read temperature data
    raw_temperature = i2cReadWordData(i2c_handle, TEMPERATURE_MSB);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    // Read humidity data
    raw_humidity = i2cReadWordData(i2c_handle, HUMIDITY_MSB);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    data->temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    data->humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC2010 sensor
    if (init_hdc2010() < 0) {
        fprintf(stderr, "HDC2010 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read temperature and humidity
        if (read_hdc2010(&sensor_data) == 0) {
            // Print temperature and humidity
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

