#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP800_ADDR 0x25

// Define the continuous measurement command
#define MEASURE_CMD 0x362F

// Define the CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables for I2C handle and program termination
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection(int bus, int addr);
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t crc8(const uint8_t *data, int len);
sensor_data_t convert_data(const char *buffer);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open an I2C connection to the specified bus and address
int open_i2c_connection(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Send a command to the SDP800 sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the SDP800 sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(const char *buffer) {
    sensor_data_t data;
    uint8_t pressure_msb = buffer[0];
    uint8_t pressure_lsb = buffer[1];
    uint8_t temperature_msb = buffer[3];
    uint8_t temperature_lsb = buffer[4];

    // CRC check for pressure data
    uint8_t pressure_crc = buffer[2];
    uint8_t pressure_data[2] = {pressure_msb, pressure_lsb};
    if (crc8(pressure_data, 2) != pressure_crc) {
        fprintf(stderr, "Pressure CRC check failed\n");
        data.pressure = -1; // Indicate error
    } else {
        data.pressure = (int16_t)((pressure_msb << 8) | pressure_lsb);
    }

    // CRC check for temperature data
    uint8_t temperature_crc = buffer[5];
    uint8_t temperature_data[2] = {temperature_msb, temperature_lsb};
    if (crc8(temperature_data, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC check failed\n");
        data.temperature = -1; // Indicate error
    } else {
        data.temperature = (int16_t)((temperature_msb << 8) | temperature_lsb);
    }

    return data;
}

// Log the pressure and temperature data to the console
void log_data(sensor_data_t data) {
    if (data.pressure != -1 && data.temperature != -1) {
        printf("Pressure: %d Pa, Temperature: %d \u00b0C\n", data.pressure, data.temperature);
    } else {
        fprintf(stderr, "Error: Invalid sensor data\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c_connection(I2C_BUS, SDP800_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to send measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete (at least 45 ms)
        gpioDelay(50); // Wait 50 ms

        // Read data
        char buffer[6];
        if (read_data(i2c_handle, buffer, 6) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert data
        sensor_data_t data = convert_data(buffer);

        // Log data
        log_data(data);

        // Wait 500 ms
        gpioDelay(500);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

