#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define RELAY_GPIO 17
#define TARGET_TEMP_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_TEMP 100.0
#define MIN_TEMP -50.0
#define MAX_DUTY_CYCLE 1.0
#define MIN_DUTY_CYCLE 0.0
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for PID controller state
typedef struct {
    double integral;
    double previous_error;
} PIDState;

PIDState pid_state = {0.0, 0.0};

// Function prototypes
int read_max6675(int spi_handle, float *temperature);
float calculate_pid(float setpoint, float actual_temperature, PIDState *pid_state);
void set_relay_duty_cycle(int gpio_pin, float duty_cycle);
void log_data(FILE *log_file, float temperature, float duty_cycle);
void signal_handler(int signal);
int load_target_profile(const char *filename, float *time_seconds, float *target_temps, int *num_points);

// Function to read temperature from MAX6675 sensor
int read_max6675(int spi_handle, float *temperature) {
    char tx_buffer[4];
    char rx_buffer[4];
    int result;

    // MCP3008 command to read channel 0 (single-ended)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80; // Single-ended, channel 0
    tx_buffer[2] = 0x00;
    tx_buffer[3] = 0x00;

    result = spiXfer(spi_handle, tx_buffer, rx_buffer, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract temperature data (12 bits)
    int raw_data = ((rx_buffer[0] & 0x03) << 8) + rx_buffer[1];

    // Check for open circuit (bit 2 of the first byte)
    if (raw_data & 0x0400) {
        fprintf(stderr, "Thermocouple open circuit!\n");
        return -2; // Indicate open circuit
    }

    // Convert raw data to temperature (Celsius)
    *temperature = (float)raw_data * 0.25;

    return 0; // Indicate success
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, PIDState *pid_state) {
    float error = setpoint - actual_temperature;
    pid_state->integral += error * SAMPLE_INTERVAL_SEC;
    float derivative = (error - pid_state->previous_error) / SAMPLE_INTERVAL_SEC;
    float output = KP * error + KI * pid_state->integral + KD * derivative;

    // Clamp output to the valid range
    if (output > MAX_DUTY_CYCLE) {
        output = MAX_DUTY_CYCLE;
    } else if (output < MIN_DUTY_CYCLE) {
        output = MIN_DUTY_CYCLE;
    }

    pid_state->previous_error = error;
    return output;
}

// Function to set relay duty cycle using pigpio
void set_relay_duty_cycle(int gpio_pin, float duty_cycle) {
    int duty_cycle_int = (int)(duty_cycle * 255.0); // pigpio uses 0-255 range
    gpioPWM(gpio_pin, duty_cycle_int);
}

// Function to log data to CSV file
void log_data(FILE *log_file, float temperature, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to load target temperature profile from file
int load_target_profile(const char *filename, float *time_seconds, float *target_temps, int *num_points) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening target profile file: %s\n", filename);
        return -1;
    }

    char line[256];
    *num_points = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\n') continue;

        if (*num_points >= 100) { // Limit the number of points to avoid memory issues
            fprintf(stderr, "Warning: Target profile file contains too many points. Limiting to 100.\n");
            break;
        }

        if (sscanf(line, "%f,%f", &time_seconds[*num_points], &target_temps[*num_points]) != 2) {
            fprintf(stderr, "Error parsing line in target profile file: %s\n", line);
            fclose(fp);
            return -1;
        }

        (*num_points)++;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }
    rewind(log_file);

    // Load target temperature profile
    float time_seconds[100];
    float target_temps[100];
    int num_points;

    if (load_target_profile(TARGET_TEMP_FILE, time_seconds, target_temps, &num_points) != 0) {
        fprintf(stderr, "Failed to load target profile. Exiting.\n");
        spiClose(spi_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float temperature;
    float duty_cycle;
    int current_point = 0;
    int target_point = 0;

    while (!terminate) {
        // Read temperature from sensor
        if (read_max6675(spi_handle, &temperature) == 0) {
            // Calculate PID output
            duty_cycle = calculate_pid(target_temps[current_point], temperature, &pid_state);

            // Set relay duty cycle
            set_relay_duty_cycle(RELAY_GPIO, duty_cycle);

            // Log data
            log_data(log_file, temperature, duty_cycle);

            // Check if target temperature is reached
            if (temperature >= target_temps[current_point]) {
                current_point++;
                if (current_point >= num_points) {
                    current_point = 0; // Reset to the beginning
                    target_point++;
                    if (target_point >= num_points) {
                        target_point = 0; // Reset to the beginning after reaching the end
                    }
                }
            }
        } else {
            fprintf(stderr, "Error reading temperature. Retrying...\n");
        }

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    set_relay_duty_cycle(RELAY_GPIO, 0.0); // Turn off relay
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

