float calculate_pid(float setpoint, float actual_temperature, PIDState *pid_state) {
    float error = setpoint - actual_temperature;
    pid_state->integral += error * SAMPLE_INTERVAL_SEC;
    float derivative = (error - pid_state->previous_error) / SAMPLE_INTERVAL_SEC;
    float output = KP * error + KI * pid_state->integral + KD * derivative;

    // Clamp output to the valid range
    if (output > MAX_DUTY_CYCLE) {
        output = MAX_DUTY_CYCLE;
    } else if (output < MIN_DUTY_CYCLE) {
        output = MIN_DUTY_CYCLE;
    }

    pid_state->previous_error = error;
    return output;
}

