    terminate = 1;
}

// Function to load target temperature profile from file
int load_target_profile(const char *filename, float *time_seconds, float *target_temps, int *num_points) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening target profile file: %s\n", filename);
        return -1;
    }

    char line[256];
    *num_points = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\n') continue;

        if (*num_points >= 100) { // Limit the number of points to avoid memory issues
            fprintf(stderr, "Warning: Target profile file contains too many points. Limiting to 100.\n");
            break;
        }

        if (sscanf(line, "%f,%f", &time_seconds[*num_points], &target_temps[*num_points]) != 2) {
            fprintf(stderr, "Error parsing line in target profile file: %s\n", line);
            fclose(fp);
            return -1;
        }

        (*num_points)++;
    }

    fclose(fp);
    return 0;
}

