        fprintf(stderr, "Error opening w1_slave file for %s: %s\n", sensor_address, strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read < 0) {
        fprintf(stderr, "Error reading w1_slave file for %s: %s\n", sensor_address, strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    buffer[bytes_read] = '\0';

    // Check for CRC error
    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for %s\n", sensor_address);
        return -1000.0; // Indicate error with a very low temperature
    }

