    duty_cycle_value.value = (duty_cycle > 0) ? 1 : 0; // Set PWM high if duty cycle is non-zero
    gpiod_line_set_value(heater_pwm_line, duty_cycle_value);

    value.value = 0; // Assuming PWM is active high
    gpiod_line_set_value(heater_pwm_line, value);
}

// Logging Function
