    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    heater_enable_line = gpiod_chip_get_line(gpio_chip, GPIO_HEATER_ENABLE);
    if (!heater_enable_line) {
        fprintf(stderr, "Error getting heater enable line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    heater_pwm_line = gpiod_chip_get_line(gpio_chip, GPIO_HEATER_PWM);
    if (!heater_pwm_line) {
        fprintf(stderr, "Error getting heater PWM line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    chip_select_line = gpiod_chip_get_line(gpio_chip, GPIO_CHIP_SELECT);
    if (!chip_select_line) {
        fprintf(stderr, "Error getting chip select line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Set heater enable line as output
    if (gpiod_line_request_output(heater_enable_line, "greenhouse_heater", 0) < 0) {
        fprintf(stderr, "Error requesting heater enable line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Set heater PWM line as output
    if (gpiod_line_request_output(heater_pwm_line, "greenhouse_heater", 0) < 0) {
        fprintf(stderr, "Error requesting heater PWM line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Set chip select line as output
    if (gpiod_line_request_output(chip_select_line, "greenhouse_heater", 0) < 0) {
        fprintf(stderr, "Error requesting chip select line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// I2C Initialization
int initialize_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, 0x48) < 0) { // Example address, adjust as needed
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Cleanup Function
void cleanup() {
    // Turn off heater
    set_heater_state(0);
    set_pwm_duty_cycle(0);

    // Close GPIO lines
    gpiod_line_release(heater_enable_line);
    gpiod_line_release(heater_pwm_line);
    gpiod_line_release(chip_select_line);

    // Close GPIO chip
    gpiod_chip_close(gpio_chip);

    // Close I2C bus
    close(i2c_fd);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint_temperature> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    setpoint_temperature = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);
    Kd = atof(argv[4]);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperatures[num_sensors];
    float pid_outputs[num_sensors];
    int duty_cycles[num_sensors];
    float integral[num_sensors] = {0.0};
    float previous_error[num_sensors] = {0.0};

    // Main loop
    while (!terminate) {
        // Read temperatures from each sensor
        for (int i = 0; i < num_sensors; i++) {
            temperatures[i] = read_temperature(sensor_addresses[i]);
            if (temperatures[i] < -999.0) { // Error reading temperature
                fprintf(stderr, "Error reading temperature from sensor %d, using previous value.\n", i);
                // Optionally, set a default value or handle the error appropriately
                temperatures[i] = 25.0; // Default temperature
            }
        }

        // Calculate PID outputs
        for (int i = 0; i < num_sensors; i++) {
            pid_outputs[i] = calculate_pid(setpoint_temperature, temperatures[i], &integral[i], &previous_error[i]);
        }

        // Map PID outputs to PWM duty cycles (0-255)
        for (int i = 0; i < num_sensors; i++) {
            if (pid_outputs[i] > 0) {
                duty_cycles[i] = (int)(pid_outputs[i] * 255.0); // Proportional control
            } else {
                duty_cycles[i] = 0;
            }
        }

        // Set heater state based on PID output
        for (int i = 0; i < num_sensors; i++) {
            if (pid_outputs[i] > 0) {
                set_heater_state(1); // Turn on heater
            } else {
                set_heater_state(0); // Turn off heater
            }
        }

        // Set PWM duty cycles
        for (int i = 0; i < num_sensors; i++) {
            set_pwm_duty_cycle(duty_cycles[i]);
        }

        // Log data
        log_data(temperatures, pid_outputs, duty_cycles, num_sensors);

        // Sleep for 5 seconds
        sleep(SLEEP_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

