    }

    setpoint_temperature = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);
    Kd = atof(argv[4]);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperatures[num_sensors];
    float pid_outputs[num_sensors];
    int duty_cycles[num_sensors];
    float integral[num_sensors] = {0.0};
    float previous_error[num_sensors] = {0.0};

    // Main loop
    while (!terminate) {
        // Read temperatures from each sensor
        for (int i = 0; i < num_sensors; i++) {
            temperatures[i] = read_temperature(sensor_addresses[i]);
            if (temperatures[i] < -999.0) { // Error reading temperature
                fprintf(stderr, "Error reading temperature from sensor %d, using previous value.\n", i);
                // Optionally, set a default value or handle the error appropriately
                temperatures[i] = 25.0; // Default temperature
            }
        }

        // Calculate PID outputs
        for (int i = 0; i < num_sensors; i++) {
            pid_outputs[i] = calculate_pid(setpoint_temperature, temperatures[i], &integral[i], &previous_error[i]);
        }

        // Map PID outputs to PWM duty cycles (0-255)
        for (int i = 0; i < num_sensors; i++) {
            if (pid_outputs[i] > 0) {
                duty_cycles[i] = (int)(pid_outputs[i] * 255.0); // Proportional control
            } else {
                duty_cycles[i] = 0;
            }
        }

        // Set heater state based on PID output
        for (int i = 0; i < num_sensors; i++) {
            if (pid_outputs[i] > 0) {
                set_heater_state(1); // Turn on heater
            } else {
                set_heater_state(0); // Turn off heater
            }
        }

        // Set PWM duty cycles
        for (int i = 0; i < num_sensors; i++) {
            set_pwm_duty_cycle(duty_cycles[i]);
        }

        // Log data
        log_data(temperatures, pid_outputs, duty_cycles, num_sensors);

        // Sleep for 5 seconds
        sleep(SLEEP_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

