#define HUMIDITY_THRESHOLD_LOW 55.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_SEC 5

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *dehumidifier_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init(int fd);
int aht20_read_data(int fd, uint8_t *data);
float calculate_humidity(uint32_t humidity_raw);
void control_dehumidifier(float humidity);
void log_data(float humidity);
void signal_handler(int sig);
int i2c_read_block_data(int fd, uint8_t reg, uint8_t *buf, int count);
int i2c_write_block_data(int fd, uint8_t reg, uint8_t *buf, int count);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the AHT20 sensor
int aht20_init(int fd) {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    uint8_t status;

    if (i2c_write_block_data(fd, 0xBE, init_cmd, 3) != 0) {
        fprintf(stderr, "Error: Failed to initialize AHT20 (write init command).\n");
        return -1;
    }

    // Wait for the sensor to be ready (at least 10ms)
    usleep(10000);

    // Read the status byte
    if (i2c_read_block_data(fd, 0x00, &status, 1) != 1) {
        fprintf(stderr, "Error: Failed to read AHT20 status byte.\n");
        return -1;
    }

    if (status != 0x83) {
        fprintf(stderr, "Error: AHT20 not ready (status: 0x%02X).\n", status);
        return -1;
    }

    return 0;
}

// Function to read data from the AHT20 sensor
int aht20_read_data(int fd, uint8_t *data) {
    uint8_t trigger_cmd[3] = {0xAC, 0x33, 0x00};
    uint8_t status;
    int retries = 0;

    // Send measurement trigger command
    if (i2c_write_block_data(fd, 0xAC, trigger_cmd, 3) != 0) {
        fprintf(stderr, "Error: Failed to send measurement trigger command.\n");
        return -1;
    }

    // Wait for the measurement to complete (at least 80ms)
    usleep(80000);

    // Read the status byte
    if (i2c_read_block_data(fd, 0x00, &status, 1) != 1) {
        fprintf(stderr, "Error: Failed to read AHT20 status byte.\n");
        return -1;
    }

    if (status != 0x83) {
        fprintf(stderr, "Error: AHT20 busy (status: 0x%02X).\n", status);
        return -1;
    }

    // Read 6 bytes of data
    if (i2c_read_block_data(fd, 0x00, data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read 6 bytes of data.\n");
        return -1;
    }

    return 0;
}

