float calculate_humidity(uint32_t humidity_raw) {
    return ((float)humidity_raw / 0x100000) * 100.0;
}

// Function to control the dehumidifier relay
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        if (gpiod_line_set_value(dehumidifier_line, 1) < 0) {
            fprintf(stderr, "Error: Failed to set dehumidifier GPIO high.\n");
        }
