    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        if (gpiod_line_set_value(dehumidifier_line, 0) < 0) {
            fprintf(stderr, "Error: Failed to set dehumidifier GPIO low.\n");
        }
        printf("Humidity: %.2f%%, Dehumidifier OFF\n", humidity);
    }
}

