    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
}

// Function to read data from I2C with retries
int i2c_read_block_data(int fd, uint8_t reg, uint8_t *buf, int count) {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = read(fd, buf, count);
        if (result == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C read failed (attempt %d/%d): %s\n", retries + 1, RETRY_COUNT, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Error: I2C read failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to write data to I2C with retries
int i2c_write_block_data(int fd, uint8_t reg, uint8_t *buf, int count) {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = write(fd, buf, count);
        if (result == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C write failed (attempt %d/%d): %s\n", retries + 1, RETRY_COUNT, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Error: I2C write failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

int main() {
    uint8_t data[6];
    float humidity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip.\n");
        close(i2c_fd);
        return 1;
    }

    dehumidifier_line = gpiod_chip_get_line(gpio_chip, DEHUMIDIFIER_GPIO);
    if (!dehumidifier_line) {
        fprintf(stderr, "Error: Failed to get GPIO line.\n");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(dehumidifier_line, "dehumidifier", 0) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line as output.\n");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init(i2c_fd) != 0) {
        fprintf(stderr, "Error: Failed to initialize AHT20 sensor.\n");
        gpiod_line_set_value(dehumidifier_line, 0); // Ensure dehumidifier is OFF on error
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    printf("AHT20 sensor initialized successfully.\n");

    // Main loop
    while (!terminate) {
        // Read data from AHT20 sensor
        if (aht20_read_data(i2c_fd, data) == 0) {
            // Extract humidity data
            uint32_t humidity_raw = (data[1] << 12) | (data[2] << 4) | (data[3] >> 4);

            // Calculate humidity
            humidity = calculate_humidity(humidity_raw);

            // Control dehumidifier
            control_dehumidifier(humidity);

            // Log data
            log_data(humidity);
        } else {
            fprintf(stderr, "Error: Failed to read data from AHT20 sensor.\n");
        }

        // Wait for the next poll interval
        sleep(POLL_INTERVAL_SEC);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpiod_line_set_value(dehumidifier_line, 0); // Ensure dehumidifier is OFF
    gpiod_line_release(dehumidifier_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    printf("Exiting.\n");
    return 0;
}

