#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 8080
#define READ_INTERVAL 60 // seconds

// Global variables
int i2c_fd = -1;
int sockfd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_htu21d(float *humidity);
int post_data(float humidity);
void signal_handler(int sig);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %s", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read humidity from HTU21D
int read_htu21d(float *humidity) {
    uint8_t cmd = 0xE5; // Measure humidity command
    uint8_t data[3];
    int result;

    result = write(i2c_fd, &cmd, 1);
    if (result != 1) {
        syslog(LOG_ERR, "Failed to write humidity command: %s", strerror(errno));
        return -1;
    }

    usleep(50000); // Wait for measurement (at least 4.5ms)

    result = read(i2c_fd, data, 3);
    if (result != 3) {
        syslog(LOG_ERR, "Failed to read humidity data: %s", strerror(errno));
        return -1;
    }

    // CRC check
    uint8_t crc = data[2];
    uint8_t calculated_crc = (data[0] + data[1]) & 0xFF;

