#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define LOG_DIR "/var/log/motion_detection"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define BACKOFF_DELAY_MS 10

// Global variables
static int i2c_fd_tmp117 = -1;
static int i2c_fd_aht20 = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *pir_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_tmp117(int fd, float *temperature);
int read_aht20(int fd, float *humidity, float *temperature);
int read_pir(int gpio);
int log_data(const char *filename, float temperature, float humidity, int motion);
void signal_handler(int sig);
int check_sensor_presence(int fd);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int motion;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read temperature from TMP117
int read_tmp117(int fd, float *temperature) {
    uint8_t buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = read(fd, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit signed integer
            int16_t raw_temp = (buf[0] << 8) | buf[1];

            // Convert to Celsius (0.0078125 degrees Celsius per LSB)
            *temperature = (float)raw_temp * 0.0078125;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading TMP117: %s (attempt %d/%d)\n", strerror(errno), retries + 1, MAX_RETRIES);
            retries++;
            usleep(BACKOFF_DELAY_MS * 1000); // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to read TMP117 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read humidity and temperature from AHT20
int read_aht20(int fd, float *humidity, float *temperature) {
    uint8_t buf[7];
    int retries = 0;
    int result;

    // Send init command (0xBE 0x08 0x00)
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    if (write(fd, init_cmd, 3) != 3) {
        perror("Error writing to AHT20 init command");
        return -1;
    }
    usleep(10000); // Wait for initialization (at least 10ms)

    // Send measure command (0xAC 0x33 0x00)
    uint8_t measure_cmd[3] = {0xAC, 0x33, 0x00};
    if (write(fd, measure_cmd, 3) != 3) {
        perror("Error writing to AHT20 measure command");
        return -1;
    }
    usleep(80000); // Wait for measurement (at least 75ms)

    // Read 7 bytes of data
    result = read(fd, buf, 7);
    if (result != 7) {
        fprintf(stderr, "Error reading from AHT20: %s (attempt %d/%d)\n", strerror(errno), retries + 1, MAX_RETRIES);
        retries++;
        usleep(BACKOFF_DELAY_MS * 1000); // Exponential backoff
        return -1; // Failure
    }

    // Check busy bit (bit 7 of data[0])
    if (buf[0] & 0x80) {
        fprintf(stderr, "AHT20 busy\n");
        return -1; // AHT20 busy
    }

    // Extract humidity and temperature data
    uint32_t humidity_raw = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | ((uint32_t)buf[3] >> 4);
    uint32_t temperature_raw = ((uint32_t)buf[3] & 0x0F) << 16 | ((uint32_t)buf[4] << 8) | buf[5];

    // Convert to Celsius and percentage
    *humidity = (float)humidity_raw / 0x100000;
    *temperature = (float)temperature_raw / 0x100000;

    return 0; // Success
}

// Function to read motion detection from PIR sensor
int read_pir(int gpio) {
    int value;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        value = gpiod_line_get_value(pir_line);
        if (value >= 0) {
            return value; // Success
        } else {
            fprintf(stderr, "Error reading PIR sensor: %s (attempt %d/%d)\n", strerror(errno), retries + 1, MAX_RETRIES);
            retries++;
            usleep(BACKOFF_DELAY_MS * 1000); // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to read PIR sensor after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to log data to CSV file
int log_data(const char *filename, float temperature, float humidity, int motion) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write data to file
    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to check sensor presence
int check_sensor_presence(int fd) {
    uint8_t buf[1];
    if (read(fd, buf, 1) == 1) {
        return 1; // Sensor present
    } else {
        return 0; // Sensor absent
    }
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");

    if (i2c_fd_tmp117 != -1) {
        close(i2c_fd_tmp117);
    }
    if (i2c_fd_aht20 != -1) {
        close(i2c_fd_aht20);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
    if (pir_line != NULL) {
        gpiod_line_release(pir_line);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd_tmp117 = init_i2c(I2C_BUS, TMP117_ADDR);
    if (i2c_fd_tmp117 < 0) {
        fprintf(stderr, "Failed to initialize TMP117 sensor. Continuing without it.\n");
    }

    i2c_fd_aht20 = init_i2c(I2C_BUS, AHT20_ADDR);
    if (i2c_fd_aht20 < 0) {
        fprintf(stderr, "Failed to initialize AHT20 sensor. Continuing without it.\n");
    }

    // Check sensor presence
    if (!check_sensor_presence(i2c_fd_tmp117)) {
        fprintf(stderr, "TMP117 sensor not found. Continuing without it.\n");
    }
    if (!check_sensor_presence(i2c_fd_aht20)) {
        fprintf(stderr, "AHT20 sensor not found. Continuing without it.\n");
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    pir_line = gpiod_chip_get_line(gpio_chip, PIR_GPIO);
    if (!pir_line) {
        perror("Error getting PIR GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(pir_line, "motion_detection") < 0) {
        perror("Error requesting PIR GPIO line as input");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data;
        float temperature, humidity;
        int motion;

        // Read sensor data
        if (i2c_fd_tmp117 != -1) {
            if (read_tmp117(i2c_fd_tmp117, &temperature) != 0) {
                fprintf(stderr, "Failed to read temperature from TMP117\n");
                temperature = -999.0; // Indicate error
            }
        } else {
            temperature = -999.0; // Indicate sensor absence
        }

        if (i2c_fd_aht20 != -1) {
            if (read_aht20(i2c_fd_aht20, &humidity, &temperature) != 0) {
                fprintf(stderr, "Failed to read humidity and temperature from AHT20\n");
                humidity = -999.0; // Indicate error
                temperature = -999.0; // Indicate error
            }
        } else {
            humidity = -999.0; // Indicate sensor absence
            temperature = -999.0; // Indicate sensor absence
        }

        motion = read_pir(PIR_GPIO);
        if (motion < 0) {
            fprintf(stderr, "Failed to read motion from PIR sensor\n");
            motion = 0; // Default to no motion
        }

        // Log data
        char filename[64];
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        strftime(filename, sizeof(filename), "%Y-%m-%d.csv", &tm);

        if (log_data(filename, temperature, humidity, motion) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

