#define MOTOR_ENA_GPIO 22
#define MOTOR_IN1_GPIO 23
#define MOTOR_IN2_GPIO 24

// Define SPI device
#define SPI_DEVICE "/dev/spidev0.0"

// Define SPI mode
#define SPI_MODE SPI_MODE_0

// Define SPI bits per word
#define SPI_BITS_PER_WORD 8

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define motor duration
#define MOTOR_DURATION 5 // seconds

// Define log file path
#define LOG_FILE "rain_sensor.log"

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *rain_sensor_line = NULL;
static struct gpiod_line *motor_ena_line = NULL;
static struct gpiod_line *motor_in1_line = NULL;
static struct gpiod_line *motor_in2_line = NULL;
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void control_motor(int direction);
void log_event(const char *message);
void cleanup();
void signal_handler(int signal);
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len);

// Function to read the rain sensor value
int read_rain_sensor() {
    int value = gpiod_line_get_value(rain_sensor_line);
    if (value < 0) {
        fprintf(stderr, "Error reading rain sensor: %s\n", strerror(-value));
        log_event("Error reading rain sensor");
        return -1; // Indicate error
    }
    return value;
}

// Function to control the motor
void control_motor(int direction) {
    if (direction != 0 && direction != 1) {
        fprintf(stderr, "Invalid motor direction: %d\n", direction);
        log_event("Invalid motor direction");
        return;
    }

    if (direction == 0) { // Forward
        if (gpiod_line_set_value(motor_in1_line, 1) < 0) {
            fprintf(stderr, "Error setting motor IN1: %s\n", strerror(-value));
            log_event("Error setting motor IN1");
            return;
        }
        if (gpiod_line_set_value(motor_in2_line, 0) < 0) {
            fprintf(stderr, "Error setting motor IN2: %s\n", strerror(-value));
            log_event("Error setting motor IN2");
            return;
        }
    } else { // Backward
        if (gpiod_line_set_value(motor_in1_line, 0) < 0) {
            fprintf(stderr, "Error setting motor IN1: %s\n", strerror(-value));
            log_event("Error setting motor IN1");
            return;
        }
        if (gpiod_line_set_value(motor_in2_line, 1) < 0) {
            fprintf(stderr, "Error setting motor IN2: %s\n", strerror(-value));
            log_event("Error setting motor IN2");
            return;
        }
    }

    if (gpiod_line_set_value(motor_ena_line, 1) < 0) {
        fprintf(stderr, "Error setting motor ENA: %s\n", strerror(-value));
        log_event("Error setting motor ENA");
        return;
    }

    sleep(MOTOR_DURATION);

    if (gpiod_line_set_value(motor_ena_line, 0) < 0) {
        fprintf(stderr, "Error setting motor ENA: %s\n", strerror(-value));
        log_event("Error setting motor ENA");
        return;
    }

    log_event("Motor stopped");
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to perform SPI transfer
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        log_event("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines and close SPI device
void cleanup() {
    if (rain_sensor_line) {
        gpiod_line_release(rain_sensor_line);
    }
    if (motor_ena_line) {
        gpiod_line_release(motor_ena_line);
    }
    if (motor_in1_line) {
        gpiod_line_release(motor_in1_line);
    }
    if (motor_in2_line) {
        gpiod_line_release(motor_in2_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received (%d). Shutting down...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
