        log_event("Error getting motor ENA GPIO line");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(motor_ena_line, "motor_ena", 0) < 0) {
        fprintf(stderr, "Error requesting motor ENA GPIO line as output: %s\n", strerror(errno));
        log_event("Error requesting motor ENA GPIO line as output");
        cleanup();
        return 1;
    }

    motor_in1_line = gpiod_chip_get_line(gpio_chip, MOTOR_IN1_GPIO);
