        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(motor_in1_line, "motor_in1", 0) < 0) {
        fprintf(stderr, "Error requesting motor IN1 GPIO line as output: %s\n", strerror(errno));
        log_event("Error requesting motor IN1 GPIO line as output");
        cleanup();
        return 1;
    }

    motor_in2_line = gpiod_chip_get_line(gpio_chip, MOTOR_IN2_GPIO);
    if (!motor_in2_line) {
        fprintf(stderr, "Error getting motor IN2 GPIO line: %s\n", strerror(errno));
        log_event("Error getting motor IN2 GPIO line");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(motor_in2_line, "motor_in2", 0) < 0) {
        fprintf(stderr, "Error requesting motor IN2 GPIO line as output: %s\n", strerror(errno));
        log_event("Error requesting motor IN2 GPIO line as output");
        cleanup();
        return 1;
    }

    log_event("Rain sensor monitoring started");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected < 0) {
            fprintf(stderr, "Error reading rain sensor, retrying...\n");
