#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variables for CPU load and PWM values
volatile float cpu_load = 0.0;
int red_pwm = 0;
int green_pwm = 0;
int blue_pwm = 0;

// Function prototypes
float calculate_cpu_load();
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    set_led_color(0, 0, 0); // Turn off LED
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to calculate CPU load
float calculate_cpu_load() {
    FILE *fp;
    char line[1024];
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    float load;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return 0.0; // Return 0.0 on error
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return 0.0; // Return 0.0 on error
    }

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fclose(fp);
        return 0.0; // Return 0.0 on error
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return 0.0; // Return 0.0 on error
    }

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fclose(fp);
        return 0.0; // Return 0.0 on error
    }

    fclose(fp);

    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;

    load = (float)(total - prev_total) / (float)(total);

    return load;
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    // Common-anode: Invert the PWM values
    red_pwm = 255 - red;
    green_pwm = 255 - green;
    blue_pwm = 255 - blue;

    // Set PWM values for each channel
    gpioPWM(RED_PIN, red_pwm);
    gpioPWM(GREEN_PIN, green_pwm);
    gpioPWM(BLUE_PIN, blue_pwm);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range for each channel (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(RED_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Calculate CPU load
        cpu_load = calculate_cpu_load();

        // Map CPU load to color gradient (Green -> Yellow -> Red)
        if (cpu_load <= 0.5) {
            red_pwm = 0;
            green_pwm = (int)(cpu_load * 510);
            blue_pwm = 0;
        } else if (cpu_load <= 1.0) {
            red_pwm = (int)((cpu_load - 0.5) * 510);
            green_pwm = 255;
            blue_pwm = 0;
        } else {
            red_pwm = 255;
            green_pwm = 255;
            blue_pwm = 0;
        }

        // Set LED color
        set_led_color(red_pwm, green_pwm, blue_pwm);

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

