            gpioDelay(100000); // 100ms delay before retrying
            continue;
        }

        // Send data over UDP
        if (send_udp_data(json_string) != 0) {
            fprintf(stderr, "Error sending UDP data, retrying...\n");
        }

        free(json_string); // Free the allocated memory

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

