#include <unistd.h>
#include <pigpio.h>

// Constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define BUFFER_SIZE 20
#define TEMP_MIN 25.0
#define TEMP_MAX 60.0
#define TEMP_MIN_PWM 0
#define TEMP_MAX_PWM 255
#define TEMP_MIN_RAMP 25.0
#define TEMP_MAX_RAMP 40.0
#define TEMP_MIN_STEEP 40.0
#define TEMP_MAX_STEEP 60.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer entries
typedef struct {
    time_t timestamp;
    float temperature;
    int pwm_duty_cycle;
} LogEntry;

// Circular buffer
LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_max31855(int spi_handle, float *temperature, int *fault_status);
int calculate_pwm_duty_cycle(float temperature);
void set_fan_speed(int gpio_pin, int duty_cycle);
void log_data(time_t timestamp, float temperature, int pwm_duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature, int *fault_status) {
    char tx_buffer[4];
    char rx_buffer[4];
    int result;

    // Read 4 bytes from MAX31855
    result = spiXfer(spi_handle, tx_buffer, rx_buffer, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract temperature data
    int16_t thermocouple_data = ((rx_buffer[0] << 8) | rx_buffer[1]) >> 2;
    *temperature = thermocouple_data * 0.25;

    // Extract fault status
    *fault_status = ((rx_buffer[3] >> 6) & 0x07);

    return 0; // Indicate success
}

// Function to calculate PWM duty cycle based on temperature
int calculate_pwm_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature < TEMP_MIN) {
        duty_cycle = TEMP_MIN_PWM;
    } else if (temperature < TEMP_MAX_RAMP) {
        duty_cycle = (int)((temperature - TEMP_MIN_RAMP) / (TEMP_MAX_RAMP - TEMP_MIN_RAMP) * (TEMP_MAX_PWM - TEMP_MIN_PWM));
    } else if (temperature < TEMP_MIN_STEEP) {
        duty_cycle = TEMP_MAX_PWM;
    } else if (temperature < TEMP_MAX) {
        duty_cycle = (int)((temperature - TEMP_MIN_STEEP) / (TEMP_MAX - TEMP_MIN_STEEP) * (TEMP_MAX_PWM - TEMP_MIN_PWM));
    } else {
        duty_cycle = TEMP_MAX_PWM;
    }

    return duty_cycle;
}

// Function to set fan speed using hardware PWM
void set_fan_speed(int gpio_pin, int duty_cycle) {
    gpioPWM(gpio_pin, duty_cycle);
}

// Function to log data to circular buffer
void log_data(time_t timestamp, float temperature, int pwm_duty_cycle) {
    log_buffer[buffer_index].timestamp = timestamp;
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].pwm_duty_cycle = pwm_duty_cycle;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&log_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%d] Timestamp: %s, Temperature: %.2f°C, PWM Duty Cycle: %d\n", index, timestamp_str, log_buffer[index].temperature, log_buffer[index].pwm_duty_cycle);
    }
    printf("--- End of Log Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float temperature;
    int fault_status;
    int pwm_duty_cycle;
    time_t current_time;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read temperature and fault status
        if (read_max31855(spi_handle, &temperature, &fault_status) == 0) {
            // Calculate PWM duty cycle
            pwm_duty_cycle = calculate_pwm_duty_cycle(temperature);

            // Set fan speed
            set_fan_speed(FAN_GPIO, pwm_duty_cycle);

            // Get current timestamp
            current_time = time(NULL);

            // Log data
            log_data(current_time, temperature, pwm_duty_cycle);

            // Print data to console
            printf("Timestamp: %ld, Temperature: %.2f°C, PWM Duty Cycle: %d\n", current_time, temperature, pwm_duty_cycle);
        } else {
            fprintf(stderr, "Failed to read temperature or fault status.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpioDelay takes milliseconds
    }

    // Stop PWM
    gpioPWM(FAN_GPIO, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Print the buffer before exiting
    print_buffer();

    // Terminate pigpio
    gpioTerminate();

    printf("Fan control program terminated.\n");

    return 0;
}

