uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_temperature(int32_t raw_temp);
double calculate_pressure(int32_t raw_pressure, int32_t raw_temp);
double calculate_altitude(double pressure);
int log_data(double temperature, double pressure, double altitude);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int16_t read_int16(int handle, uint8_t reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the BMP180
uint16_t read_uint16(int handle, uint8_t reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_int16(i2c_handle, BMP180_REG_CAL_AC1);
    ac2 = read_int16(i2c_handle, BMP180_REG_CAL_AC2);
    ac3 = read_int16(i2c_handle, BMP180_REG_CAL_AC3);
    ac4 = read_uint16(i2c_handle, BMP180_REG_CAL_AC4);
    ac5 = read_uint16(i2c_handle, BMP180_REG_CAL_AC5);
    ac6 = read_uint16(i2c_handle, BMP180_REG_CAL_AC6);
    b1 = read_int16(i2c_handle, BMP180_REG_CAL_B1);
    b2 = read_int16(i2c_handle, BMP180_REG_CAL_B2);
    mb = read_int16(i2c_handle, BMP180_REG_CAL_MB);
    mc = read_int16(i2c_handle, BMP180_REG_CAL_MC);
    md = read_int16(i2c_handle, BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature from the BMP180
int read_raw_temperature(int32_t *raw_temp)
{
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 4.5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cReadI2CBlockData(i2c_handle, buf[0], buf + 1, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure from the BMP180
int read_raw_pressure(int32_t *raw_pressure)
{
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (OSS << 6); // Pressure measurement command

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }

    gpioDelay(2 + (3 << OSS)); // Wait for conversion

    buf[0] = BMP180_REG_MSB;
    if (i2cReadI2CBlockData(i2c_handle, buf[0], buf + 1, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((uint32_t)buf[0] << 16 | (uint32_t)buf[1] << 8 | (uint32_t)buf[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int32_t raw_temp)
{
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int32_t raw_pressure, int32_t raw_temp)
{
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    X1 = (b2 * (B6 * B6) >> 12) >> 11;
    X2 = ac2 * B6 >> 11;
    int32_t X3 = X1 + X2;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << OSS) + 2) >> 2;

    X1 = ac3 * B6 >> 13;
    X2 = (b1 * (B6 * B6) >> 12) >> 16;
    X3 = ((X1 + X2) + 2) >> 2;
    uint32_t B4 = ac4 * (uint32_t)(X3 + 32768) >> 15;

    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> OSS);
    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    double pressure = p + ((X1 + X2 + 3791) >> 4);
    return pressure;
}

// Function to calculate altitude in meters
double calculate_altitude(double pressure)
{
    return 44330.0 * (1.0 - pow(pressure / 101325.0, 0.1903));
}

// Function to log data to a file
int log_data(double temperature, double pressure, double altitude)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, pressure, altitude);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data)
{
    static int logging_enabled = 0;

    if (level == FALLING_EDGE) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
    }
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO2 as input with pull-up resistor
    gpioSetMode(2, PI_INPUT);
    gpioSetPullUpDown(2, PI_PUD_UP);

    // Set interrupt handler
    gpioSetISRFuncEx(2, FALLING_EDGE, 0, interrupt_handler, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int32_t raw_temp, raw_pressure;
    double temperature, pressure, altitude;

    // Main loop
    while (program_running) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                // Calculate temperature and pressure
                temperature = calculate_temperature(raw_temp);
                pressure = calculate_pressure(raw_pressure, raw_temp);

                // Calculate altitude
                altitude = calculate_altitude(pressure);

                // Log data
                log_data(temperature, pressure, altitude);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

