#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_LINE 8
#define RTD_LOG_FILE "rtd_log.csv"
#define SENSOR_ID_FILE "sensor_id.txt"
#define SENSOR_ID_LENGTH 16
#define READ_INTERVAL_SEC 5

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static char sensor_id[SENSOR_ID_LENGTH] = {0};
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_max31865(int32_t *rtd_raw, int32_t *fault_status);
float calculate_temperature(int32_t rtd_raw);
int log_data(float temperature, int32_t fault_status);
int read_sensor_id(char *id, size_t len);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read data from MAX31865
int read_max31865(int32_t *rtd_raw, int32_t *fault_status) {
    uint8_t tx_buf[4] = {0x00, 0x00, 0x00, 0x00}; // Dummy data for reading
    uint8_t rx_buf[4];

    if (spi_transfer(tx_buf, rx_buf, 4) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    *rtd_raw = ((int32_t)rx_buf[0] << 24) | ((int32_t)rx_buf[1] << 16) | ((int32_t)rx_buf[2] << 8) | (int32_t)rx_buf[3];
    *fault_status = ((int32_t)rx_buf[3] >> 6) & 0x07; // Extract fault status bits

    return 0;
}

// Function to calculate temperature from RTD raw value
float calculate_temperature(int32_t rtd_raw) {
    // Check for fault conditions
    if (rtd_raw & 0x00000007) {
        fprintf(stderr, "Fault detected: 0x%X\n", rtd_raw & 0x00000007);
        return -273.15; // Return absolute zero on fault
    }

    // Extract RTD value (bits 31:18)
    int32_t rtd_value = rtd_raw >> 18;

    // Callendar-Van Dusen equation
    float rtd_resistance = (float)rtd_value * 430.0; // RTD resistance in ohms
    float temperature = (rtd_resistance - 100.0) / 0.385; // Temperature in Celsius

    return temperature;
}

// Function to log data to CSV file
int log_data(float temperature, int32_t fault_status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%s,%.2f,%d\n", timestamp, sensor_id, temperature, fault_status);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to read sensor ID from file
int read_sensor_id(char *id, size_t len) {
    FILE *fp = fopen(SENSOR_ID_FILE, "r");
    if (fp == NULL) {
        perror("Error opening sensor ID file");
        return -1;
    }

    if (fgets(id, len, fp) == NULL) {
        perror("Error reading sensor ID from file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_LINE);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "rtd_sensor", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpiod_line_release(cs_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Read sensor ID
    if (read_sensor_id(sensor_id, sizeof(sensor_id)) < 0) {
        fprintf(stderr, "Failed to read sensor ID, using default ID\n");
        strncpy(sensor_id, "RTD_SENSOR_00000000", sizeof(sensor_id) - 1);
        sensor_id[sizeof(sensor_id) - 1] = '\0'; // Ensure null termination
    }

    // Open log file
    log_file = fopen(RTD_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Sensor ID,Temperature (C),Fault Status\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        int32_t rtd_raw, fault_status;

        // Set CS line low
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("Error setting CS line low");
            break;
        }

        // Read data from MAX31865
        if (read_max31865(&rtd_raw, &fault_status) < 0) {
            fprintf(stderr, "Failed to read MAX31865 data\n");
            // Attempt to re-initialize SPI
            close(spi_fd);
            if (spi_init() < 0) {
                fprintf(stderr, "SPI re-initialization failed\n");
                break;
            }
            // Wait before retrying
            sleep(1);
            continue;
        }

        // Set CS line high
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Error setting CS line high");
            break;
        }

        // Calculate temperature
        float temperature = calculate_temperature(rtd_raw);

        // Log data
        if (log_data(temperature, fault_status) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next reading
        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

