#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0: ultra-low power)
#define BMP180_OSS 0

// GPIO pin for alert
#define ALERT_PIN 24

// Circular buffer size
#define BUFFER_SIZE 60

// Structure to hold calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold pressure readings
typedef struct {
    time_t timestamp;
    float pressure;
} pressure_reading_t;

// Circular buffer
pressure_reading_t pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Calibration data
bmp180_calibration_data_t calibration;

// Function prototypes
int init_i2c();
int read_calibration_data(bmp180_calibration_data_t *calibration);
int read_raw_temperature(int32_t *raw_temperature);
int read_raw_pressure(int32_t *raw_pressure);
float calculate_pressure(int32_t raw_temperature, int32_t raw_pressure);
void add_reading_to_buffer(float pressure);
float calculate_rolling_average();
void trigger_alert();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data(bmp180_calibration_data_t *calibration) {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calibration->ac1 = (data[0] << 8) | data[1];
    calibration->ac2 = (data[2] << 8) | data[3];
    calibration->ac3 = (data[4] << 8) | data[5];
    calibration->ac4 = (data[6] << 8) | data[7];
    calibration->ac5 = (data[8] << 8) | data[9];
    calibration->ac6 = (data[10] << 8) | data[11];
    calibration->b1 = (data[12] << 8) | data[13];
    calibration->b2 = (data[14] << 8) | data[15];
    calibration->mb = (data[16] << 8) | data[17];
    calibration->mc = (data[18] << 8) | data[19];
    calibration->md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature from the BMP180
int read_raw_temperature(int32_t *raw_temperature) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf, 0) != 0) {
        fprintf(stderr, "Error writing to register for temperature read\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, buf[0], buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temperature = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure from the BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf, 0) != 0) {
        fprintf(stderr, "Error writing to register for pressure read\n");
        return -1;
    }

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, buf[0], data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((uint32_t)data[0] << 16 | (uint32_t)data[1] << 8 | (uint32_t)data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate pressure in hPa
float calculate_pressure(int32_t raw_temperature, int32_t raw_pressure) {
    int32_t X1, X2, X3, B3, B5, B6, p;
    unsigned int B4, B7;

    // Temperature calculations
    X1 = ((raw_temperature - (int32_t)calibration.ac6) * (int32_t)calibration.ac5) >> 15;
    X2 = ((int32_t)calibration.mc << 11) / (X1 + calibration.md);
    B5 = X1 + X2;
    float temperature = (B5 + 8) >> 4;

    // Pressure calculations
    B6 = B5 - 4000;
    X1 = (calibration.b2 * (B6 * B6) >> 12) >> 11;
    X2 = calibration.ac2 * B6 >> 11;
    X3 = X1 + X2;
    B3 = (((((int32_t)calibration.ac1) * 4 + X3) << BMP180_OSS) + 2) >> 2;
    X1 = calibration.ac3 * B6 >> 13;
    X2 = (calibration.b1 * (B6 * B6) >> 12) >> 16;
    X3 = ((X1 + X2) + 2) >> 2;
    B4 = calibration.ac4 * (uint32_t)(X3 + 32768) >> 15;
    B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }
    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    p = p + ((X1 + X2 + 3791) >> 4);

    return p / 100.0; // Return pressure in hPa
}

// Function to add a reading to the circular buffer
void add_reading_to_buffer(float pressure) {
    pressure_buffer[buffer_index].timestamp = time(NULL);
    pressure_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average of the last 60 seconds
float calculate_rolling_average() {
    float sum = 0.0;
    int count = 0;
    time_t current_time = time(NULL);

    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE; // Calculate index from the end
        if (pressure_buffer[index].timestamp >= current_time - 60) {
            sum += pressure_buffer[index].pressure;
            count++;
        }
    }

    if (count > 0) {
        return sum / count;
    } else {
        return 0.0; // Return 0 if no readings are available
    }
}

// Function to trigger an alert by setting GPIO24 HIGH for 1 second
void trigger_alert() {
    gpioWrite(ALERT_PIN, 1); // Set GPIO HIGH
    gpioDelay(1000000);       // Wait for 1 second
    gpioWrite(ALERT_PIN, 0); // Set GPIO LOW
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(ALERT_PIN, 0); // Ensure GPIO is LOW on exit
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calibration) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up hardware timer for 50ms interval
    gpioSetTimerFuncEx(0, 50, timer_callback, NULL); // Timer 0, 50ms, callback function, NULL

    printf("BMP180 sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int32_t raw_temperature, raw_pressure;
        float pressure;

        // Read raw temperature and pressure
        if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
            // Calculate pressure
            pressure = calculate_pressure(raw_temperature, raw_pressure);

            // Add reading to buffer
            add_reading_to_buffer(pressure);

            // Calculate rolling average
            float rolling_average = calculate_rolling_average();

            // Check for pressure deviation
            if (fabs(pressure - rolling_average) > 5.0) {
                printf("Alert: Pressure deviation detected! Current: %.2f hPa, Average: %.2f hPa\n", pressure, rolling_average);
                trigger_alert();
            }

            printf("Pressure: %.2f hPa, Rolling Average: %.2f hPa\n", pressure, rolling_average);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying in 50ms.\n");
        }

        gpioDelay(50000); // Wait 50ms
    }

    return 0;
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    // Read raw temperature and pressure
    int32_t raw_temperature, raw_pressure;
    float pressure;

    if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        // Calculate pressure
        pressure = calculate_pressure(raw_temperature, raw_pressure);

        // Add reading to buffer
        add_reading_to_buffer(pressure);

        // Calculate rolling average
        float rolling_average = calculate_rolling_average();

        // Check for pressure deviation
        if (fabs(pressure - rolling_average) > 5.0) {
