            trigger_alert();
        }

        printf("Pressure: %.2f hPa, Rolling Average: %.2f hPa\n", pressure, rolling_average);
    } else {
        fprintf(stderr, "Error reading sensor data. Retrying in 50ms.\n");
    }
}

