void timer_callback();
void signal_handler(int signal);

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the BMP180 sensor
int bmp180_init() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Open I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Set the BMP180 to forced mode
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
