// Function to read calibration data from the BMP180
int bmp180_read_calibration_data() {
    char buf[2];
    char data[22];

    // Read calibration data registers
    buf[0] = BMP180_REG_CAL_AC1;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device for calibration data\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data from I2C device\n");
        return -1;
    }

    // Extract calibration data
    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int bmp180_read_raw_temperature(int32_t *raw_temperature) {
    char buf[2];
    char data[2];

    // Set the BMP180 to forced mode
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature and pressure measurement command
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device for temperature\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    // Read the uncompensated temperature value
    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device for temperature read\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature from I2C device\n");
        return -1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int bmp180_read_raw_pressure(int32_t *raw_pressure) {
    char buf[2];
    char data[3];

    // Set the BMP180 to forced mode
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device for pressure\n");
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for measurement

    // Read the uncompensated pressure value
    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device for pressure read\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure from I2C device\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double bmp180_calculate_temperature(int32_t raw_temperature) {
    int32_t X1 = ((raw_temperature - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double bmp180_calculate_pressure(int32_t raw_pressure, int32_t raw_temperature) {
    int32_t X1 = ((raw_temperature - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    X1 = (b2 * (B6 * B6) >> 12) >> 11;
    X2 = ac2 * B6 >> 11;
    int32_t X3 = X1 + X2;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << BMP180_OSS) + 2) >> 2;

    X1 = ac3 * B6 >> 13;
    X2 = (b1 * (B6 * B6) >> 12) >> 16;
    X3 = ((X1 + X2) + 2) >> 2;
    uint32_t B4 = ac4 * (uint32_t)(X3 + 32768) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);

    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    double pressure = p + ((X1 + X2 + 3791) >> 4);

    return pressure;
}

// Function to log data to a file
void log_data(double temperature, double pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f °C, Pressure: %.2f Pa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Timer callback function
void timer_callback() {
    int32_t raw_temperature, raw_pressure;

    // Read raw temperature and pressure data
    if (bmp180_read_raw_temperature(&raw_temperature) != 0) {
        fprintf(stderr, "Error reading raw temperature, skipping this reading\n");
        return;
    }
    if (bmp180_read_raw_pressure(&raw_pressure) != 0) {
        fprintf(stderr, "Error reading raw pressure, skipping this reading\n");
        return;
    }

