        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (bmp180_read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up a timer interrupt (every 500ms)
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL);

    printf("BMP180 data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
