#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define TEMP_THRESHOLD_LOW 40000  // 40°C in millidegrees Celsius
#define TEMP_THRESHOLD_HIGH 70000  // 70°C in millidegrees Celsius
#define PWM_FREQUENCY 25000       // 25 kHz
#define PWM_RANGE 255
#define LOG_INTERVAL 5          // 5 seconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_cpu_temperature();
int map_temperature_to_duty_cycle(int temperature);
void set_fan_speed(int duty_cycle);
void log_data(int temperature, int duty_cycle);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read CPU temperature from file
int read_cpu_temperature() {
    FILE *fp;
    int temperature = -1; // Initialize to an error value

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temperature) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temperature;
}

// Function to map temperature to duty cycle using linear mapping
int map_temperature_to_duty_cycle(int temperature) {
    int duty_cycle;

    if (temperature < TEMP_THRESHOLD_LOW) {
        duty_cycle = 0;
    } else if (temperature > TEMP_THRESHOLD_HIGH) {
        duty_cycle = PWM_RANGE;
    } else {
        duty_cycle = (int)(((float)(temperature - TEMP_THRESHOLD_LOW) / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW)) * PWM_RANGE);
    }

    return duty_cycle;
}

// Function to set fan speed using PWM
void set_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(int temperature, int duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

