        if (retries >= 100) {
            fprintf(stderr, "Timeout waiting for measurement. Continuing.\n");
            continue; // Skip to the next iteration
        }

        // Read raw data
        if (read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) < 0) {
