        double temperature = compensate_temperature(raw_temperature, calib);
        double pressure = compensate_pressure(raw_pressure, raw_temperature, calib);

        // Log data
        if (log_data(temperature, pressure) < 0) {
            fprintf(stderr, "Failed to log data. Continuing.\n");
        }

        printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);

        sleep(5); // Wait 5 seconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
