        fprintf(stderr, "Incorrect chip ID: 0x%02X. Expected 0x58. Exiting.\n", chip_id);
        close(i2c_fd);
        return 1;
    }

    // Configure BMP280 (forced mode, oversampling x1)
    uint8_t ctrl_meas = (3 << 5) | (3 << 2) | 3; // Temperature x1, Pressure x1, Forced mode
    if (write(i2c_fd, &ctrl_meas, 1) != 1) {
        perror("Error writing to ctrl_meas register");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        int32_t raw_temperature, raw_pressure;

        // Wait for the sensor to complete measurement (check status register)
        uint8_t status;
        int retries = 0;
        do {
            if (read(i2c_fd, &status, 1) != 1) {
                perror("Error reading status register");
                break;
            }
            if (status & 0x04) {
                break; // Measurement complete
            }
            usleep(1000); // Wait 1ms
            retries++;
        } while (retries < 100);

        if (retries >= 100) {
            fprintf(stderr, "Timeout waiting for measurement. Continuing.\n");
            continue; // Skip to the next iteration
        }

        // Read raw data
        if (read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Failed to read raw data. Continuing.\n");
            continue; // Skip to the next iteration
        }

        // Compensate temperature and pressure
        double temperature = compensate_temperature(raw_temperature, calib);
        double pressure = compensate_pressure(raw_pressure, raw_temperature, calib);

        // Log data
        if (log_data(temperature, pressure) < 0) {
            fprintf(stderr, "Failed to log data. Continuing.\n");
        }

        printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);

        sleep(5); // Wait 5 seconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

