#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <gpiod.h>
#include <pthread.h>

// Configuration
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define LED_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t terminate = 0;

// Structure for circular buffer entry
typedef struct {
    time_t timestamp;
    float temperature;
} temperature_sample_t;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
void add_to_buffer(float temperature);
float calculate_average();
void control_led(float average_temperature);
void signal_handler(int sig);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_fd = i2c_open(I2C_BUS, LM75_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature from LM75
int read_temperature(float *temperature) {
    uint8_t buf[2];
    int result = i2c_read_i2c_block_data(i2c_fd, 0x00, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert to Celsius (LSB is 0.125°C)
    *temperature = (float)raw_temp / 256.0;

    return 0;
}

// Function to add temperature to the circular buffer
void add_to_buffer(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

// Function to calculate the average temperature from the buffer
float calculate_average() {
    pthread_mutex_lock(&buffer_mutex);
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    float average = sum / BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
    return average;
}

// Function to control the LED based on the average temperature
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        led_line->set_value(1); // Turn LED on
    } else {
        led_line->set_value(0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        i2c_close(i2c_fd);
    }
    if (led_line != NULL) {
        led_line->release();
    }
    pthread_mutex_destroy(&buffer_mutex);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open GPIO line for LED control
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "temperature_monitor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
            float average_temperature = calculate_average();
            control_led(average_temperature);
            printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

