#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration file path
#define CONFIG_FILE "config.json"

// Default values
#define DEFAULT_TARGET_TEMP 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01

// GPIO pins
#define HEATER_PIN 18
#define SPI_CE0 8

// SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define SPI_MODE 1

// MAX31865 registers
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07

// PID parameters
#define PID_SAMPLE_PERIOD_MS 100

// Global variables
static volatile int running = 1;
static float target_temperature = DEFAULT_TARGET_TEMP;
static float Kp = DEFAULT_KP;
static float Ki = DEFAULT_KI;
static float Kd = DEFAULT_KD;
static int spi_handle;
static float integral = 0.0;
static float previous_error = 0.0;

// Function prototypes
void signal_handler(int signal);
int load_config(const char *filename);
int initialize_spi();
int read_max31865(float *temperature);
float convert_rtd(int rtd_code);
float calculate_temperature(float rtd_resistance);
float calculate_pid(float current_temperature, float target_temperature);
void set_pwm_duty_cycle(int duty_cycle);
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Load configuration from JSON file
int load_config(const char *filename) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        return -1;
    }

    json_t *target = json_object_get(root, "target");
    if (json_is_real(target)) {
        target_temperature = json_real_value(target);
    } else {
        fprintf(stderr, "Warning: target not found in config file, using default: %.2f\n", DEFAULT_TARGET_TEMP);
    }

    json_t *kp = json_object_get(root, "Kp");
    if (json_is_real(kp)) {
        Kp = json_real_value(kp);
    } else {
        fprintf(stderr, "Warning: Kp not found in config file, using default: %.2f\n", DEFAULT_KP);
    }

    json_t *ki = json_object_get(root, "Ki");
    if (json_is_real(ki)) {
        Ki = json_real_value(ki);
    } else {
        fprintf(stderr, "Warning: Ki not found in config file, using default: %.2f\n", DEFAULT_KI);
    }

    json_t *kd = json_object_get(root, "Kd");
    if (json_is_real(kd)) {
        Kd = json_real_value(kd);
    } else {
        fprintf(stderr, "Warning: Kd not found in config file, using default: %.2f\n", DEFAULT_KD);
    }

    json_decref(root);
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MAX31865
int read_max31865(float *temperature) {
    char tx_buffer[4] = {0x00, 0x00, 0x00, 0x00};
    char rx_buffer[4];
    int result;

    result = spiXfer(spi_handle, tx_buffer, rx_buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Check for fault
    int fault = (rx_buffer[3] >> 4) & 0x07;
    if (fault != 0) {
        fprintf(stderr, "Error: MAX31865 fault detected: %d\n", fault);
        return -1;
    }

    // Extract RTD code
    int rtd_code = ((rx_buffer[0] << 8) | rx_buffer[1]) >> 1;

    // Convert RTD code to resistance
    float rtd_resistance = (rtd_code / 32768.0) * 430.0;

    // Convert resistance to temperature
    *temperature = calculate_temperature(rtd_resistance);

    return 0;
}

// Convert RTD resistance to temperature using Callendar-Van Dusen equation
float calculate_temperature(float rtd_resistance) {
    float r0 = 100.0; // Reference resistor value
    float A = 0.0039083; // Calibration coefficient
    float B = -0.0000005775; // Calibration coefficient

    float t = A * rtd_resistance + B * rtd_resistance * rtd_resistance;

    return t;
}

// Calculate PID output
float calculate_pid(float current_temperature, float target_temperature) {
    float error = target_temperature - current_temperature;
    integral += error * PID_SAMPLE_PERIOD_MS / 1000.0;
    float derivative = (error - previous_error) * PID_SAMPLE_PERIOD_MS / 1000.0;
    float output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

// Set PWM duty cycle using pigpio
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000) duty_cycle = 1000;
    gpioPWM(HEATER_PIN, duty_cycle);
}

// Log errors to stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_PIN, 1000); // 1 kHz
    gpioSetPWMrange(HEATER_PIN, 1000); // pigpio range 0-1000

    // Load configuration
    if (load_config(CONFIG_FILE) != 0) {
        fprintf(stderr, "Error: Failed to load configuration, using default values.\n");
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature;
    int duty_cycle;

    printf("Temperature control system started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read temperature from MAX31865
        if (read_max31865(&temperature) == 0) {
            // Calculate PID output
            float pid_output = calculate_pid(temperature, target_temperature);

            // Limit PID output to 0-1000
            if (pid_output < 0) pid_output = 0;
            if (pid_output > 1000) pid_output = 1000;

            // Set PWM duty cycle
            duty_cycle = (int)pid_output;
            set_pwm_duty_cycle(duty_cycle);

            printf("Temperature: %.2f °C, PID Output: %.2f, Duty Cycle: %d\n", temperature, pid_output, duty_cycle);
        } else {
            log_error("Failed to read temperature from MAX31865.");
            // Failsafe: Set PWM to 0 and exit
            set_pwm_duty_cycle(0);
            running = 0; // Exit loop on SPI read failure
        }

        gpioDelay(PID_SAMPLE_PERIOD_MS * 1000); // Delay for PID sample period
    }

    // Cleanup
    set_pwm_duty_cycle(0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();

    printf("Temperature control system stopped.\n");
    return 0;
}

