    write_data[0] = BMP180_REG_CONTROL;
    write_data[1] = 0x2E;
    if (write(i2c_fd, write_data, 2) != 2) {
        perror("Error writing temperature measurement command");
        return -1;
    }

    // Wait for measurement (at least 4.5ms)
    usleep(5000);

    // Read raw temperature data (0xF6)
    write_data[0] = BMP180_REG_MSB;
    if (write(i2c_fd, write_data, 1) != 1) {
        perror("Error writing temperature register address");
        return -1;
    }

    if (read(i2c_fd, read_data, 2) != 2) {
        perror("Error reading raw temperature data");
        return -1;
    }

    *raw_temp = (read_data[0] << 8) | read_data[1];
    return 0;
}

// Read raw pressure data from the BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    uint8_t write_data[2];
    uint8_t read_data[3];

    // Write pressure measurement command (0x34 + (OSS << 6))
    write_data[0] = BMP180_REG_CONTROL;
    write_data[1] = 0x34 + (BMP180_OSS << 6);
    if (write(i2c_fd, write_data, 2) != 2) {
        perror("Error writing pressure measurement command");
        return -1;
    }

    // Wait for measurement (adjust delay based on OSS)
    switch (BMP180_OSS) {
        case 0: usleep(5000); break;
        case 1: usleep(8000); break;
        case 2: usleep(14000); break;
        case 3: usleep(26000); break;
        default: usleep(5000); break; // Default to OSS=0
    }

    // Read raw pressure data (0xF6, 0xF7, 0xF8)
    write_data[0] = BMP180_REG_MSB;
    if (write(i2c_fd, write_data, 1) != 1) {
        perror("Error writing pressure register address");
        return -1;
    }

    if (read(i2c_fd, read_data, 3) != 3) {
        perror("Error reading raw pressure data");
        return -1;
    }

    *raw_pressure = ((read_data[0] << 16) | (read_data[1] << 8) | read_data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Calculate temperature in degrees Celsius
double calculate_temperature(int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Calculate pressure in hPa
double calculate_pressure(int32_t raw_pressure, int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    X1 = (b2 * (B6 * B6) >> 12) >> 11;
    X2 = ac2 * B6 >> 11;
    int32_t X3 = X1 + X2;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << BMP180_OSS) + 2) >> 2;

    X1 = ac3 * B6 >> 13;
    X2 = (b1 * (B6 * B6) >> 12) >> 16;
    X3 = ((X1 + X2) + 2) >> 2;
    uint32_t B4 = ac4 * (uint32_t)(X3 + 32768) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);

    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    double pressure = p + ((X1 + X2 + 3791) >> 4);

    return pressure / 100.0; // Convert to hPa
}

// Log temperature and pressure breaches to a file
void log_breach(double temperature, double pressure) {
    FILE *fp = fopen("breach_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening breach_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Temperature: %.2f°C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fclose(fp);
}

