    float temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate true pressure (Pa)
float calculate_pressure(int32_t raw_pressure, int32_t raw_temp, int oss) {
    int32_t X1 = ((int32_t)raw_temp - (int32_t)ac6) * ((int32_t)ac5) / pow(2, 15);
