#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_BAUD 2000000 // 2 MHz
#define TARGET_TEMPERATURE 25.0
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define MAX_DUTY_CYCLE 800
#define MIN_DUTY_CYCLE 200
#define ANTI_WINDUP_GAIN 1.2
#define ANTI_WINDUP_THRESHOLD 10.0
#define LOG_FILE "heater_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_max31855(int spi_handle, float *thermocouple_temp, float *internal_temp);
float calculate_pid(float setpoint, float actual_temp, float *integral, float *previous_error);
void set_heater_duty_cycle(int gpio, int duty_cycle);
void log_data(float thermocouple_temp, float internal_temp, float pid_output, int duty_cycle);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read temperature data from MAX31855
int read_max31855(int spi_handle, float *thermocouple_temp, float *internal_temp) {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1; // Indicate SPI read error
    }

    // Check for fault conditions
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -2; // Indicate open circuit fault
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -3; // Indicate short to GND fault
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -4; // Indicate short to VCC fault
    }

    // Extract thermocouple temperature
    int16_t thermocouple_raw = (data[0] << 8) | data[1];
    if (thermocouple_raw & 0x4000) {
        thermocouple_raw |= 0xC000; // Sign extend if negative
    }
    *thermocouple_temp = thermocouple_raw * 0.25;

    // Extract internal temperature
    int16_t internal_raw = (data[2] << 8) | data[3];
    if (internal_raw & 0x4000) {
        internal_raw |= 0xC000; // Sign extend if negative
    }
    *internal_temp = internal_raw * 0.0625;

    return 0; // Indicate success
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temp, float *integral, float *previous_error) {
    float error = setpoint - actual_temp;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;

    // Anti-windup
    if (output > MAX_DUTY_CYCLE) {
        output = MAX_DUTY_CYCLE;
        *integral = setpoint - actual_temp; // Reset integral term
    } else if (output < MIN_DUTY_CYCLE) {
        output = MIN_DUTY_CYCLE;
        *integral = setpoint - actual_temp; // Reset integral term
    }

    *previous_error = error;
    return output;
}

// Function to set heater duty cycle using PWM
void set_heater_duty_cycle(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Function to log data to CSV file
void log_data(float thermocouple_temp, float internal_temp, float pid_output, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, thermocouple_temp, internal_temp, pid_output, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main(int argc, char *argv[]) {
    float target_temperature = TARGET_TEMPERATURE;
    float thermocouple_temp, internal_temp;
    float integral = 0.0, previous_error = 0.0;
    float pid_output;
    int duty_cycle;

    // Parse command-line arguments
    if (argc > 1) {
        target_temperature = atof(argv[1]);
        printf("Target temperature set to: %.2f°C\n", target_temperature);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for heater control
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 2 MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Thermocouple Temperature (C),Internal Temperature (C),PID Output (C),Duty Cycle (%%)\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature data
        if (read_max31855(spi_handle, &thermocouple_temp, &internal_temp) == 0) {
            // Calculate PID output
            pid_output = calculate_pid(target_temperature, thermocouple_temp, &integral, &previous_error);

            // Map PID output to duty cycle (0-1000)
            duty_cycle = (int)(pid_output * (MAX_DUTY_CYCLE / 1000.0));

            // Set heater duty cycle
            set_heater_duty_cycle(HEATER_GPIO, duty_cycle);

            // Log data
            log_data(thermocouple_temp, internal_temp, pid_output, duty_cycle);

            printf("Thermocouple Temp: %.2f°C, Internal Temp: %.2f°C, PID Output: %.2f°C, Duty Cycle: %d%%\n",
                   thermocouple_temp, internal_temp, pid_output, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature data. Retrying...\n");
            // Log error
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(log_file, "%s,ERROR,ERROR,ERROR,ERROR\n", timestamp);
            fflush(log_file);
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    set_heater_duty_cycle(HEATER_GPIO, 0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

