    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 2 MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Thermocouple Temperature (C),Internal Temperature (C),PID Output (C),Duty Cycle (%%)\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature data
        if (read_max31855(spi_handle, &thermocouple_temp, &internal_temp) == 0) {
            // Calculate PID output
            pid_output = calculate_pid(target_temperature, thermocouple_temp, &integral, &previous_error);

            // Map PID output to duty cycle (0-1000)
            duty_cycle = (int)(pid_output * (MAX_DUTY_CYCLE / 1000.0));

            // Set heater duty cycle
            set_heater_duty_cycle(HEATER_GPIO, duty_cycle);

            // Log data
            log_data(thermocouple_temp, internal_temp, pid_output, duty_cycle);

            printf("Thermocouple Temp: %.2f°C, Internal Temp: %.2f°C, PID Output: %.2f°C, Duty Cycle: %d%%\n",
                   thermocouple_temp, internal_temp, pid_output, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature data. Retrying...\n");
            // Log error
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(log_file, "%s,ERROR,ERROR,ERROR,ERROR\n", timestamp);
            fflush(log_file);
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    set_heater_duty_cycle(HEATER_GPIO, 0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

