// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM range
#define PWM_RANGE 255

// Define temperature thresholds (m°C)
#define TEMP_THRESHOLD_LOW  40000
#define TEMP_THRESHOLD_MED 59999
#define TEMP_THRESHOLD_HIGH 60000

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *temperature_file = NULL;

// Function prototypes
int read_temperature();
void set_led_color(int red, int green, int blue);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signal);
    set_led_color(0, 0, 0); // Turn off LED
    if (temperature_file != NULL) {
        fclose(temperature_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read CPU temperature from sysfs
int read_temperature() {
    char buffer[10];
    int temperature = -1; // Default to -1 to indicate error

    temperature_file = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (temperature_file == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), temperature_file) == NULL) {
        if (ferror(temperature_file)) {
            perror("Error reading temperature file");
        } else {
            fprintf(stderr, "Temperature file empty or incomplete.\n");
        }
        fclose(temperature_file);
        return -1;
    }

    fclose(temperature_file);

    temperature = atoi(buffer) / 1000; // Convert to m°C

    return temperature;
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    // Invert the color values (common-anode)
    red   = 255 - red;
    green = 255 - green;
    blue  = 255 - blue;

    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(RED_PIN,    1000); // 1 kHz
    gpioSetPWMfrequency(GREEN_PIN, 1000); // 1 kHz
    gpioSetPWMfrequency(BLUE_PIN,   1000); // 1 kHz

    // Register signal handlers for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    printf("Mood light control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int temperature = read_temperature();

        if (temperature != -1) {
            printf("Temperature: %d m°C\n", temperature);

            // Determine LED color based on temperature
            if (temperature < TEMP_THRESHOLD_LOW) {
                set_led_color(0, 0, 255); // Solid Blue
            } else if (temperature < TEMP_THRESHOLD_MED) {
                set_led_color(0, 255, 0); // Solid Green
            } else if (temperature < TEMP_THRESHOLD_HIGH) {
                set_led_color(255, 0, 0); // Solid Red
            } else {
                set_led_color(255, 255, 255); // White (off)
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Using default color.\n");
            set_led_color(255, 255, 255); // White (off)
        }

        gpioDelay(500); // Wait 0.5 seconds
    }

    return 0;
}

