#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <curl/curl.h>

// Configuration
#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define MAX_TIMEOUT_MS 5000

// Global variables
static volatile int running = 1;
static int gpio_initialized = 0;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int checksum_error;
} DHT22Data;

// Function prototypes
int initialize_gpio();
DHT22Data read_dht22_data();
int validate_checksum(unsigned char *data);
int post_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpio_initialized = 1;
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 1); // Release the bus
    gpioDelay(100); // Wait for the bus to settle
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // Send start signal
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // Wait for the sensor to respond
    return 0;
}

// Read data from DHT22 sensor
DHT22Data read_dht22_data() {
    DHT22Data data = {0.0, 0.0, 0};
    unsigned char data_buffer[5] = {0};
    int i, j;

    // Send start signal
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30);

    // Set data line as input
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for the sensor to pull the line low
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1 && timeout < MAX_TIMEOUT_MS) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= MAX_TIMEOUT_MS) {
        fprintf(stderr, "DHT22 timeout waiting for start signal\n");
        data.checksum_error = -1; // Timeout error
        return data;
    }

    // Wait for the sensor to pull the line high
    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 0 && timeout < MAX_TIMEOUT_MS) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= MAX_TIMEOUT_MS) {
        fprintf(stderr, "DHT22 timeout waiting for start signal high\n");
        data.checksum_error = -1; // Timeout error
        return data;
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0 && timeout < MAX_TIMEOUT_MS) {
            gpioDelay(1);
            timeout++;
        }

        if (timeout >= MAX_TIMEOUT_MS) {
            fprintf(stderr, "DHT22 timeout waiting for bit %d start\n", i);
            data.checksum_error = -1; // Timeout error
            return data;
        }

        long start = gpioTick();

        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1 && timeout < MAX_TIMEOUT_MS) {
            gpioDelay(1);
            timeout++;
        }

        if (timeout >= MAX_TIMEOUT_MS) {
            fprintf(stderr, "DHT22 timeout waiting for bit %d end\n", i);
            data.checksum_error = -1; // Timeout error
            return data;
        }

        long end = gpioTick();
        long duration = end - start;

        if (duration > 40) {
            data_buffer[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Validate checksum
    if (validate_checksum(data_buffer) != 0) {
        fprintf(stderr, "DHT22 checksum validation failed\n");
        data.checksum_error = -1; // Checksum error
        return data;
    }

    // Convert data to temperature and humidity
    data.humidity = (float)((data_buffer[0] << 8) | data_buffer[1]) / 10.0;
    data.temperature = (float)(((data_buffer[2] & 0x7F) << 8) | data_buffer[3]) / 10.0;
    if (data_buffer[2] & 0x80) {
        data.temperature *= -1;
    }

    return data;
}

// Validate DHT22 checksum
int validate_checksum(unsigned char *data) {
    unsigned char checksum = 0;
    for (int i = 0; i < 4; i++) {
        checksum += data[i];
    }
    for (int i = 4; i < 7; i++) {
        checksum += data[i];
    }
    return (checksum != data[7]) ? 1 : 0;
}

// Post data to HTTP server using libcurl
int post_data(float temperature, float humidity) {
    CURL *curl;
    CURLcode res;
    char json_payload[100];
    struct curl_slist *headers = NULL;

    // Format JSON payload
    snprintf(json_payload, sizeof(json_payload), "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_payload));

        // Set content type to application/json
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        // Set timeout
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, MAX_TIMEOUT_MS / 1000);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code != 200) {
                fprintf(stderr, "HTTP POST request failed with code: %ld\n", response_code);
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (gpio_initialized) {
        gpioTerminate();
    }
}

// Callback function for libcurl to write received data
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    return realsize;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("DHT22 sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        DHT22Data data = read_dht22_data();

        if (data.checksum_error == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", data.temperature, data.humidity);
            if (post_data(data.temperature, data.humidity) != 0) {
                fprintf(stderr, "Failed to post data to server\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    cleanup();
    return 0;
}

