    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Request temperature reading

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing temperature request\n");
        return -1;
    }

    gpioDelay(5000); // Wait 4.5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cReadI2CBlockData(i2c_handle, buf[0], buf + 1, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temperature = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Read raw pressure from the BMP180
int bmp180_read_raw_pressure(int32_t *raw_pressure)
{
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (BMP180_OSS << 6); // Request pressure reading

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing pressure request\n");
        return -1;
    }

    gpioDelay(26000); // Wait 26ms for OSS=3

    buf[0] = BMP180_REG_MSB;
    if (i2cReadI2CBlockData(i2c_handle, buf[0], buf + 1, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Calculate pressure in hPa
double bmp180_calculate_pressure(int32_t raw_temperature, int32_t raw_pressure)
{
    int32_t X1, X2, X3, B3, B5, B6, p;
    unsigned int B4, B7;

    // Temperature calculations
    X1 = ((raw_temperature - (int32_t)ac6) * (int32_t)ac5) >> 15;
    X2 = ((int32_t)mc << 11) / (X1 + md);
    B5 = X1 + X2;
    double temperature = (B5 + 8) >> 4;

    // Pressure calculations
    B6 = B5 - 4000;
    X1 = (b2 * (B6 * B6) >> 12) >> 11;
    X2 = ac2 * B6 >> 11;
    X3 = X1 + X2;
    B3 = (((((int32_t)ac1) * 4 + X3) << BMP180_OSS) + 2) >> 2;
    X1 = ac3 * B6 >> 13;
    X2 = (b1 * (B6 * B6) >> 12) >> 16;
    X3 = ((X1 + X2) + 2) >> 2;
    B4 = (ac4 * (uint32_t)(X3 + 32768)) >> 15;
    B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }
    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    double pressure = p + ((X1 + X2 + 3791) >> 4);

    return pressure / 100.0; // Convert to hPa
}

// Log pressure to file
void log_pressure(double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f hPa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Interrupt handler
void interrupt_handler(int gpio, int level, uint32_t tick)
{
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    // Debounce the interrupt
    if (current_tick - last_tick < 200000) {
        return; // Ignore the interrupt
    }

    last_tick = current_tick;

    logging_enabled = !logging_enabled;

    if (logging_enabled) {
        printf("Logging enabled\n");
        if (log_file != NULL) {
            fprintf(log_file, "Logging enabled\n");
            fflush(log_file);
        }
    } else {
        printf("Logging disabled\n");
        if (log_file != NULL) {
            fprintf(log_file, "Logging disabled\n");
            fflush(log_file);
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Ctrl+C pressed. Exiting...\n");

    // Close I2C connection
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

