int read_dht22(int gpio, DHT22Data *data);
int post_humidity(const char *url, float humidity);
void signal_handler(int signal);
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Callback function for libcurl to write received data
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    return real_size;
}

// Function to read data from DHT22 sensor
int read_dht22(int gpio, DHT22Data *data) {
    int i, j;
    int data_bits[40];
    int checksum;

    // Set GPIO pin as output
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1); // 1ms
    gpioWrite(gpio, 1);
    gpioDelay(30); // 30us

    // Set GPIO pin as input
    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT22 to pull the data line low
    int timeout = 0;
    while (gpioRead(gpio) == 1 && timeout < 1000) {
        gpioDelay(1); // 1us
        timeout++;
    }

    if (timeout >= 1000) {
        syslog(LOG_ERR, "DHT22: Timeout waiting for start signal");
        return -1;
    }

    // Wait for the DHT22 to pull the data line high
    timeout = 0;
    while (gpioRead(gpio) == 0 && timeout < 1000) {
        gpioDelay(1); // 1us
        timeout++;
    }

    if (timeout >= 1000) {
        syslog(LOG_ERR, "DHT22: Timeout waiting for data signal");
        return -1;
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0 && timeout < 1000) {
            gpioDelay(1); // 1us
            timeout++;
        }

        if (timeout >= 1000) {
            syslog(LOG_ERR, "DHT22: Timeout waiting for data bit start");
            return -1;
        }

        long start = gpioTick();

        timeout = 0;
        while (gpioRead(gpio) == 1 && timeout < 1000) {
            gpioDelay(1); // 1us
            timeout++;
        }

        if (timeout >= 1000) {
            syslog(LOG_ERR, "DHT22: Timeout waiting for data bit end");
            return -1;
        }

        long end = gpioTick();
        data_bits[i] = (end - start) > 40; // 0 if low, 1 if high
    }

