    data->humidity = (float)(((data_bits[0] << 8) + data_bits[1]) / 10.0);
    data->temperature = (float)(((data_bits[2] & 0x7F) << 8) + data_bits[3]) / 10.0;
    if (data_bits[2] & 0x80) {
        data->temperature *= -1;
    }

    data->valid = 1;

    return 0;
}

