#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Configuration
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define TEMP_THRESHOLD_1 45000 // 45°C in millidegrees Celsius
#define TEMP_THRESHOLD_2 55000 // 55°C in millidegrees Celsius
#define TEMP_THRESHOLD_3 65000 // 65°C in millidegrees Celsius
#define MAX_FAN_SPEED 3

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_cpu_temp();
int set_fan_speed(int speed);
int log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_message("Received signal, shutting down...");
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        log_message("Error opening temperature file: ");
        perror(TEMP_FILE);
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        log_message("Error reading temperature from file: ");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temp_milli_celsius;
}

// Function to set fan speed
int set_fan_speed(int speed) {
    FILE *fp;

    if (speed < 0 || speed > MAX_FAN_SPEED) {
        log_message("Invalid fan speed: ");
        fprintf(stderr, "Speed must be between 0 and %d\n", MAX_FAN_SPEED);
        return -1; // Indicate error
    }

    fp = fopen(FAN_FILE, "w");
    if (fp == NULL) {
        log_message("Error opening fan file: ");
        perror(FAN_FILE);
        return -1; // Indicate error
    }

    if (fprintf(fp, "%d", speed) < 0) {
        log_message("Error writing to fan file: ");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return 0; // Indicate success
}

// Function to log messages with timestamps
int log_message(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1; // Indicate error
    }

    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
    return 0; // Indicate success
}

int main() {
    int temp_milli_celsius, fan_speed;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Fan control program started");

    while (program_running) {
        temp_milli_celsius = read_cpu_temp();
        if (temp_milli_celsius == -1) {
            log_message("Failed to read CPU temperature, retrying in 5 seconds...");
            sleep(5);
            continue;
        }

        if (temp_milli_celsius < TEMP_THRESHOLD_1) {
            fan_speed = 0;
        } else if (temp_milli_celsius < TEMP_THRESHOLD_2) {
            fan_speed = 1;
        } else if (temp_milli_celsius < TEMP_THRESHOLD_3) {
            fan_speed = 2;
        } else {
            fan_speed = 3;
        }

        if (set_fan_speed(fan_speed) != 0) {
            log_message("Failed to set fan speed, retrying in 5 seconds...");
        } else {
            char log_message_buffer[128];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "Fan speed set to %d", fan_speed);
            log_message(log_message_buffer);
        }

        sleep(5);
    }

    // Shutdown sequence
    log_message("Shutting down fan...");
    if (set_fan_speed(0) != 0) {
        log_message("Failed to set fan to off, continuing...");
    }

    log_message("Fan control program stopped");

    return 0;
}

