#include <pigpio.h>

// Constants
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // 25 kHz
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define TEMP_THRESHOLD_LOW 40000 // 40°C in millidegrees Celsius
#define TEMP_THRESHOLD_HIGH 70000 // 70°C in millidegrees Celsius
#define PWM_RANGE 1000 // PWM range (0-1000)

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_cpu_temp();
int map_temp_to_duty_cycle(int temperature);
int set_fan_speed(int duty_cycle);
int log_data(int temperature, int duty_cycle);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        perror("Error reading temperature from file");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temp_milli_celsius;
}

// Function to map temperature to PWM duty cycle
int map_temp_to_duty_cycle(int temperature) {
    int duty_cycle;

    if (temperature < TEMP_THRESHOLD_LOW) {
        duty_cycle = 0;
    } else if (temperature > TEMP_THRESHOLD_HIGH) {
        duty_cycle = PWM_RANGE;
    } else {
        duty_cycle = (int)(((float)(temperature - TEMP_THRESHOLD_LOW) / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW)) * PWM_RANGE);
    }

    return duty_cycle;
}

// Function to set fan speed using PWM
int set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        perror("Error setting fan speed");
        return -1; // Indicate error
    }
    return 0;
}

// Function to log data to CSV file
int log_data(int temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1; // Indicate error
        }
        // Write CSV header if the file is newly created
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
        }
    }

    fprintf(log_file, "%s,%d,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int temperature, duty_cycle;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    // Set PWM range
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Cooling system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, using previous value or defaulting to 50°C.\n");
            temperature = 50000; // Default to 50°C
        }

        // Map temperature to duty cycle
        duty_cycle = map_temp_to_duty_cycle(temperature);

        // Set fan speed
        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed, using previous value or defaulting to 0%%.\n");
            duty_cycle = 0; // Default to 0%
        }

        // Log data
        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        printf("Temperature: %d mC, Duty Cycle: %d%%\n", temperature, duty_cycle);

        // Wait for 5 seconds
        sleep(5);
    }

    // Turn off fan and release resources
    set_fan_speed(0);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Cooling system stopped.\n");

    return 0;
}

