#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the encoder sensors
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18

// Define the number of pulses per revolution for the TMAG5110A1
#define PULSES_PER_REVOLUTION 360

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
static volatile int pulse_count = 0;
static volatile int current_state = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Structure to hold encoder data
typedef struct {
    int sensor_a_pin;
    int sensor_b_pin;
    int pulses_per_revolution;
    char *log_file_name;
} EncoderData;

// Function prototypes
int initialize_gpio(EncoderData *data);
void cleanup_gpio(EncoderData *data);
void signal_handler(int signal);
void encoder_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_angular_position(int pulse_count);
int log_data(FILE *fp, int state, double angular_position);

// Function to initialize GPIO pins
int initialize_gpio(EncoderData *data) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(data->sensor_a_pin, PI_INPUT);
    gpioSetMode(data->sensor_b_pin, PI_INPUT);

    // Enable pull-up resistors on both pins
    gpioSetPullUpDown(data->sensor_a_pin, PI_PUD_UP);
    gpioSetPullUpDown(data->sensor_b_pin, PI_PUD_UP);

    // Set up interrupt handlers for both pins
    gpioSetAlertFuncEx(data->sensor_a_pin, encoder_callback, NULL);
    gpioSetAlertFuncEx(data->sensor_b_pin, encoder_callback, NULL);

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio(EncoderData *data) {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Callback function for encoder interrupts
void encoder_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static int last_level_a = 0;
    static int last_level_b = 0;
    int current_level_a = gpioRead(SENSOR_A_PIN);
    int current_level_b = gpioRead(SENSOR_B_PIN);

    // Check for rising edge on Sensor A
    if (gpio == SENSOR_A_PIN && level == 1 && last_level_a == 0) {
        // Check if Sensor B is high
        if (current_level_b == 1) {
            current_state = 3; // Clockwise
        } else {
            current_state = 1; // Counter-clockwise
        }
        pulse_count++;
    }

    // Check for rising edge on Sensor B
    if (gpio == SENSOR_B_PIN && level == 1 && last_level_b == 0) {
        // Check if Sensor A is high
        if (current_level_a == 1) {
            current_state = 2; // Counter-clockwise
        } else {
            current_state = 0; // Clockwise
        }
        pulse_count++;
    }

    last_level_a = current_level_a;
    last_level_b = current_level_b;
}

// Function to calculate angular position
double calculate_angular_position(int pulse_count) {
    return (double)pulse_count * 360.0 / PULSES_PER_REVOLUTION;
}

// Function to log data to file
int log_data(FILE *fp, int state, double angular_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s, State: %d, Angular Position: %.2f\n", timestamp, state, angular_position) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return 1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    EncoderData encoder_data = {SENSOR_A_PIN, SENSOR_B_PIN, PULSES_PER_REVOLUTION, LOG_FILE};

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&encoder_data) != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(encoder_data.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup_gpio(&encoder_data);
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Calculate angular position
        double angular_position = calculate_angular_position(pulse_count);

        // Log data
        if (log_data(log_file, current_state, angular_position) != 0) {
            running = 0; // Exit loop if logging fails
        }

        // Delay to avoid excessive CPU usage
        gpioDelay(10000); // 10ms
    }

    // Cleanup and exit
    cleanup_gpio(&encoder_data);
    printf("Encoder monitoring stopped.\n");
    return 0;
}

