#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define FIFO_DATA_REG 0x60
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "adpd144ri_log.txt"

// Global variables
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *led_line = NULL;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int read_adpd144ri_data(int fd, uint16_t *red, uint16_t *ir);
void control_led(int gpio_fd, int state);
void log_data(FILE *fp, uint16_t red, uint16_t ir);
void signal_handler(int sig);
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line);

// I2C read word function
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select)");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("I2C read");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write (register write)");
        return -1;
    }
    return 0;
}

// Read ADPD144RI data function
int read_adpd144ri_data(int fd, uint16_t *red, uint16_t *ir) {
    int data = i2c_read_word(fd, FIFO_DATA_REG);
    if (data < 0) {
        fprintf(stderr, "Error reading FIFO data\n");
        return -1;
    }
    *red = (uint16_t)((data >> 8) & 0xFFFF); // MSB first
    *ir = (uint16_t)(data & 0xFFFF);
    return 0;
}

// Control LED function
void control_led(int gpio_fd, int state) {
    if (gpiod_line_set_value(led_line, state) < 0) {
        perror("Failed to set LED value");
    }
}

// Log data function
void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize GPIO function
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
