#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_gpio();
int read_register(int handle, uint8_t reg);
int write_register(int handle, uint8_t reg, uint8_t value);
int read_fifo(int handle, uint8_t reg, uint16_t *data);
int verify_sensor(int handle);
int read_sensor_data(int handle, uint16_t *red, uint16_t *ir);
void control_led(int gpio, int state);
void log_data(FILE *fp, uint16_t red, uint16_t ir);
void send_data_to_server(uint16_t red, uint16_t ir);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    uint16_t red;
    uint16_t ir;
} sensor_data_t;

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor verification failed. Exiting.\n");
        control_led(LED_GPIO, 0); // Turn off LED
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        control_led(LED_GPIO, 0); // Turn off LED
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data.red, &sensor_data.ir) == 0) {
            // Log data
            log_data(log_file, sensor_data.red, sensor_data.ir);

            // Send data to server
            send_data_to_server(sensor_data.red, sensor_data.ir);

            // Control LED based on IR reading
            if (sensor_data.ir > IR_THRESHOLD) {
                control_led(LED_GPIO, 1); // Turn on LED
            } else {
                control_led(LED_GPIO, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    return 0;
}

// Read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Failed to read register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Failed to write register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from the FIFO
int read_fifo(int handle, uint8_t reg, uint16_t *data) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read FIFO data: %s\n", strerror(errno));
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// Verify the ADPD144RI sensor
int verify_sensor(int handle) {
    int part_id = read_register(handle, 0x00);
    if (part_id < 0) {
        return -1;
    }

    if (part_id != 0x39) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    printf("Sensor verified. PART_ID: 0x%02X\n", part_id);
    return 0;
}

// Read red and IR channel data from the sensor
int read_sensor_data(int handle, uint16_t *red, uint16_t *ir) {
    if (read_fifo(handle, RED_FIFO_ADDR, red) != 0) {
        return -1;
    }
    if (read_fifo(handle, IR_FIFO_ADDR, ir) != 0) {
        return -1;
    }
    return 0;
}

// Control the LED
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Log data to a file
void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp); // Ensure data is written to disk immediately
}

// Send data to the server
void send_data_to_server(uint16_t red, uint16_t ir) {
    int sockfd;
    struct sockaddr_in servaddr;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket creation failed");
        return;
    }

    memset(&servaddr, 0, sizeof(servaddr));

    // Fill server information
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return;
    }

    // Send data
    char buffer[20];
    snprintf(buffer, sizeof(buffer), "%u,%u", red, ir);
    sendto(sockfd, (const char *)buffer, strlen(buffer), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr));

    close(sockfd);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

