#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_LOG_FILE "flow_log.csv"
#define MEASUREMENT_COMMAND 0x3608
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define READ_DELAY_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t raw_flow;
    float flow_rate;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint8_t *data);
uint8_t crc8(const uint8_t *data, int len);
sensor_data_t convert_to_flow_rate(uint8_t *data);
int log_flow_rate(sensor_data_t flow_rate);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the sensor
int initialize_sensor() {
    uint8_t command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw data to flow rate
sensor_data_t convert_to_flow_rate(uint8_t *data) {
    sensor_data_t flow_rate;
    flow_rate.raw_flow = (data[0] << 8) | data[1];
    flow_rate.flow_rate = (float)flow_rate.raw_flow / 1000.0;
    return flow_rate;
}

// Function to log flow rate to CSV file
int log_flow_rate(sensor_data_t flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate.flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (uL/min)\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    uint8_t sensor_data[3];
    sensor_data_t flow_rate;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (crc8(sensor_data, 2) == sensor_data[2]) {
                // Convert to flow rate
                flow_rate = convert_to_flow_rate(sensor_data);

                // Log flow rate
                log_flow_rate(flow_rate);
            } else {
                fprintf(stderr, "CRC check failed!\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Delay
        gpioDelay(READ_DELAY_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

