#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define TOUCH_DURATION_MS 5000
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the GPIO chip
int init_gpio(const char *chip_name) {
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "ttp223_tamper";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to check if the sensor is touched for a specified duration
int is_touched(int sensor_value, int duration_ms) {
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        int current_value = read_sensor(line);
        if (current_value < 0) {
            return 0; // Return 0 on error
        }

        if (current_value == 0) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            long elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000;
            if (elapsed_ms >= duration_ms) {
                return 1; // Tamper detected
            }
        } else {
            return 0; // Sensor released
        }
        usleep(POLL_INTERVAL_MS * 1000); // Poll every 100ms
    }
}

// Function to print an intrusion alert
void print_intrusion_alert() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Intrusion detected!\n", timestamp);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio(GPIO_CHIP) < 0) {
        return EXIT_FAILURE;
    }

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int sensor_value = read_sensor(line);
        if (sensor_value < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        if (sensor_value == 0) { // Assuming sensor is active low
            if (is_touched(sensor_value, TOUCH_DURATION_MS)) {
                print_intrusion_alert();
            }
        }

        usleep(POLL_INTERVAL_MS * 1000); // Poll every 100ms
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    printf("Tamper detection system stopped.\n");

    return EXIT_SUCCESS;
}

