#include <linux/i2s.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define I2S_DEVICE "/dev/snd/pcmC0D0c" // Or /dev/snd/pcmC0D0p
#define GPIO_PIN 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define BITS_PER_SAMPLE 24
#define BUFFER_SIZE (SAMPLE_RATE * NUM_CHANNELS * (BITS_PER_SAMPLE / 8))
#define FILE_NAME "audio_capture.pcm"
#define LOG_FILE "audio_log.txt"

// Global variables
static int i2s_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold I2S configuration
typedef struct {
    int sample_rate;
    int num_channels;
    int bits_per_sample;
} i2s_config_t;

// Function prototypes
int initialize_i2s(const char *device, i2s_config_t *config);
int read_i2s_data(int fd, uint8_t *buffer, size_t count);
int extract_pcm_samples(const uint8_t *buffer, int16_t *pcm_buffer, size_t count);
int write_pcm_samples_to_file(const int16_t *pcm_buffer, size_t count, const char *filename);
int log_error(const char *message);
void signal_handler(int sig);
int initialize_gpio(int pin);
void release_gpio();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize I2S interface
int initialize_i2s(const char *device, i2s_config_t *config) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2S device");
        return -1;
    }

    // Configure I2S parameters
    struct i2s_config cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.speed = config->sample_rate;
    cfg.channels = config->num_channels;
    cfg.format = I2S_FORMAT_S24_LE; // Left-justified, 24-bit
    cfg.period_size = BUFFER_SIZE;
    cfg.period_count = 1; // Single period
    cfg.buffer_size = BUFFER_SIZE;
    cfg.flags = 0; // No special flags

    if (ioctl(fd, I2S_IOC_INIT, &cfg) < 0) {
        perror("Error initializing I2S");
        close(fd);
        return -1;
    }

    return fd;
}

// Read I2S data from the device
int read_i2s_data(int fd, uint8_t *buffer, size_t count) {
    ssize_t bytes_read = read(fd, buffer, count);
    if (bytes_read < 0) {
        perror("Error reading I2S data");
        return -1;
    }
    return (int)bytes_read;
}

// Extract PCM samples from the I2S data
int extract_pcm_samples(const uint8_t *buffer, int16_t *pcm_buffer, size_t count) {
    size_t i;
    for (i = 0; i < count; i += 3) {
        // Assuming 24-bit data is left-justified
        int32_t sample = (int32_t)((((uint32_t)buffer[i]) << 8) | ((uint32_t)buffer[i + 1]) | ((uint32_t)buffer[i + 2])) >> 8;
        // Right-shift to get 16-bit PCM sample
        pcm_buffer[i / 3] = (int16_t)(sample >> 8); // Assuming 24-bit data is left-justified
    }
    return 0;
}

// Write PCM samples to a file
int write_pcm_samples_to_file(const int16_t *pcm_buffer, size_t count, const char *filename) {
    FILE *fp = fopen(filename, "ab");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(pcm_buffer, sizeof(int16_t), count, fp);
    if (bytes_written != count) {
        perror("Error writing to file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Log errors to a file
int log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
    return 0;
}

// Initialize GPIO pin
int initialize_gpio(int pin) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "audio_capture";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Set initial value to LOW (microphone disabled)
    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        perror("Error setting GPIO line value");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Release GPIO resources
void release_gpio() {
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0); // Ensure microphone is disabled
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2S
    i2s_config_t i2s_config = {SAMPLE_RATE, NUM_CHANNELS, BITS_PER_SAMPLE};
    i2s_fd = initialize_i2s(I2S_DEVICE, &i2s_config);
    if (i2s_fd < 0) {
        log_error("I2S initialization failed");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio(GPIO_PIN) < 0) {
        log_error("GPIO initialization failed");
        close(i2s_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        release_gpio();
        close(i2s_fd);
        return 1;
    }

    uint8_t *buffer = (uint8_t *)malloc(BUFFER_SIZE);
    if (buffer == NULL) {
        perror("Error allocating buffer");
        log_error("Failed to allocate buffer");
        release_gpio();
        close(i2s_fd);
        fclose(log_file);
        return 1;
    }

    int16_t *pcm_buffer = (int16_t *)malloc(BUFFER_SIZE / 2); // Allocate for 16-bit samples
    if (pcm_buffer == NULL) {
        perror("Error allocating PCM buffer");
        log_error("Failed to allocate PCM buffer");
        free(buffer);
        release_gpio();
        close(i2s_fd);
        fclose(log_file);
        return 1;
    }

    printf("Audio capture started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        // Select the left channel
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Error setting GPIO line value");
            log_error("Failed to set GPIO line value");
            break;
        }

        // Read I2S data
        int bytes_read = read_i2s_data(i2s_fd, buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            log_error("Failed to read I2S data");
            break;
        }

        // Extract PCM samples
        if (extract_pcm_samples(buffer, pcm_buffer, bytes_read) < 0) {
            log_error("Failed to extract PCM samples");
            break;
        }

        // Write PCM samples to file
        if (write_pcm_samples_to_file(pcm_buffer, bytes_read / 2, FILE_NAME) < 0) {
            log_error("Failed to write PCM samples to file");
            break;
        }

        usleep(1000); // Sleep for 1ms to control sampling rate
    }

    // Cleanup
    printf("Cleaning up...\n");
    free(buffer);
    free(pcm_buffer);
    release_gpio();
    close(i2s_fd);
    fclose(log_file);

    printf("Audio capture stopped.\n");

