#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define PWM range
#define PWM_RANGE 1000

// Define log file name
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int duty_cycle);
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, PWM_RANGE);

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to control the cooling fan
void control_fan(int duty_cycle) {
    if (duty_cycle >= 0 && duty_cycle <= 80) {
        gpioPWM(FAN_PIN, duty_cycle * PWM_RANGE / 100); // Scale duty cycle to PWM range
    } else {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
    }
}

// Function to log events to a file
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Stop PWM
    gpioPWM(FAN_PIN, 0);

    // Reset GPIO pins
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set back to input
    gpioSetMode(FAN_PIN, PI_INPUT);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    log_event("System started");

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0) {
            // Flame detected
            log_event("Flame detected");
            control_fan(50); // Fan on, 50% duty cycle
            gpioDelay(500000); // 500ms delay

            // Flame ended
            log_event("Flame ended");
            control_fan(0); // Fan off
            gpioDelay(500000); // 500ms delay
        } else {
            // No flame detected
            control_fan(0); // Ensure fan is off
            gpioDelay(50000); // 50ms delay
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

