#include <pigpio.h>

// Configuration structure
typedef struct {
    float start_frequency;
    float end_frequency;
    int chirps;
    int samples;
    int frame_period_ms;
} Config;

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi();
int configure_awr1642();
int read_heatmap_data(uint8_t *data, int data_len);
int log_frame(uint8_t *data, int data_len, uint64_t timestamp, int frame_number);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open SPI channel
int open_spi() {
    spi_handle = spiOpen(0, 1000000, 0); // CE0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        return -1;
    }
    return 0;
}

// Configure AWR1642 (replace with actual configuration from the SDK)
int configure_awr1642() {
    // This is a placeholder.  A real implementation would
    // configure the AWR1642 using the mmwave SDK's configuration API.
    // For example, you might write to a configuration file or
    // send commands to the AWR1642 via a serial port.
    // For this example, we'll just print a message.
    printf("AWR1642 configuration started...\n");
    // In a real implementation, you would use the mmwave SDK's
    // configuration API to configure the AWR1642.
    // For example, you might write to a configuration file or
    // send commands to the AWR1642 via a serial port.
    // For this example, we'll just print a message.
    printf("AWR1642 configuration complete.\n");
    return 0;
}

// Read heatmap data from AWR1642
int read_heatmap_data(uint8_t *data, int data_len) {
    int bytes_read = spiRead(spi_handle, (char *)data, data_len);
    if (bytes_read != data_len) {
        fprintf(stderr, "SPI read failed: %d bytes read, expected %d\n", bytes_read, data_len);
        return -1;
    }
    return 0;
}

// Log frame data to file
int log_frame(uint8_t *data, int data_len, uint64_t timestamp, int frame_number) {
    size_t bytes_written = fwrite(data, 1, data_len, log_file);
    if (bytes_written != data_len) {
        fprintf(stderr, "File write failed: wrote %zu bytes, expected %d\n", bytes_written, data_len);
        return -1;
    }

    // Write timestamp and frame number to the log file
    if (fwrite(&timestamp, sizeof(uint64_t), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write timestamp to log file\n");
        return -1;
    }
    if (fwrite(&frame_number, sizeof(int), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write frame number to log file\n");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open SPI
    if (open_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure AWR1642
    if (configure_awr1642() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("radar_data.bin", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write log file header
    uint32_t magic_number = 0x52444144; // "RDRD"
    if (fwrite(&magic_number, sizeof(uint32_t), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write magic number to log file\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configuration parameters
    Config config = {
        .start_frequency = 77.0,
        .end_frequency = 79.0,
        .chirps = 64,
        .samples = 256,
        .frame_period_ms = 100
    };

    // Main loop
    uint8_t *heatmap_data = (uint8_t *)malloc(32768); // Allocate memory for heatmap data
    if (heatmap_data == NULL) {
        fprintf(stderr, "Failed to allocate memory for heatmap data\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    uint64_t timestamp;
    int frame_number = 0;

    while (!terminate) {
        // Request data
        gpioWrite(23, 1); // Assert trigger
        gpioDelay(10); // Wait for 10 us
        gpioWrite(23, 0); // De-assert trigger

        // Wait for data ready interrupt
        gpioSetMode(24, PI_INPUT); // Set GPIO 24 as input
        int timeout = 1000; // Timeout after 1 second
        while (gpioRead(24) == 0 && timeout > 0) {
            gpioDelay(1); // Wait 1 us
            timeout--;
        }
        gpioSetMode(24, PI_INPUT); // Set GPIO 24 back to input

        if (timeout == 0) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            continue; // Skip to the next iteration
        }

        // Read heatmap data
        if (read_heatmap_data(heatmap_data, 32768) != 0) {
            fprintf(stderr, "Failed to read heatmap data\n");
            continue; // Skip to the next iteration
        }

        // Get timestamp
        timestamp = gpioTick();

        // Log frame
        if (log_frame(heatmap_data, 32768, timestamp, frame_number) != 0) {
            fprintf(stderr, "Failed to log frame\n");
        }

        frame_number++;

        // Wait for the next frame
        gpioDelay(config.frame_period_ms * 1000); // Convert ms to us
    }

    // Cleanup
    free(heatmap_data);
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

