        }

        frame_number++;

        // Wait for the next frame
        gpioDelay(config.frame_period_ms * 1000); // Convert ms to us
    }

    // Cleanup
    free(heatmap_data);
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

