    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    // Register the signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to continuously monitor the flame sensor
    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == 0) {
            log_event("Flame Detected");
            printf("Flame Detected\n");
        } else if (sensor_value == 1) {
            log_event("Flame Cleared");
            printf("Flame Cleared\n");
        } else {
            fprintf(stderr, "Error reading sensor value, retrying...\n");
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

