#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define SCALE_FACTOR 0.01
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    uint16_t config;
} sensor_config_t;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, uint16_t *result);
float convert_to_lux(uint16_t raw_data);
int log_data(float lux);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the OPT3001 sensor
int initialize_sensor(int i2c_handle) {
    sensor_config_t config = {0xCB00}; // Continuous conversion mode, 100ms conversion time
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config.config >> 8) & 0xFF;
    buf[2] = config.config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Reads the 16-bit result register from the OPT3001
int read_sensor_data(int i2c_handle, uint16_t *result) {
    char buf[1];
    buf[0] = RESULT_REG;

    int result_reg = i2cWriteDevice(i2c_handle, buf, 1);
    if (result_reg != 0) {
        fprintf(stderr, "Error writing to result register: %d\n", result_reg);
        return -1;
    }

    char data[2];
    int result_read = i2cReadDevice(i2c_handle, data, 2);
    if (result_read != 2) {
        fprintf(stderr, "Error reading from result register: %d\n", result_read);
        return -1;
    }

    *result = (data[0] << 8) | data[1];
    return 0;
}

// Converts the raw sensor data to lux
float convert_to_lux(uint16_t raw_data) {
    int exponent = (raw_data >> 12) & 0x0F;
    int mantissa = raw_data & 0x0FFF;
    return SCALE_FACTOR * (1 << exponent) * mantissa;
}

// Logs the lux value with an ISO-8601 timestamp to a file
int log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f lux\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_data;
    float lux;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &raw_data) == 0) {
            lux = convert_to_lux(raw_data);
            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

