#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define GPIO_DIRECTION "in"
#define GPIO_BIAS "pull_up"

static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static struct gpiod_line_request_config *config = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to read the flame detection status
int read_flame_status() {
    int value;
    int ret;

    ret = gpiod_line_request_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error reading line value: %s\n", strerror(-ret));
        return -1; // Indicate an error
    }

    value = ret;
    return value;
}

// Function to log the flame detection status
void log_flame_status(int status) {
    char* timestamp = get_timestamp();
    if (status == 0) {
        printf("%s Flame Detected: YES\n", timestamp);
    } else {
        printf("%s Flame Detected: NO\n", timestamp);
    }
}

int main() {
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request the GPIO line as input
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the GPIO line as input with pull-up resistor
    config = gpiod_line_request_config_new();
    if (!config) {
        fprintf(stderr, "Error creating line request config: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_config_set_consumer(config, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error setting line consumer: %s\n", strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpiod_line_request_config_free(config);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_config_set_bias(config, GPIOD_LINE_REQUEST_CONFIG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error setting line bias: %s\n", strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpiod_line_request_config_free(config);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(line, config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line: %s\n", strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpiod_line_request_config_free(config);
        return EXIT_FAILURE;
    }

    config = NULL; // No longer need the config object after requesting

    // Main loop
    while (program_running) {
        int status = read_flame_status();
        if (status >= 0) {
            log_flame_status(status);
        } else {
            fprintf(stderr, "Error reading flame status, retrying...\n");
        }

        sleep(1);
    }

    // Clean up resources before exiting
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (config) {
        gpiod_line_request_config_free(config);
    }

    return EXIT_SUCCESS;
}

