// Define the GPIO pins connected to the TTP226 channels
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < num_channels; i++) {
        if (gpioSetMode(gpio_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", gpio_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

// Function to read the state of a single channel
int read_channel(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log the state of all channels to the console
void log_channels() {
    for (int i = 0; i < num_channels; i++) {
        int state = read_channel(gpio_pins[i]);
        printf("Channel %d: %d\n", i + 1, state);
    }
}

// Function to release resources (lines and chips)
void cleanup_gpio() {
    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(gpio_pins[i], PI_INPUT); // Set back to input to avoid floating
    }
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the GPIO library and pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop to read and log the sensor data
    while (program_running) {
        log_channels();
        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Release the resources before exiting
    cleanup_gpio();

    return 0;
}

