// Define the GPIO pins connected to the TTP226 channels
const int touch_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = sizeof(touch_pins) / sizeof(touch_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set each GPIO pin as input with a pull-down resistor
    for (int i = 0; i < num_channels; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", touch_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", touch_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

// Function to read the state of each touch sensor channel
int read_touch_channels() {
    int touch_state = 0;
    for (int i = 0; i < num_channels; i++) {
        touch_state |= (gpioRead(touch_pins[i]) << i);
    }
    return touch_state;
}

// Function to format the touch state as a string
char* format_touch_state(int touch_state) {
    static char state_string[100]; // Static buffer to hold the formatted string
    snprintf(state_string, sizeof(state_string), "[%ld ms] ", time(NULL) * 1000); // Get current timestamp in milliseconds
    for (int i = 0; i < num_channels; i++) {
        snprintf(state_string + strlen(state_string), sizeof(state_string) - strlen(state_string), "CH%d=%d ", i + 1, (touch_state >> i) & 1);
    }
    return state_string;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and configure GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to continuously monitor touch sensor channels
    while (program_running) {
        // Read the touch sensor channels
        int touch_state = read_touch_channels();

        // Format the touch state as a string
        char* state_string = format_touch_state(touch_state);

        // Print the formatted string to the console
        printf("%s\n", state_string);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    printf("Touch sensor monitoring stopped.\n");

    return 0;
}

