        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(TOUCH_SENSOR_PINS[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PINS[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(TOUCH_SENSOR_PINS[i], PI_PUD_DOWN) != 0) {
