char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[30]; // Static to persist across calls

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the touch sensor data to the console
void log_touch_sensor_data(int channel_states) {
    char* timestamp = get_iso8601_timestamp();
    printf("%s,%d\n", timestamp, channel_states);
}

