// Define GPIO pins for the touch sensor array
#define TOUCH_SENSOR_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define NUM_CHANNELS 8

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(TOUCH_SENSOR_PINS[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PINS[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(TOUCH_SENSOR_PINS[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", TOUCH_SENSOR_PINS[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

// Function to read the state of all touch sensor channels
int read_touch_sensor_channels() {
    int channel_states = 0;
    for (int i = 0; i < NUM_CHANNELS; i++) {
        channel_states |= (gpioRead(TOUCH_SENSOR_PINS[i]) << i);
    }
    return channel_states;
}

// Function to format the current timestamp as an ISO-8601 string
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[30]; // Static to persist across calls

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the touch sensor data to the console
void log_touch_sensor_data(int channel_states) {
    char* timestamp = get_iso8601_timestamp();
    printf("%s,%d\n", timestamp, channel_states);
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio and configure GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop to read and log touch sensor data
    while (program_running) {
        int channel_states = read_touch_sensor_channels();
        log_touch_sensor_data(channel_states);
        gpioDelay(50000); // 50ms delay (50000 microseconds)
    }

    // Release GPIO resources before exiting
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(TOUCH_SENSOR_PINS[i], PI_INPUT); // Set back to input to avoid issues
    }
    gpioTerminate();

    printf("Touch sensor data logging stopped.\n");

    return 0;
}

