#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define REG_PART_ID 0x00
#define REG_HW_KEY 0x07
#define REG_CHLIST 0x01
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_UV_INDEX0 0x2C
#define REG_UV_INDEX1 0x2D
#define REG_COMMAND 0x30

// Command to force a measurement
#define CMD_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t uv_index;
    uint16_t als_visible;
} sensor_data_t;

// Function prototypes
int init_si1145();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Initialize the Si1145 sensor
int init_si1145() {
    // Check the PART ID
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }

    // Write the HW_KEY value
    if (i2cWriteByteData(i2c_handle, REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error writing HW_KEY\n");
        return -1;
    }

    // Configure the CHLIST register
    if (i2cWriteByteData(i2c_handle, REG_CHLIST, 0x07) < 0) {
        fprintf(stderr, "Error writing CHLIST\n");
        return -1;
    }

    // Force a measurement
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_ALS_FORCE) < 0) {
        fprintf(stderr, "Error writing command\n");
        return -1;
    }

    return 0;
}

// Read UV index and Visible ALS data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    uint8_t buffer[4];

    // Read ALS_VIS data
    if (i2cReadI2CBlockData(i2c_handle, REG_ALS_VIS_DATA0, (char *)buffer, 4) != 4) {
        fprintf(stderr, "Error reading ALS data\n");
        data.uv_index = 0; // Set to 0 on error
        data.als_visible = 0;
        return data;
    }

    data.als_visible = (buffer[1] << 8) | buffer[0];

    // Read UV index
    if (i2cReadI2CBlockData(i2c_handle, REG_UV_INDEX0, (char *)buffer, 2) != 2) {
        fprintf(stderr, "Error reading UV index\n");
        data.uv_index = 0; // Set to 0 on error
        return data;
    }

    data.uv_index = (buffer[1] << 8) | buffer[0];

    return data;
}

// Log the sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, data.uv_index, data.als_visible);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si1145() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header to the log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();

        printf("UV Index: %u, ALS Visible: %u\n", data.uv_index, data.als_visible);
        log_data(data);

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

