#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define GPIO_ALARM 17
#define FLOW_SCALE_FACTOR 0.036
#define ALARM_THRESHOLD 0.5
#define LOG_FILE "flow_log.txt"
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int handle;
    int address;
    float flow_rate;
} sensor_t;

// Function prototypes
int initialize_sensor(int i2c_handle, int address);
int read_flow_rate(int i2c_handle, float *flow_rate);
float calculate_average_flow(float flow1, float flow2);
void log_flow_rate(float flow1, float flow2, float average_flow);
void control_alarm(float average_flow);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize a sensor
int initialize_sensor(int i2c_handle, int address) {
    char cmd[2] = {0x36, 0x08}; // Start measurement command
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor at address 0x%02X: %d\n", address, result);
        return -1;
    }
    gpioDelay(100); // Wait for measurement to complete
    return 0;
}

// Function to read flow rate from a sensor
int read_flow_rate(int i2c_handle, float *flow_rate) {
    char buffer[9];
    int result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading flow rate from sensor: %d\n", result);
        return -1;
    }

    // CRC validation
    uint8_t flow_data[3] = {buffer[0], buffer[1], buffer[2]};
    uint8_t temp_data[3] = {buffer[3], buffer[4], buffer[5]};
    uint8_t crc_flow = buffer[6];
    uint8_t crc_temp = buffer[7];

    if (crc8(flow_data, 3) != crc_flow || crc8(temp_data, 3) != crc_temp) {
        fprintf(stderr, "CRC validation failed for sensor.\n");
        return -1;
    }

    // Convert raw data to signed 16-bit integer
    int16_t raw_flow = (buffer[0] << 8) | buffer[1];
    int16_t raw_temp = (buffer[3] << 8) | buffer[4];

    // Convert to ml/min
    *flow_rate = (float)raw_flow * FLOW_SCALE_FACTOR;

    return 0;
}

// Function to calculate the average flow rate
float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Function to log flow rate data to a file
void log_flow_rate(float flow1, float flow2, float average_flow) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min, Average: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            flow1, flow2, average_flow);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the alarm based on the average flow rate
void control_alarm(float average_flow) {
    if (average_flow < ALARM_THRESHOLD) {
        gpioWrite(GPIO_ALARM, 1); // Set GPIO high
    } else {
        gpioWrite(GPIO_ALARM, 0); // Set GPIO low
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");

    // Release GPIO resources
    gpioWrite(GPIO_ALARM, 0); // Ensure alarm is off
    gpioSetMode(GPIO_ALARM, PI_INPUT); // Set back to input

    // Close I2C file descriptors
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output for alarm
    gpioSetMode(GPIO_ALARM, PI_OUTPUT);
    gpioWrite(GPIO_ALARM, 0); // Ensure alarm is initially off

    // Open I2C file descriptors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        cleanup();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        cleanup();
        return 1;
    }

    // Initialize sensors
    if (initialize_sensor(i2c_handle1, SENSOR1_ADDR) != 0) {
        cleanup();
        return 1;
    }
    if (initialize_sensor(i2c_handle2, SENSOR2_ADDR) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float flow1, flow2, average_flow;
    while (!terminate) {
        // Read flow rates from sensors
        int retry1 = 0, retry2 = 0;
        while (retry1 < I2C_RETRY_COUNT) {
            if (read_flow_rate(i2c_handle1, &flow1) == 0) {
                break; // Success
            } else {
                fprintf(stderr, "Error reading flow rate from sensor 1, retrying...\n");
                retry1++;
                gpioDelay(100); // Wait before retrying
            }
        }
        if (retry1 == I2C_RETRY_COUNT) {
            fprintf(stderr, "Failed to read flow rate from sensor 1 after multiple retries.\n");
