#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define the GPIO pin connected to the KY-033 sensor
#define SENSOR_PIN 4

// Define the circular buffer size
#define BUFFER_SIZE 100

// Structure to hold sensor data and timestamp
typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

// Global variables
SensorData sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(time_t timestamp, int reading);
void print_buffer();
void signal_handler(int signal);

// Function to initialize the pigpio library and configure the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0; // Indicate success
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, int reading) {
    sensor_buffer[buffer_index].timestamp = timestamp;
    sensor_buffer[buffer_index].reading = reading;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Buffer ---\n");
    for (int i = 0; i < buffer_count; i++) {
        time_t timestamp = sensor_buffer[(buffer_index + i) % BUFFER_SIZE].timestamp;
        int reading = sensor_buffer[(buffer_index + i) % BUFFER_SIZE].reading;

        struct tm *timeinfo = localtime(&timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Reading: %d\n", timestamp_str, reading);
    }
    printf("--- End of Buffer ---\n\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop
    print_buffer(); // Print the buffer before exiting
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the GPIO library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Obstacle Avoidance Sensor Program\n");

    // Main loop to poll the sensor and add data to the buffer
    while (running) {
        int reading = read_sensor();

        if (reading == 0) { // Obstacle detected (LOW signal)
            time_t current_time = time(NULL);
            add_to_buffer(current_time, reading);
            printf("Obstacle detected! Reading: %d\n", reading);
        }

        gpioDelay(50); // Delay for 50 milliseconds
    }

    return 0;
}

