            fprintf(stderr, "Error writing to OPERATING_STATUS_REG for read: %d\n", result);
            gpioDelay(10000); // Wait 10ms before retrying
            retries++;
            continue;
        }

        result = i2cReadDevice(i2c_fd, status_buf, 1);
        if (result != 0) {
            fprintf(stderr, "Error reading from OPERATING_STATUS_REG: %d\n", result);
            gpioDelay(10000); // Wait 10ms before retrying
            retries++;
            continue;
        }

        if (status_buf[0] & 0x01) {
            return 0; // Sensor active
        }

        gpioDelay(10000); // Wait 10ms before retrying
        retries++;
    }

    fprintf(stderr, "Sensor failed to activate after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[1];
    char read_buf[6];
    int result;

    // Read X, Y, and Z registers
    buf[0] = X_LSB_REG;
    result = i2cWriteDevice(i2c_fd, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to X_LSB_REG for read: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_fd, read_buf, 6);
    if (result != 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    data->x = (int16_t)((read_buf[1] << 8) | read_buf[0]);
    data->y = (int16_t)((read_buf[3] << 8) | read_buf[2]);
    data->z = (int16_t)((read_buf[5] << 8) | read_buf[4]);

    return 0;
}

// Convert raw sensor data to g
int convert_to_g(int16_t raw_value) {
    return (int)(raw_value * 0.0009765625);
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (csv_file == NULL) {
        csv_file = fopen(CSV_FILE, "a");
        if (csv_file == NULL) {
            fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILE);
            return -1;
        }
        fprintf(csv_file, "Timestamp,X_g,Y_g,Z_g\n");
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, convert_to_g(data.x), convert_to_g(data.y), convert_to_g(data.z));
    fflush(csv_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

