#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25

// Define constants
#define OBSTACLE_THRESHOLD 0 // Active-LOW sensor
#define LED_ON_TIME 1000000 // 1 second in microseconds

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to control the LED
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == PI_BAD_GPIO || sensor2_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading sensor value\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Check if either sensor detects an obstacle
        if (sensor1_value == OBSTACLE_THRESHOLD || sensor2_value == OBSTACLE_THRESHOLD) {
            // Turn LED ON
            control_led(LED_PIN, 1);
            gpioDelay(LED_ON_TIME); // Keep LED ON for 1 second

            // Turn LED OFF
            control_led(LED_PIN, 0);
        }

        gpioDelay(100000); // Poll every 0.1 seconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

