// Define GPIO pins for the sensors
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18

// Define the stall duration in seconds
#define STALL_DURATION 2

// Global variable to track the stall start time
static volatile unsigned int stall_start_time = 0;

// Function prototypes
int read_sensor(int gpio_pin);
int is_stall_detected(int sensor1_value, int sensor2_value);
void log_stall_event();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate(); // Terminate pigpio
    exit(0); // Exit the program
}

// Function to read the value from a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to check if a stall is detected
int is_stall_detected(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

// Function to log a stall event to a file
void log_stall_event() {
    FILE *fp = fopen("stall_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening stall_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Stall detected!\n", timestamp);
    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Error reading sensor, exit loop
            break;
        }

        // Check for stall detection
        if (is_stall_detected(sensor1_value, sensor2_value)) {
            // Stall detected
            if (stall_start_time == 0) {
                // Stall started
                stall_start_time = time(NULL);
            } else {
                // Check if stall duration has elapsed
                if (time(NULL) - stall_start_time >= STALL_DURATION) {
                    // Stall duration has elapsed
                    log_stall_event();
                    stall_start_time = 0; // Reset stall start time
                }
            }
        } else {
            // No stall detected
            stall_start_time = 0; // Reset stall start time
        }

        // Delay to avoid excessive CPU usage
        gpioDelay(100); // 100 milliseconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    return 0;
}

