#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TMAG5170-Q1 I2C address
#define TMAG5170_ADDR 0x0E

// TMAG5170 register addresses
#define TMAG5170_REG_X_MSB 0x00
#define TMAG5170_REG_X_LSB 0x01
#define TMAG5170_REG_Y_MSB 0x02
#define TMAG5170_REG_Y_LSB 0x03
#define TMAG5170_REG_Z_MSB 0x04
#define TMAG5170_REG_Z_LSB 0x05
#define TMAG5170_REG_STATUS 0x06
#define TMAG5170_REG_CONFIG 0x07
#define TMAG5170_REG_ID 0x08

// Configuration values
#define TMAG5170_CONFIG_CONT_MODE 0x01 // Continuous conversion mode
#define TMAG5170_CONFIG_X_AXIS 0x01    // Enable X axis
#define TMAG5170_CONFIG_Y_AXIS 0x02    // Enable Y axis
#define TMAG5170_CONFIG_Z_AXIS 0x04    // Enable Z axis
#define TMAG5170_CONFIG_RANGE_50MT 0x00 // 50 mT range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
float convert_to_mt(int16_t raw_value);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initializes the TMAG5170 sensor
int initialize_sensor() {
    // Check device ID
    int device_id = i2cReadByteData(i2c_handle, TMAG5170_REG_ID);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0x8D) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Configure the sensor
    int config_value = TMAG5170_CONFIG_CONT_MODE | TMAG5170_CONFIG_X_AXIS | TMAG5170_CONFIG_Y_AXIS | TMAG5170_CONFIG_Z_AXIS | TMAG5170_CONFIG_RANGE_50MT;
    int result = i2cWriteByteData(i2c_handle, TMAG5170_REG_CONFIG, config_value);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Reads raw sensor data from the TMAG5170
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[6];

    int result = i2cReadI2CBlockData(i2c_handle, TMAG5170_REG_X_MSB, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        data.x = 0; data.y = 0; data.z = 0; // Return 0 values on error
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Converts raw sensor data to mT
float convert_to_mt(int16_t raw_value) {
    // LSB scale factor for 50 mT range (example value, check datasheet)
    float scale_factor = 0.0001; // Example: 1 LSB = 0.0001 mT
    return (float)raw_value * scale_factor;
}

// Logs sensor data to a CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, convert_to_mt(data.x), convert_to_mt(data.y), convert_to_mt(data.z));
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_mT,Y_mT,Z_mT\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

