#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_GPIO 23
#define LOG_FILE "flood_log.txt"
#define REINIT_DELAY 60 // seconds

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to configure the GPIO pin as an input with a pull-down resistor
int configure_gpio() {
    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN);
    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_GPIO);
}

// Function to log an alert message to the log file
int log_alert(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s ALERT: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to handle re-initialization after a failure
int handle_reinitialization() {
    printf("Attempting to re-initialize pigpio...\n");
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio re-initialisation failed\n");
        return -1;
    }
    if (configure_gpio() != 0) {
        fprintf(stderr, "GPIO re-configuration failed\n");
        gpioTerminate();
        return -1;
    }
    printf("pigpio re-initialized successfully\n");
    return 0;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Configure GPIO
    if (configure_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    time_t last_reinit_time = time(NULL);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) { // Water detected (LOW signal)
            if (log_alert("Water detected") != 0) {
                fprintf(stderr, "Failed to log alert\n");
            }
            printf("Water detected!\n");
        } else if (sensor_value != 1) {
            fprintf(stderr, "Invalid sensor reading: %d\n", sensor_value);
        }

        // Re-initialize pigpio after a specified delay
        time_t current_time = time(NULL);
        if (difftime(current_time, last_reinit_time) >= REINIT_DELAY) {
            if (handle_reinitialization() != 0) {
                fprintf(stderr, "Failed to handle re-initialization\n");
            }
            last_reinit_time = current_time;
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

