#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define SENSOR_3_GPIO 27

// Define log file name
#define LOG_FILE "rpm_log.txt"

// Define pulse counter variables
volatile int pulse_count_1 = 0;
volatile int pulse_count_2 = 0;
volatile int pulse_count_3 = 0;

// Define RPM calculation variables
double rpm_1 = 0.0;
double rpm_2 = 0.0;
double rpm_3 = 0.0;

// Define timer interval (in seconds)
#define TIMER_INTERVAL 1.0

// Define log file buffer size
#define LOG_BUFFER_SIZE 256

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
void sensor_1_callback(int gpio, int level, uint32_t tick);
void sensor_2_callback(int gpio, int level, uint32_t tick);
void sensor_3_callback(int gpio, int level, uint32_t tick);
double calculate_rpm(int pulse_count);
void log_rpm(double rpm_1, double rpm_2, double rpm_3);
void print_rpm(double rpm_1, double rpm_2, double rpm_3);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Callback function for sensor 1
void sensor_1_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        atomic_add(&pulse_count_1, 1);
    }
}

// Callback function for sensor 2
void sensor_2_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        atomic_add(&pulse_count_2, 1);
    }
}

// Callback function for sensor 3
void sensor_3_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        atomic_add(&pulse_count_3, 1);
    }
}

// Function to calculate RPM
double calculate_rpm(int pulse_count) {
    double time_elapsed = TIMER_INTERVAL; // Time elapsed in seconds
    double rpm = (double)pulse_count / time_elapsed * 60.0;
    return rpm;
}

// Function to log RPM to file
void log_rpm(double rpm_1, double rpm_2, double rpm_3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, rpm_1, rpm_2, rpm_3);
    fclose(fp);
}

// Function to print RPM to console
void print_rpm(double rpm_1, double rpm_2, double rpm_3) {
    printf("Sensor 1 RPM: %.2f, Sensor 2 RPM: %.2f, Sensor 3 RPM: %.2f\n", rpm_1, rpm_2, rpm_3);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_3_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_3_GPIO, PI_PUD_UP);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up alert functions for each sensor
    gpioSetAlertFuncEx(SENSOR_1_GPIO, sensor_1_callback, NULL);
    gpioSetAlertFuncEx(SENSOR_2_GPIO, sensor_2_callback, NULL);
    gpioSetAlertFuncEx(SENSOR_3_GPIO, sensor_3_callback, NULL);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Calculate RPM for each sensor
        rpm_1 = calculate_rpm(pulse_count_1);
        rpm_2 = calculate_rpm(pulse_count_2);
        rpm_3 = calculate_rpm(pulse_count_3);

        // Log RPM to file
        log_rpm(rpm_1, rpm_2, rpm_3);

        // Print RPM to console
        print_rpm(rpm_1, rpm_2, rpm_3);

        // Reset pulse counters
        atomic_exchange(&pulse_count_1, 0);
        atomic_exchange(&pulse_count_2, 0);
        atomic_exchange(&pulse_count_3, 0);

        // Wait for the next sample interval
        sleep(TIMER_INTERVAL);
    }

    // Disable the timer and alert callback
    gpioSetAlertFuncEx(SENSOR_1_GPIO, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_2_GPIO, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_3_GPIO, NULL, NULL);

    // Close the log file
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fclose(fp);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

