#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the rotation direction enum
typedef enum {
    CW,
    CCW,
    NONE
} RotationDirection;

// Define the shared state structure
typedef struct {
    RotationDirection direction;
    pthread_mutex_t mutex;
} SharedState;

// Global variables
static volatile int running = 1;
static SharedState shared_state = {NONE, PTHREAD_MUTEX_INITIALIZER};
static FILE *log_file = NULL;

// Function prototypes
RotationDirection determine_rotation_direction(int sensor_a_state, int sensor_b_state);
void log_rotation_event(RotationDirection direction);
void signal_handler(int signal);
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);

// Function to determine the rotation direction based on sensor states
RotationDirection determine_rotation_direction(int sensor_a_state, int sensor_b_state) {
    if (sensor_a_state == 1 && sensor_b_state == 0) {
        return CW;
    } else if (sensor_a_state == 0 && sensor_b_state == 1) {
        return CCW;
    } else {
        return NONE;
    }
}

// Function to log the rotation event to the log file
void log_rotation_event(RotationDirection direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    pthread_mutex_lock(&shared_state.mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s.%03ld: %s\n", timestamp, gpioTick() % 1000, direction == CW ? "CW" : "CCW");
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    pthread_mutex_unlock(&shared_state.mutex);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Interrupt service routine for Sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data) {
    int sensor_b_state = gpioRead(SENSOR_B_GPIO);
    RotationDirection direction = determine_rotation_direction(1, sensor_b_state);

    if (direction != NONE) {
        log_rotation_event(direction);
    }
}

// Interrupt service routine for Sensor B
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data) {
    int sensor_a_state = gpioRead(SENSOR_A_GPIO);
    RotationDirection direction = determine_rotation_direction(sensor_a_state, 1);

    if (direction != NONE) {
        log_rotation_event(direction);
    }
}

int main() {
