#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define server details
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// Global variables
static volatile int running = 1;
static int socket_fd = -1;

// Function prototypes
int initialize_gpio();
int request_line(int gpio);
int read_touch_sensor();
void control_led(int state);
void send_udp_message(const char *message);
void log_message(int priority, const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Request a GPIO line for input
int request_line(int gpio) {
    int line = gpio;
    int ret = gpioSetLineRequest(line, PI_INPUT, PI_PUD_DOWN); // Request line for input with pull-down resistor
    if (ret < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to request line %d: %d", line, ret);
        log_message(LOG_ERR, error_message);
        return -1;
    }
    return 0;
}

// Read the touch sensor value
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Control the LED state
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Send a UDP message
void send_udp_message(const char *message) {
    struct sockaddr_in server_addr;

    // Create socket
    socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        log_message(LOG_ERR, "Failed to create socket");
        return;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        log_message(LOG_ERR, "Invalid server IP address");
        close(socket_fd);
        socket_fd = -1;
        return;
    }

    // Send message
    if (sendto(socket_fd, message, strlen(message), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        log_message(LOG_ERR, "Failed to send UDP message");
    }

    close(socket_fd);
    socket_fd = -1;
}

// Log a message to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Cleanup resources before exiting
void cleanup() {
    log_message(LOG_INFO, "Cleaning up...");
    control_led(0); // Turn off LED
    if (socket_fd != -1) {
        close(socket_fd);
    }
    gpioTerminate();
    closelog();
}

int main() {
    // Open syslog
    openlog("touch_sensor_led", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Request GPIO line
    if (request_line(TOUCH_SENSOR_PIN) != 0) {
        log_message(LOG_ERR, "Failed to request touch sensor line, exiting");
        cleanup();
        return 1;
    }

    log_message(LOG_INFO, "Touch sensor and LED control started");

    // Main loop
    while (running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            control_led(1); // Turn on LED
            send_udp_message("Touch detected");
            log_message(LOG_INFO, "Touch detected, LED on");
        } else {
            control_led(0); // Turn off LED
            log_message(LOG_INFO, "No touch detected, LED off");
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

