#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_GPIO 17
#define LED_GPIO 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static struct timespec last_touch_time;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_led();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set touch sensor GPIO as input with pull-up resistor
    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    // Set LED GPIO as output
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }
    gpioWrite(LED_GPIO, 0); // Initially turn the LED off

    return 0;
}

// Read touch sensor value with debouncing
int read_touch_sensor() {
    int touch_value = gpioRead(TOUCH_SENSOR_GPIO);
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    if (touch_value == 1) {
        // Check if enough time has passed since the last touch
        if (difftime(current_time.tv_sec, last_touch_time.tv_sec) >= 0.005 ||
            (difftime(current_time.tv_sec, last_touch_time.tv_sec) == 0.000 && current_time.tv_nsec - last_touch_time.tv_nsec >= 50000000)) {
            toggle_led();
            last_touch_time = current_time;
        }
    }
    return touch_value;
}

// Toggle the LED state
void toggle_led() {
    int current_led_state = gpioRead(LED_GPIO);
    gpioWrite(LED_GPIO, !current_led_state);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Touch sensor application started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        read_touch_sensor();
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0); // Turn off LED before exiting
    gpioTerminate();

    fprintf(stderr, "Application terminated.\n");
    return 0;
}

