#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 100

// Structure to hold sensor data
typedef struct {
    int sensor_pin;
    int led_pin;
    int state;
    time_t timestamp;
} sensor_data_t;

// Circular buffer
sensor_data_t log_buffer[BUFFER_SIZE];
int buffer_index = 0;
int overflow_count = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void control_led(int pin, int state);
void log_event(int sensor_pin, int led_pin, int state);
void print_log_buffer();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    control_led(LED_1_PIN, 0); // Turn off LED 1
    control_led(LED_2_PIN, 0); // Turn off LED 2
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(LED_1_PIN, PI_OUTPUT);
    gpioSetMode(LED_2_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Control LED state
void control_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Log event to circular buffer
void log_event(int sensor_pin, int led_pin, int state) {
    log_buffer[buffer_index].sensor_pin = sensor_pin;
    log_buffer[buffer_index].led_pin = led_pin;
    log_buffer[buffer_index].state = state;
    log_buffer[buffer_index].timestamp = time(NULL);

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (buffer_index == 0) {
        overflow_count++;
    }
}

// Print log buffer contents
void print_log_buffer() {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index - BUFFER_SIZE + i + BUFFER_SIZE) % BUFFER_SIZE; // Corrected index calculation
        printf("Index: %d, Sensor: %d, LED: %d, State: %d, Timestamp: %ld\n",
               index, log_buffer[index].sensor_pin, log_buffer[index].led_pin, log_buffer[index].state, log_buffer[index].timestamp);
    }
    printf("--- End of Log Buffer ---\n");
    printf("Overflow Count: %d\n", overflow_count);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Touch sensor interface started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Control LEDs based on sensor values
        if (sensor1_value == 1) {
            control_led(LED_1_PIN, 1);
            log_event(SENSOR_1_PIN, LED_1_PIN, 1);
        } else {
            control_led(LED_1_PIN, 0);
            log_event(SENSOR_1_PIN, LED_1_PIN, 0);
        }

