               index, log_buffer[index].sensor_pin, log_buffer[index].led_pin, log_buffer[index].state, log_buffer[index].timestamp);
    }
    printf("--- End of Log Buffer ---\n");
    printf("Overflow Count: %d\n", overflow_count);
}

