#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Global variables
volatile int pulse_count = 0;
volatile unsigned long last_interrupt_time = 0;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void sensor1_callback(int gpio, int level, unsigned int tick);
void sensor2_callback(int gpio, int level, unsigned int tick);
double calculate_rpm();
void log_data(int sensor1_state, int sensor2_state);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int pin;
    int state;
} sensor_t;

sensor_t sensors[] = {
    {SENSOR1_PIN, 0},
    {SENSOR2_PIN, 0}
};

int num_sensors = sizeof(sensors) / sizeof(sensors[0]);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Calculate RPM
        double rpm = calculate_rpm();

        // Log the data
        int sensor1_state = sensors[0].state;
        int sensor2_state = sensors[1].state;
        log_data(sensor1_state, sensor2_state);

        // Print RPM to the console
        printf("RPM: %.2f\n", rpm);

        // Delay for 1 second
        gpioDelay(1000); // pigpioDelay takes milliseconds
    }

    return 0;
}

// Initialize pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    for (int i = 0; i < num_sensors; i++) {
        gpioSetMode(sensors[i].pin, PI_INPUT);
        gpioSetPullUpDown(sensors[i].pin, PI_PUD_UP);
    }

    // Set up interrupt handlers for both sensors
    gpioSetAlertFuncEx(SENSOR1_PIN, sensor1_callback, NULL);
    gpioSetAlertFuncEx(SENSOR2_PIN, sensor2_callback, NULL);

    return 0;
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, unsigned int tick) {
    unsigned long current_time = gpioTick();

    // Debounce
    if (current_time - last_interrupt_time > DEBOUNCE_TIME * 1000) { // Convert ms to us
        pulse_count++;
        last_interrupt_time = current_time;
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, unsigned int tick) {
    unsigned long current_time = gpioTick();

    // Debounce
    if (current_time - last_interrupt_time > DEBOUNCE_TIME * 1000) { // Convert ms to us
        pulse_count++;
        last_interrupt_time = current_time;
    }
}

// Calculate RPM based on pulse count
double calculate_rpm() {
    static unsigned long last_pulse_time = 0;
    unsigned long current_time = gpioTick();

    // Calculate time difference between pulses
    double time_diff = (double)(current_time - last_pulse_time) / 1000000.0; // Convert us to seconds

    // Calculate RPM
    double rpm = (double)pulse_count / time_diff * 60.0;

    // Reset pulse count
    pulse_count = 0;

    // Update last pulse time
    last_pulse_time = current_time;

    return rpm;
}

// Log data to CSV file
void log_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

