#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define alarm activation duration (in seconds)
#define ALARM_DURATION 2

// Define log file name
#define LOG_FILE "bridge_integrity.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
void activate_alarm(int gpio_pin);
void deactivate_alarm(int gpio_pin);
void log_event(const char *event_type);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to activate the alarm
void activate_alarm(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO HIGH
    log_event("ALARM_ACTIVATED");
}

// Function to deactivate the alarm
void deactivate_alarm(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set GPIO LOW
    log_event("ALARM_DEACTIVATED");
}

// Function to log events to file
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Deactivate alarm
    deactivate_alarm(ALARM_PIN);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Enable pull-down resistors
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Check for tilt events
        if (sensor1_value == 1) {
            log_event("TILT_START_SENSOR_1");
            gpioDelay(100000); // 100ms delay
            if (read_sensor(SENSOR_1_PIN) == 1) {
                log_event("TILT_THRESHOLD_EXCEEDED_SENSOR_1");
                activate_alarm(ALARM_PIN);
                gpioDelay(ALARM_DURATION * 1000000); // Activate for 2 seconds
                deactivate_alarm(ALARM_PIN);
                log_event("TILT_END_SENSOR_1");
            }
        }

        if (sensor2_value == 1) {
            log_event("TILT_START_SENSOR_2");
            gpioDelay(100000); // 100ms delay
            if (read_sensor(SENSOR_2_PIN) == 1) {
                log_event("TILT_THRESHOLD_EXCEEDED_SENSOR_2");
                activate_alarm(ALARM_PIN);
                gpioDelay(ALARM_DURATION * 1000000); // Activate for 2 seconds
                deactivate_alarm(ALARM_PIN);
                log_event("TILT_END_SENSOR_2");
            }
        }

        gpioDelay(100000); // Check every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_alarm(ALARM_PIN);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

