#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR_ADDR 0x1D
#define CTRL1_REG 0x1F
#define CTRL2_REG 0x20
#define CTRL3_REG 0x21
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define LED_GPIO 17
#define THRESHOLD 500.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_acceleration();
float calculate_magnitude(sensor_data_t data);
void control_led(int state);
void log_event(float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the Omron D7S-A0011 sensor
int initialize_sensor() {
    // Verify sensor presence by reading CTRL1 register
    int retries = RETRY_COUNT;
    while (retries > 0) {
        int status = i2cReadByteData(i2c_handle, CTRL1_REG);
        if (status >= 0) {
            // Check if the sensor is present (bit 0 of CTRL1 is set)
            if (status & 0x01) {
                printf("Sensor found at address 0x%02X\n", SENSOR_ADDR);
                // Clear power-down bit (bit 0 of CTRL1)
                if (i2cWriteByteData(i2c_handle, CTRL1_REG, 0x01) < 0) {
                    fprintf(stderr, "Error writing to CTRL1 register (power-down bit clear)\n");
                    retries--;
                    gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                    continue;
                }
                return 0; // Success
            } else {
                fprintf(stderr, "Sensor not found at address 0x%02X (CTRL1 bit 0 is clear)\n", SENSOR_ADDR);
                retries--;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }
        } else {
            fprintf(stderr, "Error reading CTRL1 register (attempt %d/%d)\n", RETRY_COUNT - retries + 1, RETRY_COUNT);
            retries--;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Reads acceleration data from the sensor
sensor_data_t read_acceleration() {
    sensor_data_t data;
    int16_t raw_x, raw_y, raw_z;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        // Read X-axis data
        int x_l = i2cReadByteData(i2c_handle, OUT_X_L);
        int x_h = i2cReadByteData(i2c_handle, OUT_X_H);
        if (x_l < 0 || x_h < 0) {
            fprintf(stderr, "Error reading X-axis data (attempt %d/%d)\n", RETRY_COUNT - retries + 1, RETRY_COUNT);
            retries--;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }
        raw_x = (int16_t)((x_h << 8) | x_l);

        // Read Y-axis data
        int y_l = i2cReadByteData(i2c_handle, OUT_Y_L);
        int y_h = i2cReadByteData(i2c_handle, OUT_Y_H);
        if (y_l < 0 || y_h < 0) {
            fprintf(stderr, "Error reading Y-axis data (attempt %d/%d)\n", RETRY_COUNT - retries + 1, RETRY_COUNT);
            retries--;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }
        raw_y = (int16_t)((y_h << 8) | y_l);

        // Read Z-axis data
        int z_l = i2cReadByteData(i2c_handle, OUT_Z_L);
        int z_h = i2cReadByteData(i2c_handle, OUT_Z_H);
        if (z_l < 0 || z_h < 0) {
            fprintf(stderr, "Error reading Z-axis data (attempt %d/%d)\n", RETRY_COUNT - retries + 1, RETRY_COUNT);
            retries--;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }
        raw_z = (int16_t)((z_h << 8) | z_l);

        // Convert raw data to g-force units (assuming +/- 2g range)
        data.x = (float)raw_x / 16384.0; // 2^14 = 16384
        data.y = (float)raw_y / 16384.0;
        data.z = (float)raw_z / 16384.0;

        return data;
    }

    fprintf(stderr, "Failed to read acceleration data after multiple retries.\n");
    data.x = 0.0; // Set to 0 to avoid further issues
    data.y = 0.0;
    data.z = 0.0;
    return data;
}

// Calculates the Euclidean vibration magnitude
float calculate_magnitude(sensor_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Controls the LED state
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Logs an event to the log file
void log_event(float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Vibration Magnitude: %.2f g\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        sensor_data_t data = read_acceleration();

        // Calculate vibration magnitude
        float magnitude = calculate_magnitude(data);

        // Check if vibration exceeds threshold
        if (magnitude > THRESHOLD) {
            printf("Vibration magnitude exceeded threshold: %.2f g\n", magnitude);
            control_led(1); // Turn on LED
            gpioDelay(1000000); // Wait for 1 second (1000000 microseconds)
            control_led(0); // Turn off LED
        }

        // Log event if vibration exceeds threshold
        if (magnitude > THRESHOLD) {
            log_event(magnitude);
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100000 microseconds = 100 milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

