#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define the GPIO chip name and lines
#define GPIOCHIP "gpiochip0"
#define NUM_CHANNELS 8

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[NUM_CHANNELS];

// Function prototypes
int initialize_gpio();
int read_sensor_data(int *sensor_data);
void log_sensor_data(int sensor_data);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initializes the GPIO chip and lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", i, strerror(errno));
            cleanup_gpio();
            return -1;
        }

        // Request the line as input
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor_reader";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting GPIO line %d: %s\n", i, strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Reads the sensor data from all 8 lines
int read_sensor_data(int *sensor_data) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", i, strerror(errno));
            return -1;
        }
        sensor_data[i] = value;
    }
    return 0;
}

// Logs the sensor data with timestamps
void log_sensor_data(int sensor_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s - Sensor Data: 0x%08X\n", timestamp, sensor_data);
}

// Cleans up the GPIO lines and chip
void cleanup_gpio() {
    if (chip) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (lines[i]) {
                gpiod_line_release(lines[i]);
            }
        }
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    int sensor_data;

    // Main loop
    while (1) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_sensor_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        usleep(50000); // 50 milliseconds
    }

    return 0;
}

