#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_REG 0x04
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_veml7700();
int read_als_data(uint16_t *lux);
float calculate_lux(uint16_t raw_lux);
int set_led_brightness(float lux);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure VEML7700 sensor
int configure_veml7700() {
    // ALS gain 1/8, integration time 100ms
    uint16_t config_value = (0x00 << 8) | 0x00; // 0x0000
    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, config_value);
    if (result < 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ambient light data from VEML7700
int read_als_data(uint16_t *lux) {
    int result = i2cReadWordData(i2c_handle, ALS_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read ALS data: %d\n", result);
        return -1;
    }
    *lux = (uint16_t)result;
    return 0;
}

// Calculate lux value from raw data
float calculate_lux(uint16_t raw_lux) {
    return raw_lux * 0.0576;
}

// Set LED brightness using hardware PWM
int set_led_brightness(float lux) {
    int brightness = 0;

    if (lux < 100) {
        brightness = 100;
    } else if (lux < 500) {
        brightness = 75;
    } else if (lux < 1000) {
        brightness = 50;
    } else {
        brightness = 25;
    }

    gpioPWM(LED_GPIO, brightness);
    return brightness;
}

// Log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f, %d, %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure VEML7700
    if (configure_veml7700() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint16_t raw_lux;
    float lux;
    int brightness;
    int error_code = 0;

    // Main loop
    while (!terminate) {
        // Read ALS data
        if (read_als_data(&raw_lux) == 0) {
            // Calculate lux
            lux = calculate_lux(raw_lux);

            // Set LED brightness
            brightness = set_led_brightness(lux);

            // Log data
            log_data(lux, brightness, error_code);
        } else {
            fprintf(stderr, "Error reading ALS data, setting brightness to 0\n");
            log_data(0.0, 0, 1); // Log error code
            brightness = 0;
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpioDelay takes milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

