#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LOG_FILE "light_data.txt"
#define SLEEP_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    uint16_t config_word;
    int exponent;
    float mantissa;
} opt3001_config_t;

// Function prototypes
int init_i2c();
int configure_opt3001(int i2c_handle);
int read_opt3001_result(int i2c_handle, uint16_t *result);
float convert_to_lux(uint16_t raw_value);
int log_data(const char *timestamp, float lux_value);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the OPT3001 sensor
int configure_opt3001(int i2c_handle) {
    uint16_t config_word = 0xC810; // Continuous conversion mode, 100ms conversion time
    char buf[2];
    buf[0] = (config_word >> 8) & 0xFF; // MSB
    buf[1] = config_word & 0xFF;       // LSB

    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, config_word);
    if (result < 0) {
        fprintf(stderr, "Failed to write configuration word: %d\n", result);
        return -1;
    }

    gpioDelay(100); // Wait for conversion to complete (100ms)

    return 0;
}

// Read the result from the OPT3001 sensor
int read_opt3001_result(int i2c_handle, uint16_t *result) {
    char buf[2];
    int result_msb, result_lsb;

    result_msb = i2cReadByteData(i2c_handle, RESULT_REG);
    if (result_msb < 0) {
        fprintf(stderr, "Failed to read MSB: %d\n", result_msb);
        return -1;
    }

    result_lsb = i2cReadByteData(i2c_handle, RESULT_REG + 1);
    if (result_lsb < 0) {
        fprintf(stderr, "Failed to read LSB: %d\n", result_lsb);
        return -1;
    }

    *result = (result_msb << 8) | result_lsb;
    return 0;
}

// Convert raw sensor data to lux
float convert_to_lux(uint16_t raw_value) {
    opt3001_config_t config;
    config.config_word = 0xC810; // Continuous conversion mode, 100ms conversion time
    config.exponent = 0;
    config.mantissa = 0.01;

    // Extract exponent and mantissa from the raw value
    int exponent = (raw_value >> 12) & 0x0F;
    int mantissa = raw_value & 0x0FFF;

    // Apply the conversion formula
    float lux = config.mantissa * (2 ^ exponent);

    return lux;
}

// Log the data to a file
int log_data(const char *timestamp, float lux_value) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Configure OPT3001
    if (configure_opt3001(i2c_handle) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_value;
        float lux_value;
        time_t current_time;
        struct tm *time_info;
        char timestamp[20];

        // Read OPT3001 result
        if (read_opt3001_result(i2c_handle, &raw_value) == 0) {
            // Convert to lux
            lux_value = convert_to_lux(raw_value);

            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Log data
            if (log_data(timestamp, lux_value) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Print lux value to stdout
            printf("%s, %.2f\n", timestamp, lux_value);
        } else {
            fprintf(stderr, "Failed to read OPT3001 result\n");
        }

        // Sleep for the specified interval
        gpioDelay(SLEEP_INTERVAL_SEC * 1000); // pigpioDelay takes milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

