#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x08
#define MEASUREMENT_COMMAND 0x3608
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define FLOW_RANGE_MIN 0.0
#define FLOW_RANGE_MAX 100.0
#define LOG_FILE "cooling_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t raw_flow;
    uint8_t status;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int start_measurement();
int read_sensor_data(sensor_data_t *data);
float convert_flow_rate(int16_t raw_flow);
int validate_flow_rate(float flow_rate);
int log_data(float flow_rate, uint8_t status);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Start continuous measurement
int start_measurement() {
    char cmd[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    gpioDelay(2); // Wait for at least 2 ms
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    data->raw_flow = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->status = buffer[2];

    return 0;
}

// Convert raw flow rate to ml/min
float convert_flow_rate(int16_t raw_flow) {
    return (float)raw_flow / 90.0;
}

// Validate flow rate
int validate_flow_rate(float flow_rate) {
    if (flow_rate < FLOW_RANGE_MIN || flow_rate > FLOW_RANGE_MAX) {
        return 0; // Out of range
    }
    return 1; // In range
}

// Log data to file
int log_data(float flow_rate, uint8_t status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%u\n", timestamp, flow_rate, status);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Check if the file is new and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    // Start measurement
    if (start_measurement() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    float flow_rate;
    uint8_t status;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Validate flow rate
            if (validate_flow_rate(convert_flow_rate(sensor_data.raw_flow))) {
                flow_rate = convert_flow_rate(sensor_data.raw_flow);
                status = sensor_data.status; // Use the status byte directly
            } else {
                flow_rate = -1.0; // Indicate out-of-range
                status = 0x02; // Indicate CRC error
            }
        } else {
            flow_rate = -1.0; // Indicate I2C read error
            status = 0x01; // Indicate I2C error
        }

        // Log data
        if (flow_rate >= 0.0) {
            log_data(flow_rate, status);
        } else {
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
            fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

