#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <gpiod.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define log file name
#define LOG_FILE "path_log.csv"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *middle_line = NULL;
static struct gpiod_line *right_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor(struct gpiod_line *line);
int log_data(int left, int middle, int right);
void cleanup_gpio(void);
void signal_handler(int sig);

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} sensor_data_t;

// Function to initialize GPIO lines
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    if (!left_line) {
        fprintf(stderr, "Error getting GPIO line for left sensor: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    if (!middle_line) {
        fprintf(stderr, "Error getting GPIO line for middle sensor: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(left_line);
        return -1;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (!right_line) {
        fprintf(stderr, "Error getting GPIO line for right sensor: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        return -1;
    }

    // Request GPIO lines as input
    if (gpiod_line_request_input(left_line, "path_monitor") < 0) {
        fprintf(stderr, "Error requesting GPIO line for left sensor as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        return -1;
    }

    if (gpiod_line_request_input(middle_line, "path_monitor") < 0) {
        fprintf(stderr, "Error requesting GPIO line for middle sensor as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        return -1;
    }

    if (gpiod_line_request_input(right_line, "path_monitor") < 0) {
        fprintf(stderr, "Error requesting GPIO line for right sensor as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        return -1;
    }

    return 0;
}

// Function to read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to log data to CSV file
int log_data(int left, int middle, int right) {
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[30];

    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ldZ", tv.tv_usec);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left, middle, right);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
