#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define TOUCH_GPIO 23
#define LED_GPIO 24
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "touch_log.txt"

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_touch_sensor();
int toggle_led();
int log_event(int touch_state, int led_state);
void cleanup();
void signal_handler(int sig);

// Structure to hold GPIO configuration
typedef struct {
    int touch_gpio;
    int led_gpio;
} gpio_config_t;

// Function to initialize GPIO lines
int initialize_gpio() {
    gpio_config_t config = {TOUCH_GPIO, LED_GPIO};

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request touch GPIO as input
    touch_line = gpiod_chip_get_line(gpio_chip, config.touch_gpio);
    if (!touch_line) {
        fprintf(stderr, "Error getting touch GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }
    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        fprintf(stderr, "Error requesting touch GPIO as input: %s\n", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request LED GPIO as output
    led_line = gpiod_chip_get_line(gpio_chip, config.led_gpio);
    if (!led_line) {
        fprintf(stderr, "Error getting LED GPIO line: %s\n", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting LED GPIO as output: %s\n", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to initialize SPI communication
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read the touch sensor value
int read_touch_sensor() {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // MCP3008 command to read channel 0 (single-ended)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error sending SPI message: %s\n", strerror(errno));
        return -1;
    }

    // Extract the ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    // Basic touch detection (adjust threshold as needed)
    return (adc_value > 500) ? 1 : 0;
}

// Function to toggle the LED state
int toggle_led() {
    int current_state = gpiod_line_get_value(led_line);
    int new_state = !current_state;

    if (gpiod_line_set_value(led_line, new_state) < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
        return -1;
    }

    return new_state;
}

// Function to log the event to a file
int log_event(int touch_state, int led_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Touch: %d, LED: %d\n", timestamp, touch_state, led_state);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
