// Structure to hold GPIO configuration
typedef struct {
    int touch_gpio;
    int led_gpio;
} gpio_config_t;

// Function to initialize GPIO lines
int initialize_gpio() {
    gpio_config_t config = {TOUCH_GPIO, LED_GPIO};

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

