        gpiod_chip_close(gpio_chip);
        return -1;
    }
    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        fprintf(stderr, "Error requesting touch GPIO as input: %s\n", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request LED GPIO as output
    led_line = gpiod_chip_get_line(gpio_chip, config.led_gpio);
    if (!led_line) {
        fprintf(stderr, "Error getting LED GPIO line: %s\n", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting LED GPIO as output: %s\n", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to initialize SPI communication
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
