#define DEBOUNCE_TIME 200

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_led();
void log_touch_event();
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int led_state;
} ProgramState;

ProgramState state = {0}; // Initialize LED state to off

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected) {
            toggle_led();
            log_touch_event();
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay
        }

        gpioDelay(10 * 1000); // Check every 10ms
    }

    // Cleanup
    printf("Cleaning up and exiting...\n");
    fclose(log_file);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Read the touch sensor value
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Toggle the LED state
void toggle_led() {
    state.led_state = !state.led_state; // Toggle the state
    gpioWrite(LED_PIN, state.led_state);
}

