    gpioWrite(LED_PIN, state.led_state);
}

// Log the touch event to a file
void log_touch_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20]; // YYYY-MM-DDTHH:MM:SSZ\0

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

