#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x4A
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A
#define MOVING_AVG_SIZE 5
#define SAMPLE_RATE_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for moving average filter
typedef struct {
    int buffer[MOVING_AVG_SIZE];
    int index;
    int count;
} MovingAverageFilter;

// Function prototypes
int initialize_sensor();
int read_heart_rate(int *raw_value);
double convert_to_bpm(int raw_value);
double apply_moving_average(MovingAverageFilter *filter, double new_value);
void log_data(double bpm);
void signal_handler(int signal);
void moving_average_init(MovingAverageFilter *filter);

// Moving average filter initialization
void moving_average_init(MovingAverageFilter *filter) {
    filter->index = 0;
    filter->count = 0;
    memset(filter->buffer, 0, sizeof(filter->buffer));
}

// Initialize the Si1182 sensor
int initialize_sensor() {
    // Reset the sensor (optional, but good practice)
    if (i2cWriteByteData(i2c_handle, 0x07, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure LED current
    if (i2cWriteByteData(i2c_handle, LED_CURRENT_REG, 0x3F) < 0) {
        fprintf(stderr, "Error: Failed to write LED current.\n");
        return -1;
    }

    // Configure averaging
    if (i2cWriteByteData(i2c_handle, AVERAGING_REG, 0x04) < 0) {
        fprintf(stderr, "Error: Failed to write averaging.\n");
        return -1;
    }

    // Enable the sensor
    if (i2cWriteByteData(i2c_handle, ENABLE_REG, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write enable.\n");
        return -1;
    }

    // Verify sensor ID
    int part_id = i2cReadByteData(i2c_handle, 0x00);
    if (part_id != 0x02) {
        fprintf(stderr, "Error: Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Verify HW_REV
    int hw_rev = i2cReadByteData(i2c_handle, 0x01);
    if (hw_rev != 0x01) {
        fprintf(stderr, "Error: Incorrect HW_REV: 0x%02X\n", hw_rev);
        return -1;
    }

    return 0;
}

// Read heart-rate data from the sensor
int read_heart_rate(int *raw_value) {
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        *raw_value = i2cReadWordData(i2c_handle, HEART_RATE_REG);
        if (*raw_value >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to read heart-rate (attempt %d): %d\n", 4 - retries, *raw_value);
            gpioDelay(delay_ms);
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    fprintf(stderr, "Error: Failed to read heart-rate after multiple retries.\n");
    return -1; // Failure
}

// Convert raw heart-rate data to BPM
double convert_to_bpm(int raw_value) {
    // Assuming raw_value is a 16-bit value, and the sensor is configured for 100Hz sampling
    // and averaging.  The formula is based on the Si1182-A-GM datasheet.
    // This is a simplified example and may need adjustment based on your sensor's configuration.
    // The formula is: BPM = (raw_value * 0.5) / 100.0;
    return (double)raw_value * 0.5 / 100.0;
}

// Apply a moving average filter
double apply_moving_average(MovingAverageFilter *filter, double new_value) {
    filter->buffer[filter->index] = (int)(new_value * 100); // Store as integer for averaging
    filter->index = (filter->index + 1) % MOVING_AVG_SIZE;
    if (filter->count < MOVING_AVG_SIZE) {
        filter->count++;
    }

    int sum = 0;
    for (int i = 0; i < filter->count; i++) {
        sum += filter->buffer[i];
    }
    return (double)sum / filter->count;
}

// Log data to a CSV file
void log_data(double bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,BPM\n");
    }
    rewind(log_file);

    // Initialize moving average filter
    MovingAverageFilter moving_avg_filter;
    moving_average_init(&moving_avg_filter);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int raw_heart_rate;
    double bpm;
    while (!terminate) {
        // Read heart-rate data
        if (read_heart_rate(&raw_heart_rate) == 0) {
            // Convert to BPM
            bpm = convert_to_bpm(raw_heart_rate);

            // Apply moving average filter
            bpm = apply_moving_average(&moving_avg_filter, bpm);

            // Validate BPM
            if (bpm >= 30.0 && bpm <= 220.0) {
                // Log the data
                log_data(bpm);
            } else {
                fprintf(stderr, "Warning: Invalid BPM value: %.2f\n", bpm);
            }
        } else {
            fprintf(stderr, "Error: Failed to read heart-rate, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_RATE_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

