    // Release the GPIO line
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT); // Set back to input
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_OFF); // Disable pull-up/down

    // Close the log file
