#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <gpiod.h>

// Define GPIO pins for touch sensor outputs and counter display
#define TOUCH_SENSOR_OUTPUT_PINS {5, 6, 7, 8, 9, 10, 11, 12}
#define COUNTER_DISPLAY_OUTPUT_PINS {17, 24, 25, 26, 27, 28, 29, 30}

// Define the number of channels
#define NUM_CHANNELS 8

// Define the log file name
#define LOG_FILE "touch_log.txt"

// Define the stabilization delay in milliseconds
#define STABILIZATION_DELAY 200

// Structure to hold the state of a touch sensor channel
typedef struct {
    int pin;
    int previous_state;
    int current_state;
    int counter;
} TouchSensorChannel;

// Global variables
static struct gpiod_chip *chip = NULL;
static TouchSensorChannel channels[NUM_CHANNELS];
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **lines, int num_lines, int *pin_numbers);
int configure_touch_sensor_channels(struct gpiod_chip *chip, struct gpiod_line **lines, int num_lines, int *pin_numbers);
int configure_counter_display_channels(struct gpiod_chip *chip, struct gpiod_line **lines, int num_lines, int *pin_numbers);
int read_touch_sensor_channel(struct gpiod_line *line);
int increment_counter(int *counter);
int display_counter(int counter, struct gpiod_line **lines, int num_lines, int *pin_numbers);
int log_touch_event(int channel, int counter);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize GPIO pins
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **lines, int num_lines, int *pin_numbers) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    *lines = calloc(num_lines, sizeof(struct gpiod_line *));
    if (!*lines) {
        fprintf(stderr, "Error allocating memory for GPIO lines\n");
        gpiod_chip_close(*chip);
        return -1;
    }

    for (int i = 0; i < num_lines; i++) {
        *lines[i] = gpiod_chip_get_line(*chip, pin_numbers[i]);
        if (!*lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", pin_numbers[i], strerror(errno));
            cleanup();
            return -1;
        }
    }

    return 0;
}

// Configure touch sensor channels
int configure_touch_sensor_channels(struct gpiod_chip *chip, struct gpiod_line **lines, int num_lines, int *pin_numbers) {
    for (int i = 0; i < num_lines; i++) {
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(*lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting GPIO line %d for input: %s\n", pin_numbers[i], strerror(errno));
            cleanup();
            return -1;
        }

        channels[i].pin = pin_numbers[i];
        channels[i].previous_state = 0; // Initialize to 0
        channels[i].current_state = 0;
        channels[i].counter = 0;
    }
    return 0;
}

// Configure counter display channels
int configure_counter_display_channels(struct gpiod_chip *chip, struct gpiod_line **lines, int num_lines, int *pin_numbers) {
    for (int i = 0; i < num_lines; i++) {
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "counter_display";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(*lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", pin_numbers[i], strerror(errno));
            cleanup();
            return -1;
        }
    }
    return 0;
}

// Read the state of a touch sensor channel
int read_touch_sensor_channel(struct gpiod_line *line) {
    int value = gpiod_line_request_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Increment the counter
int increment_counter(int *counter) {
    *counter = (*counter + 1) % 256; // Wrap around to 0-255
    return 0;
}

// Display the counter on the 8-bit binary counter
int display_counter(int counter, struct gpiod_line **lines, int num_lines, int *pin_numbers) {
    for (int i = 0; i < 8; i++) {
        int bit = (counter >> (7 - i)) & 1; // MSB first
        if (gpiod_line_request_set_value(*lines[i + 17], bit) < 0) {
            fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
            return -1; // Indicate an error
        }
    }
    return 0;
}

// Log a touch event to the log file
int log_touch_event(int channel, int counter) {
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[30];

    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Cleanup resources before exiting
void cleanup() {
    if (chip) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (channels[i].lines) {
                gpiod_line_request_release(channels[i].lines[0]);
            }
        }
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &channels[0].lines, NUM_CHANNELS, TOUCH_SENSOR_OUTPUT_PINS) < 0) {
        return 1;
    }

    // Configure touch sensor channels
    if (configure_touch_sensor_channels(chip, &channels[0].lines, NUM_CHANNELS, TOUCH_SENSOR_OUTPUT_PINS) < 0) {
        cleanup();
        return 1;
    }

    // Configure counter display channels
    if (configure_counter_display_channels(chip, &channels[0].lines, NUM_CHANNELS, COUNTER_DISPLAY_OUTPUT_PINS) < 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Warning: Could not open log file %s. Logging to stdout.\n", LOG_FILE);
    }

    // Main loop
    while (!terminate) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int current_state = read_touch_sensor_channel(channels[i].lines[0]);
            if (current_state < 0) {
                fprintf(stderr, "Error reading sensor on channel %d, skipping.\n", i + 1);
                continue; // Skip to the next channel
            }

            if (current_state == 1 && channels[i].previous_state == 0) {
                // Rising edge detected
                increment_counter(&channels[i].counter);
                display_counter(channels[i].counter, &channels[0].lines, NUM_CHANNELS, COUNTER_DISPLAY_OUTPUT_PINS);
                log_touch_event(i + 1, channels[i].counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, channels[i].counter);
                usleep(STABILIZATION_DELAY * 1000); // Stabilize for 200ms
            }

            channels[i].previous_state = current_state;
        }
        usleep(10000); // Poll every 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

