#include <arpa/inet.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22

// Define the server IP address and port
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// Define the log file name
#define LOG_FILE "tracking_log.csv"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int socket_desc;
static struct sockaddr_in server_addr;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int log_data(int sensor1_value, int sensor2_value, int sensor3_value, int sensor4_value);
int send_data_to_server(int sensor1_value, int sensor2_value, int sensor3_value, int sensor4_value);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1;
    int sensor2;
    int sensor3;
    int sensor4;
} sensor_data_t;

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetMode(SENSOR4_PIN, PI_INPUT);

    // Enable pull-up resistors (optional, depends on sensor module)
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR4_PIN, PI_PUD_UP);

    return 0;
}

