int log_data(int sensor1_value, int sensor2_value, int sensor3_value, int sensor4_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
            return -1;
        }

        // Write the header row if the file is newly created
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Sensor1,Sensor2,Sensor3,Sensor4\n");
        }
    }

    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, sensor3_value, sensor4_value);
