#include <sys/types.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO17 17
#define GPIO18 18

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define log file path
#define LOG_FILE "/var/log/tilt_events.log"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line18 = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(int gpio);
int read_gpio(struct gpiod_line *line);
void log_event(int gpio);
void cleanup_gpio(void);
void signal_handler(int sig);

// Structure to hold GPIO line numbers
typedef struct {
    int gpio17;
    int gpio18;
} gpio_lines_t;

// Function to initialize a GPIO line
int initialize_gpio(int gpio) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(chip, gpio);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", gpio);
        return -1;
    }

    ret = gpiod_line_request_input(line, "tilt_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as input: %s\n", gpio, strerror(-ret));
        gpiod_line_release(line);
        return -1;
    }

    ret = gpiod_line_set_bias(line, GPIOD_LINE_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO line %d bias to pull-up: %s\n", gpio, strerror(-ret));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to read the value of a GPIO line
int read_gpio(struct gpiod_line *line) {
    int value;
    int ret;

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not read GPIO line value: %s\n", strerror(-ret));
        return -1;
    }

    value = ret;
    return value;
}

// Function to log a tilt event to the log file
void log_event(int gpio) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, gpio);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to cleanup GPIO resources
void cleanup_gpio(void) {
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    gpio_lines_t gpio_pins = {GPIO17, GPIO18};
    int ret;
    int prev_value17 = 1; // Initialize to high (inactive)
    int prev_value18 = 1;
    struct timespec debounce_delay = {0, DEBOUNCE_TIME * 1000000L}; // 50ms

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip: %s\n", strerror(errno));
        fclose(log_file);
        return 1;
    }

    // Initialize GPIO lines
    if (initialize_gpio(gpio_pins.gpio17) < 0 || initialize_gpio(gpio_pins.gpio18) < 0) {
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }

    fprintf(stderr, "Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int value17 = read_gpio(line17);
        int value18 = read_gpio(line18);

        if (value17 < 0 || value18 < 0) {
            fprintf(stderr, "Error reading GPIO lines, exiting...\n");
            break;
        }

        // Check for tilt events on GPIO17
        if (value17 == 0 && prev_value17 == 1) {
            log_event(gpio_pins.gpio17);
            nanosleep(&debounce_delay, NULL); // Debounce
        }
        prev_value17 = value17;

        // Check for tilt events on GPIO18
        if (value18 == 0 && prev_value18 == 1) {
            log_event(gpio_pins.gpio18);
            nanosleep(&debounce_delay, NULL); // Debounce
        }
        prev_value18 = value18;

        usleep(100000); // Poll every 100ms
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    fprintf(stderr, "Tilt sensor monitoring stopped.\n");

    return 0;
}

