#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define LED_GPIO 22

// Define log file name
#define LOG_FILE "obstacle_log.csv"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor1_line = NULL;
static struct gpiod_line *sensor2_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_sensor(struct gpiod_line *line);
int control_led(struct gpiod_line *line, int state);
int log_data(int sensor1_value, int sensor2_value, int led_state);
void cleanup_gpio(void);
void signal_handler(int sig);

// Structure to hold GPIO lines
struct gpio_lines {
    struct gpiod_line *sensor1;
    struct gpiod_line *sensor2;
    struct gpiod_line *led;
};

struct gpio_lines gpio_lines;

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get GPIO lines
    gpio_lines.sensor1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!gpio_lines.sensor1) {
        fprintf(stderr, "Error getting sensor1 line: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    gpio_lines.sensor2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!gpio_lines.sensor2) {
        fprintf(stderr, "Error getting sensor2 line: %s\n", strerror(errno));
        goto cleanup_sensor1;
    }

    gpio_lines.led = gpiod_chip_get_line(chip, LED_GPIO);
    if (!gpio_lines.led) {
        fprintf(stderr, "Error getting LED line: %s\n", strerror(errno));
        goto cleanup_sensor2;
    }

    // Request GPIO lines as input
    ret = gpiod_line_request_input(gpio_lines.sensor1, "sensor1");
    if (ret < 0) {
        fprintf(stderr, "Error requesting sensor1 line as input: %s\n", strerror(errno));
        goto cleanup_led;
    }

    ret = gpiod_line_request_input(gpio_lines.sensor2, "sensor2");
    if (ret < 0) {
        fprintf(stderr, "Error requesting sensor2 line as input: %s\n", strerror(errno));
        goto cleanup_led;
    }

    ret = gpiod_line_request_output(gpio_lines.led, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        goto cleanup_led;
    }

    return 0;

cleanup_led:
    gpiod_line_release(gpio_lines.led);
cleanup_sensor2:
    gpiod_line_release(gpio_lines.sensor2);
cleanup_sensor1:
    gpiod_line_release(gpio_lines.sensor1);
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

// Function to read sensor value
int read_sensor(struct gpiod_line *line) {
    int value;
    int ret;

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error reading sensor line: %s\n", strerror(errno));
        return -1;
    }

    value = (ret == 0) ? 0 : 1; // Active-low
    return value;
}

// Function to control LED state
int control_led(struct gpiod_line *line, int state) {
    int ret;

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED line value: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to log data to file
int log_data(int sensor1_value, int sensor2_value, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to cleanup GPIO lines and close chip
void cleanup_gpio(void) {
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main(void) {
    int sensor1_value, sensor2_value, led_state;
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed, exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor values
        sensor1_value = read_sensor(gpio_lines.sensor1);
        sensor2_value = read_sensor(gpio_lines.sensor2);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Control LED based on sensor readings
        if (sensor1_value == 0 && sensor2_value == 0) {
            led_state = 1; // Turn LED on
