#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling rate (Hz)
#define SAMPLE_RATE 8000

// Define LED on time (ms)
#define LED_ON_TIME 100

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the microphone input
int read_microphone() {
    return gpioRead(MIC_PIN);
}

// Function to turn the LED on
void turn_led_on() {
    gpioWrite(LED_PIN, 1); // Set GPIO17 HIGH
}

// Function to turn the LED off
void turn_led_off() {
    gpioWrite(LED_PIN, 0); // Set GPIO17 LOW
}

// Function to get the current timestamp in milliseconds
long long get_timestamp_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input
    gpioSetMode(MIC_PIN, PI_INPUT);

    // Set GPIO17 as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Sound peak detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read microphone input
        int mic_value = read_microphone();

        // Check for a peak
        if (mic_value == 1) {
            // Get timestamp
            long long timestamp = get_timestamp_ms();

            // Print timestamp
            printf("%lld\n", timestamp);

            // Turn LED on
            turn_led_on();

            // Wait for LED on time
            gpioDelay(LED_ON_TIME * 1000); // pigpioDelay takes microseconds

            // Turn LED off
            turn_led_off();
        }

        // Small delay to avoid busy-waiting
        gpioDelay(10000); // 10ms delay (100Hz sampling rate)
    }

    // Clean up and exit
    turn_led_off(); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

