#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Si1175 I2C address
#define SI1175_ADDR 0x49

// Si1175 register addresses
#define REG_ALS_VIS_DATA0 0x24
#define REG_ALS_VIS_DATA1 0x25

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the Si1175 sensor
int init_si1175() {
    // Reset the sensor (example initialization sequence)
    uint8_t reset_cmd = 0x01; // Reset command
    if (write(i2c_fd, &reset_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(10000); // Wait for reset to complete

    // Configure the sensor (example configuration)
    uint8_t config_cmd = 0x17; // Configuration command
    uint8_t config_data[2] = {0x01, 0x02}; // Example configuration data
    if (write(i2c_fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    if (write(i2c_fd, config_data, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Function to read ALS visible data from the Si1175 sensor
int read_als_data(uint16_t *als_value) {
    uint8_t reg = REG_ALS_VIS_DATA0;
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *als_value = (data[1] << 8) | data[0];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the Si1175 sensor
    if (init_si1175() != 0) {
        fprintf(stderr, "Si1175 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("Si1175 sensor initialized successfully.\n");

    // Main loop
    while (1) {
        uint16_t als_value;

        // Read ALS data
        if (read_als_data(&als_value) == 0) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the raw sensor value
            printf("[%s] Raw ALS Value: %u\n", timestamp, als_value);
        } else {
            fprintf(stderr, "Failed to read ALS data.\n");
        }

        // Wait for 100 milliseconds
        usleep(100000);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness and to avoid compiler warnings.
    close(i2c_fd);
    return 0;
}

