// Define GPIO pins for the sensor
#define LEFT_SENSOR_PIN 2
#define MIDDLE_SENSOR_PIN 3
#define RIGHT_SENSOR_PIN 4

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Request GPIO pins as inputs
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", MIDDLE_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Main loop to read and log sensor values
    while (program_running) {
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensor values, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log the sensor values to stdout
        printf("L:%d M:%d R:%d\n", left_value, middle_value, right_value);

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Release GPIO pins and terminate the pigpio library before exiting
    gpioTerminate();
    return 0;
}

