#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the touch sensor channels
#define TOUCH_SENSOR_CHANNELS {5, 6, 13, 19, 26, 12, 16, 20}
#define NUM_CHANNELS 8

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and open the GPIO chip
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    return 0;
}

// Function to open a GPIO line as input
int open_gpio_line(int gpio_pin) {
    char buffer[64];
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", gpio_pin);
    FILE *fp = fopen(buffer, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open GPIO value file for pin %d\n", gpio_pin);
        return -1;
    }
    fclose(fp);

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", gpio_pin);
    fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open GPIO direction file for pin %d\n", gpio_pin);
        return -1;
    }
    fprintf(fp, "in");
    fclose(fp);

    return 0;
}

// Function to read the value of a GPIO line
int read_gpio_line(int gpio_pin) {
    char buffer[64];
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", gpio_pin);
    FILE *fp = fopen(buffer, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open GPIO value file for pin %d\n", gpio_pin);
        return -1;
    }
    int value;
    if (fscanf(fp, "%d", &value) != 1) {
        fprintf(stderr, "Failed to read GPIO value for pin %d\n", gpio_pin);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return value;
}

// Function to log the touch sensor data to the console
void log_touch_sensor_data(int *channel_values) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    printf("[%.3fs] ", timestamp);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        printf("CH%d=%d ", i + 1, channel_values[i]);
    }
    printf("\n");
}

// Function to release GPIO resources
void release_gpio_resources() {
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open GPIO lines for each channel
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (open_gpio_line(TOUCH_SENSOR_CHANNELS[i]) != 0) {
            release_gpio_resources();
            return 1;
        }
    }

    // Main loop
    while (program_running) {
        int channel_values[NUM_CHANNELS];

        // Read channel values
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = read_gpio_line(TOUCH_SENSOR_CHANNELS[i]);
            if (value == -1) {
                fprintf(stderr, "Error reading channel %d, exiting...\n", i + 1);
                program_running = 0; // Exit loop if there's an error
                break;
            }
            channel_values[i] = value;
        }

        // Log the data if all channels were read successfully
        if (program_running) {
            log_touch_sensor_data(channel_values);
        }

        // Wait for 200 milliseconds
        gpioDelay(200000); // 200 ms = 200000 microseconds
    }

    // Release GPIO resources before exiting
    release_gpio_resources();

    return 0;
}

