#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define UDP server address and port
#define UDP_SERVER_IP "127.0.0.1" // Replace with your server IP
#define UDP_SERVER_PORT 5000

// Define message buffer size
#define MESSAGE_BUFFER_SIZE 256

// Define fade duration (in seconds)
#define FADE_DURATION 5

// Define HSV interpolation steps
#define HSV_STEPS 50

// Global variables
static volatile int running = 1;
static int udp_socket = -1;

// Function prototypes
void signal_handler(int signal);
void cleanup();
void hsv_to_rgb(float h, float s, float v, uint8_t *r, uint8_t *g, uint8_t *b);
void fade_to_hue(float hue);
void send_udp_message(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");

    // Turn off the LED
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);

    // Close UDP socket
    if (udp_socket != -1) {
        close(udp_socket);
    }

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();
}

// HSV to RGB conversion function
void hsv_to_rgb(float h, float s, float v, uint8_t *r, uint8_t *g, uint8_t *b) {
    if (s == 0.0) {
        *r = *g = *b = (uint8_t)v;
        return;
    }

    h = fmodf(h, 360.0);
    if (h < 0.0) h += 360.0;

    float hh = h / 60.0;
    int i = (int)hh;
    float f = hh - i;
    float p = v * (1.0 - s);
    float q = v * (1.0 - s * f);
    float t = v * (1.0 - s * (1.0 - f));

    switch (i) {
        case 0:
            *r = (uint8_t)(v * 255);
            *g = (uint8_t)(t * 255);
            *b = (uint8_t)(p * 255);
            break;
        case 1:
            *r = (uint8_t)(q * 255);
            *g = (uint8_t)(v * 255);
            *b = (uint8_t)(p * 255);
            break;
        case 2:
            *r = (uint8_t)(p * 255);
            *g = (uint8_t)(v * 255);
            *b = (uint8_t)(t * 255);
            break;
        case 3:
            *r = (uint8_t)(p * 255);
            *g = (uint8_t)(q * 255);
            *b = (uint8_t)(v * 255);
            break;
        case 4:
            *r = (uint8_t)(t * 255);
            *g = (uint8_t)(p * 255);
            *b = (uint8_t)(v * 255);
            break;
        case 5:
            *r = (uint8_t)(v * 255);
            *g = (uint8_t)(p * 255);
            *b = (uint8_t)(q * 255);
            break;
        default:
            *r = 0; *g = 0; *b = 0; // Should not happen
            break;
    }
}

// Fade to hue function
void fade_to_hue(float hue) {
    uint8_t r, g, b;
    float h, s, v;
    float step_size = 1.0 / HSV_STEPS;
    float current_value = 0.0;

    for (int i = 0; i < HSV_STEPS; i++) {
        h = hue;
        s = 1.0; // Full saturation
        v = current_value;

        hsv_to_rgb(h, s, v, &r, &g, &b);

        // Invert the PWM duty cycle for common-anode
        r = 255 - r;
        g = 255 - g;
        b = 255 - b;

        gpioPWM(RED_PIN, r);
        gpioPWM(GREEN_PIN, g);
        gpioPWM(BLUE_PIN, b);

        current_value += step_size;
        gpioDelay(1000000 / HSV_STEPS); // Delay for smooth fade
    }
}

// Send UDP message function
void send_udp_message(const char *message) {
    struct sockaddr_in server_addr;

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        syslog(LOG_ERR, "Error creating UDP socket: %m");
        return;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", UDP_SERVER_IP);
        close(udp_socket);
        udp_socket = -1;
        return;
    }

    // Send message
    if (sendto(udp_socket, message, strlen(message), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Error sending UDP message: %m");
    }

    // Close socket
    close(udp_socket);
    udp_socket = -1;
}

int main() {
    // Initialize syslog
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Seed random number generator
    srand(time(NULL));

    syslog(LOG_INFO, "Mood lamp started");

    // Main loop
    while (running) {
        // Generate random hue
        float hue = (float)(rand() % 360);

        // Fade to hue
        fade_to_hue(hue);

        // Create message string
        char message[MESSAGE_BUFFER_SIZE];
        snprintf(message, sizeof(message), "Hue: %.2f", hue);

        // Send UDP message
        send_udp_message(message);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

