    if (inet_pton(AF_INET, UDP_SERVER_IP, &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", UDP_SERVER_IP);
        close(udp_socket);
        udp_socket = -1;
        return;
    }

    // Send message
    if (sendto(udp_socket, message, strlen(message), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Error sending UDP message: %m");
    }

    // Close socket
    close(udp_socket);
    udp_socket = -1;
}

int main() {
    // Initialize syslog
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Seed random number generator
    srand(time(NULL));

    syslog(LOG_INFO, "Mood lamp started");

    // Main loop
    while (running) {
        // Generate random hue
        float hue = (float)(rand() % 360);

        // Fade to hue
        fade_to_hue(hue);

        // Create message string
        char message[MESSAGE_BUFFER_SIZE];
        snprintf(message, sizeof(message), "Hue: %.2f", hue);

        // Send UDP message
        send_udp_message(message);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

