#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A
#define TCS34725_ID 0x12

// GPIO Pin for LED
#define LED_GPIO 17

// Calibration Values (example, adjust based on your sensor)
#define RED_OFFSET 0
#define RED_GAIN 1.0
#define GREEN_OFFSET 0
#define GREEN_GAIN 1.0
#define BLUE_OFFSET 0
#define BLUE_GAIN 1.0
#define CLEAR_OFFSET 0
#define CLEAR_GAIN 1.0

// Red Threshold
#define RED_THRESHOLD 200

// Global Variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_i2c(int address);
int init_sensor(int fd);
int read_sensor_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void calibrate_sensor(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *red_calibrated, float *green_calibrated, float *blue_calibrated, float *clear_calibrated);
void display_data(float red_calibrated, float green_calibrated, float blue_calibrated, float clear_calibrated);
void control_led(float red_calibrated);
void signal_handler(int sig);
void cleanup();

// Structure to hold sensor data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(TCS34725_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip. Exiting.\n");
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line. Exiting.\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "tcs34725_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize Sensor
    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize sensor. Exiting.\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    float red_calibrated, green_calibrated, blue_calibrated, clear_calibrated;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &sensor_data.clear, &sensor_data.red, &sensor_data.green, &sensor_data.blue) < 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying in 200ms.\n");
            usleep(200000); // 200ms
            continue;
        }

        // Calibrate sensor data
        calibrate_sensor(sensor_data.clear, sensor_data.red, sensor_data.green, sensor_data.blue, &red_calibrated, &green_calibrated, &blue_calibrated, &clear_calibrated);

        // Display data
        display_data(red_calibrated, green_calibrated, blue_calibrated, clear_calibrated);

        // Control LED
        control_led(red_calibrated);

        // Wait 200ms
        usleep(200000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize TCS34725 sensor
int init_sensor(int fd) {
    // Power on the sensor
    if (i2c_smbus_write_byte_data(fd, TCS34725_ENABLE, 0x03) < 0) {
        perror("Failed to power on sensor");
        return -1;
    }

    // Set integration time (ATIME)
    if (i2c_smbus_write_byte_data(fd, TCS34725_ATIME, 0xD5) < 0) {
        perror("Failed to set integration time");
        return -1;
    }

    // Set gain (CONTROL)
    if (i2c_smbus_write_byte_data(fd, TCS34725_CONTROL, 0x01) < 0) {
        perror("Failed to set gain");
        return -1;
    }

    // Verify sensor ID
    int sensor_id = i2c_smbus_read_byte_data(fd, TCS34725_ID);
    if (sensor_id < 0) {
        perror("Failed to read sensor ID");
        return -1;
    }

    if (sensor_id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buffer[8];

    if (read(fd, buffer, 8) != 8) {
        perror("Failed to read sensor data");
        return -1;
    }

    *clear = (buffer[1] << 8) | buffer[0];
    *red = (buffer[3] << 8) | buffer[2];
    *green = (buffer[5] << 8) | buffer[4];
    *blue = (buffer[7] << 8) | buffer[6];

    return 0;
}

// Calibrate sensor data
void calibrate_sensor(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *red_calibrated, float *green_calibrated, float *blue_calibrated, float *clear_calibrated) {
    *red_calibrated = (float)red * RED_GAIN - RED_OFFSET;
    *green_calibrated = (float)green * GREEN_GAIN - GREEN_OFFSET;
    *blue_calibrated = (float)blue * BLUE_GAIN - BLUE_OFFSET;
    *clear_calibrated = (float)clear * CLEAR_GAIN - CLEAR_OFFSET;
}

// Display data
void display_data(float red_calibrated, float green_calibrated, float blue_calibrated, float clear_calibrated) {
    printf("Red: %.2f, Green: %.2f, Blue: %.2f, Clear: %.2f\n", red_calibrated, green_calibrated, blue_calibrated, clear_calibrated);
}

// Control LED based on red value
void control_led(float red_calibrated) {
    if (red_calibrated > RED_THRESHOLD) {
        gpiod_line_set_value(led_line, 1); // HIGH
    } else {
        gpiod_line_set_value(led_line, 0); // LOW
    }
}

// Signal handler
void signal_handler(int sig) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (led_line) {
        gpiod_line_set_value(led_line, 0); // Turn off LED
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

