#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define WS2812B_PIN 18
#define BH1750_ADDR 0x23

// Define BH1750 commands
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Define lux thresholds for brightness mapping
#define LUX_THRESHOLD_1 0.0
#define LUX_THRESHOLD_2 100.0
#define LUX_THRESHOLD_3 200.0
#define LUX_THRESHOLD_4 300.0
#define LUX_THRESHOLD_5 400.0
#define LUX_THRESHOLD_6 500.0
#define LUX_THRESHOLD_7 600.0
#define LUX_THRESHOLD_8 700.0
#define LUX_THRESHOLD_9 800.0
#define LUX_THRESHOLD_10 900.0
#define LUX_THRESHOLD_11 1000.0

// Define PWM frequency
#define PWM_FREQUENCY 800000 // 800 kHz

// Define number of LEDs in the strip
#define NUM_LEDS 10

// Global variables
static volatile int running = 1;
static int i2c_handle;

// Function prototypes
void signal_handler(int signal);
int init_i2c();
int read_bh1750();
float calculate_lux(uint16_t raw_value);
int map_lux_to_brightness(float lux);
void set_led_brightness(int led_index, int brightness);
void send_ws2812b_data(uint8_t *data, int num_leds);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read light level from BH1750 sensor
int read_bh1750() {
    char buf[1];
    buf[0] = BH1750_CONTINUOUS_HIGH_RES_MODE;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(180000); // Wait 180 ms

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    uint16_t raw_value = (data[0] << 8) | data[1];
    return (int)raw_value;
}

// Calculate lux value from raw sensor reading
float calculate_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Map lux value to LED brightness (0-255) using a logarithmic scale
int map_lux_to_brightness(float lux) {
    if (lux < LUX_THRESHOLD_1) {
        return 0;
    } else if (lux < LUX_THRESHOLD_2) {
        return (int)(log10(lux - LUX_THRESHOLD_1 + 1) / (LUX_THRESHOLD_2 - LUX_THRESHOLD_1) * 255);
    } else if (lux < LUX_THRESHOLD_3) {
        return (int)(log10(lux - LUX_THRESHOLD_2 + 1) / (LUX_THRESHOLD_3 - LUX_THRESHOLD_2) * 255);
    } else if (lux < LUX_THRESHOLD_4) {
        return (int)(log10(lux - LUX_THRESHOLD_3 + 1) / (LUX_THRESHOLD_4 - LUX_THRESHOLD_3) * 255);
    } else if (lux < LUX_THRESHOLD_5) {
        return (int)(log10(lux - LUX_THRESHOLD_4 + 1) / (LUX_THRESHOLD_5 - LUX_THRESHOLD_4) * 255);
    } else if (lux < LUX_THRESHOLD_6) {
        return (int)(log10(lux - LUX_THRESHOLD_5 + 1) / (LUX_THRESHOLD_6 - LUX_THRESHOLD_5) * 255);
    } else if (lux < LUX_THRESHOLD_7) {
        return (int)(log10(lux - LUX_THRESHOLD_6 + 1) / (LUX_THRESHOLD_7 - LUX_THRESHOLD_6) * 255);
    } else if (lux < LUX_THRESHOLD_8) {
        return (int)(log10(lux - LUX_THRESHOLD_7 + 1) / (LUX_THRESHOLD_8 - LUX_THRESHOLD_7) * 255);
    } else if (lux < LUX_THRESHOLD_9) {
        return (int)(log10(lux - LUX_THRESHOLD_8 + 1) / (LUX_THRESHOLD_9 - LUX_THRESHOLD_8) * 255);
    } else if (lux < LUX_THRESHOLD_10) {
        return (int)(log10(lux - LUX_THRESHOLD_9 + 1) / (LUX_THRESHOLD_10 - LUX_THRESHOLD_9) * 255);
    } else if (lux < LUX_THRESHOLD_11) {
        return (int)(log10(lux - LUX_THRESHOLD_10 + 1) / (LUX_THRESHOLD_11 - LUX_THRESHOLD_10) * 255);
    } else {
        return 255;
    }
}

// Set the brightness of a single LED
void set_led_brightness(int led_index, int brightness) {
    if (led_index < 0 || led_index >= NUM_LEDS) {
        fprintf(stderr, "Invalid LED index: %d\n", led_index);
        return;
    }

    // WS2812B data format: GRB (Green, Red, Blue)
    uint8_t data[4];
    data[0] = 0xE0 | (brightness & 0x1F); // Global brightness (10 bits)
    data[1] = 0x00; // Blue
    data[2] = 0x00; // Green
    data[3] = 0x00; // Red

    // Send the data for the specified LED
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 8; j++) {
            if ((data[i] >> (7 - j)) & 0x01) {
                gpioWrite(WS2812B_PIN, 1); // High
                gpioDelay(1); // 1 us
                gpioWrite(WS2812B_PIN, 0); // Low
                gpioDelay(80); // 80 us
            } else {
                gpioWrite(WS2812B_PIN, 1); // High
                gpioDelay(80); // 80 us
                gpioWrite(WS2812B_PIN, 0); // Low
                gpioDelay(1); // 1 us
            }
        }
    }
}

// Send WS2812B data to the LED strip
void send_ws2812b_data(uint8_t *data, int num_leds) {
    for (int i = 0; i < num_leds; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 8; k++) {
                if ((data[i * 4 + j] >> (7 - k)) & 0x01) {
                    gpioWrite(WS2812B_PIN, 1); // High
                    gpioDelay(1); // 1 us
                    gpioWrite(WS2812B_PIN, 0); // Low
                    gpioDelay(80); // 80 us
                } else {
                    gpioWrite(WS2812B_PIN, 1); // High
                    gpioDelay(80); // 80 us
                    gpioWrite(WS2812B_PIN, 0); // Low
                    gpioDelay(1); // 1 us
                }
            }
        }
    }
}

