    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(WS2812B_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(WS2812B_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read light level from BH1750 sensor
        int raw_value = read_bh1750();
        if (raw_value < 0) {
