#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define NUM_SENSORS 3
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define APA102_MOSI 10
#define APA102_SCK 11
#define APA102_CS 8
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x21
#define FADE_DURATION_MS 500
#define SLEEP_DURATION_MS 100

// Global variables
int spi_handle;
int i2c_handles[NUM_SENSORS];
int sensor_present[NUM_SENSORS] = {0, 0, 0};
int brightness = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor(int i2c_handle);
float read_lux(int i2c_handle);
int calculate_average_lux(float lux_values[], int num_sensors);
void set_apa102_brightness(int brightness);
void fade_brightness(int target_brightness);
void signal_handler(int signal);

// APA102 color data structure
typedef struct {
    uint8_t red;
    uint8_t green;
    uint8_t blue;
} apa102_color_t;

// Function to initialize a BH1750 sensor
int initialize_sensor(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE) != 0) {
        fprintf(stderr, "Error: Failed to initialize BH1750 sensor at address 0x%02X\n", i2c_handle);
        return -1;
    }
    gpioDelay(180000); // Wait for measurement (at least 180ms)
    return 0;
}

// Function to read lux value from a BH1750 sensor
float read_lux(int i2c_handle) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Error: Failed to read lux value from BH1750 sensor at address 0x%02X (result = %d)\n", i2c_handle, result);
        return -1.0;
    }

    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    return (float)raw_value / 1.2;
}

// Function to calculate the average lux value from multiple sensors
int calculate_average_lux(float lux_values[], int num_sensors) {
    float sum = 0.0;
    int valid_sensors = 0;

    for (int i = 0; i < num_sensors; i++) {
        if (lux_values[i] >= 0) {
            sum += lux_values[i];
            valid_sensors++;
        }
    }

    if (valid_sensors > 0) {
        return (int)(sum / valid_sensors);
    } else {
        return 0; // Return 0 if all sensors failed
    }
}

// Function to set the brightness of the APA102 LED strip
void set_apa102_brightness(int brightness) {
    // APA102 requires a start frame (0x00000000) and end frame (0x00000000)
    uint32_t start_frame = 0x00000000;
    uint32_t end_frame = 0x00000000;

    // Construct color data for each LED (white)
    apa102_color_t color;
    color.red = 0xFF;
    color.green = 0xFF;
    color.blue = 0xFF;

    // Send start frame
    char start_frame_data[4];
    start_frame_data[0] = (start_frame >> 24) & 0xFF;
    start_frame_data[1] = (start_frame >> 16) & 0xFF;
    start_frame_data[2] = (start_frame >> 8) & 0xFF;
    start_frame_data[3] = start_frame & 0xFF;
    spiWrite(spi_handle, start_frame_data, 4);

    // Send color data for each LED
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensor_present[i]) {
            for (int j = 0; j < brightness; j++) {
                char color_data[4];
                color_data[0] = (color.red >> 24) & 0xFF;
                color_data[1] = (color.red >> 16) & 0xFF;
                color_data[2] = (color.red >> 8) & 0xFF;
                color_data[3] = color.red & 0xFF;
                spiWrite(spi_handle, color_data, 4);
            }
        }
    }

    // Send end frame
    char end_frame_data[4];
    end_frame_data[0] = (end_frame >> 24) & 0xFF;
    end_frame_data[1] = (end_frame >> 16) & 0xFF;
    end_frame_data[2] = (end_frame >> 8) & 0xFF;
    end_frame_data[3] = end_frame & 0xFF;
    spiWrite(spi_handle, end_frame_data, 4);
}

// Function to fade the brightness of the APA102 LED strip
void fade_brightness(int target_brightness) {
    int steps = 50; // Number of steps for the fade
    int increment = (target_brightness - brightness) / steps;

    for (int i = 0; i < steps; i++) {
        brightness += increment;
        set_apa102_brightness(brightness);
        gpioDelay(FADE_DURATION_MS / steps);
    }

    brightness = target_brightness;
    set_apa102_brightness(brightness);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for each sensor
    i2c_handles[0] = i2cOpen(1, BH1750_ADDR_LOW, 0);
    i2c_handles[1] = i2cOpen(1, BH1750_ADDR_HIGH, 0);
    i2c_handles[2] = i2cOpen(1, BH1750_ADDR_LOW, 0); // Open the same address again for sensor 3

    if (i2c_handles[0] < 0 || i2c_handles[1] < 0 || i2c_handles[2] < 0) {
        fprintf(stderr, "Error: Failed to open I2C device(s)\n");
        // Close any open I2C handles
        if (i2c_handles[0] >= 0) i2cClose(i2c_handles[0]);
        if (i2c_handles[1] >= 0) i2cClose(i2c_handles[1]);
        if (i2c_handles[2] >= 0) i2cClose(i2c_handles[2]);
        gpioTerminate();
        return 1;
    }

    // Initialize each sensor
    if (initialize_sensor(i2c_handles[0]) != 0) sensor_present[0] = 0;
    if (initialize_sensor(i2c_handles[1]) != 0) sensor_present[1] = 0;
    if (initialize_sensor(i2c_handles[2]) != 0) sensor_present[2] = 0;

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Failed to open SPI channel\n");
        // Close I2C handles
        i2cClose(i2c_handles[0]);
        i2cClose(i2c_handles[1]);
        i2cClose(i2c_handles[2]);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float lux_values[NUM_SENSORS];
        int i;

        // Read lux values from each sensor
        for (i = 0; i < NUM_SENSORS; i++) {
            if (sensor_present[i]) {
                lux_values[i] = read_lux(i2c_handles[i]);
                if (lux_values[i] < 0) {
                    fprintf(stderr, "Error: Failed to read lux value from sensor %d\n", i);
                    lux_values[i] = 0.0; // Set to 0 to avoid affecting average
                }
            } else {
                lux_values[i] = 0.0;
            }
        }

        // Calculate average lux value
        int average_lux = calculate_average_lux(lux_values, NUM_SENSORS);

        // Map average lux value to brightness (0-31)
        int target_brightness = (int)((float)average_lux / 1000.0 * 31.0); // Scale lux to 0-31

        // Fade brightness to target value
        fade_brightness(target_brightness);

        // Sleep for a short interval
        gpioDelay(SLEEP_DURATION_MS);
    }

    // Cleanup
    // Turn off the LED strip
    set_apa102_brightness(0);

    // Close I2C handles
    i2cClose(i2c_handles[0]);
    i2cClose(i2c_handles[1]);
    i2cClose(i2c_handles[2]);

    // Close SPI handle
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

