#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define WS2812B_GPIO 18
#define NUM_LEDS 10
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 100
#define LOG_FILE "veml7700_led_control.log"

// VEML7700 Registers
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_veml7700();
int read_veml7700_als(uint16_t *als_data);
float convert_als_to_lux(uint16_t als_data);
int map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void cleanup();
void signal_handler(int sig);
void log_message(const char *message);

// WS2812B bit-banging function
void ws2812b_bit(int gpio, int bit) {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 0;

    if (bit == 0) {
        ts.tv_nsec = 500; // 500 ns low
    } else {
        ts.tv_nsec = 800; // 800 ns high
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "veml7700_led_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        log_message("Error requesting GPIO line for output");
        return;
    }

    if (gpiod_line_set_value(gpio_line, bit) < 0) {
        log_message("Error setting GPIO line value");
        gpiod_line_release(gpio_line);
        return;
    }

    nanosleep(&ts, NULL);

    if (gpiod_line_release(gpio_line) < 0) {
        log_message("Error releasing GPIO line");
    }
}

// WS2812B data frame function
void ws2812b_data_frame(int gpio, uint8_t *data, int len) {
    for (int i = 0; i < len; i++) {
        for (int j = 7; j >= 0; j--) {
            ws2812b_bit(gpio, (data[i] >> j) & 1);
        }
    }
}

// WS2812B color function
void ws2812b_color(int gpio, uint8_t r, uint8_t g, uint8_t b) {
    uint8_t data[4] = {b, g, r, 0};
    ws2812b_data_frame(gpio, data, 4);
}

// WS2812B clear function
void ws2812b_clear(int gpio) {
    uint8_t data[4] = {0, 0, 0, 0};
    ws2812b_data_frame(gpio, data, 4);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize logging
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    log_message("Starting VEML7700 LED control program");

    // Initialize I2C
    if (init_i2c() != 0) {
        log_message("I2C initialization failed");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        log_message("GPIO initialization failed");
        cleanup();
        return 1;
    }

    // Initialize VEML7700
    if (init_veml7700() != 0) {
        log_message("VEML7700 initialization failed");
        cleanup();
        return 1;
    }

    uint16_t als_data;
    float lux;
    int brightness;

    // Main loop
    while (!terminate) {
        // Read ALS data
        if (read_veml7700_als(&als_data) == 0) {
            // Convert ALS data to lux
            lux = convert_als_to_lux(als_data);

            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Set LED brightness
            set_led_brightness(brightness);

            // Log data
            char log_buffer[100];
            snprintf(log_buffer, sizeof(log_buffer), "Lux: %.2f, Brightness: %d", lux, brightness);
            log_message(log_buffer);
        } else {
            log_message("Failed to read ALS data");
        }

        // Delay
        usleep(200000); // 200 ms
    }

    // Cleanup and exit
    cleanup();
    log_message("Exiting VEML7700 LED control program");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, WS2812B_GPIO);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Initialize VEML7700
int init_veml7700() {
    uint16_t config_value = 0x0000; // Integration time 100 ms, gain 1/8
    uint8_t config_data[2];
    config_data[0] = (config_value >> 8) & 0xFF;
    config_data[1] = config_value & 0xFF;

    for (int i = 0; i < I2C_RETRY_COUNT; i++) {
        if (write(i2c_fd, config_data, 2) == 2) {
            // Configuration register 0x00 written successfully
            return 0;
        } else {
            log_message("Error writing to VEML7700 configuration register");
            usleep(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    log_message("Failed to write to VEML7700 configuration register after multiple retries");
    return -1;
}

// Read ALS data from VEML7700
int read_veml7700_als(uint16_t *als_data) {
    uint8_t als_data_bytes[2];

    for (int i = 0; i < I2C_RETRY_COUNT; i++) {
        if (write(i2c_fd, (char[]){VEML7700_ALS_DATA}, 1) == 1) {
            if (read(i2c_fd, (char *)als_data_bytes, 2) == 2) {
                *als_data = (als_data_bytes[0] << 8) | als_data_bytes[1];
                return 0; // Success
            } else {
                log_message("Error reading ALS data from VEML7700");
                usleep(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        } else {
            log_message("Error writing to VEML7700 ALS data register");
            usleep(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    log_message("Failed to read ALS data from VEML7700 after multiple retries");
    return -1; // Failure
}

// Convert ALS data to lux
float convert_als_to_lux(uint16_t als_data) {
    return als_data * 0.0036 * (1.0 / 8.0) * (100.0 / 100.0);
}

// Map lux to brightness (0-255) using gamma correction
int map_lux_to_brightness(float lux) {
    if (lux < 0) lux = 0;
    if (lux > 120000) lux = 120000;

    return 255 * pow(lux / 120000.0, 1.0 / 2.2);
}

// Set LED brightness using WS2812B
void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    uint8_t red = brightness;
    uint8_t green = brightness;
    uint8_t blue = brightness;

    ws2812b_color(WS2812B_GPIO, red, green, blue);
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    log_message("Signal received, terminating...");
}

// Log message to file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

