#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define MAX_LUX 1000.0

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void set_led_frequency(float avg_lux);
void cleanup();
void signal_handler(int signal);

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Read data from BH1750 sensor
int read_bh1750(float *lux) {
    uint8_t config_cmd = CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(200000); // Wait for measurement (at least 180ms)

    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    uint16_t raw_value = (data[0] << 8) | data[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Set the LED frequency based on the average lux
void set_led_frequency(float avg_lux) {
    float frequency = 0.5 + (avg_lux / MAX_LUX) * 4.5; // Linear mapping
    if (frequency < 0.5) frequency = 0.5;
    if (frequency > 5.0) frequency = 5.0;

    // Calculate on-time and off-time for a square wave
    float on_time = 0.5 * (1.0 / frequency);
    float off_time = 0.5 * (1.0 / frequency);

    // Calculate the number of on and off cycles
    int on_cycles = (int)(on_time * 1000000.0); // Convert seconds to microseconds
    int off_cycles = (int)(off_time * 1000000.0);

    // Write the GPIO value to the sysfs file
    char gpio_path[64];
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/gpio%d/value", GPIO_PIN);
    int gpio_fd = open(gpio_path, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO value file");
        return;
    }

    for (int i = 0; i < on_cycles; i++) {
        if (write(gpio_fd, "1", 1) != 1) {
            perror("Error writing to GPIO value file");
            close(gpio_fd);
            return;
        }
        usleep(1000); // 1ms delay
    }

    for (int i = 0; i < off_cycles; i++) {
        if (write(gpio_fd, "0", 1) != 1) {
            perror("Error writing to GPIO value file");
            close(gpio_fd);
            return;
        }
        usleep(1000); // 1ms delay
    }

    close(gpio_fd);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Unexport GPIO pin
    char gpio_path[64];
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/unexport");
    int gpio_fd = open(gpio_path, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO unexport file");
        return;
    }
    if (write(gpio_fd, GPIO_PIN, strlen(GPIO_PIN)) != strlen(GPIO_PIN)) {
        perror("Error writing to GPIO unexport file");
    }
    close(gpio_fd);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received, exiting...\n");
}

int main() {
    // Initialize circular buffer
    CircularBuffer lux_buffer;
    init_circular_buffer(&lux_buffer);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Export GPIO pin
    char gpio_path[64];
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/export");
    int gpio_fd = open(gpio_path, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO export file");
        cleanup();
        return 1;
    }
    if (write(gpio_fd, GPIO_PIN, strlen(GPIO_PIN)) != strlen(GPIO_PIN)) {
        perror("Error writing to GPIO export file");
        cleanup();
        return 1;
    }
    close(gpio_fd);

    // Set GPIO direction to output
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/gpio%d/direction", GPIO_PIN);
    gpio_fd = open(gpio_path, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO direction file");
        cleanup();
        return 1;
    }
    if (write(gpio_fd, "out", 3) != 3) {
        perror("Error writing to GPIO direction file");
        cleanup();
        return 1;
    }
    close(gpio_fd);

    float lux;
    while (program_running) {
        if (read_bh1750(&lux) == 0) {
            add_to_buffer(&lux_buffer, lux);
            float avg_lux = calculate_average(&lux_buffer);
            set_led_frequency(avg_lux);
            printf("Lux: %.2f, Average Lux: %.2f\n", lux, avg_lux);
        } else {
            fprintf(stderr, "Error reading BH1750 sensor. Retrying...\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

