    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Set the LED frequency based on the average lux
void set_led_frequency(float avg_lux) {
    float frequency = 0.5 + (avg_lux / MAX_LUX) * 4.5; // Linear mapping
    if (frequency < 0.5) frequency = 0.5;
    if (frequency > 5.0) frequency = 5.0;

    // Calculate on-time and off-time for a square wave
    float on_time = 0.5 * (1.0 / frequency);
    float off_time = 0.5 * (1.0 / frequency);

    // Calculate the number of on and off cycles
    int on_cycles = (int)(on_time * 1000000.0); // Convert seconds to microseconds
    int off_cycles = (int)(off_time * 1000000.0);

    // Write the GPIO value to the sysfs file
    char gpio_path[64];
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/gpio%d/value", GPIO_PIN);
    int gpio_fd = open(gpio_path, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO value file");
        return;
    }

    for (int i = 0; i < on_cycles; i++) {
        if (write(gpio_fd, "1", 1) != 1) {
            perror("Error writing to GPIO value file");
            close(gpio_fd);
            return;
        }
        usleep(1000); // 1ms delay
    }

    for (int i = 0; i < off_cycles; i++) {
        if (write(gpio_fd, "0", 1) != 1) {
            perror("Error writing to GPIO value file");
            close(gpio_fd);
            return;
        }
        usleep(1000); // 1ms delay
    }

    close(gpio_fd);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Unexport GPIO pin
    char gpio_path[64];
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/unexport");
    int gpio_fd = open(gpio_path, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO unexport file");
        return;
    }
    if (write(gpio_fd, GPIO_PIN, strlen(GPIO_PIN)) != strlen(GPIO_PIN)) {
        perror("Error writing to GPIO unexport file");
    }
    close(gpio_fd);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received, exiting...\n");
}

int main() {
    // Initialize circular buffer
    CircularBuffer lux_buffer;
    init_circular_buffer(&lux_buffer);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Export GPIO pin
    char gpio_path[64];
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/export");
    int gpio_fd = open(gpio_path, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO export file");
        cleanup();
        return 1;
    }
    if (write(gpio_fd, GPIO_PIN, strlen(GPIO_PIN)) != strlen(GPIO_PIN)) {
        perror("Error writing to GPIO export file");
        cleanup();
        return 1;
    }
    close(gpio_fd);

    // Set GPIO direction to output
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/gpio%d/direction", GPIO_PIN);
    gpio_fd = open(gpio_path, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO direction file");
        cleanup();
        return 1;
    }
    if (write(gpio_fd, "out", 3) != 3) {
        perror("Error writing to GPIO direction file");
        cleanup();
        return 1;
    }
    close(gpio_fd);

    float lux;
    while (program_running) {
        if (read_bh1750(&lux) == 0) {
            add_to_buffer(&lux_buffer, lux);
            float avg_lux = calculate_average(&lux_buffer);
            set_led_frequency(avg_lux);
            printf("Lux: %.2f, Average Lux: %.2f\n", lux, avg_lux);
        } else {
            fprintf(stderr, "Error reading BH1750 sensor. Retrying...\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

