void display_digit(int digit) {
    if (digit < 0 || digit > 9) {
        fprintf(stderr, "Invalid digit: %d\n", digit);
        return;
    }

    unsigned char pattern = segments[digit];
    shift_out(pattern);

    // Set latch pin high
    gpiod_line_set_value(latch_line, 1);
    gpiod_line_set_value(latch_line, 0);
}

// Function to blink a digit on the 7-segment display
void blink_digit(int digit) {
    if (digit < 0 || digit > 9) {
        fprintf(stderr, "Invalid digit: %d\n", digit);
        return;
    }

    unsigned char pattern = segments[digit];
    shift_out(pattern);

    // Set latch pin high
    gpiod_line_set_value(latch_line, 1);
    gpiod_line_set_value(latch_line, 0);

    // Wait for 500ms
    usleep(500000);

    // Set latch pin low
    gpiod_line_set_value(latch_line, 1);
    gpiod_line_set_value(latch_line, 0);

    // Wait for 500ms
    usleep(500000);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

