// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define blinking period (in seconds)
#define BLINK_PERIOD 2

// Global variables for signal handling
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *button_line = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(void);
void blink_led(void);
void handle_button_event(void);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip.\n");
        return -1;
    }

    // Request LED line as output
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error: Could not get LED line.\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "blink_button", 0) < 0) {
        fprintf(stderr, "Error: Could not request LED line as output.\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request button line as input with pull-up resistor
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Error: Could not get button line.\n");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(button_line, "blink_button") < 0) {
        fprintf(stderr, "Error: Could not request button line as input.\n");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0); // Turn off LED
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to blink the LED
void blink_led(void) {
    struct timespec on_time = {1, 0}; // 1 second
    struct timespec off_time = {1, 0};  // 1 second

    while (program_running) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            fprintf(stderr, "Error: Could not set LED value to 1.\n");
            break;
        }
        nanosleep(&on_time, NULL);

        if (gpiod_line_set_value(led_line, 0) < 0) {
            fprintf(stderr, "Error: Could not set LED value to 0.\n");
            break;
        }
        nanosleep(&off_time, NULL);
    }
}

// Function to handle button events
void handle_button_event(void) {
    struct gpiod_line_event event;
    int ret;

    ret = gpiod_line_event_wait(button_line, &event, 1); // Wait for 1 second
    if (ret < 0) {
        fprintf(stderr, "Error: Could not wait for button event.\n");
        return;
    }

    if (event.type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        printf("Button pressed! Stopping blinking.\n");
        program_running = 0; // Stop the main loop
    }
}

int main(void) {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        return 1;
    }

    printf("Blinking LED and monitoring button... Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        blink_led();
        handle_button_event();
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    printf("Exiting.\n");
    return 0;
}

