#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_GPIO 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int result;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    result = gpioInitialise();
    if (result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", result);
        return 1;
    }

    // Set GPIO5 as an output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    printf("LED blinking started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Turn LED on
        gpioWrite(LED_GPIO, 1);
        printf("LED ON\n");
        fflush(stdout); // Ensure output is visible immediately

        // Wait for 750 ms
        time_sleep(0.75);

        // Turn LED off
        gpioWrite(LED_GPIO, 0);
        printf("LED OFF\n");
        fflush(stdout); // Ensure output is visible immediately

        // Wait for 750 ms
        time_sleep(0.75);
    }

    // Clean up and terminate pigpio
