volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO chip
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to configure a GPIO line
int configure_gpio(int pin, int direction) {
    if (gpioSetMode(pin, direction) != 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to %d\n", pin, direction);
        return -1;
    }
    return 0;
}

// Function to read the button state
int read_button() {
    return gpioRead(BUTTON_PIN);
}

// Function to blink the LED
void blink_led(int duration_ms) {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration (microseconds)
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioDelay(duration_ms * 1000); // Delay for specified duration (microseconds)
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Configure LED pin as output
    if (configure_gpio(LED_PIN, PI_OUTPUT) != 0) {
        cleanup_gpio();
        return 1;
    }

    // Configure button pin as input with pull-down resistor
    if (configure_gpio(BUTTON_PIN, PI_INPUT) != 0) {
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read button state
        int button_state = read_button();

        // Check if button is pressed (LOW signal)
        if (button_state == 0) {
            // Blink the LED
            blink_led(500); // Blink for 500ms
        } else {
            // Ensure LED is off when button is released
            gpioWrite(LED_PIN, 0);
        }

        // Small delay to prevent busy-waiting
        gpioDelay(10000); // 10ms delay (microseconds)
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

