#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for RGB LED
#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

// PWM frequency (100 Hz)
#define PWM_FREQUENCY 100

// PWM period (10 ms)
#define PWM_PERIOD_NS (1000000000 / PWM_FREQUENCY)

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Structure to hold RGB color values
typedef struct {
    uint8_t red;
    uint8_t green;
    uint8_t blue;
} rgb_color_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to generate a random RGB color
rgb_color_t generate_random_color() {
    rgb_color_t color;
    color.red   = (uint8_t)(rand() % 101);
    color.green = (uint8_t)(rand() % 101);
    color.blue  = (uint8_t)(rand() % 101);
    return color;
}

// Function to set the PWM duty cycle for a given GPIO line
int set_pwm_duty_cycle(struct gpiod_line *line, uint32_t duty_cycle) {
    if (duty_cycle > 100) {
        duty_cycle = 100;
    }
    uint32_t value = (duty_cycle * PWM_PERIOD_NS) / 100;
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting PWM duty cycle: %d\n", ret);
        return -1;
    }
    return 0;
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %d\n", -1);
        return 1;
    }

    // Request GPIO lines for output
    struct gpiod_line *red_line   = gpiod_chip_get_line(chip, RED_PIN);
    struct gpiod_line *green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    struct gpiod_line *blue_line  = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Error getting GPIO line: %d\n", -1);
        gpiod_chip_close(chip);
        return 1;
    }

    int ret = gpiod_line_request_output(red_line, "rgb_led_red", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting red line: %d\n", ret);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(green_line, "rgb_led_green", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting green line: %d\n", ret);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(blue_line, "rgb_led_blue", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting blue line: %d\n", ret);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Generate a random RGB color
        rgb_color_t color = generate_random_color();

        // Set the PWM duty cycles for each color channel
        if (set_pwm_duty_cycle(red_line, color.red) < 0) {
            program_running = 0; // Exit loop on error
        }
        if (set_pwm_duty_cycle(green_line, color.green) < 0) {
            program_running = 0; // Exit loop on error
        }
        if (set_pwm_duty_cycle(blue_line, color.blue) < 0) {
            program_running = 0; // Exit loop on error
        }

        // Wait for 100 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up GPIO lines
    gpiod_line_set_value(red_line, 0);
    gpiod_line_set_value(green_line, 0);
    gpiod_line_set_value(blue_line, 0);
    gpiod_line_release(red_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

