}

// Initializes the ADPD188BI sensor
int initialize_sensor() {
    // Set MODE register to normal operation mode (0x01)
    char buf[2];
    buf[0] = MODE_REG;
    buf[1] = 0x01;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to MODE register: %d\n", result);
        return -1;
    }

    return 0;
}

// Reads ambient light data from the sensor
int read_als(uint16_t *als) {
    char buf[1];
    buf[0] = ALS_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to ALS register: %d\n", result);
        return -1;
    }

    char data[2];
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return -1;
    }

    *als = (data[1] << 8) | data[0];
    return 0;
}

// Reads color data from the sensor
int read_color(uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[1];
    buf[0] = RED_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to Red register: %d\n", result);
        return -1;
    }

    char data[2];
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading Red data: %d\n", result);
        return -1;
    }

    *red = (data[1] << 8) | data[0];

    buf[0] = GREEN_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to Green register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading Green data: %d\n", result);
