#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// FXOS8700CQ I2C address
#define FXOS8700CQ_ADDR 0x1F

// FXOS8700CQ registers
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_CTRL_REG2 0x2B
#define FXOS8700CQ_OUT_X_MSB 0x01
#define FXOS8700CQ_OUT_X_LSB 0x02
#define FXOS8700CQ_OUT_Y_MSB 0x03
#define FXOS8700CQ_OUT_Y_LSB 0x04
#define FXOS8700CQ_OUT_Z_MSB 0x05
#define FXOS8700CQ_OUT_Z_LSB 0x06
#define FXOS8700CQ_WHO_AM_I 0x0D
#define FXOS8700CQ_XYZ_DATA_CFG 0x0E

// Impact threshold (2g)
#define IMPACT_THRESHOLD 19.62

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
float calculate_magnitude(float x, float y, float z);
void log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
    float magnitude;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the sensor
int init_sensor() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700CQ_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%X, expected 0xC7\n", who_am_i);
        return -1;
    }

    // Set CTRL_REG1 to active mode, 200 Hz ODR
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set CTRL_REG2 to +/- 2g range
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2\n");
        return -1;
    }

    // Set XYZ_DATA_CFG to +/- 2g range
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the sensor
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Convert raw acceleration data to g-force units
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / 4096.0f * 9.81f;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log the impact event to a file
void log_impact(float x, float y, float z, float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to g-force units
            x = convert_to_g(raw_x);
            y = convert_to_g(raw_y);
            z = convert_to_g(raw_z);

            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
                printf("Impact detected! Magnitude: %.3f g\n", magnitude);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

