#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F
#define SAMPLE_RATE_HZ 20
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE_HZ)
#define CALIBRATION_SAMPLES 100
#define ZERO_RATE_THRESHOLD 50.0
#define LOG_FILE "gyro_log.txt"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Structure to hold calibration offsets
typedef struct {
    float x_offset;
    float y_offset;
    float z_offset;
} calibration_offsets_t;

// Function prototypes
int init_i2c();
int configure_gyro();
gyro_data_t read_gyro_data();
calibration_offsets_t calibrate_gyro();
void log_data(gyro_data_t data, calibration_offsets_t offsets);
void check_threshold(gyro_data_t data, calibration_offsets_t offsets);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Initialize I2C communication
int init_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Configure the gyroscope
int configure_gyro() {
    // CTRL_REG1: Normal mode, all axes enabled, 100 Hz ODR
    if (write_i2c_reg(CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // CTRL_REG4: 250 dps full-scale, continuous update
    if (write_i2c_reg(CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    uint8_t buffer[6];

    if (read_i2c_block_data(OUT_X_L, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Error reading gyro data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Calibrate the gyroscope
calibration_offsets_t calibrate_gyro() {
    calibration_offsets_t offsets = {0.0, 0.0, 0.0};
    gyro_data_t data;
    float x_sum = 0.0, y_sum = 0.0, z_sum = 0.0;

    printf("Calibrating gyroscope... Please keep the sensor stationary.\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        data = read_gyro_data();
        x_sum += data.x;
        y_sum += data.y;
        z_sum += data.z;
        usleep(SAMPLE_PERIOD_MS * 1000); // Convert ms to us
    }

    offsets.x_offset = x_sum / CALIBRATION_SAMPLES;
    offsets.y_offset = y_sum / CALIBRATION_SAMPLES;
    offsets.z_offset = z_sum / CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", offsets.x_offset, offsets.y_offset, offsets.z_offset);
    return offsets;
}

// Write a byte to an I2C register
int write_i2c_reg(uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Read a block of data from an I2C register
int read_i2c_block_data(uint8_t reg, char *buf, int count) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing register address for block read");
        return -1;
    }

    if (read(i2c_fd, buf, count) != count) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Log data to file
void log_data(gyro_data_t data, calibration_offsets_t offsets) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp,
            (float)data.x - offsets.x_offset, (float)data.y - offsets.y_offset, (float)data.z - offsets.z_offset);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Check threshold and print warning
void check_threshold(gyro_data_t data, calibration_offsets_t offsets) {
    float x_rate = (float)data.x - offsets.x_offset;
    float y_rate = (float)data.y - offsets.y_offset;
    float z_rate = (float)data.z - offsets.z_offset;

    if (fabs(x_rate) > ZERO_RATE_THRESHOLD || fabs(y_rate) > ZERO_RATE_THRESHOLD || fabs(z_rate) > ZERO_RATE_THRESHOLD) {
        fprintf(stderr, "WARNING: Gyroscope threshold exceeded! X=%.2f, Y=%.2f, Z=%.2f\n", x_rate, y_rate, z_rate);
        fprintf(log_file, "WARNING: Gyroscope threshold exceeded! X=%.2f, Y=%.2f, Z=%.2f\n", x_rate, y_rate, z_rate);
        fflush(log_file);
    }
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Configure gyroscope
    if (configure_gyro() < 0) {
        cleanup();
        return 1;
    }

    // Calibrate the gyroscope
    calibration_offsets_t offsets = calibrate_gyro();

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data, offsets);
        check_threshold(data, offsets);
        usleep(SAMPLE_PERIOD_MS * 1000); // Convert ms to us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

