#include <pigpio.h>

// LSM303DLHC I2C addresses
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR 0x1E

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG1_M 0x20
#define CTRL_REG2_M 0x21
#define CTRL_REG3_M 0x22
#define CTRL_REG4_M 0x23
#define CTRL_REG5_M 0x24
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Y_H_M 0x05
#define OUT_Y_L_M 0x06
#define OUT_Z_H_M 0x07
#define OUT_Z_L_M 0x08
#define MR_REG_M 0x02

// Scaling factors
#define ACCEL_SCALE 0.000061 // mg/LSB at +/- 2g
#define MAG_SCALE 0.00014   // gauss/LSB at +/- 4 gauss

// Global variables
int i2c_handle_accel = -1;
int i2c_handle_mag = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x;
    float accel_y;
    float accel_z;
    float mag_x;
