sensor_data_t read_sensor_data(int i2c_handle);
float calculate_heading(sensor_data_t data);
void log_data(float heading, sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the LSM303DLHC accelerometer
int init_lsm303(int i2c_handle) {
    // Enable accelerometer, 50 Hz, all axes enabled
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }
    return 0;
}

// Initialize the LSM303DLHC magnetometer
int init_lsm303_mag(int i2c_handle) {
    // Continuous conversion mode, 80 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_M, 0x14) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_M\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG2_M, 0x20) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2_M\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG3_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG3_M\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_M\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG5_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG5_M\n");
        return -1;
    }
    return 0;
}

// Read sensor data from the LSM303DLHC
sensor_data_t read_sensor_data(int i2c_handle) {
    sensor_data_t data;
    char buffer[6];

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.accel_x = 0.0;
        data.accel_y = 0.0;
        data.accel_z = 0.0;
    } else {
        int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
        int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
        int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
        data.accel_x = (float)raw_x * ACCEL_SCALE;
        data.accel_y = (float)raw_y * ACCEL_SCALE;
        data.accel_z = (float)raw_z * ACCEL_SCALE;
    }

    // Read magnetometer data
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.mag_x = 0.0;
        data.mag_y = 0.0;
        data.mag_z = 0.0;
    } else {
        int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
        int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
        int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);
        data.mag_x = (float)raw_x * MAG_SCALE;
        data.mag_y = (float)raw_y * MAG_SCALE;
        data.mag_z = (float)raw_z * MAG_SCALE;
    }

    return data;
}

// Calculate the tilt-compensated heading
float calculate_heading(sensor_data_t data) {
    float roll = atan2(data.accel_y, data.accel_z) * 180 / M_PI;
    float pitch = atan2(-data.accel_x, sqrt(data.accel_y * data.accel_y + data.accel_z * data.accel_z)) * 180 / M_PI;

    float heading = roll; // Simple heading, no tilt compensation

    return heading;
}

// Log data to a file
void log_data(float heading, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, heading, data.accel_x, data.accel_y, data.accel_z, data.mag_x, data.mag_y);
    fflush(log_file); // Ensure data is written to disk immediately
}

