    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Error opening I2C bus for accelerometer: %d\n", i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

    i2c_handle_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Error opening I2C bus for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (init_lsm303(i2c_handle_accel) < 0) {
        fprintf(stderr, "Error initializing accelerometer\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    if (init_lsm303_mag(i2c_handle_mag) < 0) {
        fprintf(stderr, "Error initializing magnetometer\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data = read_sensor_data(i2c_handle_mag);
        float heading = calculate_heading(sensor_data);
        log_data(heading, sensor_data);

        gpioDelay(100); // Sample every 100 ms
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

