// Define sensor addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define register addresses
#define CTRL_REG1 0x00
#define DATA_REG 0x01

// Define sampling interval (10 ms)
#define SAMPLE_INTERVAL_US 10000

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t sample;
    struct timespec timestamp;
} sensor_data_t;

// Function prototypes
int initialize_sensor(int i2c_handle, int address);
int read_sensor_data(int i2c_handle, int16_t *data);
void log_data(FILE *fp, struct timespec ts, int16_t sensor1, int16_t sensor2, int16_t tdoa);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes a single sensor
int initialize_sensor(int i2c_handle, int address) {
    // Enable continuous measurement mode (example: 0x80)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x80) < 0) {
        fprintf(stderr, "Error writing to control register for sensor at address 0x%02x\n", address);
        return -1;
    }
    return 0;
}

// Reads data from a single sensor
int read_sensor_data(int i2c_handle, int16_t *data) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DATA_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading data from sensor: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *data = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Logs data to a CSV file
void log_data(FILE *fp, struct timespec ts, int16_t sensor1, int16_t sensor2, int16_t tdoa) {
    fprintf(fp, "%ld,%ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1, sensor2, tdoa);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus 1
    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C bus 1 for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open I2C bus 1
    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C bus 1 for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (initialize_sensor(i2c_handle1, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Error initializing sensor 1\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle2, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Error initializing sensor 2\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t sensor1_data, sensor2_data;
        struct timespec ts;

        // Read data from sensor 1
        if (read_sensor_data(i2c_handle1, &sensor1_data) == 0) {
            // Read data from sensor 2
            if (read_sensor_data(i2c_handle2, &sensor2_data) == 0) {
                // Get timestamp
                if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                    // Calculate TDOA
                    int16_t tdoa = sensor1_data - sensor2_data;

                    // Log data
                    log_data(log_file, ts, sensor1_data, sensor2_data, tdoa);
                } else {
                    fprintf(stderr, "Error getting timestamp\n");
                }
            } else {
                fprintf(stderr, "Error reading data from sensor 2\n");
            }
        } else {
            fprintf(stderr, "Error reading data from sensor 1\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

