#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16488A Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCEL 0x0A
#define Y_ACCEL 0x0C
#define Z_ACCEL 0x0E
#define SMPL_PRD 0x36
#define SENS_G 0x3C
#define SENS_A 0x3E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0b11000000000 // CPHA=1, CPOL=1, AUX SPI off

// Global Variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t running = 1;

// Structure to hold IMU data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    float accel_x;
    float accel_y;
    float accel_z;
} imu_data_t;

// Function Prototypes
int spi_transfer(int handle, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_register(int handle, uint8_t reg_addr, uint16_t *data);
imu_data_t convert_data(uint16_t gyro_x, uint16_t gyro_y, uint16_t gyro_z, uint16_t accel_x, uint16_t accel_y, uint16_t accel_z);
int log_data(FILE *fp, imu_data_t data);
void signal_handler(int signal);
void cleanup();

// SPI Transfer Function
int spi_transfer(int handle, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    int result = spiXfer(handle, tx_buf, rx_buf, len);
    if (result < 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }
    return result;
}

// Read Register Function
int read_register(int handle, uint8_t reg_addr, uint16_t *data) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the SPI message to send
    tx_buf[0] = 0x00; // Dummy byte for MSB
    tx_buf[1] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[2] = 0x00; // Dummy byte for LSB

    if (spi_transfer(handle, tx_buf, rx_buf, 3) != 3) {
        return -1;
    }

    // Extract the 16-bit data from the received bytes
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

// Convert Data Function
imu_data_t convert_data(uint16_t gyro_x, uint16_t gyro_y, uint16_t gyro_z, uint16_t accel_x, uint16_t accel_y, uint16_t accel_z) {
    imu_data_t data;

    // Convert gyroscope data
    data.gyro_x = (float)gyro_x * 0.005;
    data.gyro_y = (float)gyro_y * 0.005;
    data.gyro_z = (float)gyro_z * 0.005;

    // Convert accelerometer data
    data.accel_x = (float)accel_x * 0.00025;
    data.accel_y = (float)accel_y * 0.00025;
    data.accel_z = (float)accel_z * 0.00025;

    return data;
}

// Log Data Function
int log_data(FILE *fp, imu_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    if (fprintf(fp, "%ld.%03ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                ts.tv_sec, milliseconds,
                data.gyro_x, data.gyro_y, data.gyro_z,
                data.accel_x, data.accel_y, data.accel_z) < 0) {
        fprintf(stderr, "Error writing to CSV file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup Function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    }
    rewind(fp);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        // Read gyroscope data
        if (read_register(spi_handle, X_GYRO, &gyro_x) != 0) {
            fprintf(stderr, "Error reading X_GYRO\n");
        }
        if (read_register(spi_handle, Y_GYRO, &gyro_y) != 0) {
            fprintf(stderr, "Error reading Y_GYRO\n");
        }
        if (read_register(spi_handle, Z_GYRO, &gyro_z) != 0) {
            fprintf(stderr, "Error reading Z_GYRO\n");
        }

        // Read accelerometer data
        if (read_register(spi_handle, X_ACCEL, &accel_x) != 0) {
            fprintf(stderr, "Error reading X_ACCEL\n");
        }
        if (read_register(spi_handle, Y_ACCEL, &accel_y) != 0) {
            fprintf(stderr, "Error reading Y_ACCEL\n");
        }
        if (read_register(spi_handle, Z_ACCEL, &accel_z) != 0) {
            fprintf(stderr, "Error reading Z_ACCEL\n");
        }

        // Convert data
        imu_data_t data = convert_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Log data
        if (log_data(fp, data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

