#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// SPI Configuration
#define SPI_BUS 0
#define SPI_CHIP_SELECT 0
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_BITS_PER_WORD 8

// Global Variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int adis16448_read_register(uint8_t reg_addr, int16_t *data);
void signal_handler(int sig);
int initialize_spi();
int initialize_gpio();
void cleanup();

// Structure to hold sensor data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    float accel_x;
    float accel_y;
    float accel_z;
} sensor_data_t;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the SPI interface
int initialize_spi() {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", SPI_BUS, SPI_CHIP_SELECT);

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to initialize the GPIO chip and line
int initialize_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, SPI_CHIP_SELECT);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request the GPIO line as output
    if (gpiod_line_request_output(gpio_line, "adis16448_cs", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Set the initial chip select state to high (inactive)
    gpiod_line_set_value(gpio_line, 1);

    return 0;
}

// Function to perform SPI transfer with error handling
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer[1];

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = len;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer);
    if (ret < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read a single register from the ADIS16448
int adis16448_read_register(uint8_t reg_addr, int16_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Construct the SPI message (send register address with MSB set)
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading data

    // Set chip select low
    gpiod_line_set_value(gpio_line, 0);

    // Perform SPI transfer
    if (spi_transfer(tx_buf, rx_buf, 2) < 0) {
        gpiod_line_set_value(gpio_line, 1); // Set chip select high
        return -1;
    }

    // Set chip select high
    gpiod_line_set_value(gpio_line, 1);

    // Combine the received bytes to form the 16-bit data
    *data = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

// Function to convert raw data to physical units
sensor_data_t convert_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    sensor_data_t data;

    data.gyro_x = (float)gyro_x * 0.02; // dps/LSB
    data.gyro_y = (float)gyro_y * 0.02;
    data.gyro_z = (float)gyro_z * 0.02;
    data.accel_x = (float)accel_x * 0.00025; // g/LSB
    data.accel_y = (float)accel_y * 0.00025;
    data.accel_z = (float)accel_z * 0.00025;

    return data;
}

// Function to log sensor data to the console
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps, Accel: X=%.6f g, Y=%.6f g, Z=%.6f g\n",
           timestamp, data.gyro_x, data.gyro_y, data.gyro_z, data.accel_x, data.accel_y, data.accel_z);
}

// Function to cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 1); // Set chip select high
        gpiod_line_release(gpio_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        // Read sensor data
        if (adis16448_read_register(XGYRO_OUT, &gyro_x) < 0 ||
            adis16448_read_register(YGYRO_OUT, &gyro_y) < 0 ||
            adis16448_read_register(ZGYRO_OUT, &gyro_z) < 0 ||
            adis16448_read_register(XACCL_OUT, &accel_x) < 0 ||
            adis16448_read_register(YACCL_OUT, &accel_y) < 0 ||
            adis16448_read_register(ZACCL_OUT, &accel_z) < 0) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert data
        sensor_data_t data = convert_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Log data
        log_data(data);

        // Wait 100ms
        usleep(100000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

