#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16448 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec/LSB
#define ACCL_SCALE 0.00025 // g/LSB

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    float accel_x;
    float accel_y;
    float accel_z;
} imu_data_t;

// Function prototypes
int initialize_pigpio();
int open_spi_channel();
int read_register(uint8_t reg_addr, uint16_t *data);
imu_data_t process_imu_data(uint16_t gyro_x, uint16_t gyro_y, uint16_t gyro_z, uint16_t accel_x, uint16_t accel_y, uint16_t accel_z);
void print_imu_data(imu_data_t data);
void signal_handler(int signal);
void close_spi_channel();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Opens the SPI channel
int open_spi_channel() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Reads a register from the ADIS16448
int read_register(uint8_t reg_addr, uint16_t *data) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the SPI message to send
    tx_buffer[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buffer[1] = 0x00; // Dummy byte for reading
    tx_buffer[2] = 0x00; // Dummy byte for reading

    // Transfer the SPI message
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract the received data
    *data = ((uint16_t)rx_buffer[1] << 8) | (uint16_t)rx_buffer[2];

    return 0;
}

// Processes the raw IMU data and converts it to physical units
imu_data_t process_imu_data(uint16_t gyro_x, uint16_t gyro_y, uint16_t gyro_z, uint16_t accel_x, uint16_t accel_y, uint16_t accel_z) {
    imu_data_t data;

    // Convert raw gyroscope data to degrees per second
    data.gyro_x = (float)gyro_x * GYRO_SCALE;
    data.gyro_y = (float)gyro_y * GYRO_SCALE;
    data.gyro_z = (float)gyro_z * GYRO_SCALE;

    // Convert raw accelerometer data to g
    data.accel_x = (float)accel_x * ACCL_SCALE;
    data.accel_y = (float)accel_y * ACCL_SCALE;
    data.accel_z = (float)accel_z * ACCL_SCALE;

    return data;
}

// Prints the IMU data to the console
void print_imu_data(imu_data_t data) {
    printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n", data.gyro_x, data.gyro_y, data.gyro_z);
    printf("Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n", data.accel_x, data.accel_y, data.accel_z);
}

// Closes the SPI channel
void close_spi_channel() {
    spiClose(spi_handle);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open the SPI channel
    if (open_spi_channel() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("ADIS16448 IMU Data Acquisition\n");

    // Main loop
    while (!terminate) {
        uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        // Read gyroscope data
        if (read_register(X_GYRO_OUT, &gyro_x) != 0) {
            fprintf(stderr, "Error reading gyro X\n");
        }
        if (read_register(Y_GYRO_OUT, &gyro_y) != 0) {
            fprintf(stderr, "Error reading gyro Y\n");
        }
        if (read_register(Z_GYRO_OUT, &gyro_z) != 0) {
            fprintf(stderr, "Error reading gyro Z\n");
        }

        // Read accelerometer data
        if (read_register(X_ACCL_OUT, &accel_x) != 0) {
            fprintf(stderr, "Error reading accel X\n");
        }
        if (read_register(Y_ACCL_OUT, &accel_y) != 0) {
            fprintf(stderr, "Error reading accel Y\n");
        }
        if (read_register(Z_ACCL_OUT, &accel_z) != 0) {
            fprintf(stderr, "Error reading accel Z\n");
        }

        // Process the IMU data
        imu_data_t imu_data = process_imu_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Print the IMU data
        print_imu_data(imu_data);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

