#include <string.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t accel_x;
    int16_t accel_y;
    int16_t accel_z;
    int16_t gyro_x;
    int16_t gyro_y;
    int16_t gyro_z;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the MPU-6886
int init_mpu6886() {
    // Wake up the MPU-6886 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6886 (PWR_MGMT_1 = 0x00): %s\n", strerror(errno));
        return -1;
    }

    // Set accelerometer range to +/- 2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Could not set accelerometer range to +/- 2g (ACCEL_CONFIG = 0x00): %s\n", strerror(errno));
        return -1;
    }

    // Set gyroscope range to +/- 250 dps
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Could not set gyroscope range to +/- 250 dps (GYRO_CONFIG = 0x00): %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read raw sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[14];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14) == 14) {
            // Combine high and low bytes for each axis
            data->accel_x = (int16_t)((buf[0] << 8) | buf[1]);
            data->accel_y = (int16_t)((buf[2] << 8) | buf[3]);
            data->accel_z = (int16_t)((buf[4] << 8) | buf[5]);
            data->gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
            data->gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
            data->gyro_z = (int16_t)((buf[12] << 8) | buf[13]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Could not read sensor data (I2C read failed): %s, retries remaining: %d\n", strerror(errno), retries);
            retries--;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Error: Could not read sensor data after multiple retries.\n");
    return -1; // Failure
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6886_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6886
    if (init_mpu6886() != 0) {
        fprintf(stderr, "Error: MPU-6886 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Print raw sensor data
            printf("Accel: X=%6d, Y=%6d, Z=%6d | Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z,
                   sensor_data.gyro_x, sensor_data.gyro_y, sensor_data.gyro_z);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying...\n");
        }

        // Delay for 50ms
        gpioDelay(50000);
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

