#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADXL345 Registers
#define ADXL345_REG_DEVID_AD 0x00
#define ADXL345_REG_THRESH_TAP 0x1D
#define ADXL345_REG_OFSX 0x1E
#define ADXL345_REG_OFSY 0x1F
#define ADXL345_REG_OFSZ 0x20
#define ADXL345_REG_DUR 0x21
#define ADXL345_REG_LATENT 0x22
#define ADXL345_REG_WINDOW 0x23
#define ADXL345_REG_THRESH_ACT 0x24
#define ADXL345_REG_TIME_ACT 0x25
#define ADXL345_REG_THRESH_INACT 0x26
#define ADXL345_REG_TIME_INACT 0x27
#define ADXL345_REG_ACT_INACT_CTL 0x28
#define ADXL345_REG_THRESH_FF 0x29
#define ADXL345_REG_TIME_FF 0x2A
#define ADXL345_REG_TAP_AXES 0x2B
#define ADXL345_REG_ACT_TAP_STATUS 0x2C
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Configuration
#define I2C_BUS 1
#define ADXL345_ADDRESS 0x53
#define RED_LED_GPIO 17
#define IMPACT_THRESHOLD 2.5f // g
#define LOG_FILE "impact_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_adxl345();
int read_acceleration(accelerometer_data_t *data);
float calculate_magnitude(accelerometer_data_t data);
void log_impact(accelerometer_data_t data, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the ADXL345 accelerometer
int initialize_adxl345() {
    // Verify device ID
    int devid = i2cReadByteData(i2c_handle, ADXL345_REG_DEVID_AD);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID register: %d\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect DEVID: 0x%02X\n", devid);
        return -1;
    }

    // Set data format: full resolution, +/- 2g range
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Set bandwidth rate: 100 Hz
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error writing to BW_RATE register\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Reads acceleration data from the ADXL345
int read_acceleration(accelerometer_data_t *data) {
    char buffer[6];
    int16_t x, y, z;

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, buffer, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    x = (int16_t)((buffer[1] << 8) | buffer[0]);
    y = (int16_t)((buffer[3] << 8) | buffer[2]);
    z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g-force units (assuming +/- 2g range)
    data->x = (float)x / 256.0f;
    data->y = (float)y / 256.0f;
    data->z = (float)z / 256.0f;

    return 0;
}

// Calculates the magnitude of the acceleration vector
float calculate_magnitude(accelerometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Logs the impact event to a file
void log_impact(accelerometer_data_t data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f g, X: %.2f g, Y: %.2f g, Z: %.2f g\n",
            timestamp, magnitude, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(RED_LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    accelerometer_data_t acceleration;
    float magnitude;

    printf("Monitoring accelerometer... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&acceleration) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(acceleration);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                log_impact(acceleration, magnitude);
                gpioWrite(RED_LED_GPIO, 1); // Turn on LED
                gpioDelay(500);           // Wait for 500ms
                gpioWrite(RED_LED_GPIO, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error reading acceleration, retrying...\n");
        }

