    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the ICM-20602 sensor
int initialize_imu() {
    // Wake up the sensor
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up IMU (PWR_MGMT_1)\n");
        return -1;
    }

    // Configure accelerometer range to +/- 2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range (ACCEL_CONFIG)\n");
        return -1;
    }

    // Configure gyroscope range to +/- 250 dps
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range (GYRO_CONFIG)\n");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Could not read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x12) {
