int read_sensor_data(sensor_data_t *data) {
    char buffer[14];
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 14) < 0) {
        fprintf(stderr, "Error: Could not read sensor data\n");
        return -1;
    }

    // Combine high and low bytes for accelerometer data
    accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Combine high and low bytes for gyroscope data
    gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
    gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
    gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);

    // Convert to g and dps
    data->accel_x = (float)accel_x / ACCEL_SCALE;
    data->accel_y = (float)accel_y / ACCEL_SCALE;
    data->accel_z = (float)accel_z / ACCEL_SCALE;
    data->gyro_x = (float)gyro_x / GYRO_SCALE;
    data->gyro_y = (float)gyro_y / GYRO_SCALE;
    data->gyro_z = (float)gyro_z / GYRO_SCALE;

