#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define LED_GPIO 17
#define THRESHOLD 2.0 // g
#define LOG_FILE "impact_log.txt"
#define SAMPLE_RATE_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact(double magnitude);
void cleanup();
void signal_handler(int sig);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Configure the accelerometer (enable measurement, 2g range)
    uint8_t config_data = 0x01 | (0x00 << 2); // Active mode, 2g range
    if (write(i2c_fd, &config_data, 1) != 1) {
        perror("Error writing to CTRL_REG1");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "impact_detector", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the MMA8451Q
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading acceleration data");
        return -1;
    }

    *x = (int16_t)((buffer[OUT_X_MSB] << 8) | buffer[OUT_X_LSB]);
    *y = (int16_t)((buffer[OUT_Y_MSB] << 8) | buffer[OUT_Y_LSB]);
    *z = (int16_t)((buffer[OUT_Z_MSB] << 8) | buffer[OUT_Z_LSB]);

    return 0;
}

// Function to calculate the magnitude of the acceleration vector
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z) / 1024.0; // Convert to g
