#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define POWER_CTL 0x2D
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37
#define THRESH_FF 0x0A
#define TIME_FF 0x20
#define INT_ENABLE 0x2E
#define INT_MAP 0x2F
#define INT_SOURCE 0x30

// GPIO pin for interrupt
#define INTERRUPT_PIN 17

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Freefall threshold (mg)
#define FREEFALL_THRESHOLD 300.0

// Freefall time (ms)
#define FREEFALL_TIME 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int adxl345_init(int i2c_fd);
accelerometer_data_t read_accelerometer_data(int i2c_fd);
void log_data(FILE *fp, accelerometer_data_t data);
void freefall_interrupt_handler(struct gpiod_line *line, unsigned int events);
void signal_handler(int sig);

// Function to initialize the ADXL345
int adxl345_init(int i2c_fd) {
    // Set POWER_CTL to standby mode
    if (i2c_smbus_write_byte_data(i2c_fd, POWER_CTL, 0x00) < 0) {
        perror("Failed to set POWER_CTL to standby mode");
        return -1;
    }

    // Set THRESH_FF and TIME_FF registers
    if (i2c_smbus_write_byte_data(i2c_fd, THRESH_FF, (int)(FREEFALL_THRESHOLD / 256.0 * 255.0)) < 0) {
        perror("Failed to write THRESH_FF");
        return -1;
    }
    if (i2c_smbus_write_byte_data(i2c_fd, TIME_FF, (int)(FREEFALL_TIME / 256.0 * 255.0)) < 0) {
        perror("Failed to write TIME_FF");
        return -1;
    }

    // Enable freefall interrupt
    if (i2c_smbus_write_byte_data(i2c_fd, INT_ENABLE, 0x04) < 0) {
        perror("Failed to write INT_ENABLE");
        return -1;
    }

    // Map freefall interrupt to INT1
    if (i2c_smbus_write_byte_data(i2c_fd, INT_MAP, 0x00) < 0) {
        perror("Failed to write INT_MAP");
        return -1;
    }

    // Enter measurement mode
    if (i2c_smbus_write_byte_data(i2c_fd, POWER_CTL, 0x08) < 0) {
        perror("Failed to set POWER_CTL to measurement mode");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
accelerometer_data_t read_accelerometer_data(int i2c_fd) {
    accelerometer_data_t data;
    uint8_t buffer[6];

    if (i2c_smbus_read_i2c_block_data(i2c_fd, DATAX0, (char *)buffer, 6) < 0) {
        perror("Failed to read accelerometer data");
        data.x = 0; data.y = 0; data.z = 0; // Return 0s on error
        return data;
    }

    // Combine high and low bytes for each axis
    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Function to log data to a CSV file
void log_data(FILE *fp, accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Interrupt handler function
void freefall_interrupt_handler(struct gpiod_line *line, unsigned int events) {
    if (events & GPIOD_LINE_EVENT_FALLING_EDGE) {
        accelerometer_data_t data = read_accelerometer_data(i2c_fd);
        log_data(log_file, data);
    }
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, INTERRUPT_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line as input
    if (gpiod_line_request_input(gpio_line, "adxl345_interrupt") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Set up interrupt handler
    struct gpiod_line_event_callback_data callback_data;
    callback_data.line = gpio_line;
    callback_data.handler = freefall_interrupt_handler;

    if (gpiod_line_event_callback_add(gpio_line, &callback_data) < 0) {
        perror("Failed to set up interrupt handler");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    printf("ADXL345 freefall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Disable interrupts
    if (i2c_smbus_write_byte_data(i2c_fd, INT_ENABLE, 0x00) < 0) {
        perror("Failed to disable interrupts");
    }

    // Close I2C bus
    close(i2c_fd);

    // Close GPIO line
    gpiod_line_event_callback_remove(gpio_line, &callback_data);
    gpiod_line_release(gpio_line);

    // Close GPIO chip
    gpiod_chip_close(gpio_chip);

    // Close log file
    fclose(log_file);

    printf("ADXL345 freefall detection stopped.\n");

    return 0;
}

