#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D
#define WHO_AM_I 0x0F

// Accelerometer and gyroscope sensitivity
#define ACCEL_SENSITIVITY 0.061 // mg/LSB at +/- 2g
#define GYRO_SENSITIVITY 8.75  // mdps/LSB at +/- 250 dps

// Freefall and impact thresholds
#define FREEFALL_THRESHOLD 0.2 // g
#define IMPACT_THRESHOLD 2.5  // g
#define IMPACT_WINDOW 1.0     // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x;
    float accel_y;
    float accel_z;
    float gyro_x;
    float gyro_y;
    float gyro_z;
} sensor_data_t;

// Function prototypes
int init_lsm6dsr();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void detect_fall(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the LSM6DSR sensor
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x6A) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: +/- 2g, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x60) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: +/- 250 dps, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x60) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Read sensor data from the LSM6DSR
int read_sensor_data(sensor_data_t *data) {
    char buffer[12];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 12) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Read gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    raw_gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw data to g and dps
    data->accel_x = (float)raw_accel_x * ACCEL_SENSITIVITY / 1000.0f;
    data->accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY / 1000.0f;
    data->accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY / 1000.0f;
    data->gyro_x = (float)raw_gyro_x * GYRO_SENSITIVITY / 1000.0f;
    data->gyro_y = (float)raw_gyro_y * GYRO_SENSITIVITY / 1000.0f;
    data->gyro_z = (float)raw_gyro_z * GYRO_SENSITIVITY / 1000.0f;

    return 0;
}

// Log sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Detect fall and impact states
void detect_fall(sensor_data_t data) {
    static time_t fall_start_time = 0;
    static int impact_detected = 0;
    static time_t impact_start_time = 0;
    static int freefall_state = 0; // 0: IDLE, 1: FREEFALL, 2: IMPACT

    // Calculate acceleration magnitude
    float magnitude = sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);

    // Fall detection
    if (magnitude < FREEFALL_THRESHOLD && freefall_state == 0) {
        fall_start_time = time(NULL);
        freefall_state = 1;
        printf("Fall detected!\n");
    } else if (magnitude > FREEFALL_THRESHOLD && freefall_state == 1) {
        freefall_state = 0;
    }

    // Impact detection
    if (magnitude > IMPACT_THRESHOLD && freefall_state == 1 && impact_detected == 0) {
        impact_start_time = time(NULL);
        impact_detected = 1;
        printf("Impact detected!\n");
    } else if (magnitude < IMPACT_THRESHOLD && impact_detected == 1) {
        time_t current_time = time(NULL);
        if (difftime(current_time, impact_start_time) >= IMPACT_WINDOW) {
            impact_detected = 0;
            printf("Impact ended.\n");
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);

            // Detect fall and impact
            detect_fall(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Delay for 10 ms
        gpioDelay(10000); // 10 ms = 10000 microseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

