#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define X_GYRO_OUT 0x14
#define Y_GYRO_OUT 0x16
#define Z_GYRO_OUT 0x18
#define WHO_AM_I 0x02

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data);
gyro_data_t read_gyro_data(int handle);
float scale_gyro_data(int16_t raw_data);
void log_gyro_data(FILE *fp, gyro_data_t data);
void signal_handler(int signal);
int initialize_spi(int channel, int baud, int mode);
int initialize_adis16266(int handle);

// Signal Handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI
int initialize_spi(int channel, int baud, int mode) {
    int handle = spiOpen(channel, baud, mode);
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// Initialize ADIS16266
int initialize_adis16266(int handle) {
    uint16_t who_am_i;
    if (spi_read_register(handle, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x3F5A) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x3F5A\n", who_am_i);
        return -1;
    }

    printf("ADIS16266 WHO_AM_I: 0x%X\n", who_am_i);
    return 0;
}

// Read a register from the ADIS16266
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the SPI message to send
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    // Extract the 16-bit data from the response
    *data = ((uint16_t)rx_buf[1] << 8) | (uint16_t)rx_buf[2];

    return 0;
}

// Write a register to the ADIS16266
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the SPI message to send
    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF; // LSB of data

    if (spiXfer(handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data(int handle) {
    gyro_data_t data;
    uint16_t raw_x, raw_y, raw_z;

    if (spi_read_register(handle, X_GYRO_OUT, &raw_x) != 0) {
        fprintf(stderr, "Error reading X_GYRO_OUT\n");
        data.x = 0.0;
    } else {
        data.x = scale_gyro_data(raw_x);
    }

    if (spi_read_register(handle, Y_GYRO_OUT, &raw_y) != 0) {
        fprintf(stderr, "Error reading Y_GYRO_OUT\n");
        data.y = 0.0;
    } else {
        data.y = scale_gyro_data(raw_y);
    }

    if (spi_read_register(handle, Z_GYRO_OUT, &raw_z) != 0) {
        fprintf(stderr, "Error reading Z_GYRO_OUT\n");
        data.z = 0.0;
    } else {
        data.z = scale_gyro_data(raw_z);
    }

    return data;
}

// Scale raw gyroscope data to degrees/sec
float scale_gyro_data(int16_t raw_data) {
    return (float)raw_data * 0.0305;
}

// Log gyroscope data to a CSV file
void log_gyro_data(FILE *fp, gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_handle = initialize_spi(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize ADIS16266
    if (initialize_adis16266(spi_handle) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write the CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Rate(deg/s),Y_Rate(deg/s),Z_Rate(deg/s)\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t gyro_data = read_gyro_data(spi_handle);
        log_gyro_data(log_file, gyro_data);
        gpioDelay(10); // 10 ms delay
    }

    // Close SPI and log file
    spiClose(spi_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

