#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SENSITIVITY 8.75 // mdps/LSB
#define SAMPLE_RATE_MS 10
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int initialize_gyro();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the gyroscope
int initialize_gyro() {
    int retries = 0;
    int status;

    // Wake up the gyroscope (set CTRL_REG1 to 0x0F)
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (status == 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error writing to CTRL_REG1 (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(10000); // 10ms delay
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to wake up gyroscope after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Set full-scale range to +/- 250 dps (set CTRL_REG4 to 0x00)
    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (status == 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error writing to CTRL_REG4 (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(10000); // 10ms delay
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to set full-scale range after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Verify WHO_AM_I register (should be 0xD3)
    retries = 0;
    while (retries < MAX_RETRIES) {
        int who_am_i = i2cReadByteData(i2c_handle, 0x0F);
        if (who_am_i == 0xD3) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading WHO_AM_I (attempt %d): 0x%X\n", retries + 1, who_am_i);
            gpioDelay(10000); // 10ms delay
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read WHO_AM_I after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    return 0;
}

// Reads gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];
    int status;

    // Read 6 bytes starting from OUT_X_L
    status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading gyro data: %s\n", strerror(errno));
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to degrees per second
    data.x = (float)x / SENSITIVITY;
    data.y = (float)y / SENSITIVITY;
    data.z = (float)z / SENSITIVITY;

    return data;
}

// Logs data to a CSV file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + (long long)ts.tv_nsec;

    fprintf(log_file, "%lld,%.3f,%.3f,%.3f\n", timestamp_ns, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the gyroscope
    if (initialize_gyro() != 0) {
        fprintf(stderr, "Gyro initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for 10ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

