        fprintf(stderr, "Failed to read WHO_AM_I after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    return 0;
}

// Reads gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];
    int status;

    // Read 6 bytes starting from OUT_X_L
    status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading gyro data: %s\n", strerror(errno));
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to degrees per second
    data.x = (float)x / SENSITIVITY;
    data.y = (float)y / SENSITIVITY;
    data.z = (float)z / SENSITIVITY;

    return data;
}

// Logs data to a CSV file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + (long long)ts.tv_nsec;

    fprintf(log_file, "%lld,%.3f,%.3f,%.3f\n", timestamp_ns, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the gyroscope
    if (initialize_gyro() != 0) {
        fprintf(stderr, "Gyro initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for 10ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

