void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Set the GPIO mode for the flame sensor
    if (set_gpio_mode() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected == 0) {
            log_flame_event(1);
            print_fire_alarm();
        } else if (flame_detected == 1) {
            log_flame_event(0);
        } else {
            // Error reading sensor, log the error
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (log_file != NULL) {
                fprintf(log_file, "%s - Error reading flame sensor\n", timestamp);
                fflush(log_file);
            } else {
                fprintf(stderr, "Log file is not open\n");
            }
        }

        gpioDelay(500); // Wait 500 milliseconds
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Flame sensor monitoring stopped.\n");

    return 0;
}

