#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define D7S_I2C_ADDR 0x53

// Define the register addresses for X, Y, and Z axis acceleration
#define X_LSB_REG 0x28
#define X_MSB_REG 0x29
#define Y_LSB_REG 0x2A
#define Y_MSB_REG 0x2B
#define Z_LSB_REG 0x2C
#define Z_MSB_REG 0x2D

// Define the CSV file name
#define CSV_FILE "vibration_log.csv"

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *csv_file = NULL; // CSV file pointer
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read sensor data from the D7S-0001
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[6];
    ssize_t bytes_read;

    bytes_read = read(i2c_fd, buffer, 6);
    if (bytes_read != 6) {
        if (bytes_read < 0) {
            perror("Error reading sensor data");
        } else {
            fprintf(stderr, "Warning: Read %zd bytes, expected 6\n", bytes_read);
        }
        return -1;
    }

    // Combine the LSB and MSB for each axis
    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Log the sensor data to a CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20]; // ISO 8601 format: YYYY-MM-DDTHH:MM:SSZ

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(csv_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open the CSV file for appending
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    rewind(csv_file);

    // Main loop
    sensor_data_t sensor_data;
    while (program_running) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Skipping logging.\n");
        }

        usleep(100000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

