#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D

// Define register addresses
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define WHO_AM_I 0x0D

// Define tilt angle threshold
#define TILT_THRESHOLD 45.0

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
accelerometer_data_t read_accelerometer_data();
float calculate_tilt_angle(accelerometer_data_t data);
void log_data(accelerometer_data_t data, float tilt_angle);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize the MMA8452Q sensor
int init_sensor() {
    // Set CTRL_REG1 to standby mode
    uint8_t ctrl_reg1_value = 0x00; // 0b00000000
    if (write(i2c_fd, &ctrl_reg1_value, 1) != 1) {
        perror("Error writing to CTRL_REG1");
        return -1;
    }
    usleep(10000); // Wait for the sensor to stabilize

    // Set CTRL_REG1 to active mode, 100 Hz data rate
    ctrl_reg1_value = 0x01; // 0b00000001
    if (write(i2c_fd, &ctrl_reg1_value, 1) != 1) {
        perror("Error writing to CTRL_REG1");
        return -1;
    }
    usleep(10000); // Wait for the sensor to stabilize

    return 0;
}

// Read accelerometer data from the MMA8452Q
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    uint8_t buffer[6];

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading accelerometer data");
        data.x = 0; // Set to 0 to avoid using uninitialized data
        data.y = 0;
        data.z = 0;
        return data;
    }

    // Combine MSB and LSB for each axis
    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Calculate tilt angle in degrees
float calculate_tilt_angle(accelerometer_data_t data) {
    float x = (float)data.x;
    float y = (float)data.y;
    float z = (float)data.z;

    float tilt_angle = atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;
    return tilt_angle;
}

// Log data to file
void log_data(accelerometer_data_t data, float tilt_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Tilt: %.2f\n", timestamp, data.x, data.y, data.z, tilt_angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() < 0) {
        cleanup();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read accelerometer data
        accelerometer_data_t data = read_accelerometer_data();

        // Calculate tilt angle
        float tilt_angle = calculate_tilt_angle(data);

        // Log data if tilt angle exceeds threshold
        if (fabs(tilt_angle) > TILT_THRESHOLD) {
            log_data(data, tilt_angle);
        }

        // Delay for 10 ms
        usleep(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

