#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define CTRL_REG3 0x22
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Calibration constants (example values, adjust based on your sensor)
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 0.146
#define Y_SCALE 0.146
#define Z_SCALE 0.146

// Metal-detector threshold (in milliGauss)
#define METAL_THRESHOLD 800.0

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(sensor_data_t *data);
void calibrate_sensor(sensor_data_t *data);
void log_data(sensor_data_t data);
void check_metal_detector(sensor_data_t data);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Initialize I2C communication
int init_i2c() {
    char *i2c_device = "/dev/i2c-1";
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize the LIS3MDL sensor
int init_sensor() {
    // Configure CTRL_REG1: Continuous conversion mode, 80 Hz ODR, all axes enabled
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1, 0x70) < 0) {
        perror("Error writing to CTRL_REG1");
        return -1;
    }

    // Configure CTRL_REG4: High-performance mode on all axes
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG4, 0x0C) < 0) {
        perror("Error writing to CTRL_REG4");
        return -1;
    }

    // Configure CTRL_REG3: Continuous conversion mode
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG3, 0x00) < 0) {
        perror("Error writing to CTRL_REG3");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2c_smbus_read_byte_data(i2c_fd, WHO_AM_I);
    if (who_am_i < 0) {
        perror("Error reading WHO_AM_I");
        return -1;
    }
    if (who_am_i != 0x3D) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x3D\n", who_am_i);
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading sensor data");
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to milliGauss
    data->x = (float)x * X_SCALE - X_OFFSET;
    data->y = (float)y * Y_SCALE - Y_OFFSET;
    data->z = (float)z * Z_SCALE - Z_OFFSET;

    return 0;
}

// Calibrate the sensor data
void calibrate_sensor(sensor_data_t *data) {
    // Implement calibration logic here if needed
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Check metal-detector threshold
void check_metal_detector(sensor_data_t data) {
    float total_field = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    if (total_field > METAL_THRESHOLD) {
        fprintf(stderr, "Metal-detector alert: Total field magnitude exceeds %.2f mG\n", METAL_THRESHOLD);
    }
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize sensor
    if (init_sensor() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calibrate sensor data
            calibrate_sensor(&sensor_data);

            // Log data
            log_data(sensor_data);

            // Check metal-detector threshold
            check_metal_detector(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Delay for 100ms (10 Hz sampling rate)
        usleep(100000); // 100000 microseconds = 100 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

