#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16362 Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float x_gyro;
    float y_gyro;
    float z_gyro;
    float x_accel;
    float y_accel;
    float z_accel;
} imu_data_t;

// Function Prototypes
int initialize_pigpio();
int initialize_spi();
int read_register(uint8_t address, uint16_t *data);
imu_data_t process_imu_data(uint16_t raw_data);
int log_data(imu_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from ADIS16362 register
int read_register(uint8_t address, uint16_t *data) {
    char tx_buffer[2];
    char rx_buffer[2];

    // Construct the transmit buffer (MSB = 1 for read, address)
    tx_buffer[0] = (address | 0x80) << 1; // MSB = 1 for read
    tx_buffer[1] = 0x00; // Dummy byte

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);

    if (result != 2) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Combine the received bytes to form the 16-bit data
    *data = ((uint16_t)rx_buffer[0] << 8) | (uint16_t)rx_buffer[1];

    return 0;
}

// Process raw IMU data (convert to degrees/sec and g)
imu_data_t process_imu_data(uint16_t raw_data) {
    imu_data_t data;

    // Gyroscope data (0.05 deg/sec/LSB)
    data.x_gyro = (float)raw_data * 0.05;
    data.y_gyro = (float)((raw_data >> 8) * 0.05);
    data.z_gyro = (float)((raw_data >> 16) * 0.05);

    // Accelerometer data (0.0025 g/LSB)
    data.x_accel = (float)raw_data * 0.0025;
    data.y_accel = (float)((raw_data >> 8) * 0.0025);
    data.z_accel = (float)((raw_data >> 16) * 0.0025);

    return data;
}

// Log data to CSV file
int log_data(imu_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec ts;

    // Get current timestamp
    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    // Write data to log file
    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", timestamp, data.x_gyro, data.y_gyro, data.z_gyro, data.x_accel, data.y_accel, data.z_accel);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        uint16_t raw_data;

        // Read gyroscope data
        if (read_register(X_GYRO, &raw_data) == 0) {
            imu_data_t gyro_data = process_imu_data(raw_data);
            log_data(gyro_data);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        // Read accelerometer data
        if (read_register(X_ACCL, &raw_data) == 0) {
            imu_data_t accel_data = process_imu_data(raw_data);
            log_data(accel_data);
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        // Delay for approximately 10 ms (100 Hz sampling)
        gpioDelay(10000); // 10 ms = 10000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

