    data.y_accel = (float)((raw_data >> 8) * 0.0025);
    data.z_accel = (float)((raw_data >> 16) * 0.0025);

    return data;
}

// Log data to CSV file
int log_data(imu_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec ts;

    // Get current timestamp
    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    // Write data to log file
    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", timestamp, data.x_gyro, data.y_gyro, data.z_gyro, data.x_accel, data.y_accel, data.z_accel);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        uint16_t raw_data;

        // Read gyroscope data
        if (read_register(X_GYRO, &raw_data) == 0) {
            imu_data_t gyro_data = process_imu_data(raw_data);
            log_data(gyro_data);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        // Read accelerometer data
        if (read_register(X_ACCL, &raw_data) == 0) {
            imu_data_t accel_data = process_imu_data(raw_data);
            log_data(accel_data);
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        // Delay for approximately 10 ms (100 Hz sampling)
        gpioDelay(10000); // 10 ms = 10000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

