#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define SENSOR_THRESHOLD 0 // Obstacle detected when sensor value is below this threshold
#define SELF_PARKING_DURATION 5 // seconds
#define SENSOR_READ_INTERVAL 1 // seconds

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static int spi_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_sensor_value();
void trigger_self_parking();
void log_event(const char *message);
void cleanup();
void signal_handler(int sig);

// Structure to hold sensor data
typedef struct {
    int sensor_value;
    time_t timestamp;
} sensor_data_t;

// Function to initialize the GPIO chip
int initialize_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    sensor_line = gpiod_chip_get_line(gpio_chip, 17);
    if (!sensor_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_input(sensor_line, "sensor_input") < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to initialize the SPI interface
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read the sensor value from the MCP3008 ADC
int read_sensor_value() {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // MCP3008 command to read channel 0 (single-ended)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to trigger the self-parking sequence
void trigger_self_parking() {
    log_event("Self-parking sequence started");
    sleep(SELF_PARKING_DURATION);
    log_event("Self-parking sequence completed");
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Function to cleanup resources before exiting
void cleanup() {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    log_event("System started");

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor_value();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value. Retrying in %d seconds.\n", SENSOR_READ_INTERVAL);
            sleep(SENSOR_READ_INTERVAL);
            continue;
        }

        if (sensor_value < SENSOR_THRESHOLD) {
            trigger_self_parking();
        }

        sleep(SENSOR_READ_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    log_event("System stopped");
    return 0;
}

