#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_LINE 8
#define MSC_CTRL_REG 0x24
#define X_RATE_REG 0x04
#define Y_RATE_REG 0x06
#define Z_RATE_REG 0x08
#define SCALE_FACTOR 0.02 // deg/sec/LSB
#define READ_INTERVAL_MS 100

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int spi_init(const char *device, int mode, int bits_per_word, int speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int gpio_init(struct gpiod_chip *chip, int line);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_get_value(struct gpiod_line *line);
int adis16266_init(int fd);
gyro_data_t read_gyro_data(int fd);
void log_data(gyro_data_t data);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, int mode, int bits_per_word, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_buf[2];
    mode_buf[0] = 0x00; // SPI mode register address
    mode_buf[1] = mode;

    if (spi_transfer(fd, mode_buf, NULL, 2) != 0) {
        fprintf(stderr, "Error setting SPI mode\n");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_per_word_buf[2];
    bits_per_word_buf[0] = 0x01; // Bits per word register address
    bits_per_word_buf[1] = bits_per_word;

    if (spi_transfer(fd, bits_per_word_buf, NULL, 2) != 0) {
        fprintf(stderr, "Error setting bits per word\n");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint8_t speed_buf[2];
    speed_buf[0] = 0x02; // SPI speed register address
    speed_buf[1] = (speed >> 16) & 0xFF; // MSB
    speed_buf[2] = (speed >> 8) & 0xFF; // Middle byte
    speed_buf[3] = speed & 0xFF; // LSB

    if (spi_transfer(fd, speed_buf, NULL, 4) != 0) {
        fprintf(stderr, "Error setting SPI speed\n");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(struct gpiod_chip *chip, int line) {
    cs_line = gpiod_chip_get_line(chip, line);
    if (!cs_line) {
        perror("Error getting GPIO line");
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "adis16266";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(cs_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(cs_line);
        cs_line = NULL;
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO get value function
int gpio_get_value(struct gpiod_line *line) {
    int value;
    if (gpiod_line_get_value(line, &value) < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

// ADIS16266 initialization function
int adis16266_init(int fd) {
    // Enable data ready mode (MSC_CTRL = 0x01)
    uint8_t msc_ctrl_buf[3];
    msc_ctrl_buf[0] = MSC_CTRL_REG | 0x80; // MSB = 1 for write
    msc_ctrl_buf[1] = 0x01; // Enable data ready mode
    msc_ctrl_buf[2] = 0x00; // Dummy byte

    if (spi_transfer(fd, msc_ctrl_buf, NULL, 3) != 0) {
        fprintf(stderr, "Error writing to MSC_CTRL register\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data function
gyro_data_t read_gyro_data(int fd) {
