#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5 // seconds
#define SAMPLE_INTERVAL 1 // milliseconds

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int threshold;
    int high_count = 0;
    time_t start_time;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    // Convert threshold to integer
    threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Error: Threshold must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Main loop
    while (program_running) {
        // Reset high count
        high_count = 0;

        // Get current time
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Start of the 5-second window
        start_time = current_time;

        // Sample GPIO pin for 5 seconds
        while (current_time - start_time < WINDOW_SIZE && program_running) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in microseconds
            time(&current_time);
        }

        // End of the 5-second window

        // Check if alert condition is met
        if (high_count > threshold) {
            printf("%s ALERT: Sound level exceeded threshold (%d high readings)\n", timestamp, high_count);
        } else {
            printf("%s Normal: Sound level (%d high readings)\n", timestamp, high_count);
        }

        // Wait for 1 second before the next window
        sleep(1);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

