#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the doors
#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "access_log.txt"

// Define the code length
#define CODE_LENGTH 6

// Define the unlock duration (seconds)
#define UNLOCK_DURATION 5

// Global variables
static volatile sig_atomic_t terminate = 0;
static FILE *log_file = NULL;

// Function prototypes
int generate_code(char *code);
int validate_code(const char *code);
void unlock_door(int gpio);
void lock_door(int gpio);
void log_access(const char *code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to generate a random 6-digit security code
int generate_code(char *code) {
    if (code == NULL) {
        fprintf(stderr, "Error: Code buffer is NULL.\n");
        return -1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Generate a random number between 100000 and 999999
    int code_value = rand() % 900000 + 100000;

    // Convert the number to a string
    sprintf(code, "%d", code_value);

    return 0;
}

// Function to validate the security code
int validate_code(const char *code) {
    if (code == NULL) {
        fprintf(stderr, "Error: Code buffer is NULL.\n");
        return -1;
    }

    // Check if the code is a 6-digit number
    if (strlen(code) != CODE_LENGTH) {
        fprintf(stderr, "Error: Code length is not %d digits.\n", CODE_LENGTH);
        return -1;
    }

    // Check if the code contains only digits
    for (int i = 0; i < CODE_LENGTH; i++) {
        if (isdigit(code[i]) == 0) {
            fprintf(stderr, "Error: Code contains non-digit character.\n");
            return -1;
        }
    }

    return 0;
}

// Function to unlock the door
void unlock_door(int gpio) {
    gpioWrite(gpio, 1); // HIGH to unlock
    printf("Door %d unlocked for %d seconds.\n", gpio, UNLOCK_DURATION);
    gpioDelay(UNLOCK_DURATION * 1000000); // Delay for unlock duration (microseconds)
    gpioWrite(gpio, 0); // LOW to lock
}

// Function to lock the door
void lock_door(int gpio) {
    gpioWrite(gpio, 1); // HIGH to lock
