#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750FVI_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x21
#define LOG_FILE "light_log.txt"
#define READ_INTERVAL_SEC 5

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int write_command(uint8_t command);
int read_data(uint16_t *data);
float calculate_lux(uint16_t raw_value);
int log_data(float lux_value);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750FVI_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Write a command to the BH1750FVI sensor
int write_command(uint8_t command) {
    uint8_t buf[2];
    buf[0] = 0x00; // Register address (not used in this mode)
    buf[1] = command;

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing command");
        return -1;
    }

    return 0;
}

// Read data from the BH1750FVI sensor
int read_data(uint16_t *data) {
    uint8_t buf[2];
    buf[0] = 0x00; // Register address (not used in this mode)

    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }

    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading data");
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// Calculate illuminance in lux
float calculate_lux(uint16_t raw_value) {
    return (float)raw_value * 5 / 6.0;
}

// Log data to a file
int log_data(float lux_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        perror("Log file is not open");
        return -1;
    }

    fprintf(log_file, "%s, Lux: %.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("BH1750FVI sensor reading started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint16_t raw_value;
        if (read_data(&raw_value) == 0) {
            float lux_value = calculate_lux(raw_value);
            if (log_data(lux_value) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
            printf("Lux: %.2f\n", lux_value);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

