#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define GPIO_PWM 18
#define PORT 12345
#define SHARED_SECRET "MySecretKey"
#define LOG_FILE "frequency_log.txt"
#define PWM_FREQUENCY 440 // Default frequency
#define PWM_RANGE 1000
#define PWM_DUTY_CYCLE 500
#define PWM_PERIOD 1000000 // 1 ms
#define PWM_CLOCK 19200000 // 19.2 MHz
#define PWM_MODE PI_OUTPUT

// Global variables
int i2c_handle;
int server_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_data(unsigned short *touch_data);
float map_touch_data_to_frequency(unsigned short touch_data);
void play_tone(float frequency);
void log_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the MPR121
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x0A) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x05) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure MPR121 to enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Enable all electrodes
        fprintf(stderr, "Error: Failed to enable all electrodes\n");
        return -1;
    }

    // Configure MPR121 to enter run mode
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // Enter run mode
        fprintf(stderr, "Error: Failed to enter run mode\n");
        return -1;
    }

    return 0;
}

// Read touch data from the MPR121
int mpr121_read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }
    *touch_data = (buf[1] << 8) | buf[0];
    return 0;
}

// Map touch data to a frequency using a logarithmic scale
float map_touch_data_to_frequency(unsigned short touch_data) {
    // Scale the touch data to a range of 0-1023
    float touch_value = (float)touch_data;
    float frequency = 220.0 + (touch_value / 1023.0) * (880.0 - 220.0);

    // Apply a logarithmic scale to the frequency
    frequency = 220.0 * pow(10.0, (log10(frequency) - log10(220.0)) / (log10(880.0) - log10(220.0)));

    return frequency;
}

// Play a tone using hardware PWM
void play_tone(float frequency) {
    // Calculate the PWM period based on the desired frequency
    int period_us = (int)(PWM_CLOCK / (frequency * 2));

    // Set the PWM period
    gpioSetPWMfrequency(GPIO_PWM, frequency);
    gpioSetPWMrange(GPIO_PWM, PWM_RANGE);

    // Set the PWM duty cycle
    gpioPWM(GPIO_PWM, PWM_DUTY_CYCLE);

    // Wait for the specified period
    gpioDelay(period_us);

    // Stop the PWM signal
    gpioPWM(GPIO_PWM, 0);
}

// Log the frequency to a file
void log_frequency(float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Frequency: %.2f Hz\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Handle a client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    int valread;

    valread = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        perror("Error: Receive failed");
        close(client_socket);
        return;
    }

    buffer[valread] = '\0';
    printf("Received: %s\n", buffer);

    // Check for the shared secret
    if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0 && strncmp(buffer + 16, SHARED_SECRET, strlen(SHARED_SECRET)) == 0) {
        printf("Shared secret matched!\n");

        // Play tones for 5 seconds
        for (int i = 0; i < 50; i++) {
            unsigned short touch_data;
            if (mpr121_read_touch_data(&touch_data) == 0) {
                float frequency = map_touch_data_to_frequency(touch_data);
                play_tone(frequency);
                log_frequency(frequency);
            } else {
                fprintf(stderr, "Error: Failed to read touch data during tone playback\n");
            }
            gpioDelay(20000); // 20ms delay
        }
    } else {
        printf("Shared secret not matched!\n");
    }

    close(client_socket);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int opt = 1;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(GPIO_PWM, PI_OUTPUT);

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
