#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <pigpio.h>

// LSM303DLHC Magnetometer I2C Address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define OUT_X_H_M 0x09
#define OUT_Y_L_M 0x0A
#define OUT_Y_H_M 0x0B
#define OUT_Z_L_M 0x0C
#define OUT_Z_H_M 0x0D

// LED GPIO Pin
#define LED_PIN 17

// PWM Frequency (Hz)
#define PWM_FREQUENCY 100

// I2C Bus
#define I2C_BUS 1

// Global variables
int i2c_fd;
struct gpiod_chip *gpio_chip;
struct gpiod_line *led_line;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_magnetometer();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int set_led_brightness(float magnitude);
void log_error(const char *message);
void signal_handler(int sig);
void cleanup();

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        log_error("Failed to initialize I2C");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        log_error("Failed to initialize GPIO");
        cleanup();
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer() != 0) {
        log_error("Failed to initialize magnetometer");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetometer.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    magnetometer_data_t mag_data;
    float magnitude;
    int brightness;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&mag_data.x, &mag_data.y, &mag_data.z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(mag_data.x, mag_data.y, mag_data.z);

            // Set LED brightness
            brightness = set_led_brightness(magnitude);

            // Log data
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, X: %d, Y: %d, Z: %d, Magnitude: %.2f, Brightness: %d\n",
                    t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec,
                    mag_data.x, mag_data.y, mag_data.z, magnitude, brightness);
            fflush(log_file); // Ensure data is written to file immediately
        } else {
            log_error("Failed to read magnetometer data");
        }

        // Delay
        usleep(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "magnetometer_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Initialize magnetometer
int init_magnetometer() {
    // Configure magnetometer (10 Hz continuous conversion)
    uint8_t config_value = 0x70; // 0b01110000
    if (write(i2c_fd, &config_value, 1) != 1) {
        perror("Failed to write to CTRL_REG1_M");
        return -1;
    }
    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Failed to read magnetometer data");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate magnitude of Z-axis field
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Set LED brightness using PWM
int set_led_brightness(float magnitude) {
    // Map magnitude to brightness (0-255)
    int brightness = (int)(magnitude * 255.0 / 1000.0); // Assuming max magnitude is 1000

    // Clamp brightness to 0-255
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    // Set PWM duty cycle
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "magnetometer_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        perror("Failed to request GPIO line for PWM");
        return -1;
    }

    if (gpiod_line_set_value(led_line, brightness) < 0) {
        perror("Failed to set GPIO line value");
        gpiod_line_release(led_line);
        return -1;
    }

    gpiod_line_release(led_line);

    return brightness;
}

// Log error messages
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
    perror(message);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

// Cleanup resources
void cleanup() {
    // Close I2C file descriptor
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    // Release GPIO line
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Stop PWM
    gpioPWM(LED_PIN, 0);

    // Terminate pigpio
    gpioTerminate();
}

