        return -1;
    }

    if (gpiod_line_set_value(led_line, brightness) < 0) {
        perror("Failed to set GPIO line value");
        gpiod_line_release(led_line);
        return -1;
    }

    gpiod_line_release(led_line);

    return brightness;
}

// Log error messages
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
    perror(message);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

// Cleanup resources
void cleanup() {
    // Close I2C file descriptor
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    // Release GPIO line
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Stop PWM
    gpioPWM(LED_PIN, 0);

    // Terminate pigpio
    gpioTerminate();
