#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L registers
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Hard-iron offset calibration window size
#define OFFSET_WINDOW_SIZE 100

// I2C handle
int i2c_handle;

// Hard-iron offsets
int16_t x_offset = 0, y_offset = 0, z_offset = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to initialize the HMC5883L sensor
int initialize_sensor(int handle) {
    // Configure Configuration Register A (8-average, 15 Hz, Gain = 1.3 Gauss)
    if (write_register(handle, HMC5883L_CONFIG_A, 0x70) < 0) return -1;

    // Configure Configuration Register B (Gain = 1.3 Gauss)
    if (write_register(handle, HMC5883L_CONFIG_B, 0x20) < 0) return -1;

    // Set continuous measurement mode
    if (write_register(handle, HMC5883L_MODE, 0x00) < 0) return -1;

    return 0;
}

// Function to read raw magnetometer data
int read_magnetometer_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    int x_msb, x_lsb, z_msb, z_lsb, y_msb, y_lsb;

    x_msb = read_register(handle, HMC5883L_DATA_X_MSB);
    x_lsb = read_register(handle, HMC5883L_DATA_X_LSB);
    z_msb = read_register(handle, HMC5883L_DATA_Z_MSB);
    z_lsb = read_register(handle, HMC5883L_DATA_Z_LSB);
    y_msb = read_register(handle, HMC5883L_DATA_Y_MSB);
    y_lsb = read_register(handle, HMC5883L_DATA_Y_LSB);

    if (x_msb < 0 || x_lsb < 0 || z_msb < 0 || z_lsb < 0 || y_msb < 0 || y_lsb < 0) {
        return -1;
    }

    *x = (int16_t)((x_msb << 8) | x_lsb);
    *z = (int16_t)((z_msb << 8) | z_lsb);
    *y = (int16_t)((y_msb << 8) | y_lsb);

    return 0;
}

// Function to apply hard-iron offsets
void apply_offsets(int16_t x, int16_t y, int16_t z, int16_t x_offset, int16_t y_offset, int16_t z_offset, int16_t *corrected_x, int16_t *corrected_y, int16_t *corrected_z) {
    *corrected_x = x - x_offset;
    *corrected_y = y - y_offset;
    *corrected_z = z - z_offset;
}

// Function to calculate the running average of hard-iron offsets
void calculate_running_average(int16_t x, int16_t y, int16_t z, int16_t *x_offset, int16_t *y_offset, int16_t *z_offset) {
    static int16_t x_sum = 0, y_sum = 0, z_sum = 0;
    static int sample_count = 0;

    x_sum -= x_offset[sample_count % OFFSET_WINDOW_SIZE];
    y_sum -= y_offset[sample_count % OFFSET_WINDOW_SIZE];
    z_sum -= z_offset[sample_count % OFFSET_WINDOW_SIZE];

    x_offset[sample_count % OFFSET_WINDOW_SIZE] = x;
    y_offset[sample_count % OFFSET_WINDOW_SIZE] = y;
    z_offset[sample_count % OFFSET_WINDOW_SIZE] = z;

    x_sum += x;
    y_sum += y;
    z_sum += z;

    sample_count++;

    *x_offset = x_sum / OFFSET_WINDOW_SIZE;
    *y_offset = y_sum / OFFSET_WINDOW_SIZE;
    *z_offset = z_sum / OFFSET_WINDOW_SIZE;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Allocate memory for hard-iron offsets
    int16_t *x_offsets = (int16_t *)malloc(OFFSET_WINDOW_SIZE * sizeof(int16_t));
    int16_t *y_offsets = (int16_t *)malloc(OFFSET_WINDOW_SIZE * sizeof(int16_t));
    int16_t *z_offsets = (int16_t *)malloc(OFFSET_WINDOW_SIZE * sizeof(int16_t));

    if (x_offsets == NULL || y_offsets == NULL || z_offsets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(x_offsets);
        free(y_offsets);
        free(z_offsets);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t x, y, z;
    int16_t corrected_x, corrected_y, corrected_z;
    while (1) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_handle, &x, &y, &z) == 0) {
            // Apply hard-iron offsets
            apply_offsets(x, y, z, x_offsets, y_offsets, z_offsets, &corrected_x, &corrected_y, &corrected_z);

            // Calculate running average of offsets
            calculate_running_average(corrected_x, corrected_y, corrected_z, x_offsets, y_offsets, z_offsets);

            // Print the corrected values
            printf("Corrected X: %d, Corrected Y: %d, Corrected Z: %d\n", corrected_x, corrected_y, corrected_z);
        } else {
            fprintf(stderr, "Error reading magnetometer data\n");
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Cleanup (should not reach here under normal circumstances due to the signal handler)
    free(x_offsets);
    free(y_offsets);
    free(z_offsets);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

