#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define INT1_CFG 0x30
#define INT1_THS 0x32
#define INT1_DURATION 0x33

// GPIO pin for INT1 interrupt
#define INT1_GPIO 23

// Circular buffer size
#define BUFFER_SIZE 64

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *int1_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Circular buffer structure
typedef struct {
    accelerometer_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Function prototypes
int init_i2c();
int init_gpio();
int init_lsm303d();
int read_lsm303d_data(accelerometer_data_t *data);
void interrupt_handler(struct gpiod_line *line, unsigned int events);
void add_to_buffer(circular_buffer_t *buffer, accelerometer_data_t data);
void dump_buffer(circular_buffer_t *buffer);
void signal_handler(int sig);
void cleanup();

// Initialize I2C
int init_i2c() {
    char *i2c_device = "/dev/i2c-1";
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    int1_line = gpiod_chip_get_line(gpio_chip, INT1_GPIO);
    if (!int1_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "lsm303d_mon";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0;

    if (gpiod_line_request(int1_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Initialize LSM303D
int init_lsm303d() {
    // Check WHO_AM_I register
    uint8_t who_am_i;
    if (i2c_smbus_read_byte_data(i2c_fd, 0x0F) < 0) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }
    who_am_i = i2c_smbus_read_byte_data(i2c_fd, 0x0F);
    if (who_am_i != 0x49) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x49\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1_A, 0x57) < 0) {
        perror("Error writing to CTRL_REG1_A");
        return -1;
    }

    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG4_A, 0x00) < 0) {
        perror("Error writing to CTRL_REG4_A");
        return -1;
    }

    // Configure INT1_CFG
    if (i2c_smbus_write_byte_data(i2c_fd, INT1_CFG, 0x2A) < 0) {
        perror("Error writing to INT1_CFG");
        return -1;
    }

    // Configure INT1_THS
    if (i2c_smbus_write_byte_data(i2c_fd, INT1_THS, 0x7D) < 0) {
        perror("Error writing to INT1_THS");
        return -1;
    }

    // Configure INT1_DURATION
    if (i2c_smbus_write_byte_data(i2c_fd, INT1_DURATION, 0x00) < 0) {
        perror("Error writing to INT1_DURATION");
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_lsm303d_data(accelerometer_data_t *data) {
    uint8_t buffer[6];
    if (i2c_smbus_read_i2c_block_data(i2c_fd, OUT_X_L_A | 0x80, (char *)buffer, 6) < 0) {
        perror("Error reading accelerometer data");
        return -1;
    }

    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Interrupt handler
void interrupt_handler(struct gpiod_line *line, unsigned int events) {
    if (events & GPIOD_LINE_EVENT_FALLING_EDGE) {
        accelerometer_data_t data;
        if (read_lsm303d_data(&data) == 0) {
            add_to_buffer(&circular_buffer, data);
            dump_buffer(&circular_buffer);
        } else {
            fprintf(stderr, "Error reading data in interrupt handler\n");
        }
    }
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, accelerometer_data_t data) {
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Dump contents of circular buffer
void dump_buffer(circular_buffer_t *buffer) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Last 10 samples:\n", timestamp);
    int start_index = (buffer->head - buffer->count + BUFFER_SIZE) % BUFFER_SIZE;
    for (int i = 0; i < buffer->count; i++) {
        int index = (start_index + i) % BUFFER_SIZE;
        printf("  X: %6d, Y: %6d, Z: %6d\n", buffer->buffer[index].x, buffer->buffer[index].y, buffer->buffer[index].z);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_chip) {
        gpiod_line_release(int1_line);
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Initialize signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    // Initialize LSM303D
    if (init_lsm303d() < 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    circular_buffer_t circular_buffer = {{0}, 0, 0};

    // Request interrupt line
    struct gpiod_line_request_config int1_config;
    memset(&int1_config, 0, sizeof(int1_config));
    int1_config.consumer = "lsm303d_mon";
    int1_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    int1_config.flags = 0;

    if (gpiod_line_request(int1_line, &int1_config, 0) < 0) {
        perror("Error requesting GPIO line for interrupt");
        cleanup();
        return 1;
    }

    // Set interrupt handler
    struct gpiod_line_event_callback int1_callback = {interrupt_handler};
    if (gpiod_line_set_callback(int1_line, &int1_callback) < 0) {
        perror("Error setting interrupt handler");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        usleep(10000); // 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

