#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Function prototypes
void activate_solenoid(int gpio_pin);
void deactivate_solenoid(int gpio_pin);
void alternate_solenoids(int solenoid1_pin, int solenoid2_pin);
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, cleaning up and exiting...\n", signal);
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);
    gpioTerminate();
    exit(0);
}

// Function to activate a solenoid
void activate_solenoid(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate solenoid on GPIO %d\n", gpio_pin);
    }
}

// Function to deactivate a solenoid
void deactivate_solenoid(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate solenoid on GPIO %d\n", gpio_pin);
    }
}

// Function to alternate solenoids
void alternate_solenoids(int solenoid1_pin, int solenoid2_pin) {
    activate_solenoid(solenoid1_pin);
    gpioDelay(500000); // 500 ms
    deactivate_solenoid(solenoid1_pin);
    activate_solenoid(solenoid2_pin);
    gpioDelay(500000); // 500 ms
    deactivate_solenoid(solenoid2_pin);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    // Initialize solenoids to OFF state (LOW)
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        alternate_solenoids(SOLENOID_1_PIN, SOLENOID_2_PIN);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);
    gpioTerminate();

    return 0;
}

