#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define UART device paths
#define UART0_DEVICE "/dev/serial0"
#define UART1_DEVICE "/dev/serial1"

// Define expected code
#define EXPECTED_CODE "123456"

// Define timeout duration (in seconds)
#define TIMEOUT_DURATION 5

// Global variables for UART file descriptors
int uart0_fd = -1;
int uart1_fd = -1;

// Function prototypes
int initialize_gpio();
int initialize_uart(const char *device);
int read_code(int fd, char *code, int max_length);
int compare_codes(const char *code1, const char *code2);
void unlock_doors();
void lock_doors();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);

    // Ensure both locks are initially locked
    lock_doors();

    return 0;
}

// Function to initialize UART communication
int initialize_uart(const char *device) {
    int fd = serOpen(device, 9600, 0); // 8N1
    if (fd < 0) {
        fprintf(stderr, "Failed to open UART %s: %d\n", device, fd);
        return -1;
    }
    return fd;
}

// Function to read code from UART with timeout
int read_code(int fd, char *code, int max_length) {
    int i = 0;
    time_t start_time = time(NULL);

    while (i < max_length) {
        int c = serReadByte(fd);
        if (c >= 0) {
            if (c >= '0' && c <= '9') {
                code[i] = (char)c;
                i++;
            } else {
                // Reset the input buffer if a non-digit is received
                code[0] = '\0';
                i = 0;
                fprintf(stderr, "Invalid character received: %c\n", c);
            }
        } else {
            // Handle serial read error (e.g., no data available)
            if (time(NULL) - start_time >= TIMEOUT_DURATION) {
                fprintf(stderr, "Timeout reading from UART %s\n", device);
                return -1; // Timeout
            }
            gpioDelay(1000); // Small delay to avoid busy-waiting
            continue;
        }
        start_time = time(NULL);
    }

    code[i] = '\0';
    return 0; // Success
}

// Function to compare two codes
int compare_codes(const char *code1, const char *code2) {
    if (strlen(code1) != strlen(code2)) {
        return 0; // Codes are different lengths
    }

    for (int i = 0; code1[i] != '\0'; i++) {
        if (code1[i] != code2[i]) {
            return 0; // Codes differ at index i
        }
    }

    return 1; // Codes are identical
}

// Function to unlock both doors
void unlock_doors() {
    gpioWrite(LOCK1_GPIO, 1); // Set GPIO HIGH to unlock
    gpioWrite(LOCK2_GPIO, 1);
    fprintf(stderr, "Doors unlocked\n");
}

// Function to lock both doors
void lock_doors() {
    gpioWrite(LOCK1_GPIO, 0); // Set GPIO LOW to lock
    gpioWrite(LOCK2_GPIO, 0);
    fprintf(stderr, "Doors locked\n");
}

// Function to perform cleanup before exiting
void cleanup() {
    lock_doors(); // Ensure doors are locked on exit

    if (uart0_fd != -1) {
        serClose(uart0_fd);
    }
    if (uart1_fd != -1) {
        serClose(uart1_fd);
    }

    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize UART
    uart0_fd = initialize_uart(UART0_DEVICE);
    if (uart0_fd < 0) {
        cleanup();
        return 1;
    }

    uart1_fd = initialize_uart(UART1_DEVICE);
    if (uart1_fd < 0) {
        cleanup();
        return 1;
    }

    char code1[7] = {0}; // Buffer for code from UART0
    char code2[7] = {0}; // Buffer for code from UART1

    fprintf(stderr, "Dual-factor authentication system started. Press Ctrl+C to exit.\n");

    while (1) {
        // Read code from UART0
        if (read_code(uart0_fd, code1, sizeof(code1)) == 0) {
            fprintf(stderr, "Code from UART0: %s\n", code1);

            // Read code from UART1
            if (read_code(uart1_fd, code2, sizeof(code2)) == 0) {
                fprintf(stderr, "Code from UART1: %s\n", code2);

                // Compare codes
                if (compare_codes(code1, code2)) {
                    fprintf(stderr, "Codes match!\n");

                    // Unlock doors
                    unlock_doors();

                    // Wait for 2 seconds
                    gpioDelay(2000000); // 2 seconds in microseconds

                    // Lock doors
                    lock_doors();
                } else {
                    fprintf(stderr, "Codes do not match\n");
                }
            }
        }

        gpioDelay(100000); // Small delay to avoid busy-waiting
    }

    return 0;
}

