#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define PIR_GPIO 4
#define RELAY_GPIO 17
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define DEBOUNCE_DELAY_MS 200
#define MOTION_THRESHOLD_SEC 10
#define SHUTDOWN_TIMEOUT_SEC 5

// Global variables
static volatile int running = 1;
static int pir_fd = -1;
static int relay_fd = -1;
static int sockfd = -1;
static struct sockaddr_in server_addr;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_relay(int state);
int send_motion_event(int motion_detected);
void log_event(int priority, const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO lines
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Request PIR sensor line as input
    pir_fd = gpioSetMode(PIR_GPIO, PI_INPUT);
    if (pir_fd < 0) {
        log_event(LOG_ERR, "Failed to set PIR GPIO mode");
        gpioTerminate();
        return -1;
    }

    // Request relay line as output
    relay_fd = gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    if (relay_fd < 0) {
        log_event(LOG_ERR, "Failed to set relay GPIO mode");
        gpioTerminate();
        return -1;
    }

    // Initialize relay to OFF state
    gpioWrite(RELAY_GPIO, 0);

    return 0;
}

// Function to read the PIR sensor value
int read_pir_sensor() {
    int value = gpioRead(PIR_GPIO);
    if (value < 0) {
        log_event(LOG_ERR, "Failed to read PIR sensor value");
        return -1;
    }
    return value;
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        log_event(LOG_ERR, "Failed to write to relay GPIO");
        return -1;
    }
    return 0;
}

// Function to send motion event to the server
int send_motion_event(int motion_detected) {
    char message[100];
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    snprintf(message, sizeof(message), "%s - Motion detected: %s", buf, motion_detected ? "YES" : "NO");

    if (sendto(sockfd, message, strlen(message), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        log_event(LOG_ERR, "Failed to send motion event to server");
        return -1;
    }
    return 0;
}

// Function to log events to syslog
void log_event(int priority, const char *message) {
    syslog(priority, "%s", message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    log_event(LOG_INFO, "Cleaning up...");

    // De-energize relay
    control_relay(0);

    // Close GPIO lines
    if (pir_fd >= 0) {
        gpioSetMode(PIR_GPIO, PI_INPUT); // Set back to input to avoid issues
        gpioTerminate();
    }
    if (relay_fd >= 0) {
        gpioSetMode(RELAY_GPIO, PI_INPUT); // Set back to input to avoid issues
        gpioTerminate();
    }

    // Close socket
    if (sockfd >= 0) {
        close(sockfd);
    }

    // Close syslog
    closelog();
}

int main() {
    // Open syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event(LOG_ERR, "GPIO initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Create socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        log_event(LOG_ERR, "Failed to create socket");
        cleanup();
        return 1;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        log_event(LOG_ERR, "Invalid server IP address");
        cleanup();
        return 1;
    }

    // Main loop
    int motion_detected = 0;
    time_t last_motion_time = 0;
    time_t last_shutdown_time = 0;

    while (running) {
        int pir_value = read_pir_sensor();
        if (pir_value < 0) {
            log_event(LOG_ERR, "Failed to read PIR sensor, retrying...");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (pir_value == 1) {
            // Motion detected
            if (!motion_detected) {
                log_event(LOG_INFO, "Motion detected!");
                send_motion_event(1);
                control_relay(1); // Energize relay
                motion_detected = 1;
                last_motion_time = time(NULL);
            } else {
                // Debouncing
                gpioDelay(DEBOUNCE_DELAY_MS);
            }
        } else {
            // No motion
            if (motion_detected) {
                log_event(LOG_INFO, "No motion detected.");
                send_motion_event(0);
                control_relay(0); // De-energize relay
                motion_detected = 0;
            }
        }

        // Failsafe: Check if PIR sensor remains HIGH for too long
        time_t current_time = time(NULL);
        if (motion_detected && (current_time - last_motion_time) > MOTION_THRESHOLD_SEC) {
            log_event(LOG_WARNING, "PIR sensor remains HIGH for too long, triggering failsafe.");
            send_motion_event(0); // De-energize relay
            control_relay(0); // De-energize relay
            motion_detected = 0;
            last_motion_time = current_time; // Reset last motion time
        }

        // Shutdown failsafe: Check if relay remains ON for too long
        if (!motion_detected && (current_time - last_shutdown_time) > SHUTDOWN_TIMEOUT_SEC) {
            log_event(LOG_WARNING, "Relay remains ON for too long, triggering shutdown.");
            send_motion_event(0); // De-energize relay
            control_relay(0); // De-energize relay
            motion_detected = 0;
            last_motion_time = current_time; // Reset last motion time
            last_shutdown_time = current_time; // Reset last shutdown time
            sleep(SHUTDOWN_TIMEOUT_SEC); // Simulate shutdown
            cleanup();
            return 0;
        }

        gpioDelay(50); // Check every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

