#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the number of relays
#define NUM_RELAYS 4

// Define the number of seconds in a minute
#define SECONDS_PER_MINUTE 60

// Define the number of seconds in 5 minutes
#define SECONDS_PER_5_MINUTES 300

// Define the number of seconds in 1 minute
#define SECONDS_PER_1_MINUTE 60

// Define the number of seconds in 10 seconds
#define SECONDS_PER_10_SECONDS 10

// Define the number of seconds in 5 seconds
#define SECONDS_PER_5_SECONDS 5

// Define the number of seconds in 1 second
#define SECONDS_PER_1_SECOND 1

// Define the number of relays to activate sequentially
#define NUM_RELAYS_TO_ACTIVATE 4

// Global variable to track the current relay state
volatile int current_relay_state = 0;

// Global variable to track the current action
volatile int current_action = 0; // 0: none, 1: activation, 2: deactivation, 3: pause

// Global variable to track the current timer ID
volatile int current_timer_id = -1;

// Function prototypes
void signal_handler(int signal);
void log_message(int priority, const char *message);
void activate_relay(int relay_pin);
void deactivate_relay(int relay_pin);
void pause_irrigation(int seconds);
void timer_callback(int timer_id, void *user_data);

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");

    // Deactivate all relays
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    // Exit the program
    exit(0);
}

// Function to log messages with timestamps
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(priority, "%s: %s", timestamp, message);
}

// Function to activate a relay
void activate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 0) != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to activate relay on pin %d", relay_pin);
        log_message(LOG_ERR, error_message);
        return;
    }

    char log_message_buffer[100];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Relay on pin %d activated", relay_pin);
    log_message(LOG_INFO, log_message_buffer);

    current_relay_state = relay_pin;
    current_action = 1; // Activation
}

// Function to deactivate a relay
void deactivate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 1) != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to deactivate relay on pin %d", relay_pin);
        log_message(LOG_ERR, error_message);
        return;
    }

    char log_message_buffer[100];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Relay on pin %d deactivated", relay_pin);
    log_message(LOG_INFO, log_message_buffer);

    current_relay_state = relay_pin;
    current_action = 2; // Deactivation
}

// Function to pause irrigation for a specified number of seconds
void pause_irrigation(int seconds) {
    char log_message_buffer[100];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Pausing irrigation for %d seconds", seconds);
    log_message(LOG_INFO, log_message_buffer);

    current_action = 3; // Pause

    // Set a timer to trigger after the specified number of seconds
    current_timer_id = gpioSetTimerFuncEx(0, seconds * 1000, timer_callback, NULL); // Timer 0, seconds * 1000 ms, callback function, user data
    if (current_timer_id < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to set timer for %d seconds", seconds);
        log_message(LOG_ERR, error_message);
        current_action = 0; // Reset action
    }
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    current_timer_id = -1; // Reset timer ID

    if (current_action == 1) {
        // Activate the next relay
        current_relay_state = 0; // Reset relay state
        current_action = 0; // Reset action

        if (current_relay_state == 0) {
            current_relay_state = RELAY1_PIN;
        } else if (current_relay_state == RELAY1_PIN) {
            current_relay_state = RELAY2_PIN;
        } else if (current_relay_state == RELAY2_PIN) {
            current_relay_state = RELAY3_PIN;
        } else if (current_relay_state == RELAY3_PIN) {
            current_relay_state = RELAY4_PIN;
        } else {
            current_relay_state = 0; // Reset to the first relay
        }

        if (current_relay_state != 0) {
            activate_relay(current_relay_state);
        } else {
            pause_irrigation(SECONDS_PER_5_MINUTES);
        }
    } else if (current_action == 2) {
        // Deactivate the next relay
        current_relay_state = 0; // Reset relay state
        current_action = 0; // Reset action

        if (current_relay_state == 0) {
            current_relay_state = RELAY1_PIN;
        } else if (current_relay_state == RELAY1_PIN) {
            current_relay_state = RELAY2_PIN;
        } else if (current_relay_state == RELAY2_PIN) {
            current_relay_state = RELAY3_PIN;
        } else if (current_relay_state == RELAY3_PIN) {
            current_relay_state = RELAY4_PIN;
        } else {
            current_relay_state = 0; // Reset to the first relay
        }

        if (current_relay_state != 0) {
            deactivate_relay(current_relay_state);
        } else {
            pause_irrigation(SECONDS_PER_5_MINUTES);
        }
    } else if (current_action == 3) {
        // Pause irrigation
        pause_irrigation(SECONDS_PER_5_MINUTES);
    }
}

int main() {
    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Start the irrigation sequence
    pause_irrigation(SECONDS_PER_5_MINUTES);

    // Keep the program running until a signal is received
    while (1) {
        sleep(1); // Reduce CPU usage
    }

    return 0;
}

