        snprintf(error_message, sizeof(error_message), "Failed to activate relay on pin %d", relay_pin);
        log_message(LOG_ERR, error_message);
        return;
    }

    char log_message_buffer[100];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Relay on pin %d activated", relay_pin);
    log_message(LOG_INFO, log_message_buffer);

    current_relay_state = relay_pin;
    current_action = 1; // Activation
}

// Function to deactivate a relay
void deactivate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 1) != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to deactivate relay on pin %d", relay_pin);
        log_message(LOG_ERR, error_message);
        return;
    }

    char log_message_buffer[100];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Relay on pin %d deactivated", relay_pin);
    log_message(LOG_INFO, log_message_buffer);

    current_relay_state = relay_pin;
    current_action = 2; // Deactivation
}

// Function to pause irrigation for a specified number of seconds
void pause_irrigation(int seconds) {
    char log_message_buffer[100];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Pausing irrigation for %d seconds", seconds);
    log_message(LOG_INFO, log_message_buffer);

    current_action = 3; // Pause

    // Set a timer to trigger after the specified number of seconds
    current_timer_id = gpioSetTimerFuncEx(0, seconds * 1000, timer_callback, NULL); // Timer 0, seconds * 1000 ms, callback function, user data
    if (current_timer_id < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to set timer for %d seconds", seconds);
        log_message(LOG_ERR, error_message);
        current_action = 0; // Reset action
    }
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    current_timer_id = -1; // Reset timer ID

    if (current_action == 1) {
        // Activate the next relay
        current_relay_state = 0; // Reset relay state
        current_action = 0; // Reset action

        if (current_relay_state == 0) {
            current_relay_state = RELAY1_PIN;
        } else if (current_relay_state == RELAY1_PIN) {
            current_relay_state = RELAY2_PIN;
        } else if (current_relay_state == RELAY2_PIN) {
            current_relay_state = RELAY3_PIN;
        } else if (current_relay_state == RELAY3_PIN) {
            current_relay_state = RELAY4_PIN;
        } else {
            current_relay_state = 0; // Reset to the first relay
        }

        if (current_relay_state != 0) {
            activate_relay(current_relay_state);
        } else {
            pause_irrigation(SECONDS_PER_5_MINUTES);
        }
    } else if (current_action == 2) {
        // Deactivate the next relay
        current_relay_state = 0; // Reset relay state
        current_action = 0; // Reset action

        if (current_relay_state == 0) {
            current_relay_state = RELAY1_PIN;
        } else if (current_relay_state == RELAY1_PIN) {
            current_relay_state = RELAY2_PIN;
        } else if (current_relay_state == RELAY2_PIN) {
            current_relay_state = RELAY3_PIN;
        } else if (current_relay_state == RELAY3_PIN) {
            current_relay_state = RELAY4_PIN;
        } else {
            current_relay_state = 0; // Reset to the first relay
        }

        if (current_relay_state != 0) {
            deactivate_relay(current_relay_state);
        } else {
            pause_irrigation(SECONDS_PER_5_MINUTES);
        }
    } else if (current_action == 3) {
        // Pause irrigation
        pause_irrigation(SECONDS_PER_5_MINUTES);
    }
}

int main() {
    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Start the irrigation sequence
    pause_irrigation(SECONDS_PER_5_MINUTES);

    // Keep the program running until a signal is received
    while (1) {
        sleep(1); // Reduce CPU usage
    }

    return 0;
}

