#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Circular buffer structure
typedef struct {
    accelerometer_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_raw_acceleration(int16_t *x, int16_t *y, int16_t *z);
float scale_acceleration(int16_t raw_value);
void add_to_buffer(circular_buffer_t *buffer, accelerometer_data_t data);
accelerometer_data_t get_latest_data(circular_buffer_t *buffer);
int export_sysfs_interface(const char *path);
int unexport_sysfs_interface(const char *path);
int write_sysfs_file(const char *path, const char *value);
int read_sysfs_file(const char *path, char *buffer, size_t buffer_size);
void signal_handler(int signal);

// Initialize the circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize I2C communication
int init_i2c() {
    char *i2c_device = "/dev/i2c-1";
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize the MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (write_sysfs_file("/sys/kernel/mpu6050_accel/power_management", "0") < 0) {
        fprintf(stderr, "Error waking up MPU6050\n");
        return -1;
    }

    // Set accelerometer range to +-2g
    if (write_sysfs_file("/sys/kernel/mpu6050_accel/accel_config", "0") < 0) {
        fprintf(stderr, "Error setting accelerometer range\n");
        return -1;
    }

    return 0;
}

// Read raw acceleration data from the MPU6050
int read_raw_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading acceleration data");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Scale raw acceleration data to g-force units
float scale_acceleration(int16_t raw_value) {
    return (float)raw_value / 16384.0f;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, accelerometer_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get the latest data from the circular buffer
accelerometer_data_t get_latest_data(circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        accelerometer_data_t empty_data = {0.0f, 0.0f, 0.0f};
        return empty_data;
    }

    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->data[index];
}

// Export sysfs interface
int export_sysfs_interface(const char *path) {
    char buffer[3];
    snprintf(buffer, sizeof(buffer), "%d", 1); // Export the interface
    if (write_sysfs_file(path, buffer) < 0) {
        fprintf(stderr, "Error exporting sysfs interface\n");
        return -1;
    }
    return 0;
}

// Unexport sysfs interface
int unexport_sysfs_interface(const char *path) {
    char buffer[3];
    snprintf(buffer, sizeof(buffer), "%d", 1); // Unexport the interface
    if (write_sysfs_file(path, buffer) < 0) {
        fprintf(stderr, "Error unexporting sysfs interface\n");
        return -1;
    }
    return 0;
}

// Write to sysfs file
int write_sysfs_file(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening sysfs file for writing");
        return -1;
    }

    if (write(fd, value, strlen(value)) < 0) {
        perror("Error writing to sysfs file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Read from sysfs file
int read_sysfs_file(const char *path, char *buffer, size_t buffer_size) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Error opening sysfs file for reading");
        return -1;
    }

    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read < 0) {
        perror("Error reading from sysfs file");
        close(fd);
        return -1;
    }

    buffer[bytes_read] = '\0'; // Null-terminate the buffer
    close(fd);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize circular buffer
    circular_buffer_t buffer;
    init_circular_buffer(&buffer);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() < 0) {
        close(i2c_fd);
        return 1;
    }

    // Export sysfs interface
    if (export_sysfs_interface("/sys/kernel/mpu6050_accel") < 0) {
        close(i2c_fd);
        return 1;
    }

    // Create sysfs files for reading acceleration data
    char path[64];
    snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest");
    if (write_sysfs_file(path, "x") < 0) {
        unexport_sysfs_interface("/sys/kernel/mpu6050_accel");
        close(i2c_fd);
        return 1;
    }
    snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest");
    if (write_sysfs_file(path, "y") < 0) {
        unexport_sysfs_interface("/sys/kernel/mpu6050_accel");
        close(i2c_fd);
        return 1;
    }
    snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest");
    if (write_sysfs_file(path, "z") < 0) {
        unexport_sysfs_interface("/sys/kernel/mpu6050_accel");
        close(i2c_fd);
        return 1;
    }

    // Set up timer for 100 Hz sampling
    struct sigevent sev;
    struct itimerspec its;
    struct sigaction sa;

    // Set up signal handler for timer signal
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = SIGEV_SIGNAL;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGEV_SIGNAL, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        unexport_sysfs_interface("/sys/kernel/mpu6050_accel");
        close(i2c_fd);
        return 1;
    }

    // Set up timer interval
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 100000000; // 100 Hz = 100000000 nanoseconds
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 100000000; // 100 Hz = 100000000 nanoseconds

    // Create timer
    if (timer_create(CLOCK_REALTIME, &sev, NULL) == -1) {
        perror("Error creating timer");
        unexport_sysfs_interface("/sys/kernel/mpu6050_accel");
        close(i2c_fd);
        return 1;
    }

    // Start timer
    if (timer_settime(0, 0, &its, NULL) == -1) {
        perror("Error starting timer");
        unexport_sysfs_interface("/sys/kernel/mpu6050_accel");
        close(i2c_fd);
        return 1;
    }

    int16_t raw_x, raw_y, raw_z;
    float x_g, y_g, z_g;
    accelerometer_data_t data;

    // Main loop
    while (program_running) {
        // Read raw acceleration data
        if (read_raw_acceleration(&raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Error reading raw acceleration data, retrying...\n");
            nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 100000000}, NULL); // Wait 100ms before retrying
            continue;
        }

        // Scale acceleration data
        x_g = scale_acceleration(raw_x);
        y_g = scale_acceleration(raw_y);
        z_g = scale_acceleration(raw_z);

        // Add data to circular buffer
        data.x = x_g;
        data.y = y_g;
        data.z = z_g;
        add_to_buffer(&buffer, data);

        // Read acceleration data from sysfs
        char x_str[16], y_str[16], z_str[16];
        snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest");
        if (read_sysfs_file(path, x_str, sizeof(x_str)) < 0) {
            fprintf(stderr, "Error reading X acceleration from sysfs\n");
        }
        snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest");
        if (read_sysfs_file(path, y_str, sizeof(y_str)) < 0) {
            fprintf(stderr, "Error reading Y acceleration from sysfs\n");
        }
        snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest");
        if (read_sysfs_file(path, z_str, sizeof(z_str)) < 0) {
            fprintf(stderr, "Error reading Z acceleration from sysfs\n");
        }

        // Print acceleration data to console
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g, X: %s, Y: %s, Z: %s\n", x_g, y_g, z_g, x_str, y_str, z_str);

        // Sleep for 100ms
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 100000000}, NULL);
    }

    // Clean up
    timer_delete(0);
    unexport_sysfs_interface("/sys/kernel/mpu6050_accel");
    close(i2c_fd);

    return 0;
}

