#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define constants
#define SOUND_THRESHOLD 1 // Digital HIGH indicates sound
#define RELAY_DURATION 3 // seconds
#define DEBOUNCE_DELAY 50 // milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int control_relay(int state);
int log_alarm_event();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int sound_sensor_pin;
    int relay_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Ensure relay is initially off
    gpioWrite(RELAY_PIN, 0);

    return 0; // Indicate success
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    return 0; // Indicate success
}

// Function to log the alarm event
int log_alarm_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: Alarm triggered\n", timestamp);
        fflush(log_file); // Ensure the log is written immediately
        return 0; // Indicate success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1; // Indicate failure
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Set the flag to exit the main loop

    // Turn off the relay
    control_relay(0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file
    log_file = fopen("alarm_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Clean up pigpio before exiting
        return 1;
    }

    printf("Alarm system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == SOUND_THRESHOLD) {
            printf("Sound detected!\n");

            // Activate the relay
            if (control_relay(1) != 0) {
                fprintf(stderr, "Error activating relay!\n");
            }

            // Log the alarm event
            if (log_alarm_event() != 0) {
                fprintf(stderr, "Error logging alarm event!\n");
            }

            // Wait for the relay duration
            gpioDelay(RELAY_DURATION * 1000000); // Convert seconds to microseconds

            // Deactivate the relay
            if (control_relay(0) != 0) {
                fprintf(stderr, "Error deactivating relay!\n");
            }
        }

        gpioDelay(DEBOUNCE_DELAY * 1000); // Delay for debounce
    }

    return 0;
}

