        fprintf(log_file, "%s: Alarm triggered\n", timestamp);
        fflush(log_file); // Ensure the log is written immediately
        return 0; // Indicate success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1; // Indicate failure
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Set the flag to exit the main loop

    // Turn off the relay
    control_relay(0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file
    log_file = fopen("alarm_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Clean up pigpio before exiting
        return 1;
    }

    printf("Alarm system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == SOUND_THRESHOLD) {
            printf("Sound detected!\n");

            // Activate the relay
            if (control_relay(1) != 0) {
                fprintf(stderr, "Error activating relay!\n");
            }

            // Log the alarm event
            if (log_alarm_event() != 0) {
                fprintf(stderr, "Error logging alarm event!\n");
            }

            // Wait for the relay duration
            gpioDelay(RELAY_DURATION * 1000000); // Convert seconds to microseconds

            // Deactivate the relay
            if (control_relay(0) != 0) {
                fprintf(stderr, "Error deactivating relay!\n");
            }
        }

        gpioDelay(DEBOUNCE_DELAY * 1000); // Delay for debounce
    }

    return 0;
}

