#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define WHO_AM_I    0x75

// Gyroscope sensitivity (LSB/deg/s)
#define GYRO_SENSITIVITY 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Threshold for angular velocity (degrees/second)
#define THRESHOLD 50.0

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Structure to hold the circular buffer
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd;
circular_buffer_t gyro_buffer;
bool running = true;

// Function prototypes
int init_i2c();
int init_mpu6050();
gyro_data_t read_gyro_data();
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
gyro_data_t get_average_data(circular_buffer_t *buffer);
float calculate_magnitude(gyro_data_t data);
void check_threshold(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int init_i2c() {
    char *i2c_device = "/dev/i2c-1"; // Standard I2C bus on Raspberry Pi
    if ((i2c_fd = open(i2c_device, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return 0;
}

// Function to initialize the MPU-6050 sensor
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep bit in PWR_MGMT_1)
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0; // Clear sleep bit
    if (write(i2c_fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }
    usleep(100000); // Wait for the sensor to wake up (adjust as needed)

    // Verify WHO_AM_I register
    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        perror("Error reading WHO_AM_I");
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x68\n", who_am_i);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data from the MPU-6050
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    uint8_t buffer[6];

    // Read 6 bytes of gyroscope data (X, Y, Z)
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        data.x = 0.0; // Set to 0 in case of error
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert raw data to degrees/second
    data.x = (float)raw_x / GYRO_SENSITIVITY;
    data.y = (float)raw_y / GYRO_SENSITIVITY;
    data.z = (float)raw_z / GYRO_SENSITIVITY;

    return data;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to calculate the average gyroscope data from the buffer
gyro_data_t get_average_data(circular_buffer_t *buffer) {
    gyro_data_t sum = {0.0, 0.0, 0.0};
    if (buffer->count > 0) {
        for (int i = 0; i < buffer->count; i++) {
            sum.x += buffer->data[i].x;
            sum.y += buffer->data[i].y;
            sum.z += buffer->data[i].z;
        }
        sum.x /= buffer->count;
        sum.y /= buffer->count;
        sum.z /= buffer->count;
    }
    return sum;
}

// Function to calculate the magnitude of the gyroscope data vector
float calculate_magnitude(gyro_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to check if the angular velocity exceeds the threshold
void check_threshold(gyro_data_t data) {
    float magnitude = calculate_magnitude(data);
    if (magnitude > THRESHOLD) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        printf("[%s] Angular velocity threshold exceeded! Magnitude: %.2f degrees/second\n", timestamp, magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    close(i2c_fd);
    printf("I2C bus closed.\n");
}

int main() {
    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }
    printf("I2C initialized.\n");

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        cleanup();
        return 1;
    }
    printf("MPU-6050 initialized.\n");

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read gyroscope data
        gyro_data_t gyro_data = read_gyro_data();

        // Add data to circular buffer
        add_to_buffer(&gyro_buffer, gyro_data);

        // Calculate average gyroscope data
        gyro_data_t average_data = get_average_data(&gyro_buffer);

        // Check threshold
        check_threshold(average_data);

        // Delay for 100ms
        usleep(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

