    int handle = serOpen(device, baud_rate, 0); // 0 for default flags
    if (handle < 0) {
        fprintf(stderr, "Failed to open UART %s: %d\n", device, handle);
        return -1;
    }
    return handle;
}

// Send read command to MH-Z19B
int send_read_command(int handle) {
    if (serWrite(handle, READ_COMMAND, sizeof(READ_COMMAND)) != sizeof(READ_COMMAND)) {
        fprintf(stderr, "Failed to send read command\n");
        return -1;
    }
    return 0;
}

// Read CO2 data from UART
int read_co2_data(int handle, unsigned char *buffer, int max_len) {
    int bytes_read = serRead(handle, buffer, max_len);
    if (bytes_read < 0) {
        fprintf(stderr, "Failed to read data from UART: %d\n", bytes_read);
        return -1;
    }
    return bytes_read;
}

// Validate checksum
int validate_checksum(const unsigned char *buffer, int len) {
    unsigned char checksum = 0xFF;
    for (int i = 1; i < len - 1; i++) {
        checksum += buffer[i];
    }
    checksum = ~checksum + 1;
    if (checksum != buffer[len - 1]) {
        fprintf(stderr, "Checksum mismatch: calculated 0x%02X, received 0x%02X\n", checksum, buffer[len - 1]);
        return -1;
    }
    return 0;
}

// Extract CO2 ppm value from buffer
int extract_co2_ppm(const unsigned char *buffer) {
    return (buffer[2] << 8) | buffer[3];
}

// Log CO2 data to file
int log_co2_data(FILE *file, unsigned int co2, int error) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(file, "{\"timestamp\": %lld, \"co2\": %u, \"error\": %d}\n", timestamp_ms, co2, error);
    fflush(file); // Ensure data is written to disk immediately
    return 0;
}

// Log error to file
int log_error(FILE *file, const char *message) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(file, "{\"timestamp\": %lld, \"error\": \"%s\"}\n", timestamp_ms, message);
    fflush(file);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open UART port
    uart_handle = open_uart(UART_DEVICE, BAUD_RATE);
    if (uart_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log files
    log_file = fopen(CO2_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", CO2_LOG_FILE);
        cleanup();
        return 1;
    }

    error_file = fopen(ERROR_LOG_FILE, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file %s\n", ERROR_LOG_FILE);
        cleanup();
        return 1;
    }

    unsigned char read_buffer[9];
    int co2_ppm;
    int retry_count;
    int read_result;

    printf("CO2 monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Send read command
        if (send_read_command(uart_handle) != 0) {
            log_error(error_file, "Failed to send read command");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for 100ms
        gpioDelay(100);

        // Read CO2 data with retries
        retry_count = 0;
        read_result = -1; // Initialize to an error value
        while (retry_count < 3 && read_result < 0) {
            read_result = read_co2_data(uart_handle, read_buffer, sizeof(read_buffer));
            if (read_result < 0) {
                log_error(error_file, "Failed to read CO2 data");
                gpioDelay(100); // Wait 100ms before retrying
                retry_count++;
            }
        }

        if (read_result < 0) {
            log_error(error_file, "Failed to read CO2 data after multiple retries");
            gpioDelay(1000); // Wait 1 second before next attempt
            continue;
        }

        // Validate checksum
        if (validate_checksum(read_buffer, sizeof(read_buffer)) != 0) {
            log_error(error_file, "Checksum validation failed");
            gpioDelay(1000); // Wait 1 second before next attempt
            continue;
        }

        // Extract CO2 ppm
        co2_ppm = extract_co2_ppm(read_buffer);

        // Log CO2 data
        log_co2_data(log_file, co2_ppm, 0);

        // Print CO2 data to stdout
        printf("CO2: %u ppm\n", co2_ppm);

        // Check CO2 threshold
        if (co2_ppm > CO2_THRESHOLD) {
            log_error(error_file, "CO2 level exceeds threshold");
        }

        gpioDelay(READ_INTERVAL_SEC * 1000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

