#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L registers
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_X_MSB 0x03
#define DATA_X_LSB 0x04
#define DATA_Z_MSB 0x05
#define DATA_Z_LSB 0x06
#define DATA_Y_MSB 0x07
#define DATA_Y_LSB 0x08

// Hard-iron calibration offsets
#define HARD_IRON_X 100.0
#define HARD_IRON_Y -50.0

// Target heading (in degrees)
#define TARGET_HEADING 90.0

// GPIO pin for LED control
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float headings[BUFFER_SIZE];
    int headings_index;
    int buffer_count;
} CircularBuffer;

CircularBuffer heading_buffer;

// Function prototypes
int init_i2c();
int configure_hmc5883l();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float compensate_heading(int16_t x, int16_t y, float hard_iron_x, float hard_iron_y);
void control_led(float compensated_heading);
void add_heading_to_buffer(float heading);
void print_heading_buffer();
void signal_handler(int signal);

// Function to initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to configure the HMC5883L sensor
int configure_hmc5883l() {
    // Set configuration register A (8-average, 15 Hz output rate, normal measurement)
    if (i2cWriteByteData(i2c_handle, CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Failed to write to CONFIG_A\n");
        return -1;
    }

    // Set configuration register B (1.3 Gauss gain)
    if (i2cWriteByteData(i2c_handle, CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Failed to write to CONFIG_B\n");
        return -1;
    }

    // Set mode register (continuous measurement)
    if (i2cWriteByteData(i2c_handle, MODE, 0x00) < 0) {
        fprintf(stderr, "Failed to write to MODE\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to compensate the heading
float compensate_heading(int16_t x, int16_t y, float hard_iron_x, float hard_iron_y) {
    float heading = atan2((float)y - hard_iron_y, (float)x - hard_iron_x) * 180 / M_PI;

    // Normalize to 0-360 degrees
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Function to control the LED based on the heading deviation
void control_led(float compensated_heading) {
    float heading_deviation = fabs(compensated_heading - TARGET_HEADING);

    if (heading_deviation > 10.0) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Function to add a heading to the circular buffer
void add_heading_to_buffer(float heading) {
    heading_buffer.headings[heading_buffer.headings_index] = heading;
    heading_buffer.headings_index = (heading_buffer.headings_index + 1) % BUFFER_SIZE;

    if (heading_buffer.buffer_count < BUFFER_SIZE) {
        heading_buffer.buffer_count++;
    }
}

// Function to print the contents of the circular buffer
void print_heading_buffer() {
    printf("Heading Buffer:\n");
    for (int i = 0; i < heading_buffer.buffer_count; i++) {
        int index = (heading_buffer.headings_index - heading_buffer.buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%d]: %.2f\n", i, heading_buffer.headings[index]);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize circular buffer
    heading_buffer.headings_index = 0;
    heading_buffer.buffer_count = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Configure HMC5883L
    if (configure_hmc5883l() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    int16_t x, y, z;
    float compensated_heading;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Compensate heading
            compensated_heading = compensate_heading(x, y, HARD_IRON_X, HARD_IRON_Y);

            // Control LED
            control_led(compensated_heading);

            // Add heading to buffer
            add_heading_to_buffer(compensated_heading);

            // Print heading (for debugging)
            printf("Heading: %.2f\n", compensated_heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data, retrying...\n");
        }

        // Wait 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

