#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define LOG_FILE "lighting_log.txt"
#define SENSOR_READ_INTERVAL 1 // seconds
#define LUX_THRESHOLD_LOW 50
#define LUX_THRESHOLD_MED 150
#define LUX_THRESHOLD_HIGH 300

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
int control_relays(float lux);
int log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    unsigned char config_cmd = 0x10;
    if (write(i2c_fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    unsigned char data[2];
    int retries = 3;

    while (retries > 0) {
        if (read(i2c_fd, data, 2) == 2) {
            unsigned int raw_value = (data[0] << 8) | data[1];
            *lux = (float)raw_value / 1.2;
            return 0; // Success
        } else {
            perror("Error reading from I2C device");
            retries--;
            usleep(100000); // Wait 100ms before retrying
        }
    }

    fprintf(stderr, "Failed to read BH1750 after multiple retries.\n");
    return -1; // Failure
}

// Control relays based on lux value
int control_relays(float lux) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux < LUX_THRESHOLD_LOW) {
        red_state = 1;
    } else if (lux < LUX_THRESHOLD_MED) {
        green_state = 1;
    } else if (lux < LUX_THRESHOLD_HIGH) {
        blue_state = 1;
    } else {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    if (gpiod_line_set_value(red_line, red_state) < 0) {
        perror("Error setting RED relay state");
        return -1;
    }
    if (gpiod_line_set_value(green_line, green_state) < 0) {
        perror("Error setting GREEN relay state");
        return -1;
    }
    if (gpiod_line_set_value(blue_line, blue_state) < 0) {
        perror("Error setting BLUE relay state");
        return -1;
    }

    return 0;
}

// Log data to file
int log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f, %d, %d, %d\n", timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (red_line != NULL) {
        gpiod_line_release(red_line);
    }
    if (green_line != NULL) {
        gpiod_line_release(green_line);
    }
    if (blue_line != NULL) {
        gpiod_line_release(blue_line);
    }

    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    // Get GPIO lines
    red_line = gpiod_chip_get_line(gpio_chip, RED_GPIO);
    green_line = gpiod_chip_get_line(gpio_chip, GREEN_GPIO);
    blue_line = gpiod_chip_get_line(gpio_chip, BLUE_GPIO);

    if (!red_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    // Request GPIO lines as outputs
    if (gpiod_line_request_output(red_line, "red_relay", 0) < 0) {
        perror("Error requesting RED relay GPIO as output");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(green_line, "green_relay", 0) < 0) {
        perror("Error requesting GREEN relay GPIO as output");
        cleanup();
        return 1;
    }
