#define SERVO_ANGLE_TO_PULSE_WIDTH(angle) ((int)(((float)(angle) / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH))

