int init_i2c();
int init_mpu6050();
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
float calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z);
float calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z);
int set_servo_angle(int angle);
int log_data(float pitch, float roll, int servo_angle);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2c_smbus_write_byte_data(i2c_fd, PWR_MGMT_1, 0) < 0) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }

    return 0;
}

// Read raw accelerometer and gyroscope data from MPU-6050
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[14];
    if (read(i2c_fd, buf, 14) != 14) {
        perror("Error reading MPU-6050 data");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gyro_x  = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y  = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z  = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

// Calculate pitch angle from accelerometer data
float calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    float pitch = atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180 / M_PI;
    return pitch;
}

// Calculate roll angle from accelerometer data
float calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    float roll = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
    return roll;
}

