        while (retries < 3 && !read_success) {
            if (read_mpu6050_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
                read_success = 1;
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/3)...\n", retries + 1);
                retries++;
                usleep(delay_ms * 1000); // Exponential backoff
                delay_ms *= 2;
            }
        }

