            fprintf(stderr, "Failed to read sensor data after multiple retries. Skipping.\n");
            usleep(100000); // Wait 100ms before next attempt
            continue;
        }

        // Calculate pitch and roll
        pitch = calculate_pitch(accel_x, accel_y, accel_z);
        roll = calculate_roll(accel_x, accel_y, accel_z);

        // Map pitch to servo angle (0-180 degrees)
        servo_angle = (int)((pitch + 90) / 180.0 * 180.0); // Map pitch to 0-180 degrees

        // Clamp servo angle to valid range
        if (servo_angle < SERVO_MIN_ANGLE) {
            servo_angle = SERVO_MIN_ANGLE;
        } else if (servo_angle > SERVO_MAX_ANGLE) {
            servo_angle = SERVO_MAX_ANGLE;
        }

