            fprintf(stderr, "Failed to log data. Skipping.\n");
        }

        // Print data to console
        printf("Pitch: %.2f, Roll: %.2f, Servo Angle: %d\n", pitch, roll, servo_angle);

        // Wait for 100ms
        usleep(100000);
    }

    // Cleanup
    printf("Cleaning up...\n");

