#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency and range
#define PWM_FREQUENCY 100
#define PWM_RANGE 100

// Define sunrise and sunset times
#define SUNRISE_TIME "06:00:00"
#define SUNSET_TIME "18:00:00"

// Define fade duration (in seconds)
#define FADE_DURATION 1800

// Global variables
FILE *schedule_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int read_schedule(const char *filename, char schedule[24][20]);
void set_relay_state(int pin, int state);
void fade_in(int pin, int duration);
void fade_out(int pin, int duration);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the lighting schedule from a file
int read_schedule(const char *filename, char schedule[24][20]) {
    schedule_file = fopen(filename, "r");
    if (schedule_file == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    for (int i = 0; i < 24; i++) {
        if (fscanf(schedule_file, "%s", schedule[i]) != 1) {
            fprintf(stderr, "Error reading schedule entry %d\n", i);
            fclose(schedule_file);
            return -1;
        }
    }

    fclose(schedule_file);
    return 0;
}

// Function to set the state of a relay
void set_relay_state(int pin, int state) {
