#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 30.0      // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define TIMEOUT_US 50000      // 50ms timeout

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long pulseIn(int gpio, int level, uint32_t timeout);
float calculateDistance(long pulseWidth);
float mapDistanceToFrequency(float distance);
void setBuzzerFrequency(float frequency);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Stop the buzzer
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width with timeout
long pulseIn(int gpio, int level, uint32_t timeout) {
    uint32_t start = 0, end = 0;

    // Wait for the pulse to start
    while (gpioRead(gpio) != level) {
        if (gpioTick() - start > timeout) {
            return -1; // Timeout
        }
    }
    start = gpioTick();

    // Wait for the pulse to end
    while (gpioRead(gpio) == level) {
        if (gpioTick() - start > timeout) {
            return -1; // Timeout
        }
    }
    end = gpioTick();

    return end - start;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) {
        return -1.0; // Indicate error
    }
    return (pulseWidth * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map the distance to a frequency
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the buzzer frequency
void setBuzzerFrequency(float frequency) {
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }
    int dutyCycle = (int)((frequency / MAX_FREQUENCY) * 1000000); // pigpio duty cycle is 0-1000000
    gpioPWM(BUZZER_PIN, dutyCycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (0-1000000 for 0-100% duty cycle)
    gpioSetPWMrange(BUZZER_PIN, 1000000);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulseWidth = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

        if (pulseWidth > 0) {
            float distance = calculateDistance(pulseWidth);
            if (distance > 0) {
                float frequency = mapDistanceToFrequency(distance);
                setBuzzerFrequency(frequency);
                printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
            } else {
                fprintf(stderr, "Error: Invalid distance reading\n");
            }
        } else {
            fprintf(stderr, "Error: No echo received\n");
        }

        gpioDelay(20); // Delay for 20ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();

    return 0;
}

