#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the color of the RGB LED using PWM
void set_led_color(int red, int green, int blue) {
    // Invert the color values (common anode)
    red   = PWM_RANGE - red;
    green = PWM_RANGE - green;
    blue  = PWM_RANGE - blue;

    // Set PWM duty cycles for each color
    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

// Function to generate a sine wave-like proximity value
float generate_proximity_value() {
    // Generate a sine wave over time
    float time = time_time();
    float value = sin(time * 2 * M_PI); // Sine wave with period 2*pi

    // Scale the sine wave to the range 0.0 to 1.0
    return value * 0.5 + 0.5; // Scale to 0.5-1.5 and shift to 0.0-1.0
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Set PWM frequency for each color
    gpioSetPWMfrequency(RED_PIN,   PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQUENCY);

    // Set PWM range for each color
    gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Generate proximity value
        float proximity = generate_proximity_value();

        // Map proximity value to RGB color values
        int red   = (int)(proximity * 255.0);
        int green = (int)((1.0 - proximity) * 255.0);
        int blue  = 0; // Blue is always off

        // Set the LED color
        set_led_color(red, green, blue);

        // Delay for a short period
        gpioDelay(10000); // 10ms
    }

    // Turn off the LED before exiting
    set_led_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

