#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody notes (frequencies in Hz)
#define NOTE_C4 262
#define NOTE_D4 294
#define NOTE_E4 330
#define NOTE_F4 349
#define NOTE_G4 392
#define NOTE_A4 440
#define NOTE_B4 494
#define NOTE_C5 523

// Define melody duration (in milliseconds)
#define NOTE_DURATION 250

// Debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Global variables
volatile int melody_playing = 0;
volatile unsigned long last_interrupt_time = 0;

// Function prototypes
void button_interrupt_handler(int gpio, int level, unsigned int tick, void *user_data);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Lookup table for melody notes
const int melody[] = {NOTE_C4, NOTE_D4, NOTE_E4, NOTE_F4, NOTE_G4, NOTE_A4, NOTE_B4, NOTE_C5};
const int melody_length = sizeof(melody) / sizeof(melody[0]);

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-up resistor on button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency for buzzer pin
    gpioSetPWMfrequency(BUZZER_PIN, 440); // 440 Hz
    gpioSetPWMrange(BUZZER_PIN, 1000);   // 1 kHz PWM range

    // Set up interrupt handler for button pin
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (melody_playing) {
            // Check if the melody has finished playing
            if (gpioRead(BUTTON_PIN) == 0) { // Button is pressed
                stop_melody();
                melody_playing = 0;
            }
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

// Interrupt handler function
void button_interrupt_handler(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();

    // Debounce the button
    if (current_time - last_interrupt_time > DEBOUNCE_TIME * 1000) {
        if (level == 0) { // Button pressed (active-low)
            if (!melody_playing) {
                play_melody();
                melody_playing = 1;
            }
        }
        last_interrupt_time = current_time;
    }
}

// Function to play the melody
void play_melody() {
    printf("Playing melody...\n");
    for (int i = 0; i < melody_length; i++) {
        gpioHardwarePWM(BUZZER_PIN, 500, 1000); // 50% duty cycle
        gpioDelay(NOTE_DURATION * 1000); // Delay for note duration
        gpioHardwarePWM(BUZZER_PIN, 0, 0);   // Stop the tone
        gpioDelay(50 * 1000); // Short pause between notes
    }
    printf("Melody finished.\n");
}

// Function to stop the melody
void stop_melody() {
    printf("Stopping melody...\n");
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop the tone
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, stopping...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

