#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "vibration_events.log"
#define SLIDING_WINDOW_SIZE 5

// Structure to hold the last 5 events
typedef struct {
    int events[SLIDING_WINDOW_SIZE];
    int head;
    int count;
} SlidingWindow;

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;
static SlidingWindow sliding_window;

// Function prototypes
int initialize_gpio(void);
int read_sensor(void);
void log_event(int value);
void simulate_earthquake(void);
void cleanup(void);
void signal_handler(int sig);
void sliding_window_init(SlidingWindow *window);
void sliding_window_add(SlidingWindow *window, int value);
int sliding_window_check(SlidingWindow *window);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Initialize the GPIO chip and line
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "vibration_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read the sensor value
int read_sensor(void) {
    int value = gpiod_line_event_read(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Log the event to the file
void log_event(int value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return;
        }
    }

    fprintf(log_file, "%s,%d\n", timestamp, value);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Simulate earthquake alert
void simulate_earthquake(void) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    printf("EARTHQUAKE ALERT: %s\n", timestamp);
}

// Initialize the sliding window
void sliding_window_init(SlidingWindow *window) {
    window->head = 0;
    window->count = 0;
    memset(window->events, 0, sizeof(window->events));
}

// Add a new event to the sliding window
void sliding_window_add(SlidingWindow *window, int value) {
    window->events[window->head] = value;
    window->head = (window->head + 1) % SLIDING_WINDOW_SIZE;
    if (window->count < SLIDING_WINDOW_SIZE) {
        window->count++;
    }
}

// Check if the sliding window contains 3 or more HIGH events
int sliding_window_check(SlidingWindow *window) {
    int high_count = 0;
    for (int i = 0; i < window->count; i++) {
        if (window->events[i] == 1) {
            high_count++;
        }
    }
    return (high_count >= 3);
}

// Cleanup resources before exiting
void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int poll_timeout_ms = 1000; // Default timeout

    // Parse command-line argument for poll timeout
    if (argc > 1) {
        poll_timeout_ms = atoi(argv[1]);
        if (poll_timeout_ms <= 0) {
            fprintf(stderr, "Invalid poll timeout. Using default value (1000 ms).\n");
            poll_timeout_ms = 1000;
        }
    }

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Initialize sliding window
    sliding_window_init(&sliding_window);

    fprintf(stderr, "Vibration sensor monitoring started. Polling timeout: %d ms\n", poll_timeout_ms);

    // Main loop
    while (!terminate) {
        int value = read_sensor();
        if (value < 0) {
            break; // Exit loop on read error
        }

        log_event(value);

        sliding_window_add(&sliding_window, value);

        if (sliding_window_check(&sliding_window)) {
            simulate_earthquake();
        }

        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = poll_timeout_ms * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&ts, NULL);
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Vibration sensor monitoring stopped.\n");
    return 0;
}

