#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC magnetometer registers
#define MR_REG_M 0x02
#define CRA_REG_M 0x00
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Hard-iron calibration offsets
#define X_OFFSET 10.0
#define Y_OFFSET -5.0
#define Z_OFFSET 20.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int init_i2c();
int configure_magnetometer();
magnetometer_data_t read_magnetometer_data();
float calibrate_magnetometer_data(magnetometer_data_t raw_data);
float calculate_heading(float x, float y);
char* get_compass_direction(float heading);
int log_data(float x, float y, float z, float heading);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the LSM303DLHC magnetometer
int configure_magnetometer() {
    // Continuous conversion mode, 15 Hz ODR
    if (i2cWriteByteData(i2c_handle, CRA_REG_M, 0x14) < 0) {
        fprintf(stderr, "Failed to write to CRA_REG_M\n");
        return -1;
    }

    // Set magnetometer to +/- 4 gauss full scale
    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to MR_REG_M\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return 0s on error
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Calibrate magnetometer data
float calibrate_magnetometer_data(magnetometer_data_t raw_data) {
    return (float)(raw_data.x - X_OFFSET) + (float)(raw_data.y - Y_OFFSET) + (float)(raw_data.z - Z_OFFSET);
}

// Calculate compass heading
float calculate_heading(float x, float y) {
    float heading = atan2f(y, x) * 180 / M_PI;

    // Normalize to 0-360 degrees
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Get compass direction
char* get_compass_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) {
        return "N";
    } else if (heading >= 22.5 && heading < 45.0) {
        return "NE";
    } else if (heading >= 45.0 && heading < 67.5) {
        return "E";
    } else if (heading >= 67.5 && heading < 90.0) {
        return "SE";
    } else if (heading >= 90.0 && heading < 112.5) {
        return "S";
    } else if (heading >= 112.5 && heading < 135.0) {
        return "SW";
    } else if (heading >= 135.0 && heading < 157.5) {
        return "W";
    } else {
        return "NW";
    }
}

// Log data to CSV file
int log_data(float x, float y, float z, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%s\n", timestamp, x, y, z, heading, get_compass_direction(heading));
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Configure magnetometer
    if (configure_magnetometer() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t raw_data = read_magnetometer_data();

        // Calibrate magnetometer data
        float calibrated_data = calibrate_magnetometer_data(raw_data);

        // Calculate heading
        float heading = calculate_heading(calibrated_data, calibrated_data);

        // Log data
        log_data(calibrated_data, calibrated_data, calibrated_data, heading);

        // Print heading to console
        printf("Heading: %.2f degrees, Direction: %s\n", heading, get_compass_direction(heading));

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C device and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

