#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void touch_callback(int gpio, int level, unsigned int tick);
int log_relay_state(int state);
void signal_handler(int signal);

// Structure to hold relay state and timestamp
typedef struct {
    int state;
    char timestamp[32];
} RelayState;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN); // Use pull-down resistor

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially OFF

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate();
}

// Callback function for touch sensor
void touch_callback(int gpio, int level, unsigned int tick) {
    if (level == 0) { // Touch detected (LOW signal)
        unsigned long current_time = gpioTick();

        // Debounce
        if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) { // Convert ms to us
            last_touch_time = current_time;

            // Toggle relay state
            relay_state = !relay_state;
            gpioWrite(RELAY_PIN, relay_state);

            // Log relay state
            if (log_relay_state(relay_state) != 0) {
                fprintf(stderr, "Error logging relay state\n");
            }
        }
    }
}

// Function to log relay state to JSON file
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("relay_log.json", "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return 1;
        }
        fprintf(log_file, "[\n"); // Start JSON array
    } else {
        fprintf(log_file, ",\n"); // Add comma for new entry
    }

    fprintf(log_file, "  {\n");
    fprintf(log_file, "    \"timestamp\": \"%s\",\n", timestamp);
    fprintf(log_file, "    \"relay_state\": \"%s\"\n", state ? "ON" : "OFF");
    fprintf(log_file, "  }\n");

    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    if (log_file != NULL) {
        fprintf(log_file, "]\n"); // End JSON array
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up interrupt callback for touch sensor
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        cleanup_gpio();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Keep the program running
    while (1) {
        sleep(1); // Reduce CPU usage
    }

    return 0;
}

