    fprintf(log_file, "  }\n");

    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    if (log_file != NULL) {
        fprintf(log_file, "]\n"); // End JSON array
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up interrupt callback for touch sensor
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        cleanup_gpio();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Keep the program running
    while (1) {
        sleep(1); // Reduce CPU usage
    }

    return 0;
}

