#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the moisture threshold
#define MOISTURE_THRESHOLD 30

// Define the server IP address and port
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int socket_desc;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void log_event(int relay_number, int moisture_level);
void send_data_to_server(int moisture_level);
void signal_handler(int signal);
void cleanup();

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set all relays to OFF initially
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0;
}

// Function to read the soil moisture sensor value
int read_moisture_sensor() {
    // Simulate a soil moisture reading between 0 and 100
    return rand() % 101;
}

// Function to activate a relay
void activate_relay(int relay_number) {
    int pin;

    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    gpioWrite(pin, 0); // Activate the relay (drive the line LOW)
    printf("Relay %d activated\n", relay_number);
}

// Function to deactivate a relay
void deactivate_relay(int relay_number) {
    int pin;

    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    gpioWrite(pin, 1); // Deactivate the relay (drive the line HIGH)
    printf("Relay %d deactivated\n", relay_number);
}

// Function to log an event to the log file
void log_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Relay %d, Moisture Level: %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file); // Ensure the data is written to the file immediately
}

// Function to send data to the server
void send_data_to_server(int moisture_level) {
    char message[50];
    struct sockaddr_in server_addr;

    // Create socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc == -1) {
        perror("Could not create socket");
        return;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(socket_desc);
        return;
    }

    // Connect to server
    if (connect(socket_desc, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        close(socket_desc);
        return;
    }

    // Format the message
    snprintf(message, sizeof(message), "Moisture Level: %d", moisture_level);

    // Send the message
    if (send(socket_desc, message, strlen(message), 0) < 0) {
        perror("Send failed");
    }

    close(socket_desc);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to deactivate all relays and close the log file
void cleanup() {
    // Deactivate all relays
    deactivate_relay(1);
    deactivate_relay(2);
    deactivate_relay(3);
    deactivate_relay(4);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close the socket
    if (socket_desc > 0) {
        close(socket_desc);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read the moisture sensor value
        int moisture_level = read_moisture_sensor();

        // Log the event
        log_event(1, moisture_level);
        log_event(2, moisture_level);
        log_event(3, moisture_level);
        log_event(4, moisture_level);

        // Send data to the server
        send_data_to_server(moisture_level);

        // Check if the moisture level is below the threshold
        if (moisture_level < MOISTURE_THRESHOLD) {
            // Activate relays sequentially
            activate_relay(1);
            sleep(5);
            deactivate_relay(1);

            activate_relay(2);
            sleep(5);
            deactivate_relay(2);

            activate_relay(3);
            sleep(5);
            deactivate_relay(3);

            activate_relay(4);
            sleep(5);
            deactivate_relay(4);
        }

        // Wait for 10 seconds
        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

