#define STEPS_PER_REVOLUTION 2048

// Define delay between steps (in milliseconds)
#define STEP_DELAY 3

// Define lock and unlock angles (in steps)
#define LOCK_ANGLE 512
#define UNLOCK_ANGLE 1536

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
void step_motor(int step);
void lock_door();
void unlock_door();
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioTerminate();
    exit(0);
}

// Function to step the motor
void step_motor(int step) {
    int in1, in2, in3, in4;

    switch (step) {
        case 0:
            in1 = 1; in2 = 0; in3 = 0; in4 = 0; break;
        case 1:
            in1 = 0; in2 = 1; in3 = 0; in4 = 0; break;
        case 2:
            in1 = 0; in2 = 0; in3 = 1; in4 = 0; break;
        case 3:
            in1 = 0; in2 = 0; in3 = 0; in4 = 1; break;
        default:
