            return;
    }

    gpioWrite(IN1, in1);
    gpioWrite(IN2, in2);
    gpioWrite(IN3, in3);
    gpioWrite(IN4, in4);
    gpioDelay(STEP_DELAY * 1000); // Delay in microseconds
}

// Function to lock the door
void lock_door() {
    printf("Locking door...\n");
    for (int i = 0; i < LOCK_ANGLE; i++) {
        step_motor(i % 4);
