    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    printf("Door lock system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for lock button press
        if (gpioRead(LOCK_BUTTON) == 0) {
            lock_door();
            gpioDelay(500 * 1000); // Debounce delay
        }

        // Check for unlock button press
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            unlock_door();
            gpioDelay(500 * 1000); // Debounce delay
        }

        gpioDelay(100 * 1000); // Small delay to prevent busy-waiting
    }

    // Cleanup and exit (should not reach here if signal handler works correctly)
    cleanup(0);

    return 0;
