#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MODE 0x0080
#define VL53L1X_REG_START_STOP_CONTROL 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD1 0x0097

// GPIO pin for relay control
#define RELAY_GPIO 18

// Distance threshold in centimeters
#define DISTANCE_THRESHOLD 50

// I2C handle
int i2c_handle;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void control_relay(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Set relay LOW
    gpioTerminate();
    exit(0);
}

// Initialize the VL53L1X sensor
int vl53l1x_init() {
    // Software reset
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write to register 0x0000 for reset.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Set ranging mode to short-range
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write to register 0x0080 for ranging mode.\n");
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_START_STOP_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write to register 0x0080 for start/stop control.\n");
        return -1;
    }

    return 0;
}

// Read the distance from the VL53L1X sensor
int vl53l1x_read_distance(int *distance) {
    int msb, lsb;

    // Read MSB
    msb = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (msb < 0) {
        fprintf(stderr, "Error: Failed to read MSB from register 0x0096.\n");
        return -1;
    }

    // Read LSB
    lsb = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD1);
    if (lsb < 0) {
        fprintf(stderr, "Error: Failed to read LSB from register 0x0097.\n");
        return -1;
    }

    // Combine MSB and LSB to form the distance
    *distance = (msb << 8) | lsb;

    return 0;
}

// Control the relay based on the distance
void control_relay(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(RELAY_GPIO, 1); // Set relay HIGH
    } else {
        gpioWrite(RELAY_GPIO, 0); // Set relay LOW
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int distance;

    // Main loop
    while (1) {
        // Read distance from VL53L1X
        if (vl53l1x_read_distance(&distance) == 0) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log distance to console
            printf("[%s] Distance: %d mm\n", timestamp, distance);

            // Control relay
            control_relay(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

