#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor for +/- 250 dps range
#define GYRO_SCALE 131.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set gyroscope full-scale range to ±250 dps
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope full-scale range\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to convert raw gyroscope data to degrees/second
void convert_to_dps(gyro_data_t *data) {
    data->x = (int16_t)((float)data->x / GYRO_SCALE);
    data->y = (int16_t)((float)data->y / GYRO_SCALE);
    data->z = (int16_t)((float)data->z / GYRO_SCALE);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    gyro_data_t gyro_data;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 milliseconds

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Convert to degrees/second
            convert_to_dps(&gyro_data);

            // Get current timestamp
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);

            // Log data to console
            printf("%ld.%09ld, X: %d dps, Y: %d dps, Z: %d dps\n", ts.tv_sec, ts.tv_nsec, gyro_data.x, gyro_data.y, gyro_data.z);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data. Retrying...\n");
        }

        // Sleep for 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

