#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the log file name
#define LOG_FILE "watering_log.txt"

// Define the server IP address and port
#define SERVER_IP "127.0.0.1" // Replace with your server's IP address
#define SERVER_PORT 12345

// Define the watering duration (seconds)
#define WATERING_DURATION 5

// Define the watering interval (seconds)
#define WATERING_INTERVAL 86400 // 24 hours

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay1_line = NULL;
static struct gpiod_line *relay2_line = NULL;
static struct gpiod_line *relay3_line = NULL;
static struct gpiod_line *relay4_line = NULL;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
int initialize_gpio();
int activate_relay(int pin);
int deactivate_relay(int pin);
int log_watering_cycle(int relay_number);
int send_watering_status(int relay_number, int status);
void signal_handler(int signal);
void cleanup();

// Function to initialize the GPIO chip and lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    if (!relay1_line) {
        perror("Error getting GPIO line for relay 1");
        gpiod_chip_close(chip);
        return -1;
    }

    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    if (!relay2_line) {
        perror("Error getting GPIO line for relay 2");
        gpiod_chip_close(chip);
        gpiod_line_release(relay1_line);
        return -1;
    }

    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    if (!relay3_line) {
        perror("Error getting GPIO line for relay 3");
        gpiod_chip_close(chip);
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        return -1;
    }

    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);
    if (!relay4_line) {
        perror("Error getting GPIO line for relay 4");
        gpiod_chip_close(chip);
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        return -1;
    }

    // Set the direction of each line to output
    if (gpiod_line_request_output(relay1_line, "watering", 0) < 0) {
        perror("Error requesting output for relay 1");
        gpiod_chip_close(chip);
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        gpiod_line_release(relay4_line);
        return -1;
    }

    if (gpiod_line_request_output(relay2_line, "watering", 0) < 0) {
        perror("Error requesting output for relay 2");
        gpiod_chip_close(chip);
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        gpiod_line_release(relay4_line);
        return -1;
    }

    if (gpiod_line_request_output(relay3_line, "watering", 0) < 0) {
        perror("Error requesting output for relay 3");
        gpiod_chip_close(chip);
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        gpiod_line_release(relay4_line);
        return -1;
    }

    if (gpiod_line_request_output(relay4_line, "watering", 0) < 0) {
        perror("Error requesting output for relay 4");
        gpiod_chip_close(chip);
        gpiod_line_release(relay1_line);
        gpiod_line_release(relay2_line);
        gpiod_line_release(relay3_line);
        gpiod_line_release(relay4_line);
        return -1;
    }

    return 0;
}

// Function to activate a relay
int activate_relay(int pin) {
    struct gpiod_line *line = NULL;

    switch (pin) {
        case RELAY1_PIN:
            line = relay1_line;
            break;
        case RELAY2_PIN:
            line = relay2_line;
            break;
        case RELAY3_PIN:
            line = relay3_line;
            break;
        case RELAY4_PIN:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay pin: %d\n", pin);
            return -1;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting value for relay");
        return -1;
    }

    return 0;
}

// Function to deactivate a relay
int deactivate_relay(int pin) {
    struct gpiod_line *line = NULL;

    switch (pin) {
        case RELAY1_PIN:
            line = relay1_line;
            break;
        case RELAY2_PIN:
            line = relay2_line;
            break;
        case RELAY3_PIN:
            line = relay3_line;
            break;
        case RELAY4_PIN:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay pin: %d\n", pin);
            return -1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting value for relay");
        return -1;
    }

    return 0;
}

// Function to log a watering cycle to the log file
int log_watering_cycle(int relay_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Relay %d activated\n", timestamp, relay_number);
    fflush(log_file); // Ensure the log is written immediately

    return 0;
}

// Function to send watering status to the server
int send_watering_status(int relay_number, int status) {
    int sockfd;
    struct sockaddr_in servaddr;
    char message[100];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    snprintf(message, sizeof(message), "Relay %d: %s", relay_number, status ? "ON" : "OFF");
    if (sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Error sending message");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Deactivate all relays
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Release GPIO lines
    gpiod_line_release(relay1_line);
    gpiod_line_release(relay2_line);
    gpiod_line_release(relay3_line);
    gpiod_line_release(relay4_line);

    // Close the log file
    if (log_file) {
        fclose(log_file);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Activate relay 1
        if (activate_relay(RELAY1_PIN) < 0) {
            fprintf(stderr, "Error activating relay 1. Continuing...\n");
        } else {
            log_watering_cycle(1);
            send_watering_status(1, 1);
            sleep(WATERING_DURATION);
            deactivate_relay(RELAY1_PIN);
            send_watering_status(1, 0);
        }

        // Activate relay 2
        if (activate_relay(RELAY2_PIN) < 0) {
            fprintf(stderr, "Error activating relay 2. Continuing...\n");
        } else {
            log_watering_cycle(2);
            send_watering_status(2, 1);
            sleep(WATERING_DURATION);
            deactivate_relay(RELAY2_PIN);
            send_watering_status(2, 0);
        }

        // Activate relay 3
        if (activate_relay(RELAY3_PIN) < 0) {
            fprintf(stderr, "Error activating relay 3. Continuing...\n");
        } else {
            log_watering_cycle(3);
            send_watering_status(3, 1);
            sleep(WATERING_DURATION);
            deactivate_relay(RELAY3_PIN);
            send_watering_status(3, 0);
        }

        // Activate relay 4
        if (activate_relay(RELAY4_PIN) < 0) {
            fprintf(stderr, "Error activating relay 4. Continuing...\n");
        } else {
            log_watering_cycle(4);
            send_watering_status(4, 1);
            sleep(WATERING_DURATION);
            deactivate_relay(RELAY4_PIN);
            send_watering_status(4, 0);
        }

        sleep(WATERING_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

