#define PWM_FREQUENCY 1000

// Define sunrise duration (30 minutes)
#define SUNRISE_DURATION 1800 // seconds

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void sunrise_effect();
