    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    return 0; // Indicate success
}

// Function to simulate sunrise effect
void sunrise_effect() {
    time_t start_time = time(NULL);
    time_t current_time;
    int duty_cycle;

    while (program_running && (current_time = time(NULL)) - start_time < SUNRISE_DURATION) {
        // Calculate duty cycle based on elapsed time
        duty_cycle = (int)(((current_time - start_time) % SUNRISE_DURATION) * 255.0 / SUNRISE_DURATION);

        // Set PWM duty cycles for each relay
        gpioPWM(RELAY1_PIN, duty_cycle);
        gpioPWM(RELAY2_PIN, duty_cycle);
        gpioPWM(RELAY3_PIN, duty_cycle);
        gpioPWM(RELAY4_PIN, duty_cycle);

