        fprintf(log_file, "%s - Sunrise effect: All relays turned off\n", buf);
        fclose(log_file);
    } else {
        fprintf(stderr, "Error opening log file!\n");
    }
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioPWM(RELAY1_PIN, 0);
    gpioPWM(RELAY2_PIN, 0);
    gpioPWM(RELAY3_PIN, 0);
    gpioPWM(RELAY4_PIN, 0);
    gpioTerminate();
}

int main() {
