    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Run sunrise effect
    sunrise_effect();

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

