#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

// GPIO pin for LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to store gyroscope data
typedef struct {
    double timestamp;
    double x;
    double y;
    double z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int init_mpu6050();
int read_gyro_data(double *x, double *y, double *z);
void process_gyro_data(double x, double y, double z, double *x_rate, double *y_rate, double *z_rate);
void add_to_buffer(double timestamp, double x, double y, double z);
void check_threshold(double x_rate, double y_rate, double z_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    exit(0);
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set sample rate divider
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Set gyroscope full-scale range
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope full-scale range\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(double *x, double *y, double *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes, convert to degrees/second
    int16_t raw_x = (buffer[0] << 8) | buffer[1];
    int16_t raw_y = (buffer[2] << 8) | buffer[3];
    int16_t raw_z = (buffer[4] << 8) | buffer[5];

    *x = (double)raw_x / 131.0;
    *y = (double)raw_y / 131.0;
    *z = (double)raw_z / 131.0;

    return 0;
}

// Process gyroscope data (convert to degrees/second)
void process_gyro_data(double x, double y, double z, double *x_rate, double *y_rate, double *z_rate) {
    *x_rate = x;
    *y_rate = y;
    *z_rate = z;
}

// Add data to circular buffer
void add_to_buffer(double timestamp, double x, double y, double z) {
    gyro_buffer[buffer_index].timestamp = timestamp;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check if any axis exceeds the threshold
void check_threshold(double x_rate, double y_rate, double z_rate) {
    if (fabs(x_rate) > 250.0 || fabs(y_rate) > 250.0 || fabs(z_rate) > 250.0) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C connection\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    double x, y, z, x_rate, y_rate, z_rate;
    struct timespec ts;
    double timestamp;

    while (1) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Process gyroscope data
            process_gyro_data(x, y, z, &x_rate, &y_rate, &z_rate);

            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
            } else {
                fprintf(stderr, "Error: Could not get timestamp\n");
                timestamp = 0.0; // Use 0.0 as a default value
            }

            // Add data to circular buffer
            add_to_buffer(timestamp, x, y, z);

            // Check threshold
            check_threshold(x_rate, y_rate, z_rate);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data, retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C connection\n");
                // Exit if re-initialization fails after multiple attempts
                gpioTerminate();
                return 1;
            }
            if (init_mpu6050() < 0) {
                fprintf(stderr, "Error: Could not re-initialize MPU-6050\n");
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }
        }

        // Delay for 50 ms (20 Hz)
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

