    *y = (double)raw_y / 131.0;
    *z = (double)raw_z / 131.0;

    return 0;
}

// Process gyroscope data (convert to degrees/second)
void process_gyro_data(double x, double y, double z, double *x_rate, double *y_rate, double *z_rate) {
    *x_rate = x;
    *y_rate = y;
    *z_rate = z;
}

// Add data to circular buffer
void add_to_buffer(double timestamp, double x, double y, double z) {
    gyro_buffer[buffer_index].timestamp = timestamp;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check if any axis exceeds the threshold
void check_threshold(double x_rate, double y_rate, double z_rate) {
    if (fabs(x_rate) > 250.0 || fabs(y_rate) > 250.0 || fabs(z_rate) > 250.0) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C connection\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    double x, y, z, x_rate, y_rate, z_rate;
    struct timespec ts;
    double timestamp;

    while (1) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Process gyroscope data
            process_gyro_data(x, y, z, &x_rate, &y_rate, &z_rate);

            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
            } else {
                fprintf(stderr, "Error: Could not get timestamp\n");
                timestamp = 0.0; // Use 0.0 as a default value
            }

            // Add data to circular buffer
            add_to_buffer(timestamp, x, y, z);

            // Check threshold
            check_threshold(x_rate, y_rate, z_rate);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data, retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C connection\n");
                // Exit if re-initialization fails after multiple attempts
                gpioTerminate();
                return 1;
            }
            if (init_mpu6050() < 0) {
                fprintf(stderr, "Error: Could not re-initialize MPU-6050\n");
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }
        }

        // Delay for 50 ms (20 Hz)
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

