#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <stdbool.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define GYRO_SCALE_FACTOR 131.0
#define CS_LINE 8
#define LOG_FILE "gyro_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function prototypes
int spi_init(const char *device, int mode, int bits_per_word, int speed);
gyro_data_t read_gyro_data(int fd);
double convert_to_degrees_per_second(int16_t raw_data);
char* get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size);
int log_data(const char *timestamp, double x_rate, double y_rate, double z_rate);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, int mode, int bits_per_word, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_per_word_val = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word_val) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed hz
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) < 0) {
        perror("Error setting max speed hz");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read gyroscope data from MPU-9250
gyro_data_t read_gyro_data(int fd) {
    gyro_data_t data;
    uint8_t tx_buf[6] = {GYRO_XOUT_H, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t rx_buf[6];
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 6,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int retries = 0;
    while (retries < RETRY_COUNT) {
        if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
            perror("Error during SPI transfer");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to us
            continue;
        }

        // Combine high and low bytes for each axis
        data.x = (int16_t)((rx_buf[1] << 8) | rx_buf[0]);
        data.y = (int16_t)((rx_buf[3] << 8) | rx_buf[2]);
        data.z = (int16_t)((rx_buf[5] << 8) | rx_buf[4]);

        return data;
    }

    fprintf(stderr, "Failed to read gyro data after %d retries.\n", RETRY_COUNT);
    data.x = 0; // Return 0 on failure
    data.y = 0;
    data.z = 0;
    return data;
}

// Function to convert raw gyroscope data to degrees per second
double convert_to_degrees_per_second(int16_t raw_data) {
    return (double)raw_data / GYRO_SCALE_FACTOR;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *timeinfo;
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%S", timeinfo);
    snprintf(timestamp_str + strlen(timestamp_str), timestamp_str_size - strlen(timestamp_str), ".%09ldZ", ts.tv_nsec);

    return timestamp_str;
}

// Function to log data to a file
int log_data(const char *timestamp, double x_rate, double y_rate, double z_rate) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_chip != NULL) {
        gpiod_line_release(cs_line);
        gpiod_chip_close(gpio_chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        close(spi_fd);
        return 1;
    }

    // Get CS line
    cs_line = gpiod_chip_get_line(gpio_chip, CS_LINE);
    if (!cs_line) {
        perror("Error getting CS line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Request CS line as output
    if (gpiod_line_request_output(cs_line, "gyro_control", 0) < 0) {
        perror("Error requesting CS line as output");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpiod_line_release(cs_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        gyro_data_t gyro_data = read_gyro_data(spi_fd);

        // Convert to degrees per second
        double x_rate = convert_to_degrees_per_second(gyro_data.x);
        double y_rate = convert_to_degrees_per_second(gyro_data.y);
        double z_rate = convert_to_degrees_per_second(gyro_data.z);

        // Get timestamp
        char timestamp[30];
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log data
        if (log_data(timestamp, x_rate, y_rate, z_rate) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Delay
        usleep(10000); // 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

