#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <stdbool.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 3900000 // 3.9 MHz
#define GYRO_SENSITIVITY 131.0 // LSB/(deg/s)
#define BUFFER_SIZE 64
#define LED_GPIO 17
#define THRESHOLD 200.0
#define BLINK_DURATION_MS 500

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float x;
    float y;
    float z;
} Reading;

Reading circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int spi_init(const char *device, int mode, int bits_per_word, int speed);
int spi_read_register(int fd, uint8_t reg);
int spi_write_register(int fd, uint8_t reg, uint8_t value);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float convert_to_degrees_per_second(int16_t raw_data);
void add_reading(Reading reading);
void print_buffer();
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, int mode, int bits_per_word, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_per_word_val = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word_val) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed hz
    uint32_t speed_hz = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) < 0) {
        perror("Error setting max speed hz");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read register function
int spi_read_register(int fd, uint8_t reg) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    tx_buf[0] = reg | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00;       // Dummy byte for reading

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return rx_buf[1];
}

// SPI write register function
int spi_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write operation
    tx_buf[1] = value;

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read gyroscope data function
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    *x = (int16_t)((spi_read_register(fd, 0x43) << 8) | spi_read_register(fd, 0x44));
