int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading

    // Perform the SPI transfer
    int result = spiXfer(handle, tx_buf, rx_buf, 2);

    if (result != 2) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate failure
    }

    // Extract the data from the response
    *data = rx_buf[1];

    return 0; // Indicate success
}

