    if (spi_read_register(handle, ADXRS290_X_RATE_REG, &x_rate_data) != 0) {
        fprintf(stderr, "Failed to read X-axis rate\n");
        data.x_rate = 0; // Set to 0 to indicate error
    } else {
        data.x_rate = (int16_t)((x_rate_data << 8) | x_rate_data); // Combine high and low bytes
    }

    // Read Y-axis rate
    if (spi_read_register(handle, ADXRS290_Y_RATE_REG, &y_rate_data) != 0) {
