    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Write data to file
    fprintf(fp, "%ld.%09ld,%d,%d\n", timeinfo->tm_sec, ts.tv_nsec, data.x_rate, data.y_rate);
    fflush(fp); // Ensure data is written to disk immediately
}

