    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open data file
    data_file = fopen("gyro_data.csv", "w");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file
    fprintf(data_file, "timestamp,X_rate,Y_rate\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t gyro_data = read_gyro_data(spi_handle);
        log_data(data_file, gyro_data);
        gpioDelay(10000); // 10 ms delay (100 Hz sampling rate)
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(data_file);
    gpioTerminate();

