#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the tilt sensors
#define SENSOR_1_GPIO 23
#define SENSOR_2_GPIO 24

// Define GPIO pin for the alert signal
#define ALERT_GPIO 17

// Define the alert duration in seconds
#define ALERT_DURATION 2

// Define the log file name
#define LOG_FILE "seismic_events.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data);
void trigger_alert();
void log_event();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int gpio;
    int sensor_number;
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs with pull-down resistors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN);

    // Set GPIO pin as output for the alert signal
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Ensure alert is initially LOW

    return 0; // Indicate success
}

// Callback function for sensor events
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data) {
    sensor_data_t *sensor_data = (sensor_data_t *)user_data;
    int sensor_number = sensor_data->sensor_number;

    if (level == 1) { // Rising edge detected
        printf("Sensor %d (GPIO %d) tilted\n", sensor_number, gpio);
        trigger_alert();
        log_event();
    }
}

// Function to trigger the alert
void trigger_alert() {
    gpioWrite(ALERT_GPIO, 1); // Set alert pin HIGH
    gpioDelay(ALERT_DURATION * 1000000); // Delay for ALERT_DURATION seconds
    gpioWrite(ALERT_GPIO, 0); // Set alert pin LOW
}

// Function to log the event to a file
void log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0; // Set the flag to exit the main loop

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Set the alert pin LOW
    gpioWrite(ALERT_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate(); // Clean up pigpio before exiting
        return 1;
    }

    // Register callback functions for each sensor
    sensor_data_t sensor1_data = {SENSOR_1_GPIO, 1};
    sensor_data_t sensor2_data = {SENSOR_2_GPIO, 2};

    gpioSetAlertFuncEx(SENSOR_1_GPIO, sensor_callback, &sensor1_data);
    gpioSetAlertFuncEx(SENSOR_2_GPIO, sensor_callback, &sensor2_data);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gpioDelay(100000); // Sleep for 100 milliseconds to reduce CPU usage
    }

    return 0;
}

