#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0
#define LED_GPIO 17
#define THRESHOLD 20.0
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ) // microseconds

// ADXRS290 Register Addresses
#define RATE_XL 0x02
#define RATE_XH 0x03

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer entry
typedef struct {
    struct timespec timestamp;
    int16_t x_rate;
} circular_buffer_entry_t;

// Circular buffer
circular_buffer_entry_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
int spi_read_register(int handle, uint8_t address, uint8_t *data);
int spi_write_register(int handle, uint8_t address, uint8_t data);
int16_t combine_bytes(uint8_t msb, uint8_t lsb);
float convert_to_degrees_per_second(int16_t raw_rate);
void *data_processing_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Function to read a register from the ADXRS290
int spi_read_register(int handle, uint8_t address, uint8_t *data) {
    char tx_buffer[2];
    char rx_buffer[2];

    tx_buffer[0] = address | 0x80; // Set MSB for read operation
    tx_buffer[1] = 0x00; // Dummy byte for reading data

    if (spiXfer(handle, tx_buffer, rx_buffer, 2) != 2) {
        fprintf(stderr, "Error: SPI read failed\n");
        return -1;
    }

    *data = rx_buffer[1];
    return 0;
}

// Function to write a register to the ADXRS290
int spi_write_register(int handle, uint8_t address, uint8_t data) {
    char tx_buffer[2];

    tx_buffer[0] = address & 0x7F; // Clear MSB for write operation
    tx_buffer[1] = data;

    if (spiXfer(handle, tx_buffer, NULL, 2) != 2) {
        fprintf(stderr, "Error: SPI write failed\n");
        return -1;
    }

    return 0;
}

// Function to combine two bytes into a 16-bit signed integer
int16_t combine_bytes(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 8) | lsb);
}

// Function to convert raw angular rate data to degrees per second
float convert_to_degrees_per_second(int16_t raw_rate) {
    return (float)raw_rate / 200.0;
}

// Data processing thread function
void *data_processing_thread(void *arg) {
    while (!terminate) {
        uint8_t msb, lsb;
        int16_t raw_rate;
        float degrees_per_second;
        struct timespec ts;

        // Read X-axis rate
        if (spi_read_register(spi_handle, RATE_XL, &msb) != 0) {
            fprintf(stderr, "Error reading X-axis rate\n");
            continue;
        }
        if (spi_read_register(spi_handle, RATE_XH, &lsb) != 0) {
            fprintf(stderr, "Error reading X-axis rate (MSB)\n");
            continue;
        }

        raw_rate = combine_bytes(msb, lsb);
        degrees_per_second = convert_to_degrees_per_second(raw_rate);

        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            perror("clock_gettime");
            continue;
        }

        // Store data in circular buffer
        pthread_mutex_lock(&buffer_mutex);
        circular_buffer[buffer_index].timestamp = ts;
        circular_buffer[buffer_index].x_rate = raw_rate;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&buffer_mutex);

        // Check for threshold exceedance
        if (fabs(degrees_per_second) > THRESHOLD) {
            gpioWrite(LED_GPIO, 1); // Turn on LED
        } else {
            gpioWrite(LED_GPIO, 0); // Turn off LED
        }

        usleep(SAMPLE_PERIOD_US); // Sleep for the sample period
    }

    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    pthread_mutex_destroy(&buffer_mutex);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize LED to off
    gpioWrite(LED_GPIO, 0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create data processing thread
    pthread_t data_processing_thread_id;
    if (pthread_create(&data_processing_thread_id, NULL, data_processing_thread, NULL) != 0) {
        perror("pthread_create");
        cleanup();
        return 1;
    }

    // Main loop (keep the program running until a signal is received)
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

    // Wait for data processing thread to finish
    pthread_join(data_processing_thread_id, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

