#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency (100 Hz)
#define PWM_FREQUENCY 100

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the brightness of a lamp using PWM
void set_lamp_brightness(int gpio, int brightness) {
    if (brightness < 0 || brightness > 255) {
        fprintf(stderr, "Error: Brightness value out of range (0-255). Using 0 for off.\n");
        brightness = 0;
    }
    gpioPWM(gpio, brightness);
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio, int duration_seconds) {
    int brightness = 255;
    int steps = 256; // Number of steps for the fade
    int step_delay_ms = (int)(duration_seconds * 1000.0 / steps);

    for (int i = 0; i < steps && program_running; ++i) {
        set_lamp_brightness(gpio, brightness);
        brightness -= (int)(255.0 / steps);
        gpioDelay(step_delay_ms);
    }

    set_lamp_brightness(gpio, 0); // Turn off the lamp after the fade
}

int main(int argc, char *argv[]) {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    printf("Smart Sunset Simulator started. Press Ctrl+C to exit.\n");

    // Validate command-line argument
    if (argc != 2) {
        fprintf(stderr, "Error: Invalid command-line argument. Usage: %s <total_fade_duration_seconds>\n", argv[0]);
        gpioTerminate();
        return 1;
    }

    int total_fade_duration_seconds = atoi(argv[1]);
    if (total_fade_duration_seconds <= 0 || total_fade_duration_seconds > 3600) {
        fprintf(stderr, "Error: Total fade duration must be between 1 and 3600 seconds.\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency for all GPIO pins
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    // Set PWM range for all GPIO pins
    gpioSetPWMrange(LAMP1_GPIO, 255);
    gpioSetPWMrange(LAMP2_GPIO, 255);
    gpioSetPWMrange(LAMP3_GPIO, 255);

    // Main loop to simulate sunset
    while (program_running) {
        // Fade lamp 1
        printf("Fading lamp 1 (GPIO %d)...\n", LAMP1_GPIO);
        fade_lamp(LAMP1_GPIO, total_fade_duration_seconds);
        printf("Lamp 1 fading complete.\n");

        // Fade lamp 2
        printf("Fading lamp 2 (GPIO %d)...\n", LAMP2_GPIO);
        fade_lamp(LAMP2_GPIO, total_fade_duration_seconds);
        printf("Lamp 2 fading complete.\n");

        // Fade lamp 3
        printf("Fading lamp 3 (GPIO %d)...\n", LAMP3_GPIO);
        fade_lamp(LAMP3_GPIO, total_fade_duration_seconds);
        printf("Lamp 3 fading complete.\n");

        // Wait for a short period before the next sunset
        gpioDelay(5000); // 5 seconds
    }

    // Turn off all lamps before exiting
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);

    // Release GPIO resources
    gpioTerminate();

    printf("Smart Sunset Simulator stopped.\n");

    return 0;
}

