    // Red+Yellow
    if (set_relay_state(RED_PIN, 0) != 0) return;
    if (set_relay_state(YELLOW_PIN, 0) != 0) return;
    if (set_relay_state(GREEN_PIN, 1) != 0) return;
    if (set_relay_state(YELLOW_PIN, 1) != 0) return;
    sleep(RED_YELLOW_DURATION);

    // Green
    if (set_relay_state(RED_PIN, 1) != 0) return;
    if (set_relay_state(YELLOW_PIN, 1) != 0) return;
    if (set_relay_state(GREEN_PIN, 0) != 0) return;
    if (set_relay_state(YELLOW_PIN, 0) != 0) return;
    sleep(GREEN_DURATION);

    // Yellow
    if (set_relay_state(RED_PIN, 1) != 0) return;
    if (set_relay_state(YELLOW_PIN, 0) != 0) return;
    if (set_relay_state(GREEN_PIN, 1) != 0) return;
    if (set_relay_state(YELLOW_PIN, 0) != 0) return;
    sleep(YELLOW_DURATION);
}

