#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define DEBOUNCE_DELAY_MS 100
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define CHARGE_TIME 0x0D
#define RUN_MODE 0x0D

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
int configure_mpr121();
int read_touch_status();
void control_relay(int state);
void log_message(const char *message);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int relay_gpio;
    int mpr121_addr;
    int i2c_bus;
    int debounce_delay_ms;
    int touch_threshold;
    int release_threshold;
    int charge_time;
    int run_mode;
} Config;

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially turn the relay off

    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C device");
        return -1;
    }

    return 0;
}

// Function to configure MPR121
int configure_mpr121() {
    // Reset MPR121
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        log_message("Failed to reset MPR121");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x00) < 0) {
        log_message("Failed to set MPR121 to stop mode");
        return -1;
    }
    gpioDelay(10);

    // Enable electrode 0
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) {
        log_message("Failed to enable electrode 0");
        return -1;
    }
    gpioDelay(10);

    // Set touch and release thresholds
    if (i2cWriteByteData(i2c_handle, 0x41, TOUCH_THRESHOLD) < 0) {
        log_message("Failed to set touch threshold");
        return -1;
    }
    gpioDelay(10);

    if (i2cWriteByteData(i2c_handle, 0x42, RELEASE_THRESHOLD) < 0) {
        log_message("Failed to set release threshold");
        return -1;
    }
    gpioDelay(10);

    // Set debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, DEBOUNCE_DELAY_MS) < 0) {
        log_message("Failed to set debounce");
        return -1;
    }
    gpioDelay(10);

    // Set charge time
    if (i2cWriteByteData(i2c_handle, 0x5C, CHARGE_TIME) < 0) {
        log_message("Failed to set charge time");
        return -1;
    }
    gpioDelay(10);

    // Set run mode
    if (i2cWriteByteData(i2c_handle, 0x5E, RUN_MODE) < 0) {
        log_message("Failed to set run mode");
        return -1;
    }
    gpioDelay(10);

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status() {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        log_message("Failed to read touch status");
        return -1;
    }

    return (buf[1] << 8) | buf[0];
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure the message is written to the file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_message("Received signal, shutting down...");
}

int main() {
    // Initialize configuration
    Config config = {
        .relay_gpio = RELAY_GPIO,
        .mpr121_addr = MPR121_ADDR,
        .i2c_bus = I2C_BUS,
        .debounce_delay_ms = DEBOUNCE_DELAY_MS,
        .touch_threshold = TOUCH_THRESHOLD,
        .release_threshold = RELEASE_THRESHOLD,
        .charge_time = CHARGE_TIME,
        .run_mode = RUN_MODE
    };

    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Configure MPR121
    if (configure_mpr121() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    log_message("Touch relay system started");

    // Main loop
    int relay_state = 0; // 0 = off, 1 = on
    int last_touch_status = 0;
    while (program_running) {
        int touch_status = read_touch_status();
        if (touch_status < 0) {
            log_message("Error reading touch status, retrying...");
