#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Define log file path
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int keep_running = 1;
static FILE *log_file = NULL;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
int gpio_write(int pin, int value);
int log_event(const char *message);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal %d, exiting gracefully.\n", sig);
        keep_running = 0;
    }
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to read the value of a GPIO pin
int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return atoi(value_str);
}

// Function to write a value to a GPIO pin
int gpio_write(int pin, int value) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, strlen(value_str)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to log an event to the log file
int log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    int flame_detected = 0;
    int consecutive_readings = 0;
    int current_reading;
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = DEBOUNCE_DELAY * 1000000; // Convert milliseconds to nanoseconds

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Export GPIO pins
    if (gpio_export(FLAME_SENSOR_PIN) < 0 ||
        gpio_export(BUZZER_PIN) < 0 ||
        gpio_export(LED_PIN) < 0) {
        fprintf(stderr, "Error exporting GPIO pins. Exiting.\n");
        fclose(log_file);
        return 1;
    }

    // Set GPIO directions
    if (gpio_set_direction(FLAME_SENSOR_PIN, "in") < 0 ||
        gpio_set_direction(BUZZER_PIN, "out") < 0 ||
        gpio_set_direction(LED_PIN, "out") < 0) {
        fprintf(stderr, "Error setting GPIO directions. Exiting.\n");
        gpio_unexport(FLAME_SENSOR_PIN);
        gpio_unexport(BUZZER_PIN);
        gpio_unexport(LED_PIN);
        fclose(log_file);
        return 1;
    }

    printf("Fire alarm system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        current_reading = gpio_read(FLAME_SENSOR_PIN);
        if (current_reading < 0) {
            fprintf(stderr, "Error reading flame sensor. Retrying.\n");
            nanosleep(&delay, NULL);
            continue;
        }

        if (current_reading == 0) { // Flame detected (LOW signal)
            flame_detected = 1;
            consecutive_readings++;

            if (consecutive_readings >= 3) {
                // Activate buzzer and LED
                if (gpio_write(BUZZER_PIN, 1) < 0 ||
                    gpio_write(LED_PIN, 1) < 0) {
                    fprintf(stderr, "Error activating buzzer or LED. Continuing.\n");
                }

                // Log the event
                if (log_event("Flame Detected") < 0) {
                    fprintf(stderr, "Error logging event. Continuing.\n");
                }

                printf("Flame Detected!\n");

                // Wait for a short period to avoid repeated triggers
                nanosleep(&delay, NULL);

                // Deactivate buzzer and LED
                if (gpio_write(BUZZER_PIN, 0) < 0 ||
                    gpio_write(LED_PIN, 0) < 0) {
                    fprintf(stderr, "Error deactivating buzzer or LED. Continuing.\n");
                }

                // Reset consecutive readings
                consecutive_readings = 0;
            }
        } else {
            // Flame not detected
            flame_detected = 0;
            consecutive_readings = 0;
        }

        nanosleep(&delay, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpio_unexport(FLAME_SENSOR_PIN);
    gpio_unexport(BUZZER_PIN);
    gpio_unexport(LED_PIN);
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

