#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense duration (in milliseconds)
#define DISPENSE_DURATION 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int dispense_solenoid(int solenoid_pin, int duration_ms);
int log_event(int solenoid_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioWrite(SOLENOID_1_PIN, 0); // Deactivate solenoid 1
    gpioWrite(SOLENOID_2_PIN, 0); // Deactivate solenoid 2
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    // Ensure solenoids are initially off
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);

    return 0; // Indicate success
}

// Function to dispense a solenoid for a specified duration
int dispense_solenoid(int solenoid_pin, int duration_ms) {
    if (duration_ms <= 0) {
        fprintf(stderr, "Invalid dispense duration: %d ms\n", duration_ms);
        return 1; // Indicate failure
    }

    // Activate the solenoid
    gpioWrite(solenoid_pin, 1);
    printf("Solenoid %d activated for %d ms\n", solenoid_pin, duration_ms);

    // Wait for the specified duration
    gpioDelay(duration_ms * 1000); // pigpioDelay takes microseconds

    // Deactivate the solenoid
    gpioWrite(solenoid_pin, 0);
    printf("Solenoid %d deactivated\n", solenoid_pin);

    return 0; // Indicate success
}

// Function to log an event to a file
int log_event(int solenoid_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Solenoid %d, Duration: %d ms\n", timestamp, solenoid_pin, duration_ms);
    fclose(fp);

    return 0; // Indicate success
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Pneumatic Dispensing System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Dispense solenoid 1 for half the duration
        if (dispense_solenoid(SOLENOID_1_PIN, DISPENSE_DURATION / 2) != 0) {
            fprintf(stderr, "Error dispensing solenoid 1\n");
        }

        // Log the event
        if (log_event(SOLENOID_1_PIN, DISPENSE_DURATION / 2) != 0) {
            fprintf(stderr, "Error logging event for solenoid 1\n");
        }

        // Dispense solenoid 2 for the remaining half the duration
        if (dispense_solenoid(SOLENOID_2_PIN, DISPENSE_DURATION / 2) != 0) {
            fprintf(stderr, "Error dispensing solenoid 2\n");
        }

        // Log the event
        if (log_event(SOLENOID_2_PIN, DISPENSE_DURATION / 2) != 0) {
            fprintf(stderr, "Error logging event for solenoid 2\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds = 5000000 microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();

    return 0;
}

