#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Motor A GPIO pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B GPIO pins
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// L298N Enable pins
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

// PID constants
#define KP 1.0
#define Ki 0.01
#define Kd 0.1

// Ultrasonic sensor GPIO pin
#define ULTRASONIC_TRIGGER 4
#define ULTRASONIC_ECHO 17

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
float generate_tilt_error();
float calculate_distance();
int calculate_motor_commands(float tilt_error, float distance, int *motor_a_speed, int *motor_b_speed);
void set_motor_speed(int motor_a_speed, int motor_b_speed);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
}

// Function to generate a random tilt error
float generate_tilt_error() {
    return (float)(rand() % 201 - 100) / 10.0; // Random float between -10.0 and 10.0
}

// Function to calculate the distance from the ultrasonic sensor
float calculate_distance() {
    gpioWrite(ULTRASONIC_TRIGGER, 0);
    gpioDelay(2);
    gpioWrite(ULTRASONIC_TRIGGER, 1);
    gpioDelay(10);
    gpioWrite(ULTRASONIC_TRIGGER, 0);

    long long start_tick = gpioTick();
    long long end_tick = start_tick;

    // Wait for echo to go high
    int timeout = 10000; // Timeout after 10ms
    while (gpioRead(ULTRASONIC_ECHO) == 0 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout == 0) {
        fprintf(stderr, "Error: Ultrasonic sensor timeout (ECHO high)\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    timeout = 10000; // Timeout after 10ms
    while (gpioRead(ULTRASONIC_ECHO) == 1 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout == 0) {
        fprintf(stderr, "Error: Ultrasonic sensor timeout (ECHO low)\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    long long diff = end_tick - start_tick;
    float distance = (float)diff * 0.0343 / 2.0; // Speed of sound: 343 m/s

    return distance;
}

// Function to calculate motor commands using PID
int calculate_motor_commands(float tilt_error, float distance, int *motor_a_speed, int *motor_b_speed) {
    float error = tilt_error;
    static float integral = 0.0;
    static float previous_error = 0.0;

    integral += error;
    float derivative = error - previous_error;

    float output = KP * error + Ki * integral + Kd * derivative;

    // Limit the output to +/- 255
    if (output > 255.0) output = 255.0;
    if (output < -255.0) output = -255.0;

    // Proportional control for motor A
    if (error > 0) {
        *motor_a_speed = (int)output;
        *motor_b_speed = 0;
    } else if (error < 0) {
        *motor_a_speed = 0;
        *motor_b_speed = (int)-output;
    } else {
        *motor_a_speed = 0;
        *motor_b_speed = 0;
    }

    previous_error = error;

    return 0;
}

// Function to set the motor speeds using PWM
void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    // Motor A
    if (motor_a_speed > 0) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_A_ENABLE, motor_a_speed);
    } else if (motor_a_speed < 0) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
        gpioPWM(MOTOR_A_ENABLE, -motor_a_speed);
    } else {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_A_ENABLE, 0);
    }

    // Motor B
    if (motor_b_speed > 0) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(MOTOR_B_ENABLE, motor_b_speed);
    } else if (motor_b_speed < 0) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
        gpioPWM(MOTOR_B_ENABLE, -motor_b_speed);
    } else {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(MOTOR_B_ENABLE, 0);
    }
}

// Function to log data to a file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_A_ENABLE, 255);
    gpioSetPWMrange(MOTOR_B_ENABLE, 255);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(MOTOR_A_ENABLE, 1000);
    gpioSetPWMfrequency(MOTOR_B_ENABLE, 1000);

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Self-balancing robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Generate tilt error
        float tilt_error = generate_tilt_error();

        // Calculate distance
        float distance = calculate_distance();

        // Calculate motor commands
        int motor_a_speed, motor_b_speed;
        calculate_motor_commands(tilt_error, distance, &motor_a_speed, &motor_b_speed);

        // Set motor speeds
        set_motor_speed(motor_a_speed, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay for 50ms
        gpioDelay(50);
    }

    // Stop motors
    set_motor_speed(0, 0);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Self-balancing robot stopped.\n");

    return 0;
}

