#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Configuration
#define ALSA_DEVICE "default"
#define SAMPLE_RATE 8000
#define SAMPLE_FORMAT SND_PCM_FORMAT_S16_LE
#define NUM_CHANNELS 1
#define PERIOD_SIZE 1024
#define RED_GPIO 17
#define GREEN_GPIO 18
#define BLUE_GPIO 27
#define SINE_WAVE_FREQUENCY 440.0
#define SINE_WAVE_AMPLITUDE 1000.0
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000000 // 0-1000000
#define DEFAULT_SENSITIVITY 1.0
#define MAX_SENSITIVITY 10.0
#define MIN_SENSITIVITY 0.1

// Global variables
snd_pcm_t *pcm_handle;
volatile sig_atomic_t terminate = 0;
double sensitivity = DEFAULT_SENSITIVITY;

// Function prototypes
int init_alsa();
int read_audio_samples(short *samples, int num_samples);
double calculate_rms(const short *samples, int num_samples);
void map_rms_to_rgb(double rms, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void simulate_audio_input();
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize ALSA
int init_alsa() {
    int err;

    if ((err = snd_pcm_open(&pcm_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_t *hw_params;
    if ((err = snd_pcm_hw_params_malloc(&hw_params)) < 0) {
        fprintf(stderr, "Error allocating hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SAMPLE_FORMAT)) < 0) {
        fprintf(stderr, "Error setting sample format: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if (rate != SAMPLE_RATE) {
        fprintf(stderr, "Sample rate changed to %d\n", rate);
    }

    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channel count: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(pcm_handle);
        return -1;
    }

    unsigned int period_size = PERIOD_SIZE;
    if ((err = snd_pcm_hw_params_set_period_size_near(pcm_handle, hw_params, &period_size, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if (period_size != PERIOD_SIZE) {
        fprintf(stderr, "Period size changed to %d\n", period_size);
    }

    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(pcm_handle);
        return -1;
    }

    snd_pcm_hw_params_free(hw_params);

    return 0;
}

// Read audio samples from ALSA
int read_audio_samples(short *samples, int num_samples) {
    int err;
    if ((err = snd_pcm_readi(pcm_handle, samples, num_samples)) != num_samples) {
        if (err == -EPIPE) {
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err == -ESTRPIPE) {
            fprintf(stderr, "Underrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else {
            fprintf(stderr, "Error reading audio: %s\n", snd_strerror(err));
            return -1;
        }
    }
    return 0;
}

// Calculate RMS amplitude
double calculate_rms(const short *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Map RMS amplitude to RGB color values
void map_rms_to_rgb(double rms, int *red, int *green, int *blue) {
    // Non-linear mapping (logarithmic)
    double log_rms = log10(rms + 1.0); // Add 1 to avoid log(0)
    double normalized_log_rms = log_rms / log10(10000.0); // Scale to 0-1

    // Cool colors for low amplitude
    if (normalized_log_rms < 0.25) {
        *red = (int)(255.0 * (1.0 - normalized_log_rms * 4.0));
        *green = (int)(255.0 * (normalized_log_rms * 4.0));
        *blue = 0;
    }

    // Warm colors for high amplitude
    else if (normalized_log_rms >= 0.25 && normalized_log_rms < 0.75) {
        *red = 0;
        *green = (int)(255.0 * (1.0 - (normalized_log_rms - 0.25) * 4.0));
        *blue = (int)(255.0 * ((normalized_log_rms - 0.25) * 4.0));
    }

    // Full brightness for very high amplitude
    else {
        *red = 0;
        *green = 0;
        *blue = 255;
    }
}

// Set RGB LED color using software PWM
void set_led_color(int red, int green, int blue) {
    // Invert the color (common cathode)
    int inverted_red = 255 - red;
    int inverted_green = 255 - green;
    int inverted_blue = 255 - blue;

    // Map PWM duty cycle (0-1000000) to 0-255
    int red_duty_cycle = (int)((double)inverted_red / 255.0 * PWM_RANGE);
    int green_duty_cycle = (int)((double)inverted_green / 255.0 * PWM_RANGE);
    int blue_duty_cycle = (int)((double)inverted_blue / 255.0 * PWM_RANGE);

    gpioPWM(RED_GPIO, red_duty_cycle);
    gpioPWM(GREEN_GPIO, green_duty_cycle);
    gpioPWM(BLUE_GPIO, blue_duty_cycle);
}

// Simulate audio input by generating a sine wave
void simulate_audio_input() {
    short samples[PERIOD_SIZE];
    for (int i = 0; i < PERIOD_SIZE; i++) {
        samples[i] = (short)(SINE_WAVE_AMPLITUDE * sin(2 * M_PI * SINE_WAVE_FREQUENCY * (double)i / SAMPLE_RATE));
    }
    set_led_color(samples[0], samples[0], samples[0]); // Set color based on first sample
}

// Cleanup resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    gpioPWM(RED_GPIO, 0);
    gpioPWM(GREEN_GPIO, 0);
    gpioPWM(BLUE_GPIO, 0);
    gpioTerminate();
    if (pcm_handle) {
        snd_pcm_close(pcm_handle);
    }
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main(int argc, char *argv[]) {
    // Parse command-line argument for sensitivity scaling
    if (argc > 1) {
        char *endptr;
        sensitivity = strtod(argv[1], &endptr);
        if (*endptr != '\0' || sensitivity <= MIN_SENSITIVITY || sensitivity > MAX_SENSITIVITY) {
            fprintf(stderr, "Invalid sensitivity value. Using default value: %.2f\n", DEFAULT_SENSITIVITY);
            sensitivity = DEFAULT_SENSITIVITY;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RED_GPIO, PI_OUTPUT);
    gpioSetMode(GREEN_GPIO, PI_OUTPUT);
    gpioSetMode(BLUE_GPIO, PI_OUTPUT);

    // Initialize ALSA
    if (init_alsa() != 0) {
        fprintf(stderr, "ALSA initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(RED_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(RED_GPIO, PWM_RANGE);
    gpioSetPWMrange(GREEN_GPIO, PWM_RANGE);
    gpioSetPWMrange(BLUE_GPIO, PWM_RANGE);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    short samples[PERIOD_SIZE];
    double rms;
    int red, green, blue;
    while (!terminate) {
        // Read audio samples
        if (read_audio_samples(samples, PERIOD_SIZE) == 0) {
            // Calculate RMS amplitude
            rms = calculate_rms(samples, PERIOD_SIZE);

            // Map RMS to RGB color values
            map_rms_to_rgb(rms * sensitivity, &red, &green, &blue);

            // Set LED color
            set_led_color(red, green, blue);
        } else {
            // Simulate audio input if ALSA fails
            simulate_audio_input();
        }

        // Delay for 10ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

