int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold color data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} color_data_t;

// Function prototypes
int init_sensor();
color_data_t read_color_data();
void log_data(color_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the TCS34725 sensor
int init_sensor() {
    // Enable power and RGBC
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", i2c_handle);
        return -1;
    }

    // Set integration time (ATIME)
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error writing to ATIME register: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Read color data from the TCS34725 sensor
color_data_t read_color_data() {
    color_data_t data;
    uint8_t buffer[8];

    // Read all 8 bytes of data in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)buffer, 8) != 8) {
        fprintf(stderr, "Error reading color data: %d\n", i2c_handle);
        data.clear = 0; data.red = 0; data.green = 0; data.blue = 0;
        return data;
    }

    // Combine the bytes to form the color values
    data.clear = (buffer[1] << 8) | buffer[0];
    data.red = (buffer[3] << 8) | buffer[2];
    data.green = (buffer[5] << 8) | buffer[4];
    data.blue = (buffer[7] << 8) | buffer[6];

    return data;
}

