        fprintf(stderr, "Error opening color_data.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Clear,Red,Green,Blue\n");
    }
    rewind(fp);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        color_data_t data = read_color_data();
        log_data(data);
        gpioDelay(500); // Wait 500ms
    }

    // Close I2C bus and file
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

