#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define sunrise and sunset times (in seconds)
#define SUNRISE_TIME 3600
#define SUNSET_TIME 3600

// Define nighttime time (in seconds)
#define NIGHTTIME_TIME 57600

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY3_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY4_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to set the brightness of a relay using PWM
void set_relay_brightness(int relay_pin, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    gpioPWM(relay_pin, brightness);
}

// Function to simulate sunrise
void sunrise() {
    int brightness = 0;
    int increment = 255 / (SUNRISE_TIME / 60); // Increment brightness by 255/SUNRISE_TIME

    while (brightness < 255 && program_running) {
        set_relay_brightness(RELAY1_PIN, brightness);
        set_relay_brightness(RELAY2_PIN, brightness);
        set_relay_brightness(RELAY3_PIN, brightness);
        set_relay_brightness(RELAY4_PIN, brightness);
        brightness += increment;
        gpioDelay(60000); // Delay for 60ms (1/1000 of a second)
    }
}

// Function to simulate daytime
void daytime() {
    int brightness = 255;
    int decrement = 255 / (6 * 60); // Decrement brightness by 255/6*60

    while (brightness > 0 && program_running) {
        set_relay_brightness(RELAY1_PIN, brightness);
        set_relay_brightness(RELAY2_PIN, brightness);
        set_relay_brightness(RELAY3_PIN, brightness);
        set_relay_brightness(RELAY4_PIN, brightness);
        brightness -= decrement;
        gpioDelay(60000); // Delay for 60ms (1/1000 of a second)
    }
}

// Function to simulate sunset
void sunset() {
    int brightness = 255;
    int decrement = 255 / (SUNSET_TIME / 60); // Decrement brightness by 255/SUNSET_TIME

    while (brightness > 0 && program_running) {
        set_relay_brightness(RELAY1_PIN, brightness);
        set_relay_brightness(RELAY2_PIN, brightness);
        set_relay_brightness(RELAY3_PIN, brightness);
        set_relay_brightness(RELAY4_PIN, brightness);
        brightness -= decrement;
        gpioDelay(60000); // Delay for 60ms (1/1000 of a second)
    }
}

// Function to simulate nighttime
void nighttime() {
    int brightness = 0;
    int increment = 255 / (NIGHTTIME_TIME / 60); // Increment brightness by 255/NIGHTTIME_TIME

    while (brightness < 255 && program_running) {
        set_relay_brightness(RELAY1_PIN, brightness);
        set_relay_brightness(RELAY2_PIN, brightness);
        set_relay_brightness(RELAY3_PIN, brightness);
        set_relay_brightness(RELAY4_PIN, brightness);
        brightness += increment;
        gpioDelay(60000); // Delay for 60ms (1/1000 of a second)
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        sunrise();
        daytime();
        sunset();
        nighttime();
    }

    // Turn off all relays before exiting
    set_relay_brightness(RELAY1_PIN, 0);
    set_relay_brightness(RELAY2_PIN, 0);
    set_relay_brightness(RELAY3_PIN, 0);
    set_relay_brightness(RELAY4_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

