#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define LED_PIN 27

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Define video recording parameters
#define VIDEO_WIDTH 640
#define VIDEO_HEIGHT 480
#define VIDEO_FPS 30
#define VIDEO_DURATION 5 // seconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
void control_led(int state);
int record_video();
int log_motion();
void signal_handler(int signal);
char* get_timestamp();

// Structure to hold configuration data
typedef struct {
    int sensor_pin;
    int led_pin;
    int debounce_time;
    int video_width;
    int video_height;
    int video_fps;
    int video_duration;
    char* log_file_path;
} Config;

Config config = {
    SENSOR_PIN,
    LED_PIN,
    DEBOUNCE_TIME,
    VIDEO_WIDTH,
    VIDEO_HEIGHT,
    VIDEO_FPS,
    VIDEO_DURATION,
    "/home/pi/logs/motion_log.txt"
};

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) { // Obstacle detected (LOW signal)
            printf("Obstacle detected!\n");
            control_led(1); // Turn on LED
            if (record_video() == 0) {
                log_motion(); // Log motion event
            }
            control_led(0); // Turn off LED
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay
        }

        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    // Cleanup
    printf("Cleaning up and exiting...\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.sensor_pin, PI_INPUT);
    gpioSetMode(config.led_pin, PI_OUTPUT);

    return 0;
}

// Read sensor value with debouncing
int read_sensor() {
    int value = gpioRead(config.sensor_pin);
    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay
    return value;
}

// Control LED state
void control_led(int state) {
    gpioWrite(config.led_pin, state);
}

// Record video using raspivid
int record_video() {
    char filename[100];
    char command[200];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S", timeinfo);

    snprintf(command, sizeof(command), "raspivid -o /home/pi/videos/%s.h264 -w %d -h %d -fps %d -t %d",
             filename, config.video_width, config.video_height, config.video_fps, config.video_duration * 1000);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Failed to execute raspivid command.\n");
        return 1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid command failed with status %d.\n", WEXITSTATUS(status));
        return 1;
    }

    return 0;
}

// Log motion event to file
int log_motion() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: Motion detected\n", timestamp);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = 0;
}

// Get current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[30]; // Static to persist across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

