#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY_1 4
#define RELAY_2 17
#define RELAY_3 27
#define RELAY_4 22

// Define the moisture threshold
#define MOISTURE_THRESHOLD 30

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void control_relay(int zone, int state);
void log_data(int zone, int moisture, int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY_1, PI_OUTPUT);
    gpioSetMode(RELAY_2, PI_OUTPUT);
    gpioSetMode(RELAY_3, PI_OUTPUT);
    gpioSetMode(RELAY_4, PI_OUTPUT);

    // Initialize relays to HIGH (inactive)
    gpioWrite(RELAY_1, 1);
    gpioWrite(RELAY_2, 1);
    gpioWrite(RELAY_3, 1);
    gpioWrite(RELAY_4, 1);

    return 0; // Indicate success
}

// Function to read the moisture sensor value
int read_moisture_sensor() {
    return rand() % 101; // Simulate moisture reading between 0 and 100
}

// Function to control the relay for a given zone
void control_relay(int zone, int state) {
    int gpio_pin;

    switch (zone) {
        case 1:
            gpio_pin = RELAY_1;
            break;
        case 2:
            gpio_pin = RELAY_2;
            break;
        case 3:
            gpio_pin = RELAY_3;
            break;
        case 4:
            gpio_pin = RELAY_4;
            break;
        default:
            fprintf(stderr, "Invalid zone number: %d\n", zone);
            return;
    }

    gpioWrite(gpio_pin, state); // Set the GPIO pin to the specified state
}

// Function to log the sensor data to a file
void log_data(int zone, int moisture, int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Zone: %d, Moisture: %d, Relay: %s\n", timestamp, zone, moisture, relay_state ? "ON" : "OFF");
    fclose(fp);
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read moisture sensor values
        int moisture1 = read_moisture_sensor();
        int moisture2 = read_moisture_sensor();
        int moisture3 = read_moisture_sensor();
        int moisture4 = read_moisture_sensor();

        // Control relays based on moisture levels
        control_relay(1, (moisture1 < MOISTURE_THRESHOLD) ? 0 : 1); // Zone 1
        control_relay(2, (moisture2 < MOISTURE_THRESHOLD) ? 0 : 1); // Zone 2
        control_relay(3, (moisture3 < MOISTURE_THRESHOLD) ? 0 : 1); // Zone 3
        control_relay(4, (moisture4 < MOISTURE_THRESHOLD) ? 0 : 1); // Zone 4

        // Log the data
        log_data(1, moisture1, gpioRead(RELAY_1));
        log_data(2, moisture2, gpioRead(RELAY_2));
        log_data(3, moisture3, gpioRead(RELAY_3));
        log_data(4, moisture4, gpioRead(RELAY_4));

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Deactivate all relays before exiting
    gpioWrite(RELAY_1, 1);
    gpioWrite(RELAY_2, 1);
    gpioWrite(RELAY_3, 1);
    gpioWrite(RELAY_4, 1);

    printf("Smart Greenhouse Irrigation System stopped.\n");

    gpioTerminate(); // Terminate pigpio

    return 0;
}

