        log_data(2, moisture2, gpioRead(RELAY_2));
        log_data(3, moisture3, gpioRead(RELAY_3));
        log_data(4, moisture4, gpioRead(RELAY_4));

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Deactivate all relays before exiting
    gpioWrite(RELAY_1, 1);
    gpioWrite(RELAY_2, 1);
    gpioWrite(RELAY_3, 1);
    gpioWrite(RELAY_4, 1);

    printf("Smart Greenhouse Irrigation System stopped.\n");

    gpioTerminate(); // Terminate pigpio

    return 0;
}

