#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 100000      // 100 ms
#define MAX_DISTANCE_CM 400.0   // Maximum measurable distance (4 meters)

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_rising_edge(int gpio, int level, uint32_t tick);
void echo_falling_edge(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t start_tick, uint32_t end_tick);
void log_distance(double distance);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for rising edge of echo pulse
void echo_rising_edge(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        start_tick = tick;
        echo_received = 1; // Set flag to indicate rising edge received
    }
}

// Callback function for falling edge of echo pulse
void echo_falling_edge(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        end_tick = tick;
        echo_received = 1; // Set flag to indicate falling edge received
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t start_tick, uint32_t end_tick) {
    if (end_tick < start_tick) {
        // Handle tick wrap-around
        uint32_t diff = (0xFFFFFFFF - start_tick) + end_tick;
        return (double)diff * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
    } else {
        return (double)(end_tick - start_tick) * SPEED_OF_SOUND / 2000000.0;
    }
}

// Function to log distance to file
void log_distance(double distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%llu,%.2f\n", timestamp_ns, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0; // Set flag to exit the main loop

    // Cancel callbacks
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioSetAlertFuncEx(TRIGGER_PIN, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&log_mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse(); // Trigger the sensor

        echo_received = 0; // Reset flag for echo reception
        start_tick = 0;   // Reset start tick
        end_tick = 0;     // Reset end tick

        // Wait for echo to arrive or timeout
        int timeout_count = 0;
        while (!echo_received && timeout_count < TIMEOUT_US) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout_count++;
        }

        if (!echo_received) {
            fprintf(stderr, "Timeout waiting for echo.\n");
            continue; // Skip to the next iteration
        }

        // Calculate distance
        double distance = calculate_distance(start_tick, end_tick);

        // Validate distance
        if (distance >= 0 && distance <= MAX_DISTANCE_CM) {
            log_distance(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Invalid distance: %.2f cm\n", distance);
        }

        gpioDelay(200); // Wait 200 ms before next measurement
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioSetAlertFuncEx(TRIGGER_PIN, NULL, NULL);
    fclose(log_file);
    pthread_mutex_destroy(&log_mutex);
    gpioTerminate();

    return 0;
}

