#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// GPIO pin for buzzer
#define BUZZER_PIN 17

// Default freefall threshold (g)
#define DEFAULT_FREEFALL_THRESHOLD 0.2

// Default impact threshold (g)
#define DEFAULT_IMPACT_THRESHOLD 1.5

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int initialize_i2c();
int configure_lis3dh();
accelerometer_data_t read_acceleration();
float convert_to_g(int16_t raw_value);
void activate_buzzer(int duration_ms);
void handle_freefall(float freefall_threshold);
