#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 5

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

// Circular buffer
SensorReadings sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_sensor(int gpio_pin);
void add_to_buffer(SensorReadings reading);
SensorReadings get_latest_reading();
void move_forward();
void turn_left();
void turn_right();
void stop();
void alert();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    stop(); // Stop the robot
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to add sensor readings to the circular buffer
void add_to_buffer(SensorReadings reading) {
    sensor_buffer[buffer_index] = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to get the latest sensor readings from the circular buffer
SensorReadings get_latest_reading() {
    return sensor_buffer[buffer_index];
}

// Function to move the robot forward
void move_forward() {
    printf("Moving forward...\n");
    gpioWrite(ALERT_PIN, 0); // Turn off alert
}

// Function to turn the robot left
void turn_left() {
    printf("Turning left...\n");
    gpioWrite(ALERT_PIN, 0); // Turn off alert
}

// Function to turn the robot right
void turn_right() {
    printf("Turning right...\n");
    gpioWrite(ALERT_PIN, 0); // Turn off alert
}

// Function to stop the robot
void stop() {
    printf("Stopping...\n");
    gpioWrite(ALERT_PIN, 0); // Turn off alert
}

// Function to trigger an alert (buzzer/LED)
void alert() {
    printf("Alert triggered!\n");
    gpioWrite(ALERT_PIN, 1); // Turn on alert
    gpioDelay(2000);          // Wait for 2 seconds
    gpioWrite(ALERT_PIN, 0); // Turn off alert
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Initialize circular buffer with all 'no line' readings
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sensor_buffer[i].left = 1;
        sensor_buffer[i].center = 1;
        sensor_buffer[i].right = 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        SensorReadings current_readings;
        current_readings.left = read_sensor(LEFT_SENSOR_PIN);
        current_readings.center = read_sensor(CENTER_SENSOR_PIN);
        current_readings.right = read_sensor(RIGHT_SENSOR_PIN);

        add_to_buffer(current_readings);

        // Check if all sensors detect a line
        if (current_readings.center == 0) {
            move_forward();
        } else if (current_readings.left == 0) {
            turn_left();
        } else if (current_readings.right == 0) {
            turn_right();
        } else {
            stop();
        }

        gpioDelay(10); // Delay for 10 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop();
    gpioTerminate();
    return 0;
}

