#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0
#define POLL_ATTEMPTS 50
#define POLL_DELAY_MS 10
#define LOG_FILE "magnetic_events.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int16_t *field_raw);
float convert_to_mt(int16_t field_raw);
int control_relay(int state);
int log_event(const char *event_type, int16_t field_raw, float field_mt_x100, int relay_state);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    int16_t field_raw;
    float field_mt_x100;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *field_raw) {
    char buf[2];
    int result;

    // Start measurement (write 0x01 to register 0xC1)
    result = i2cWriteByteData(i2c_handle, 0xC1, 0x01);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (poll register 0xC1 until it reads 0x00)
    int attempts = 0;
    while (attempts < POLL_ATTEMPTS) {
        result = i2cReadByteData(i2c_handle, 0xC1);
        if (result < 0) {
            fprintf(stderr, "Error reading from I2C: %d\n", result);
            return -1;
        }
        if (result == 0) {
            break;
        }
        gpioDelay(POLL_DELAY_MS * 1000); // Delay in microseconds
        attempts++;
    }

    if (attempts == POLL_ATTEMPTS) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read 2 bytes from register 0xC0
    result = i2cReadI2CBlockData(i2c_handle, 0xC0, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *field_raw = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw data to milliTesla
float convert_to_mt(int16_t field_raw) {
    return (float)field_raw * 25.0 / 1000.0;
}

// Function to control the relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Function to log events to a file
int log_event(const char *event_type, int16_t field_raw, float field_mt_x100, int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, %s, %d, %.2f, %d\n", timestamp, event_type, field_raw, field_mt_x100, relay_state);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int16_t field_raw;
        float field_mt_x100;
        int relay_state;

        // Read sensor data
        if (read_sensor_data(&field_raw) == 0) {
            // Convert to milliTesla
            field_mt_x100 = convert_to_mt(field_raw);

            // Control relay based on threshold
            if (field_mt_x100 > THRESHOLD_MT * 100) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    log_event("Relay ON", field_raw, field_mt_x100, relay_state);
                } else {
                    fprintf(stderr, "Error controlling relay\n");
                }
            } else {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    log_event("Relay OFF", field_raw, field_mt_x100, relay_state);
                } else {
                    fprintf(stderr, "Error controlling relay\n");
                }
            }

            printf("Field: %.2f mT, Relay: %s\n", field_mt_x100, relay_state ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            log_event("ERROR", 0, 0.0, -1); // Log error
        }

        gpioDelay(100 * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(0); // Ensure relay is off
    gpioTerminate();

    printf("Magnetic field monitoring stopped.\n");

    return 0;
}

