            // Control relay based on threshold
            if (field_mt_x100 > THRESHOLD_MT * 100) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    log_event("Relay ON", field_raw, field_mt_x100, relay_state);
                } else {
                    fprintf(stderr, "Error controlling relay\n");
                }
            } else {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    log_event("Relay OFF", field_raw, field_mt_x100, relay_state);
                } else {
                    fprintf(stderr, "Error controlling relay\n");
                }
            }

            printf("Field: %.2f mT, Relay: %s\n", field_mt_x100, relay_state ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            log_event("ERROR", 0, 0.0, -1); // Log error
        }

        gpioDelay(100 * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(0); // Ensure relay is off
    gpioTerminate();

    printf("Magnetic field monitoring stopped.\n");

    return 0;
}

