#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define LOG_FILE "relay_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int server_socket = -1;
FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int setup_gpio();
int setup_socket();
void log_event(const char *event);
void handle_client(int client_socket);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Setup GPIO pin for output
int setup_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_PIN);
        return -1;
    }
    gpioWrite(GPIO_PIN, 0); // Ensure relay is initially off
    return 0;
}

// Setup TCP socket
int setup_socket() {
    int socket_fd;
    struct sockaddr_in server_address;

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("Error creating socket");
        return -1;
    }

    // Configure server address
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(socket_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        close(socket_fd);
        return -1;
    }

    // Listen for connections
    if (listen(socket_fd, 5) < 0) {
        perror("Error listening on socket");
        close(socket_fd);
        return -1;
    }

    printf("Listening on port %d...\n", PORT);
    return socket_fd;
}

// Log events to file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;

    while (program_running && (bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0'; // Null-terminate the received data

        // Convert to uppercase
        for (int i = 0; buffer[i] != '\0'; i++) {
            buffer[i] = toupper(buffer[i]);
        }

        printf("Received command: %s\n", buffer);

        if (strcmp(buffer, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1);
            log_event("Relay ON");
            send(client_socket, "Relay ON\n", strlen("Relay ON\n"), 0);
        } else if (strcmp(buffer, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0);
            log_event("Relay OFF");
            send(client_socket, "Relay OFF\n", strlen("Relay OFF\n"), 0);
        } else {
            log_event("Invalid command");
            send(client_socket, "Invalid command\n", strlen("Invalid command\n"), 0);
        }
    }

    if (bytes_received == 0) {
        printf("Client disconnected.\n");
    } else if (bytes_received < 0) {
        perror("Error receiving data");
    }

    close(client_socket);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Setup GPIO
    if (setup_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Setup socket
    server_socket = setup_socket();
    if (server_socket == -1) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(server_socket);
        gpioTerminate();
        return 1;
    }

    // Main loop
    struct sockaddr_in client_address;
    socklen_t client_address_len = sizeof(client_address);
    int client_socket;

    while (program_running) {
        // Accept connection
        client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        // Handle client
        handle_client(client_socket);
    }

    // Cleanup
    close(server_socket);
    fclose(log_file);
    gpioWrite(GPIO_PIN, 0); // Ensure relay is off
    gpioTerminate();

    return 0;
}

