#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define GPIO_RELAY 18
#define FLOW_THRESHOLD 5.0
#define POLLING_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int bus, int addr);
int start_measurement(int handle);
int read_sensor_data(int handle, int16_t *flow_rate);
float convert_to_ml_min(int16_t raw_value);
int validate_crc(uint8_t data[], int len, uint8_t crc);
void control_relay(int state);
void log_flow_rate(float flow1, float flow2);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len, uint8_t crc) {
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 1. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 2. Exiting.\n");
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO 18 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initially de-energized

    // Main loop
    while (!terminate) {
        int16_t raw_flow1, raw_flow2;
        float flow1, flow2;

        // Read sensor 1
        if (read_sensor_data(i2c_handle1, &raw_flow1) == 0) {
            flow1 = convert_to_ml_min(raw_flow1);
            if (flow1 < FLOW_THRESHOLD) {
                control_relay(1); // Energize relay
            } else {
                control_relay(0); // De-energize relay
            }
        } else {
            fprintf(stderr, "Error reading sensor 1 data.\n");
            control_relay(0); // De-energize relay
        }

        // Read sensor 2
        if (read_sensor_data(i2c_handle2, &raw_flow2) == 0) {
            flow2 = convert_to_ml_min(raw_flow2);
            if (flow2 < FLOW_THRESHOLD) {
                control_relay(1); // Energize relay
            } else {
                control_relay(0); // De-energize relay
            }
        } else {
            fprintf(stderr, "Error reading sensor 2 data.\n");
            control_relay(0); // De-energize relay
        }

        // Log flow rates
        log_flow_rate(flow1, flow2);

        // Wait for the next polling interval
        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is de-energized on exit
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Start measurement on the SLF3S-1300F sensor
int start_measurement(int handle) {
    char cmd[2] = {0x36, 0x08};
    int result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write start measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read 3 bytes from the sensor (2 data + 1 CRC-8)
int read_sensor_data(int handle, int16_t *flow_rate) {
    char buffer[3];
    int result = i2cReadDevice(handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    // Validate CRC-8
    uint8_t data[2] = {buffer[0], buffer[1]};
    uint8_t crc = buffer[2];
    if (validate_crc(data, 2, crc) != 0) {
        fprintf(stderr, "CRC validation failed.\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit raw flow rate
    *flow_rate = (int16_t)((buffer[0] << 8) | buffer[1]);

    return 0;
}

// Convert raw sensor data to ml/min
float convert_to_ml_min(int16_t raw_value) {
    return (float)raw_value / 1500.0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = crc8(data, len, 0xFF);
    return calculated_crc != crc;
}

// Control the relay (active-high)
void control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
}

// Log flow rates to a file
void log_flow_rate(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            flow1, flow2);

    fclose(fp);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

