#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define RAIN_DETECTED_LOW 0
#define RAIN_DETECTED_HIGH 1
#define MOTOR_RUN_TIME_MS 5000
#define RAIN_POLLING_INTERVAL_MS 200
#define RAIN_SUPPRESSION_TIME_MS 600
#define RAIN_SUPPRESSION_COUNT 3

// Global variables
static volatile int running = 1;
static volatile int rain_suppression_count = 0;
static volatile int rain_detected = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
void control_motor(int direction);
void log_message(int priority, const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    gpioWrite(MOTOR_ENA_PIN, 0); // Ensure motor is initially off
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);

    log_message(LOG_INFO, "GPIO initialized successfully");
    return 0;
}

// Read rain sensor value
int read_rain_sensor() {
    int value = gpioRead(RAIN_SENSOR_PIN);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read rain sensor value");
        return -1; // Indicate error
    }
    return value;
}

// Control the motor
void control_motor(int direction) {
    if (direction == 1) { // Close window
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioWrite(MOTOR_ENA_PIN, 1);
        log_message(LOG_INFO, "Closing window...");
    } else if (direction == 0) { // Stop motor
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioWrite(MOTOR_ENA_PIN, 0);
        log_message(LOG_INFO, "Stopping motor...");
    } else {
        log_message(LOG_ERR, "Invalid motor direction");
    }
}

// Log messages with timestamps
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    syslog(priority, "%s: %s", timestamp, message);
    printf("%s: %s\n", timestamp, message); // Also print to console
}

// Cleanup GPIO resources
void cleanup() {
    log_message(LOG_INFO, "Cleaning up GPIO resources...");
    gpioWrite(MOTOR_ENA_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioTerminate();
    log_message(LOG_INFO, "GPIO resources cleaned up");
}

int main() {
    // Open syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Rain window controller started");

    // Main loop
    while (running) {
        int current_rain_detected = read_rain_sensor();
        if (current_rain_detected < 0) {
            log_message(LOG_ERR, "Failed to read rain sensor, retrying...");
            gpioDelay(RAIN_POLLING_INTERVAL_MS * 1000); // Wait before retrying
            continue;
        }

        rain_detected = current_rain_detected;

        if (rain_detected == RAIN_DETECTED_LOW) {
            // Rain detected
            log_message(LOG_INFO, "Rain detected!");

            // Close window if it's not already closed
            if (rain_suppression_count < RAIN_SUPPRESSION_COUNT) {
                control_motor(1); // Close window
                gpioDelay(MOTOR_RUN_TIME_MS * 1000); // Run motor for 5 seconds
                control_motor(0); // Stop motor
                rain_suppression_count++;
                log_message(LOG_INFO, "Window closed, rain suppression count: %d", rain_suppression_count);
            } else {
                log_message(LOG_WARNING, "Rain detected, but window already closed, skipping motor control");
            }
        } else {
            // Rain not detected
            rain_suppression_count = 0; // Reset suppression count
            log_message(LOG_INFO, "Rain not detected, resetting rain suppression count");
        }

        gpioDelay(RAIN_POLLING_INTERVAL_MS * 1000); // Wait for 200ms
    }

    // Cleanup and exit
    cleanup();
    closelog();
    return 0;
}

