#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define BUTTON_LOCK 21
#define BUTTON_UNLOCK 22

// Define pulse widths (microseconds)
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000

// Debounce delay (milliseconds)
#define DEBOUNCE_DELAY 50

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void lock_door();
void unlock_door();
void shutdown_system();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_LOCK, PI_INPUT);
    gpioSetMode(BUTTON_UNLOCK, PI_INPUT);

    // Enable pull-ups
    gpioSetPullUpDown(BUTTON_LOCK, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_UNLOCK, PI_PUD_UP);

    return 0; // Indicate success
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();
}

// Lock the door
void lock_door() {
    printf("Locking door...\n");
    gpioServo(SERVO_PIN, LOCK_PULSE_WIDTH);
    gpioDelay(500000); // 500ms delay
}

// Unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    gpioServo(SERVO_PIN, UNLOCK_PULSE_WIDTH);
    gpioDelay(500000); // 500ms delay
}

// Shutdown the system
void shutdown_system() {
    printf("Shutting down system...\n");
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for button press (lock)
        if (gpioRead(BUTTON_LOCK) == 0) {
            lock_door();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        // Check for button press (unlock)
        if (gpioRead(BUTTON_UNLOCK) == 0) {
            unlock_door();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        gpioDelay(10000); // Small delay to reduce CPU usage
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

