#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define FLOODLIGHT_PIN 17

// Define log file path
#define LOG_FILE "security_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void activate_floodlight();
void deactivate_floodlight();
void log_event(const char *event_type);
void signal_handler(int signal);

// Structure to hold floodlight activation data
typedef struct {
    time_t start_time;
    int duration_seconds;
} FloodlightActivationData;

FloodlightActivationData floodlight_data = {0, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read PIR sensor
        int motion_detected = read_pir_sensor();

        if (motion_detected) {
            // Activate floodlight
            activate_floodlight();

            // Log event
            log_event("Motion Detected");

            // Wait for 60 seconds
            gpioDelay(60000); // 60000 milliseconds = 60 seconds

            // Deactivate floodlight
            deactivate_floodlight();

            // Log event
            log_event("Motion Stopped");
        }

        // Small delay to avoid busy-waiting
        gpioDelay(100); // 100 milliseconds
    }

    // Cleanup
    printf("Cleaning up and exiting.\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT);

    // Initialize floodlight to off state
    gpioWrite(FLOODLIGHT_PIN, 0);

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Activate floodlight
void activate_floodlight() {
    gpioWrite(FLOODLIGHT_PIN, 1);
    floodlight_data.start_time = time(NULL);
    floodlight_data.duration_seconds = 60;
}

// Deactivate floodlight
void deactivate_floodlight() {
    gpioWrite(FLOODLIGHT_PIN, 0);
    floodlight_data.start_time = 0; // Reset start time
    floodlight_data.duration_seconds = 0; // Reset duration
}

// Log event to file
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    running = 0;

    // Deactivate floodlight
    deactivate_floodlight();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

