    // Main loop
    while (program_running) {
        int touch_status = read_touch_status();
        if (touch_status >= 0) {
            // Check if electrode 0 is touched (rising edge)
            if ((touch_status & 0x01) && !(touch_status & 0x02)) {
                toggle_relay();
                gpioDelay(200); // Debounce delay
            }
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Cleanup
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF on exit
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

