#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <stdarg.h>

// Constants
#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PORT 5000
#define PWM_FREQUENCY 50
#define PWM_RANGE 2000000 // 2ms
#define SERVO_MIN_PULSE_WIDTH 1000 // 1ms
#define SERVO_MAX_PULSE_WIDTH 2000 // 2ms
#define SERVO_ANGLE_MIN 0
#define SERVO_ANGLE_MAX 180
#define SERVO_ANGLE_RANGE (SERVO_ANGLE_MAX - SERVO_ANGLE_MIN)
#define SERVO_ANGLE_TO_PULSE_WIDTH(angle) ((int)(((float)(angle) / SERVO_ANGLE_RANGE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH))
#define SERVO_PULSE_WIDTH_TO_ANGLE(pulse_width) ((int)(((float)(pulse_width - SERVO_MIN_PULSE_WIDTH) / (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)) * SERVO_ANGLE_RANGE) + SERVO_ANGLE_MIN)
#define SERVO_TOGGLE_DELAY_MS 100

// Global variables
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int setup_gpio();
int setup_socket();
void cleanup();
void log_message(int priority, const char *format, ...);
void *servo_control_thread(void *arg);
void *pir_sensor_thread(void *arg);
int parse_command(const char *command, char *action, int *angle);

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    log_message(LOG_INFO, "Signal received, exiting...");
}

// Setup GPIO
int setup_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(SERVO_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_GPIO, PWM_RANGE);

    return 0;
}

// Setup socket
int setup_socket() {
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_message(LOG_ERR, "Socket creation failed");
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_message(LOG_ERR, "Setsockopt failed");
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed");
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed");
        return -1;
    }

    log_message(LOG_INFO, "Server listening on port %d", PORT);
    return 0;
}

// Cleanup
void cleanup() {
    log_message(LOG_INFO, "Cleaning up...");

    // Stop servo thread
    pthread_cancel(servo_control_thread);
    pthread_join(servo_control_thread, NULL);

    // Stop PIR thread
    pthread_cancel(pir_sensor_thread);
    pthread_join(pir_sensor_thread, NULL);

    // Close socket
    close(new_socket);
    close(server_fd);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    log_message(LOG_INFO, "Cleanup complete. Exiting.");
}

// Log message
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);
}

// Servo control thread
void *servo_control_thread(void *arg) {
    int angle = 0;
    int pulse_width;
    char command[10];
    int angle_received;

    while (program_running) {
        // Receive command
        if (recv(new_socket, command, sizeof(command) - 1, 0) < 0) {
            log_message(LOG_ERR, "Receive failed");
            break;
        }
        command[sizeof(command) - 1] = '\0'; // Ensure null termination

        // Parse command
        if (parse_command(command, action, &angle_received) == 0) {
            if (strcmp(action, "SERVO") == 0) {
                if (angle_received >= SERVO_ANGLE_MIN && angle_received <= SERVO_ANGLE_MAX) {
                    angle = angle_received;
                    pulse_width = SERVO_ANGLE_TO_PULSE_WIDTH(angle);
                    gpioPWM(SERVO_GPIO, pulse_width);
                    char log_message_buffer[100];
                    snprintf(log_message_buffer, sizeof(log_message_buffer), "SERVO: Angle=%d, Pulse Width=%d", angle, pulse_width);
                    log_message(LOG_INFO, "%s", log_message_buffer);
                } else {
                    log_message(LOG_ERR, "Invalid servo angle: %d", angle_received);
                }
            } else if (strcmp(action, "PIR") == 0) {
                char log_message_buffer[100];
                snprintf(log_message_buffer, sizeof(log_message_buffer), "PIR: %d", gpioRead(PIR_GPIO));
                log_message(LOG_INFO, "%s", log_message_buffer);
            } else {
                log_message(LOG_ERR, "Unknown command: %s", action);
            }
        } else {
            log_message(LOG_ERR, "Invalid command format: %s", command);
        }

        gpioDelay(SERVO_TOGGLE_DELAY_MS * 1000); // Delay for servo toggle
    }

    pthread_exit(NULL);
}

// PIR sensor thread
void *pir_sensor_thread(void *arg) {
    int pir_value;
    char log_message_buffer[100];

    while (program_running) {
        pir_value = gpioRead(PIR_GPIO);
        snprintf(log_message_buffer, sizeof(log_message_buffer), "PIR: %d", pir_value);
        log_message(LOG_INFO, "%s", log_message_buffer);
        gpioDelay(100 * 1000); // Delay for 100ms
    }

    pthread_exit(NULL);
}

// Parse command
int parse_command(const char *command, char *action, int *angle) {
    if (strncmp(command, "SERVO", 5) == 0) {
        if (sscanf(command, "SERVO %d", angle) == 1) {
            strcpy(action, "SERVO");
            return 0;
        } else {
            return -1;
        }
    } else if (strncmp(command, "PIR", 3) == 0) {
        strcpy(action, "PIR");
        return 0;
    } else {
        return -1;
    }
}

int main() {
    pthread_t servo_thread, pir_thread;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    // Open syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() != 0) {
        log_message(LOG_ERR, "GPIO setup failed, exiting");
        closelog();
        return 1;
    }

    // Setup socket
    if (setup_socket() != 0) {
        log_message(LOG_ERR, "Socket setup failed, exiting");
        cleanup();
        closelog();
        return 1;
    }

    // Create threads
