#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define SAMPLE_INTERVAL_SEC 2
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (i2cWriteByte(i2c_handle, 0x10) < 0) {
        fprintf(stderr, "Error writing to BH1750: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit value
            int raw_value = (buf[0] << 8) | buf[1];

            // Convert raw value to lux (datasheet formula)
            *lux = (float)raw_value / 1.2;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Control the relay (activate/deactivate)
int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Error writing to relay GPIO: %d\n", state);
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f lux\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;

    // Main loop
    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);
            log_data(lux);

            if (lux < LUX_THRESHOLD) {
                if (control_relay(1) == 0) {
                    printf("Relay activated\n");
                } else {
                    fprintf(stderr, "Failed to activate relay\n");
                }
            } else {
                if (control_relay(0) == 0) {
                    printf("Relay deactivated\n");
                } else {
                    fprintf(stderr, "Failed to deactivate relay\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    control_relay(0); // Ensure relay is off on exit
    gpioTerminate();

    return 0;
}

