#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration structure
typedef struct {
    int dout_pin;
    int sck_pin;
    int solenoid_pin;
    int threshold_grams;
    float scale_factor;
    int duration_ms;
} Config;

// Global variables
static volatile int running = 1;
static Config config;
static int hx711_handle;
static int solenoid_state = 0; // 0 = unlocked, 1 = locked

// Function prototypes
int read_hx711();
float calculate_weight(int raw_value);
void control_solenoid(int state);
void log_message(int priority, const char *message);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[], Config *config);

// Function to read raw data from HX711
int read_hx711() {
    int i;
    int data = 0;

    gpioSetMode(config.dout_pin, PI_INPUT);
    gpioSetMode(config.sck_pin, PI_OUTPUT);

    // Wait for DOUT to go LOW (data ready)
    int timeout = 1000; // Timeout after 1 second
    while (gpioRead(config.dout_pin) == 1 && timeout > 0) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout--;
    }

    if (timeout == 0) {
        log_message(LOG_ERR, "HX711: Timeout waiting for DOUT to go LOW.");
        return -1; // Indicate error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(config.sck_pin, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(config.dout_pin)) {
            data++;
        }
        gpioWrite(config.sck_pin, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse SCK one more time to set gain to Channel A / Gain 128
    gpioWrite(config.sck_pin, 1);
    gpioDelay(1);
    gpioWrite(config.sck_pin, 0);
    gpioDelay(1);

    // Two's complement conversion
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to calculate weight in grams
float calculate_weight(int raw_value) {
    return (float)(raw_value - config.tare_offset) / config.scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(int state) {
    if (state != solenoid_state) {
        gpioWrite(config.solenoid_pin, state);
        solenoid_state = state;
        log_message(LOG_INFO, "Solenoid set to state: " + (state == 1 ? "LOCKED" : "UNLOCKED"));
    }
}

// Function to log messages with timestamps
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    syslog(priority, "%s: %s", timestamp, message);
    printf("%s: %s\n", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[], Config *config) {
    int opt;

    config->dout_pin = 23;
    config->sck_pin = 24;
    config->solenoid_pin = 25;
    config->threshold_grams = 1000;
    config->scale_factor = 1.0;
    config->duration_ms = 200;

    while ((opt = getopt(argc, argv, "d:s:g:t:f:d:")) != -1) {
        switch (opt) {
            case 'd':
                config->dout_pin = atoi(optarg);
                break;
            case 's':
                config->sck_pin = atoi(optarg);
                break;
            case 'g':
                config->solenoid_pin = atoi(optarg);
                break;
            case 't':
                config->threshold_grams = atoi(optarg);
                break;
            case 'f':
                config->scale_factor = atof(optarg);
                break;
            case 'd':
                config->duration_ms = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-d dout_pin] [-s sck_pin] [-g solenoid_pin] [-t threshold_grams] [-f scale_factor] [-d duration_ms]\n", argv[0]);
                return 1;
        }
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int i, raw_values[5];
    float average_weight;

    // Initialize syslog
    openlog("weight_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Parse command-line arguments
    if (parse_arguments(argc, argv, &config) != 0) {
        closelog();
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(config.dout_pin, PI_INPUT);
    gpioSetMode(config.sck_pin, PI_OUTPUT);
    gpioSetMode(config.solenoid_pin, PI_OUTPUT);

    // Initialize solenoid to unlocked state
    control_solenoid(0);

    // Main loop
    while (running) {
        // Read raw data from HX711
        for (i = 0; i < 5; i++) {
            raw_values[i] = read_hx711();
