#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17
#define KEEPALIVE_INTERVAL 60
#define RETRY_DELAY_SECONDS 5

static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Function to log MQTT events
void log_mqtt_event(const char *event, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_USER, "%s [%s] %s", timestamp, MQTT_CLIENT_ID, message);
}

// Function to set the relay state
int set_relay_state(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", GPIO_PIN);
        return -1;
    }
    return 0;
}

// Callback function for MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        char *payload = (char *)message->payload;
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);

        if (strcmp(payload, "ON") == 0) {
            if (set_relay_state(1) == 0) {
                log_mqtt_event("Relay ON", "Relay turned ON");
            } else {
                log_mqtt_event("Relay ON", "Failed to turn ON relay");
            }
        } else if (strcmp(payload, "OFF") == 0) {
            if (set_relay_state(0) == 0) {
                log_mqtt_event("Relay OFF", "Relay turned OFF");
            } else {
                log_mqtt_event("Relay OFF", "Failed to turn OFF relay");
            }
        } else {
            syslog(LOG_ERR, "Invalid payload received: %s", payload);
        }
    } else {
        syslog(LOG_INFO, "Received empty message on topic %s", message->topic);
    }
}

int main() {
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new mosquitto client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto client instance");
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    // Set callbacks
    mosquitto_message_callback_set(mosq, message_callback);

    // Connect to the MQTT broker
    int rc = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, KEEPALIVE_INTERVAL);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    log_mqtt_event("Connected", "Connected to MQTT broker");

    // Subscribe to the MQTT topic
    rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    log_mqtt_event("Subscribed", "Subscribed to MQTT topic");

    // Main loop
    while (running) {
        rc = mosquitto_loop(mosq, -1, 1); // -1 means block indefinitely, 1 means max 1 message at a time
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(rc));
            mosquitto_disconnect(mosq);
            mosquitto_destroy(mosq);
            gpioTerminate();
            mosquitto_lib_cleanup();
            closelog();
            return 1;
        }

        sleep(1); // Reduce CPU usage
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    gpioTerminate();
    mosquitto_lib_cleanup();
    closelog();

    return 0;
}

