#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define pulse widths for the servos (microseconds)
#define SERVO1_PULSE_WIDTH 1000
#define SERVO2_PULSE_WIDTH 1500
#define SERVO3_PULSE_WIDTH 2000
#define SERVO4_PULSE_WIDTH 500
#define SERVO5_PULSE_WIDTH 2500

// Define the PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Define the PWM range (microseconds)
#define PWM_RANGE 2000

// Function to set the pulse width of a servo
int set_servo_pulse_width(int gpio_pin, int pulse_width) {
    if (gpioPWM(gpio_pin, pulse_width) != 0) {
        fprintf(stderr, "Error setting pulse width for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(SERVO1_PIN, PI_OUTPUT);
    gpioSetMode(SERVO2_PIN, PI_OUTPUT);
    gpioSetMode(SERVO3_PIN, PI_OUTPUT);
    gpioSetMode(SERVO4_PIN, PI_OUTPUT);
    gpioSetMode(SERVO5_PIN, PI_OUTPUT);

    // Set PWM frequency and range for each servo
    gpioSetPWMfrequency(SERVO1_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO1_PIN, PWM_RANGE);
    gpioSetPWMfrequency(SERVO2_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO2_PIN, PWM_RANGE);
    gpioSetPWMfrequency(SERVO3_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO3_PIN, PWM_RANGE);
    gpioSetPWMfrequency(SERVO4_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO4_PIN, PWM_RANGE);
    gpioSetPWMfrequency(SERVO5_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO5_PIN, PWM_RANGE);

    // Move servos to predefined positions
    if (set_servo_pulse_width(SERVO1_PIN, SERVO1_PULSE_WIDTH) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_servo_pulse_width(SERVO2_PIN, SERVO2_PULSE_WIDTH) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_servo_pulse_width(SERVO3_PIN, SERVO3_PULSE_WIDTH) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_servo_pulse_width(SERVO4_PIN, SERVO4_PULSE_WIDTH) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_servo_pulse_width(SERVO5_PIN, SERVO5_PULSE_WIDTH) != 0) {
        gpioTerminate();
        return 1;
    }

    // Hold servos for 3 seconds
    sleep(3);

    // Stop PWM signals
    gpioPWM(SERVO1_PIN, 0);
    gpioPWM(SERVO2_PIN, 0);
    gpioPWM(SERVO3_PIN, 0);
    gpioPWM(SERVO4_PIN, 0);
    gpioPWM(SERVO5_PIN, 0);

    // Release the pigpio library
    gpioTerminate();

    printf("Servos stopped and pigpio terminated.\n");
    return 0;
}

