            pwm_duty_cycle_b = 255;
        } else if (pwm_duty_cycle_b < 0) {
            pwm_duty_cycle_b = 0;
        }

        // Control motors
        if (error_a > 0) {
            motor_a_forward((int)pwm_duty_cycle_a);
        } else if (error_a < 0) {
            motor_a_backward((int)pwm_duty_cycle_a);
        } else {
