        // Update previous errors
        previous_error_a = error_a;
        previous_error_b = error_b;

        // Reset encoder counts after a short period
        encoder_a_count = 0;
        encoder_b_count = 0;

        // Stall Detection
        if (abs(encoder_a_count) < STALL_THRESHOLD && abs(encoder_b_count) < STALL_THRESHOLD) {
            stall_detected = 1;
        } else {
            stall_detected = 0;
