#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 17
#define LUX_THRESHOLD_LOW 50
#define LUX_THRESHOLD_HIGH 200
#define POLL_INTERVAL_SEC 5
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
float read_lux();
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is initially off

    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Set BH1750 to continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) < 0) {
        fprintf(stderr, "Failed to set BH1750 mode\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
float read_lux() {
    char buffer[2];
    int bytes_read;

    bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read lux data: %d\n", bytes_read);
        return -1.0;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return (float)raw_value / 1.2;
}

// Control the relay (active-high)
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log data to file
void log_data(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    control_relay(0); // Turn off relay
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    int relay_state = 0; // 0 = OFF, 1 = ON
    float lux;

    printf("Smart Chicken Coop Lighting System\n");

    while (!terminate) {
        lux = read_lux();

        if (lux >= 0) {
            log_data(lux, relay_state);

            if (lux < LUX_THRESHOLD_LOW && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                printf("Lux below threshold, turning relay ON\n");
            } else if (lux > LUX_THRESHOLD_HIGH && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                printf("Lux above threshold, turning relay OFF\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux, skipping relay control\n");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

