    // Main loop
    while (running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // pigpioDelay takes microseconds

            // Re-read the sensor after the debounce
            if (read_touch_sensor() == 1) {
                toggle_relay();
                log_relay_state(relay_state);
            }
        }

        gpioDelay(10 * 1000); // Check every 10ms
    }

    return 0;
}

