#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define PULSES_PER_LITER 450.0
#define LPM_PER_PULSE 60.0
#define HYSTERESIS_LOW 4.5
#define HYSTERESIS_HIGH 0.5
#define SOLENOID_OPEN_TIME 5 // seconds
#define SOLENOID_CLOSE_TIME 5 // seconds
#define DEBOUNCE_TIME 1 // seconds

// Global variables
static volatile int pulse_count = 0;
static volatile int solenoid_state = 0; // 0 = open, 1 = closed
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int running = 1;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm(int pulses);
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);

// Callback function for flow sensor interrupts
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Function to calculate LPM from pulse count
double calculate_lpm(int pulses) {
    return (double)pulses / PULSES_PER_LITER * LPM_PER_PULSE;
}

// Function to control the solenoid valve
void control_solenoid(double lpm) {
    if (lpm > HYSTERESIS_HIGH && solenoid_state == 0) {
        gpioWrite(SOLENOID_PIN, 1); // Open solenoid
        solenoid_state = 1;
        log_data(lpm, solenoid_state);
        printf("Solenoid opened (LPM: %.2f)\n", lpm);
        sleep(SOLENOID_OPEN_TIME);
        gpioWrite(SOLENOID_PIN, 0); // Close solenoid
        solenoid_state = 0;
        log_data(lpm, solenoid_state);
        printf("Solenoid closed (LPM: %.2f)\n", lpm);
    } else if (lpm < HYSTERESIS_LOW && solenoid_state == 1) {
        gpioWrite(SOLENOID_PIN, 0); // Close solenoid
        solenoid_state = 0;
        log_data(lpm, solenoid_state);
        printf("Solenoid closed (LPM: %.2f)\n", lpm);
    }
}

// Function to log data to a file
void log_data(double lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // unused
    running = 0;
    printf("Caught signal, exiting gracefully...\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Initialize solenoid to closed state
    gpioWrite(SOLENOID_PIN, 0);
    solenoid_state = 0;

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up ISR for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int current_pulse_count;
        double lpm;

        // Debounce the sensor
        sleep(DEBOUNCE_TIME);

        pthread_mutex_lock(&pulse_mutex);
        current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        lpm = calculate_lpm(current_pulse_count);
        control_solenoid(lpm);
        log_data(lpm, solenoid_state);

        printf("LPM: %.2f, Solenoid: %s\n", lpm, solenoid_state ? "OPEN" : "CLOSED");

        sleep(1);
    }

    // Cleanup
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is closed on exit
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();

    printf("Water flow monitoring stopped.\n");
    return 0;
}

