#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration file path
#define CONFIG_FILE "config.ini"

// Default values
#define DEFAULT_CALIBRATION_FACTOR 100.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_SERVO_PIN 18
#define DEFAULT_SERVO_MIN_PULSEWIDTH 1000
#define DEFAULT_SERVO_MAX_PULSEWIDTH 2000
#define DEFAULT_TIMEOUT_MS 1000

// Global variables
static volatile int running = 1;
static int server_fd = -1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[INET_ADDRSTRLEN] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;
static int servo_pin = DEFAULT_SERVO_PIN;
static int servo_min_pulsewidth = DEFAULT_SERVO_MIN_PULSEWIDTH;
static int servo_max_pulsewidth = DEFAULT_SERVO_MAX_PULSEWIDTH;
static int timeout_ms = DEFAULT_TIMEOUT_MS;

// Function prototypes
int load_config();
int setup_gpio();
int setup_socket();
void handle_client(int client_fd);
double read_hx711();
double calibrate_weight(double raw_value);
int set_servo_angle(int angle);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// HX711 GPIO pins
#define HX711_DATA_PIN 23
#define HX711_CLOCK_PIN 24

// Function to load configuration from file
int load_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open config file %s. Using default values.\n", CONFIG_FILE);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "calibration_factor") == 0) {
            calibration_factor = atof(value);
        } else if (strcmp(key, "server_ip") == 0) {
            strncpy(server_ip, value, INET_ADDRSTRLEN - 1);
            server_ip[INET_ADDRSTRLEN - 1] = '\0'; // Ensure null termination
        } else if (strcmp(key, "server_port") == 0) {
            server_port = atoi(value);
        } else if (strcmp(key, "servo_pin") == 0) {
            servo_pin = atoi(value);
        } else if (strcmp(key, "servo_min_pulsewidth") == 0) {
            servo_min_pulsewidth = atoi(value);
        } else if (strcmp(key, "servo_max_pulsewidth") == 0) {
            servo_max_pulsewidth = atoi(value);
        } else if (strcmp(key, "timeout_ms") == 0) {
            timeout_ms = atoi(value);
        }
    }

    fclose(fp);
    return 0;
}

// Function to setup GPIO pins
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(servo_pin, PI_OUTPUT);

    // Set PWM range (optional, but good practice)
    gpioSetPWMrange(servo_pin, 1000); // 1000 steps for 1000-2000 us range
    gpioSetPWMfrequency(servo_pin, 50); // 50 Hz PWM frequency

    return 0;
}

// Function to setup socket
int setup_socket() {
    struct sockaddr_in address;
    int opt = 1;

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port 12345
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(server_port);

    // Forcefully attaching socket to the port 12345
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        return -1;
    }

    printf("Listening on %s:%d...\n", server_ip, server_port);
    return 0;
}

// Function to handle client connection
void handle_client(int client_fd) {
