        double target_weight = atof(buffer);

        // Read raw value from HX711
        double raw_value = read_hx711();

        // Calibrate weight
        double actual_weight = calibrate_weight(raw_value);

        // Set servo angle
        int angle = (int)((actual_weight / target_weight) * 1000.0); // Map weight to angle (0-1000)
        if (angle < 0) angle = 0;
        if (angle > 1000) angle = 1000;
        if (set_servo_angle(angle) != 0) {
            log_event("Error: Failed to set servo angle");
