        gpioDelay(1000000); // 1 second

        // Read raw value from HX711 again
        raw_value = read_hx711();

        // Calibrate weight again
        actual_weight = calibrate_weight(raw_value);

        // Send actual weight back to client
        char response[1024];
        snprintf(response, sizeof(response), "%.2f", actual_weight);
        send(client_fd, response, strlen(response), 0);

        // Log event
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Target Weight: %.2f g, Actual Weight: %.2f g", target_weight, actual_weight);
        log_event(log_message);
    }

    if (valread == 0) {
        printf("Client disconnected\n");
    } else if (valread < 0) {
        perror("recv failed");
    }

    close(client_fd);
}

// Function to read raw value from HX711
double read_hx711() {
    long count = 0;
    int attempts = 0;
    int timeout = timeout_ms; // Timeout in microseconds

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for DATA pin to go low
    while (gpioRead(HX711_DATA_PIN) == 1 && attempts < 1000) {
