#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
static int debounce_delay = DEBOUNCE_DELAY;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void log_relay_state(int state);
void signal_handler(int signal);
void parse_arguments(int argc, char *argv[]);

// Structure to hold program state
typedef struct {
    int relay_state;
} ProgramState;

ProgramState state = {0}; // Initialize relay state to OFF

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    parse_arguments(argc, argv);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch-controlled desk lamp started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read touch sensor
        int touch_detected = read_touch_sensor();

        if (touch_detected) {
            // Toggle relay
            toggle_relay();

            // Debounce delay
            gpioDelay(debounce_delay * 1000); // pigpioDelay takes microseconds
        }

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // 1 ms delay
    }

    // Cleanup and exit
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio
    printf("Touch-controlled desk lamp stopped.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set touch sensor pin as input
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch sensor pin as input\n");
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin as output\n");
        gpioTerminate();
        return 1;
    }

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);

    return 0;
}

// Read touch sensor state
int read_touch_sensor() {
    int touch_state = gpioRead(TOUCH_SENSOR_PIN);
    return (touch_state == 0) ? 1 : 0; // TTP223 outputs LOW when touched
}

// Toggle relay state
void toggle_relay() {
    state.relay_state = !state.relay_state; // Toggle the state
    gpioWrite(RELAY_PIN, state.relay_state); // Write the new state to the relay pin
    log_relay_state(state.relay_state);
}

// Log relay state change
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    running = 0;
}

// Parse command-line arguments
void parse_arguments(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_delay = atoi(optarg);
                if (debounce_delay <= 0) {
                    fprintf(stderr, "Invalid debounce delay. Using default value (%d ms).\n", DEBOUNCE_DELAY);
                    debounce_delay = DEBOUNCE_DELAY;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

