    running = 0;
}

// Parse command-line arguments
void parse_arguments(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_delay = atoi(optarg);
                if (debounce_delay <= 0) {
                    fprintf(stderr, "Invalid debounce delay. Using default value (%d ms).\n", DEBOUNCE_DELAY);
                    debounce_delay = DEBOUNCE_DELAY;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

