#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define pulse width limits (500-2500 µs)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define angle limits (0-180°)
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Global variables
volatile sig_atomic_t program_running = 1;
int current_angle = 90;

// Function prototypes
int initialize_gpio();
int set_servo_angle(int angle);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_PIN, 1000); // Set PWM range to 1000 for 0-1000 us

    return 0;
}

// Set servo angle using hardware PWM
int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Angle out of range: %d\n", angle);
        return 1;
    }

    // Calculate pulse width based on angle (SG90 servo)
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle) / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    gpioServo(SERVO_PIN, pulse_width);
    current_angle = angle;
    return 0;
}

// Cleanup GPIO resources
void cleanup() {
    gpioServo(SERVO_PIN, 0); // Stop PWM
    gpioTerminate();
}

int main() {
    // Set up signal handling for Ctrl+C and SIGINT
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Servo control program started. Press '+' to increase angle, '-' to decrease angle, 'q' to quit.\n");

    // Main loop
    while (program_running) {
        char input;
        if (read(STDIN_FILENO, &input, 1) == 1) {
            switch (input) {
                case '+':
                    current_angle += 10;
                    if (current_angle > MAX_ANGLE) {
                        current_angle = MAX_ANGLE;
                    }
                    break;
                case '-':
                    current_angle -= 10;
                    if (current_angle < MIN_ANGLE) {
                        current_angle = MIN_ANGLE;
                    }
                    break;
                case 'q':
                    program_running = 0;
                    break;
                default:
                    // Ignore other input
                    break;
            }

            if (set_servo_angle(current_angle) != 0) {
                fprintf(stderr, "Error setting servo angle\n");
            }

            printf("Current angle: %d°\n", current_angle);
        } else {
            // Handle read error (e.g., Ctrl+C)
            break;
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

