#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define failsafe timeout (in seconds)
#define FAILSAFE_TIMEOUT 10

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void failsafe_handler();
void signal_handler(int signal);

// Structure to hold relay state
typedef struct {
    int state;
} RelayState;

RelayState relay_state = {0}; // Initialize relay to OFF

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Touch sensor relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read touch sensor
        int touch_detected = read_touch_sensor();

        // Toggle relay if touch is detected
        if (touch_detected) {
            toggle_relay();
        }

        // Failsafe handler
        failsafe_handler();

        // Delay for 50ms
        gpioDelay(50000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set touch sensor pin as input
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize relay to OFF
    gpioWrite(RELAY_PIN, 0);

    return 0;
}

// Read touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Toggle relay state
void toggle_relay() {
    relay_state.state = !relay_state.state; // Toggle the state
    gpioWrite(RELAY_PIN, relay_state.state); // Write the new state to the relay pin
    printf("Relay toggled to state: %d\n", relay_state.state);
}

// Failsafe handler
void failsafe_handler() {
    static unsigned long last_touch_time = 0;
    unsigned long current_time = gpioTick();

    if (read_touch_sensor() == 1) {
        // Touch detected
        if (current_time - last_touch_time > FAILSAFE_TIMEOUT * 1000000) {
            // Failsafe triggered
            printf("Failsafe triggered! Touch sensor remains HIGH for %d seconds. Disabling relay.\n", FAILSAFE_TIMEOUT);
            gpioWrite(RELAY_PIN, 0); // Turn off the relay
            program_running = 0; // Stop the program
        }
        last_touch_time = current_time;
    } else {
        // Touch released
        last_touch_time = 0; // Reset the timer
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

