#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define VALVE_GPIO 18
#define DIRECTION_GPIO 23
#define FLOW_SENSOR_GPIO 24
#define PULSES_PER_LITER 450.0
#define TARGET_FLOW_RATE_DEFAULT 5.0
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 255
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_MS 100

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;
static double target_flow_rate = TARGET_FLOW_RATE_DEFAULT;

// Function prototypes
double calculate_flow_rate(int pulse_count);
int set_valve_position(int duty_cycle);
int log_data(double flow_rate, int valve_position);
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold program state
typedef struct {
    int valve_enabled;
} ProgramState;

ProgramState state = {1}; // Initialize valve to enabled

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t target_flow_rate]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Calculate flow rate
        double flow_rate = calculate_flow_rate(pulse_count);

        // Set valve position
        int duty_cycle = (int)(target_flow_rate * 1000.0 / flow_rate); // Proportional control
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
        if (set_valve_position(duty_cycle) != 0) {
            fprintf(stderr, "Failed to set valve position.\n");
        }

        // Log data
        if (log_data(flow_rate, duty_cycle) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Reset pulse count
        pulse_count = 0;

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio and GPIO pins
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetMode(DIRECTION_GPIO, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Enable the valve (HIGH)
    gpioWrite(DIRECTION_GPIO, 1); // Set direction to forward
    gpioWrite(VALVE_GPIO, 1); // Enable the valve

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp_ms,flow_rate,valve_position\n");
    }
    fflush(log_file);

    // Set up interrupt handler for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Calculate flow rate in L/min
double calculate_flow_rate(int pulse_count) {
    return (double)pulse_count / PULSES_PER_LITER * 60.0;
}

// Set valve position using PWM
int set_valve_position(int duty_cycle) {
    gpioPWM(VALVE_GPIO, duty_cycle);
    return 0;
}

// Log data to CSV file
int log_data(double flow_rate, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Interrupt handler for flow sensor
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pulse_count++;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Cleanup resources before exiting
void cleanup() {
