#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK_1_PIN 17
#define LOCK_2_PIN 27
#define BUTTON_PIN 22

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 100000

// Define valid tag ID
const unsigned char valid_tag_id[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rfid_tag(unsigned char *tag_id);
int validate_tag(const unsigned char *tag_id);
int engage_lock(int lock_pin);
int disengage_lock(int lock_pin);
int log_access(const char *message);
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to read RFID tag from SPI
int read_rfid_tag(unsigned char *tag_id) {
    char tx_buffer[1] = {0x00}; // Dummy transmit buffer
    char rx_buffer[10]; // Receive buffer for 10 bytes
    int result;

    result = spiXfer(spi_handle, tx_buffer, rx_buffer, 10);
    if (result != 10) {
        log_access("Error reading RFID tag");
        return -1; // Indicate error
    }

    memcpy(tag_id, rx_buffer, 10);
    return 0; // Indicate success
}

// Function to validate RFID tag
int validate_tag(const unsigned char *tag_id) {
    return (memcmp(tag_id, valid_tag_id, sizeof(valid_tag_id)) == 0);
}

// Function to engage a lock
int engage_lock(int lock_pin) {
    if (gpioWrite(lock_pin, 0) != 0) {
        log_access("Error engaging lock");
        return -1; // Indicate error
    }
    gpioDelay(5000); // Wait 5 seconds
    return 0; // Indicate success
}

// Function to disengage a lock
int disengage_lock(int lock_pin) {
    if (gpioWrite(lock_pin, 1) != 0) {
        log_access("Error disengaging lock");
        return -1; // Indicate error
    }
    return 0; // Indicate success
}

// Function to log access attempts
int log_access(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
        return 0; // Indicate success
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1; // Indicate error
    }
}

// Callback function for button press
void button_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed (active-low)
        unsigned char tag_id[10];
        if (read_rfid_tag(tag_id) == 0) {
            if (validate_tag(tag_id)) {
                log_access("Two-factor authentication successful");
                engage_lock(LOCK_1_PIN);
                engage_lock(LOCK_2_PIN);
                gpioDelay(5000); // Wait 5 seconds
                disengage_lock(LOCK_1_PIN);
                disengage_lock(LOCK_2_PIN);
            } else {
                log_access("Invalid tag ID");
            }
        } else {
            log_access("RFID read failure");
        }
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_access("Program terminated by signal");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable internal pull-up resistor

    // Set initial lock states to engaged
    gpioWrite(LOCK_1_PIN, 1);
    gpioWrite(LOCK_2_PIN, 1);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up button callback
    gpioSetAlertFuncEx(BUTTON_PIN, button_callback, NULL);

    log_access("Program started");

    // Main loop
    while (program_running) {
        gpioDelay(100); // Check for signals every 100ms
    }

    // Cleanup
    disengage_lock(LOCK_1_PIN);
    disengage_lock(LOCK_2_PIN);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    log_access("Program terminated");

    return 0;
}

