#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target RPMs
#define TARGET_RPM1 60.0
#define TARGET_RPM2 60.0

// PWM Frequency
#define PWM_FREQUENCY 100

// Log File
#define LOG_FILE "motor_log.csv"

// Global Variables
static volatile int encoder1_count = 0;
static volatile int encoder2_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Mutexes
static pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
void signal_handler(int signal);
void log_data(double rpm1, double rpm2, double pid_p, double pid_i, double pid_d, double pid_output);
void motor_control(double rpm1, double rpm2);
void encoder1_callback(int gpio, int level, uint32_t tick, void *user_data);
void encoder2_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(int encoder_count, double time_elapsed);
double pid_control(double setpoint, double actual_value, double *integral, double *previous_error, double *previous_time);

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;
}

// Log Data
void log_data(double rpm1, double rpm2, double pid_p, double pid_i, double pid_d, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, rpm1, rpm2, pid_p, pid_i, pid_d, pid_output);
    fflush(log_file); // Ensure data is written to file immediately
}

// Motor Control
void motor_control(double rpm1, double rpm2) {
    int pwm_value1, pwm_value2;

    // Calculate PWM values (0-255)
    pwm_value1 = (int)(fabs(rpm1) / TARGET_RPM1 * 255.0);
    pwm_value2 = (int)(fabs(rpm2) / TARGET_RPM2 * 255.0);

    // Clamp PWM values to 0-255
    if (pwm_value1 < 0) pwm_value1 = 0;
    if (pwm_value1 > 255) pwm_value1 = 255;
    if (pwm_value2 < 0) pwm_value2 = 0;
    if (pwm_value2 > 255) pwm_value2 = 255;

    // Set motor directions based on RPM sign
    if (rpm1 > 0) {
        gpioWrite(MOTOR1_IN1, 1);
        gpioWrite(MOTOR1_IN2, 0);
    } else {
        gpioWrite(MOTOR1_IN1, 0);
        gpioWrite(MOTOR1_IN2, 1);
    }

    if (rpm2 > 0) {
        gpioWrite(MOTOR2_IN3, 1);
        gpioWrite(MOTOR2_IN4, 0);
    } else {
        gpioWrite(MOTOR2_IN3, 0);
        gpioWrite(MOTOR2_IN4, 1);
    }

    // Set PWM duty cycles
    gpioPWM(MOTOR1_ENA, pwm_value1);
    gpioPWM(MOTOR2_ENB, pwm_value2);
}

// Encoder 1 Callback
void encoder1_callback(int gpio, int level, uint32_t tick, void *user_data) {
    int a_value = gpioRead(ENCODER1_A);
    int b_value = gpioRead(ENCODER1_B);

    if (a_value == 0 && b_value == 1) {
        pthread_mutex_lock(&encoder1_mutex);
        encoder1_count++;
        pthread_mutex_unlock(&encoder1_mutex);
    } else if (a_value == 1 && b_value == 0) {
        pthread_mutex_lock(&encoder1_mutex);
        encoder1_count--;
        pthread_mutex_unlock(&encoder1_mutex);
    }
}

// Encoder 2 Callback
void encoder2_callback(int gpio, int level, uint32_t tick, void *user_data) {
    int a_value = gpioRead(ENCODER2_A);
    int b_value = gpioRead(ENCODER2_B);

    if (a_value == 0 && b_value == 1) {
        pthread_mutex_lock(&encoder2_mutex);
        encoder2_count++;
        pthread_mutex_unlock(&encoder2_mutex);
    } else if (a_value == 1 && b_value == 0) {
        pthread_mutex_lock(&encoder2_mutex);
        encoder2_count--;
        pthread_mutex_unlock(&encoder2_mutex);
    }
}

// Calculate RPM
double calculate_rpm(int encoder_count, double time_elapsed) {
    double rpm = (double)encoder_count / 60.0 * 60.0 / time_elapsed; // Assuming 600 pulses per revolution
    return rpm;
}

// PID Control
double pid_control(double setpoint, double actual_value, double *integral, double *previous_error, double *previous_time) {
    double error = setpoint - actual_value;
    double time_elapsed = time_elapsed; // Time elapsed is passed as a global variable

    // Calculate proportional term
    double proportional = KP * error;

    // Calculate integral term
    *integral += error * time_elapsed;
    if (*integral > 1000) *integral = 1000; // Limit integral term
    if (*integral < -1000) *integral = -1000;

    // Calculate derivative term
    double derivative = KD * (error - *previous_error) / time_elapsed;

    // Calculate PID output
    double output = proportional + (*integral) + derivative;

    // Update previous error and time
    *previous_error = error;
    *previous_time = time_elapsed;

    return output;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Motor1 RPM,Motor2 RPM,PID P,PID I,PID D,PID Output\n");
    }
    rewind(log_file);

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set pull-up/down resistors (optional, adjust as needed)
    gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR1_ENA, 255);
    gpioSetPWMrange(MOTOR2_ENB, 255);

    // Set PWM duty cycle to 0 initially
    gpioPWM(MOTOR1_ENA, 0);
    gpioPWM(MOTOR2_ENB, 0);

    // Set up interrupt handlers for encoder 1
    if (gpioSetISRFuncEx(ENCODER1_A, RISING_EDGE, 0, encoder1_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR for encoder 1 A\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER1_B, RISING_EDGE, 0, encoder1_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR for encoder 1 B\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
