// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define the log file name
#define LOG_FILE "valve_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int set_valve_state(int gpio, int state);
int log_event(const char *message);
void signal_handler(int signal);

// Structure to hold valve schedule
typedef struct {
    int valve1_duration;
    int valve2_duration;
} ValveSchedule;

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(VALVE1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(VALVE2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE2_GPIO);
        gpioTerminate();
        return -1;
    }

    // Ensure valves are initially off
    gpioWrite(VALVE1_GPIO, 1); // Assuming HIGH means OFF
    gpioWrite(VALVE2_GPIO, 1);

    return 0;
}

// Function to set the state of a valve (ON or OFF)
int set_valve_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to log an event to the log file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Valve schedule
    ValveSchedule schedule = {500, 1000};

    printf("Water distribution system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate Valve 1
        if (set_valve_state(VALVE1_GPIO, 0) == 0) {
            log_event("Valve 1 activated");
        } else {
            fprintf(stderr, "Failed to activate Valve 1\n");
        }
        gpioDelay(schedule.valve1_duration * 1000); // Delay in microseconds

        // Pause
        if (set_valve_state(VALVE1_GPIO, 1) == 0) {
            log_event("Valve 1 deactivated");
        } else {
            fprintf(stderr, "Failed to deactivate Valve 1\n");
        }
        gpioDelay(5000 * 1000); // Delay in microseconds

        // Activate Valve 2
        if (set_valve_state(VALVE2_GPIO, 0) == 0) {
            log_event("Valve 2 activated");
        } else {
            fprintf(stderr, "Failed to activate Valve 2\n");
        }
        gpioDelay(schedule.valve2_duration * 1000); // Delay in microseconds

        // Pause
        if (set_valve_state(VALVE2_GPIO, 1) == 0) {
            log_event("Valve 2 deactivated");
        } else {
            fprintf(stderr, "Failed to deactivate Valve 2\n");
        }
        gpioDelay(10000 * 1000); // Delay in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_valve_state(VALVE1_GPIO, 1); // Ensure valves are off
    set_valve_state(VALVE2_GPIO, 1);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

