#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_1 17
#define PIR_SENSOR_2 22
#define RELAY_PIN 18

// Define rate limiting parameters
#define RATE_LIMIT_DURATION 2 // seconds
#define RATE_LIMIT_WINDOW 500 // milliseconds

// Define log file path
#define LOG_FILE "door_events.log"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Mutex for rate limiting
pthread_mutex_t rate_limit_mutex = PTHREAD_MUTEX_INITIALIZER;

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int sensor_id;
    int last_motion_time;
} sensor_data_t;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void activate_relay(int duration_ms);
void log_event(int sensor_id, const char *event_type);
void *sensor_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_1, PI_PUD_DOWN);
    gpioSetMode(PIR_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_2, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off initially

    return 0;
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to activate the relay for a specified duration
void activate_relay(int duration_ms) {
    gpioWrite(RELAY_PIN, 1); // Activate relay
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
}

// Function to log events to a file
void log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, sensor_id, event_type);
    fflush(log_file); // Ensure immediate write to file
}

// Sensor thread function
void *sensor_thread(void *arg) {
    sensor_data_t *sensor_data = (sensor_data_t *)arg;
    int last_motion_time = 0;

    while (program_running) {
        int motion_detected = read_sensor(sensor_data->gpio_pin);

        if (motion_detected == 1) {
            int current_time = gpioTick();

            // Rate limiting logic
            if (current_time - last_motion_time > RATE_LIMIT_WINDOW * 1000) {
                pthread_mutex_lock(&rate_limit_mutex);
                if (current_time - last_motion_time > RATE_LIMIT_WINDOW * 1000) {
                    activate_relay(500);
                    log_event(sensor_data->sensor_id, "Door Unlocked");
                    last_motion_time = current_time;
                }
                pthread_mutex_unlock(&rate_limit_mutex);
            }
        }

        gpioDelay(50 * 1000); // Check every 50ms
    }

    pthread_exit(NULL);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&rate_limit_mutex);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Sensor data
    sensor_data_t sensor1_data = {PIR_SENSOR_1, 1, 0};
    sensor_data_t sensor2_data = {PIR_SENSOR_2, 2, 0};

    // Create threads for each sensor
    pthread_t sensor1_thread, sensor2_thread;
    if (pthread_create(&sensor1_thread, NULL, sensor_thread, &sensor1_data) != 0) {
        fprintf(stderr, "Error creating sensor 1 thread!\n");
        cleanup();
        return 1;
    }
    if (pthread_create(&sensor2_thread, NULL, sensor_thread, &sensor2_data) != 0) {
        fprintf(stderr, "Error creating sensor 2 thread!\n");
        cleanup();
        return 1;
    }

    // Wait for threads to finish (or until a signal is received)
    pthread_join(sensor1_thread, NULL);
    pthread_join(sensor2_thread, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

