#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define the number of steps in each pattern
#define NUM_STEPS 5

// Define the minimum and maximum duration for each step (ms)
#define MIN_DURATION 50
#define MAX_DURATION 200

// Global variable to indicate program termination
volatile sig_atomic_t shutdown = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    shutdown = 1;
    printf("\nCaught signal, stopping motors and exiting...\n");
}

// Function to generate a random PWM duty cycle
int generate_random_duty_cycle() {
    return rand() % PWM_RANGE;
}

// Function to generate a random duration
int generate_random_duration() {
    return rand() % (MAX_DURATION - MIN_DURATION + 1) + MIN_DURATION;
}

// Function to play a haptic feedback pattern
void play_pattern(int motor1_duty_cycle, int motor2_duty_cycle, int duration_ms) {
    gpioPWM(MOTOR1_PIN, motor1_duty_cycle);
    gpioPWM(MOTOR2_PIN, motor2_duty_cycle);
    gpioDelay(duration_ms * 1000); // Convert ms to microseconds
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE);

    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Haptic feedback pattern generator started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!shutdown) {
        // Generate random haptic feedback patterns
        for (int i = 0; i < 10; i++) {
            int motor1_duty_cycle = generate_random_duty_cycle();
            int motor2_duty_cycle = generate_random_duty_cycle();
            int duration_ms = generate_random_duration();

            play_pattern(motor1_duty_cycle, motor2_duty_cycle, duration_ms);
        }

        // Pause between patterns
        gpioDelay(500 * 1000); // 500ms
    }

    // Stop the motors and release resources
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();

    return 0;
}

