int read_rain_sensor();
void close_window();
void stop_motor();
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int readings[DEBOUNCE_READINGS];
    int i, sum = 0;

    for (i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = gpioRead(RAIN_SENSOR_PIN);
        gpioDelay(50); // 50 ms delay
    }

    for (i = 0; i < DEBOUNCE_READINGS; i++) {
        sum += readings[i];
    }

    return (sum >= RAIN_THRESHOLD);
}

// Function to close the window
void close_window() {
    log_event("Closing window...");
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 150); // 150 duty cycle
    gpioDelay(MOTOR_DURATION * 1000); // Motor duration in milliseconds
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    log_event("Window closed.");
}

// Function to stop the motor
void stop_motor() {
    log_event("Stopping motor...");
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    log_event("Motor stopped.");
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Signal received, shutting down...");
    running = 0;
    stop_motor();
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    closelog();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_PWM_PIN, 255);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
