        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("System started.");

    // Main loop
    while (running) {
        if (read_rain_sensor()) {
            close_window();
        }
        gpioDelay(60000); // Check every 60 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();
    fclose(log_file);
    closelog();

    return 0;
}

