#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17

// Calibration factor (adjust based on your setup)
#define CALIBRATION_FACTOR 100.0

// Threshold weight (in grams)
#define WEIGHT_THRESHOLD 100.0

// Solenoid activation duration (in seconds)
#define SOLENOID_DURATION 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
float convert_to_weight(int raw_value);
void control_solenoid(int state);
void log_event(const char *event_type);
void signal_handler(int signal);

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DT to go low (data line is ready)
    int timeout = 1000; // Timeout after 1000 attempts
    while (gpioRead(HX711_DT) == 1 && timeout > 0) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Error: HX711 data line stuck high.\n");
        return -1; // Indicate error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse the SCK line 25th time to set the gain to 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1);

    // Convert to signed 2's complement if negative
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw data to weight in grams
float convert_to_weight(int raw_value) {
    return (float)raw_value / CALIBRATION_FACTOR;
}

// Function to control the solenoid lock
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
}

// Function to log events to a file
void log_event(const char *event_type) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;

    // Deactivate solenoid lock
    control_solenoid(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    int raw_value;
    float weight;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("stock_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Stock monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read raw value from HX711
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read HX711 data.\n");
            log_event("Error: Failed to read HX711 data.");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Convert raw value to weight
        weight = convert_to_weight(raw_value);

        // Check if weight is below threshold
        if (weight < WEIGHT_THRESHOLD) {
            printf("Weight below threshold: %.2f g\n", weight);
            log_event("Weight below threshold");

            // Activate solenoid lock
            control_solenoid(1);
            printf("Solenoid activated.\n");
            log_event("Solenoid activated");

            // Wait for solenoid duration
            gpioDelay(SOLENOID_DURATION * 1000); // Convert seconds to milliseconds

            // Deactivate solenoid lock
            control_solenoid(0);
            printf("Solenoid deactivated.\n");
            log_event("Solenoid deactivated");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_solenoid(0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

