#define LOG_FILE "relay_events.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
int toggle_relay();
int log_event(int relay_state);
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int sensor_pin;
    int relay_pin;
    char *log_file_name;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Request GPIO lines for sensor and relay
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to toggle the relay state
int toggle_relay() {
    int current_state = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_state);
    return !current_state;
}

// Function to log the relay event to a file
int log_event(int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Relay state: %s\n", timestamp, relay_state ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup_gpio();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) { // Obstacle detected (LOW signal)
            int relay_state = toggle_relay();
            if (log_event(relay_state) != 0) {
                fprintf(stderr, "Error logging event.\n");
            }
            printf("Obstacle detected! Relay toggled to %s\n", relay_state ? "ON" : "OFF");
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Cleanup and exit
    cleanup_gpio();
    fclose(log_file);
    printf("Program terminated.\n");
    return 0;
}

