#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Configuration file path
#define CONFIG_FILE "watering.conf"

// Default watering duration (seconds)
#define DEFAULT_DURATION 60

// GPIO pin for the solenoid valve
#define VALVE_GPIO 18

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_watering_duration(const char *filename);
int set_valve_state(int state);
void signal_handler(int sig);
int initialize_gpio(void);
void cleanup_gpio(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to read watering duration from the configuration file
int read_watering_duration(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file %s: %s\n", filename, strerror(errno));
        return DEFAULT_DURATION; // Return default duration on error
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading from config file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return DEFAULT_DURATION; // Return default duration on error
    }

    fclose(fp);

    // Remove newline character
    line[strcspn(line, "\n")] = 0;

    // Parse the duration
    char *endptr;
    long duration = strtol(line, &endptr, 10);

    if (*endptr != '\0' || duration <= 0 || duration > 3600) {
        fprintf(stderr, "Invalid duration in config file %s: %s\n", filename, line);
        return DEFAULT_DURATION; // Return default duration on error
    }

    return (int)duration;
}

// Function to set the valve state
int set_valve_state(int state) {
    int ret;

    if (state != 0 && state != 1) {
        fprintf(stderr, "Invalid valve state: %d\n", state);
        return -1;
    }

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting valve state: %s\n", strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to initialize the GPIO line
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, VALVE_GPIO);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", VALVE_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", VALVE_GPIO, strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    // Ensure the valve is initially off
    if (set_valve_state(0) != 0) {
        fprintf(stderr, "Error setting initial valve state to off\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to cleanup the GPIO line and close the chip
void cleanup_gpio(void) {
    if (line) {
        gpiod_line_set_value(line, 0); // Ensure valve is off
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read watering duration from configuration file
    int watering_duration = read_watering_duration(CONFIG_FILE);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Watering system started. Duration: %d seconds\n", watering_duration);

    // Main loop
    while (!terminate) {
        // Activate the valve
        if (set_valve_state(1) != 0) {
            fprintf(stderr, "Error activating valve. Exiting.\n");
            break;
        }

        printf("Valve ON\n");

        // Wait for the specified duration
        sleep(watering_duration);

        // Deactivate the valve
        if (set_valve_state(0) != 0) {
            fprintf(stderr, "Error deactivating valve. Exiting.\n");
            break;
        }

        printf("Valve OFF\n");
    }

    // Cleanup GPIO
    cleanup_gpio();

    printf("Watering system stopped.\n");

    return 0;
}

