void control_motor(int left_speed, int right_speed) {
    gpioPWM(LEFT_MOTOR_PIN, left_speed);
    gpioPWM(RIGHT_MOTOR_PIN, right_speed);
}

// Function to log data to file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;
    control_motor(MOTOR_STOP, MOTOR_STOP);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LEFT_MOTOR_PIN, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_PIN, PI_OUTPUT);
    gpioSetMode(ENABLE_PIN, PI_OUTPUT);

    // Enable the motors
    gpioWrite(ENABLE_PIN, 1);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int left_sensor = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        // Control motor speeds based on sensor readings
        int left_speed = MOTOR_SPEED;
        int right_speed = MOTOR_SPEED;

        if (middle_sensor == 0) {
            // Straight ahead
        } else if (left_sensor == 0) {
            // Turn right
            left_speed = MOTOR_SPEED / 2;
            right_speed = MOTOR_SPEED;
        } else if (right_sensor == 0) {
            // Turn left
            left_speed = MOTOR_SPEED;
            right_speed = MOTOR_SPEED / 2;
        } else {
            // Stop
            left_speed = MOTOR_STOP;
            right_speed = MOTOR_STOP;
        }

        // Control motor
        control_motor(left_speed, right_speed);

        // Log data
        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_motor(MOTOR_STOP, MOTOR_STOP);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

