#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define LOG_FILE "grow_log.txt"
#define READ_DELAY_MS 180

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_lux();
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read illuminance from BH1750 sensor
float read_lux() {
    char buffer[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1.0;
    }

    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    float lux = (float)raw_value / 1.2;
    return lux;
}

// Control the relay (on/off)
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    log_data(-1.0, state); // Log lux value as -1.0 for relay state
}

// Log data to file
void log_data(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Grow lamp control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float lux = read_lux();

        if (lux >= 0) {
            printf("Lux: %.2f\n", lux);

            if (lux < LUX_THRESHOLD) {
                control_relay(1); // Turn relay ON
            } else {
                control_relay(0); // Turn relay OFF
            }
        } else {
            fprintf(stderr, "Failed to read lux. Retrying in %d ms.\n", READ_DELAY_MS);
        }

        gpioDelay(READ_DELAY_MS * 1000); // Delay for 180 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(0); // Ensure relay is OFF on exit
    fclose(log_file);
    gpioTerminate();

    printf("Grow lamp control system stopped.\n");

    return 0;
}

