// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse width limits
#define SERVO_LOCKED_PULSE_WIDTH 1000
#define SERVO_UNLOCKED_PULSE_WIDTH 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set lock button pin as input with pull-up resistor
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);

    // Set unlock button pin as input with pull-up resistor
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the state of a button
int read_button(int pin) {
    return gpioRead(pin);
}

// Function to move the servo to a specified pulse width
void move_servo(int pulse_width) {
    gpioServo(SERVO_PIN, pulse_width);
}

// Function to debounce a button press
void debounce_button(int pin) {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int lock_button_pressed = read_button(LOCK_BUTTON_PIN);
        int unlock_button_pressed = read_button(UNLOCK_BUTTON_PIN);

        // Check for lock button press
        if (lock_button_pressed == 0) {
            debounce_button(LOCK_BUTTON_PIN);
            move_servo(SERVO_LOCKED_PULSE_WIDTH);
            printf("Door locked.\n");
        }

        // Check for unlock button press
        if (unlock_button_pressed == 0) {
            debounce_button(UNLOCK_BUTTON_PIN);
            move_servo(SERVO_UNLOCKED_PULSE_WIDTH);
            printf("Door unlocked.\n");
        }

        gpioDelay(10000); // Delay to avoid excessive CPU usage
    }

    // Clean up GPIO resources before exiting
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio

    printf("Door lock control program stopped.\n");

    return 0;
}

