#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for motor 1 and motor 2
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define pulse duration in milliseconds
#define PULSE_DURATION 200

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
}

// Function to set the value of a GPIO line
int set_gpio_value(int gpio, int value) {
    int result = gpiod_line_set_value(gpio, value);
    if (result < 0) {
        fprintf(stderr, "Error setting GPIO %d value: %d\n", gpio, result);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for motor control
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Motor 1: 200 ms pulse
        if (set_gpio_value(MOTOR1_GPIO, 1) < 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        gpioDelay(PULSE_DURATION * 1000); // Delay in microseconds
        if (set_gpio_value(MOTOR1_GPIO, 0) < 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        gpioDelay(50 * 1000); // Small delay to prevent motor 1 from running too fast

        // Motor 2: 300 ms pulse
        if (set_gpio_value(MOTOR2_GPIO, 1) < 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        gpioDelay(PULSE_DURATION * 1000); // Delay in microseconds
        if (set_gpio_value(MOTOR2_GPIO, 0) < 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        gpioDelay(50 * 1000); // Small delay to prevent motor 2 from running too fast
    }

    // Release GPIO lines before exiting
    if (set_gpio_value(MOTOR1_GPIO, 0) < 0) {
        fprintf(stderr, "Error releasing GPIO %d\n", MOTOR1_GPIO);
    }
    if (set_gpio_value(MOTOR2_GPIO, 0) < 0) {
        fprintf(stderr, "Error releasing GPIO %d\n", MOTOR2_GPIO);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Haptic feedback system stopped.\n");

    return 0;
}

