    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);
    gpioWrite(ALARM_LED_PIN, 0); // Initially turn off the LED

    return 0;
}

// Function to initialize ZeroMQ
int initialize_zmq() {
    sound_sensor_context = zmq_ctx_new();
    if (!sound_sensor_context) {
        fprintf(stderr, "Failed to create ZeroMQ context for sound sensor\n");
        return -1;
    }

    sound_sensor_socket = zmq_socket(sound_sensor_context, ZMQ_SUB);
    if (!sound_sensor_socket) {
        fprintf(stderr, "Failed to create ZeroMQ socket for sound sensor\n");
        zmq_ctx_destroy(sound_sensor_context);
        return -1;
