    if (rc != 0) {
        fprintf(stderr, "Failed to set ZeroMQ socket options for sound sensor: %s\n", zmq_strerror(errno));
        zmq_close(sound_sensor_socket);
        zmq_ctx_destroy(sound_sensor_context);
        return -1;
    }

    alarm_node_context = zmq_ctx_new();
