        }

        if (pulse_buffer[i + 1] < NEC_ONE_SPACE * 0.8 || pulse_buffer[i + 1] > NEC_ONE_SPACE * 1.2) {
            if (pulse_buffer[i + 1] < NEC_ZERO_SPACE * 0.8 || pulse_buffer[i + 1] > NEC_ZERO_SPACE * 1.2) {
                log_message(LOG_ERR, "Invalid space");
                return -1;
            } else {
                // Logic 0
                *command |= (1 << (31 - (i / 2)));
            }
        } else {
            // Logic 1
            *address |= (1 << (31 - (i / 2)));
        }
    }

    // Validate inverted copy
    uint32_t inverted_address = ~(*address);
    uint32_t inverted_command = ~(*command);

    if (inverted_address != (inverted_command >> 16) || inverted_command != (inverted_address >> 16)) {
        log_message(LOG_ERR, "Inverted address/command mismatch");
        return -1;
    }

    return 0;
}

// Function to publish MQTT message
int publish_mqtt(uint32_t address, uint32_t command) {
    char payload[100];
    snprintf(payload, sizeof(payload), "{\"address\": 0x%08X, \"command\": 0x%08X}", address, command);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to publish MQTT message: %s", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

// Function to log messages with timestamps
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(priority, "%s: %s", timestamp, message);
    printf("%s: %s\n", timestamp, message);
}

int main() {
    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO mode
    gpioSetMode(IR_GPIO, PI_INPUT);

    // Set pull-up/down resistor (optional, depending on your IR receiver)
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create mosquitto instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set MQTT callbacks
    mosquitto_message_callback_set(mosq, NULL);
    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_disconnect_callback_set(mosq, NULL);

    // Start network loop
    ret = mosquitto_loop_start(mosq);
    if (ret != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to start MQTT network loop: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set alert function for IR pulse detection
    gpioSetAlertFuncEx(IR_GPIO, pulse_callback, NULL);

    log_message(LOG_INFO, "IR decoder started");

    // Main loop
    while (running) {
        // Wait for a short period to avoid busy-waiting
        gpioDelay(10000); // 10ms

        // Reset pulse count and buffer
        pulse_count = 0;
        memset(pulse_buffer, 0, sizeof(pulse_buffer));

        // Wait for a short period to allow the IR receiver to settle
        gpioDelay(10000); // 10ms

        // Decode NEC signal
        uint32_t address, command;
        if (decode_nec(pulse_buffer, pulse_count, &address, &command) == 0) {
            // Publish MQTT message
            if (publish_mqtt(address, command) != 0) {
                log_message(LOG_ERR, "Failed to publish MQTT message");
            } else {
                char log_message_buffer[200];
                snprintf(log_message_buffer, sizeof(log_message_buffer), "Decoded: Address 0x%08X, Command 0x%08X", address, command);
                log_message(LOG_INFO, log_message_buffer);
            }
        } else {
            log_message(LOG_ERR, "NEC decoding failed");
        }
    }

    // Cleanup
    log_message(LOG_INFO, "Cleaning up...");
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

