#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESSES {0x23, 0x24, 0x25, 0x26}
#define NUM_SENSORS (sizeof(SENSOR_ADDRESSES) / sizeof(SENSOR_ADDRESSES[0]))
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define READ_DELAY_MS 180
#define MAX_RETRIES 3

// Global variables
int i2c_fds[NUM_SENSORS];
int udp_socket;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int address);
int read_bh1750(int fd, float *lux);
int send_udp_packet(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c(int address) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read lux value from BH1750 sensor
int read_bh1750(int fd, float *lux) {
    uint8_t command = 0x10; // High Resolution Mode
    uint8_t data[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(fd, &command, 1) != 1) {
            perror("Error writing to I2C device");
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        usleep(READ_DELAY_MS * 1000); // Wait for conversion

        if (read(fd, data, 2) == 2) {
            uint16_t raw_value = (data[0] << 8) | data[1];
            *lux = (float)raw_value / 1.2;
            return 0; // Success
        } else {
            perror("Error reading from I2C device");
            retries++;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read from sensor after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Send UDP multicast packet
int send_udp_packet(const char *message) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(udp_socket, message, strlen(message), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP packet");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize I2C file descriptors
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = init_i2c(SENSOR_ADDRESSES[i]);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Failed to initialize sensor at address 0x%02x.\n", SENSOR_ADDRESSES[i]);
            // Attempt to close any previously initialized file descriptors
            for (int j = 0; j < i; j++) {
                close(i2c_fds[j]);
            }
            return 1;
        }
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating UDP socket");
        // Close I2C file descriptors
        for (int i = 0; i < NUM_SENSORS; i++) {
            close(i2c_fds[i]);
        }
        return 1;
    }

    // Set multicast TTL
    int ttl = 1;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("Error setting multicast TTL");
        close(udp_socket);
        // Close I2C file descriptors
        for (int i = 0; i < NUM_SENSORS; i++) {
            close(i2c_fds[i]);
        }
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    char message[256];

    // Main loop
    while (program_running) {
        // Read sensor data
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (read_bh1750(i2c_fds[i], &lux) == 0) {
                // Format data
                snprintf(message, sizeof(message), "%d,%.2f", i + 1, lux);
            } else {
                // Format data with NaN if read failed
                snprintf(message, sizeof(message), "%d,NaN", i + 1);
            }

            // Send UDP packet
            if (send_udp_packet(message) != 0) {
                fprintf(stderr, "Failed to send UDP packet for sensor %d.\n", i + 1);
            }
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    close(udp_socket);
    for (int i = 0; i < NUM_SENSORS; i++) {
        close(i2c_fds[i]);
    }

    return 0;
}

