#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define AWM7300V_ADDR 0x28
#define FLOW_SCALE_FACTOR 0.1
#define LOG_FILE "airflow_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_flow_data(int16_t *raw_flow);
float convert_to_slpm(int16_t raw_flow);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for I2C configuration (optional, but good practice)
typedef struct {
    int bus;
    int addr;
} i2c_config_t;

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AWM7300V_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read flow data from the sensor
int read_flow_data(int16_t *raw_flow) {
    uint8_t write_buf[1] = {0x00}; // Start condition for reading two bytes
    uint8_t read_buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, write_buf, 1) != 1) {
            perror("Error writing to I2C device");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            continue;
        }

        if (read(i2c_fd, read_buf, 2) != 2) {
            perror("Error reading from I2C device");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            continue;
        }

        *raw_flow = (read_buf[0] << 8) | read_buf[1];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read flow data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw flow data to SLPM
float convert_to_slpm(int16_t raw_flow) {
    return (raw_flow - 3277) * FLOW_SCALE_FACTOR;
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    int16_t raw_flow;
    float flow_rate;

    // Main loop
    while (program_running) {
        // Read flow data
        if (read_flow_data(&raw_flow) == 0) {
            // Convert to SLPM
            flow_rate = convert_to_slpm(raw_flow);

            // Log flow rate
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Error logging flow rate.\n");
            }
        } else {
            fprintf(stderr, "Error reading flow data.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

