#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Default values
#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"

// Register addresses
#define REG_X_L 0x28
#define REG_X_H 0x29
#define REG_Y_L 0x2A
#define REG_Y_H 0x2B
#define REG_Z_L 0x2C
#define REG_Z_H 0x2D

// Scaling factor for ±8g range (0.000244 g/LSB)
#define SCALE_FACTOR 0.000244

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
int i2c_address = DEFAULT_I2C_ADDRESS;
int interval = DEFAULT_INTERVAL;
char *filename = DEFAULT_FILENAME;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int address);
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int log_data(float x_g, float y_g, float z_g);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(int address) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-1");

    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    int retries = 3;

    while (retries > 0) {
        if (read(i2c_fd, buffer, 6) == 6) {
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            log_error("I2C read error");
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    return -1; // Failure after retries
}

// Function to convert raw data to g
float convert_to_g(int16_t raw_value) {
    return (float)raw_value * SCALE_FACTOR;
}

// Function to log data to CSV file
int log_data(float x_g, float y_g, float z_g) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (csv_file == NULL) {
        log_error("CSV file is not open");
        return -1;
    }

    fprintf(csv_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x_g, y_g, z_g);
    fflush(csv_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to log errors to file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "%s: %s (errno: %d)\n", timestamp, message, errno);

    if (csv_file != NULL) {
        fprintf(csv_file, "%s: %s (errno: %d)\n", timestamp, message, errno);
        fflush(csv_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to close I2C and CSV file
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = strtol(optarg, NULL, 0);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize I2C
    if (init_i2c(i2c_address) < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen(filename, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");
    }
    rewind(csv_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float x_g, y_g, z_g;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to g
            x_g = convert_to_g(raw_x);
            y_g = convert_to_g(raw_y);
            z_g = convert_to_g(raw_z);

            // Log data
            if (log_data(x_g, y_g, z_g) != 0) {
                log_error("Failed to log data");
            }
        } else {
            log_error("Failed to read sensor data");
        }

        // Wait for the specified interval
        sleep(interval);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

