#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_fd = -1;
int sockfd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_udp_socket();
int read_bh1750(float *lux);
int send_udp_multicast(float lux);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return -1;
    }

    // Send power-on command
    if (i2cWriteByteData(i2c_fd, 0x00, 0x00) < 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        i2cClose(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Set continuous high-resolution mode
    if (i2cWriteByteData(i2c_fd, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        i2cClose(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize UDP socket
int init_udp_socket() {
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }

    // Set multicast TTL
    int ttl_val = TTL;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl_val, sizeof(ttl_val)) < 0) {
        perror("Error setting TTL");
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    // Configure multicast address
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    return 0;
}

// Read light level from BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_fd, 0x00, buf, 2) == 2) {
            // Convert big-endian data to lux
            uint16_t raw_value = (buf[0] << 8) | buf[1];
            *lux = (float)raw_value / 1.2;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device, retrying...\n");
            retries--;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Send light level over UDP multicast
int send_udp_multicast(float lux) {
    char message[32];
    snprintf(message, sizeof(message), "%.2f", lux);

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sockfd, message, strlen(message), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP multicast");
        return -1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (sockfd != -1) {
        close(sockfd);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize UDP socket
    if (init_udp_socket() != 0) {
        cleanup();
        return 1;
    }

    float lux;

    // Main loop
    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            if (send_udp_multicast(lux) != 0) {
                fprintf(stderr, "Failed to send UDP multicast\n");
            }
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Failed to read light level\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

