#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define UART parameters
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define BUFFER_SIZE 4096

// Define TLV types
#define TLV_TYPE_DETECTED_OBJECTS 1

// Define magic word
#define MAGIC_WORD_0 0x0204
#define MAGIC_WORD_1 0x0306
#define MAGIC_WORD_2 0x0805
#define MAGIC_WORD_3 0x0709

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold detected object data
typedef struct {
    float range;
    float velocity;
} detected_object_t;

// Function prototypes
int initialize_uart();
int read_uart_data(unsigned char *buffer, int max_len);
int validate_tlv_header(const unsigned char *buffer, int len);
int parse_detected_objects(const unsigned char *buffer, int len, detected_object_t *objects, int *num_objects);
int write_to_csv(const detected_object_t *objects, int num_objects);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

// Read data from UART with timeout
int read_uart_data(unsigned char *buffer, int max_len) {
    int bytes_read = 0;
    int start_time = time(NULL);

    while (bytes_read < max_len && !terminate) {
        int available = serDataAvailable(uart_handle);
        if (available > 0) {
            int bytes_to_read = (available > max_len - bytes_read) ? (max_len - bytes_read) : available;
            int bytes_read_now = serRead(uart_handle, buffer + bytes_read, bytes_to_read);
            if (bytes_read_now > 0) {
                bytes_read += bytes_read_now;
            } else {
                fprintf(stderr, "Error reading from UART: %d\n", bytes_read_now);
                return -1;
            }
        } else {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        if (time(NULL) - start_time > 1) { // Timeout after 1 second
            fprintf(stderr, "Timeout reading from UART\n");
            return -1;
        }
    }

    return bytes_read;
}

// Validate TLV header
int validate_tlv_header(const unsigned char *buffer, int len) {
    if (len < 8) {
        fprintf(stderr, "TLV header too short\n");
        return -1;
    }

    unsigned int magic_word = (buffer[0] << 24) | (buffer[1] << 16) | (buffer[2] << 8) | buffer[3];
    if (magic_word != MAGIC_WORD_0 || buffer[4] != MAGIC_WORD_1 || buffer[5] != MAGIC_WORD_2 || buffer[6] != MAGIC_WORD_3) {
        fprintf(stderr, "Invalid magic word: 0x%08X\n", magic_word);
        return -1;
    }

    return 0;
}

// Parse detected objects from TLV payload
int parse_detected_objects(const unsigned char *buffer, int len, detected_object_t *objects, int *num_objects) {
    int offset = 8; // Skip magic word and length
    *num_objects = 0;

    while (offset < len) {
        unsigned short type = (buffer[offset] << 8) | buffer[offset + 1];
        unsigned short length = (buffer[offset + 2] << 8) | buffer[offset + 3];

        if (offset + length > len) {
            fprintf(stderr, "TLV length exceeds buffer size\n");
            return -1;
        }

        if (type == TLV_TYPE_DETECTED_OBJECTS) {
            if (length % 8 != 0) {
                fprintf(stderr, "Detected objects TLV length is not a multiple of 8\n");
                return -1;
            }

            *num_objects = length / 8;
            if (*num_objects > 10) { // Limit the number of objects to avoid memory issues
                *num_objects = 10;
            }

            for (int i = 0; i < *num_objects; i++) {
                objects[i].range = *((float *)(buffer + offset + 4 + i * 8));
                objects[i].velocity = *((float *)(buffer + offset + 4 + i * 8 + 4));
            }
        }

        offset += length;
    }

    return 0;
}

// Write data to CSV file
int write_to_csv(const detected_object_t *objects, int num_objects) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s", timestamp);
    for (int i = 0; i < num_objects; i++) {
        fprintf(csv_file, ",%d,%.2f,%.2f", i, objects[i].range, objects[i].velocity);
    }
    fprintf(csv_file, "\n");
    fflush(csv_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources
void cleanup() {
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen("radar_data.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    rewind(csv_file);

    unsigned char buffer[BUFFER_SIZE];
    detected_object_t objects[10]; // Array to store detected objects
    int num_objects;

    // Main loop
    while (!terminate) {
        int bytes_read = read_uart_data(buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            if (validate_tlv_header(buffer, bytes_read) == 0) {
                if (parse_detected_objects(buffer, bytes_read, objects, &num_objects) == 0) {
                    write_to_csv(objects, num_objects);
                } else {
                    fprintf(stderr, "Error parsing detected objects\n");
                }
            } else {
                fprintf(stderr, "Error validating TLV header\n");
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting...\n");
            break;
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

