    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen("radar_data.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    rewind(csv_file);

    unsigned char buffer[BUFFER_SIZE];
    detected_object_t objects[10]; // Array to store detected objects
    int num_objects;

    // Main loop
    while (!terminate) {
        int bytes_read = read_uart_data(buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            if (validate_tlv_header(buffer, bytes_read) == 0) {
                if (parse_detected_objects(buffer, bytes_read, objects, &num_objects) == 0) {
                    write_to_csv(objects, num_objects);
                } else {
                    fprintf(stderr, "Error parsing detected objects\n");
                }
            } else {
                fprintf(stderr, "Error validating TLV header\n");
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting...\n");
            break;
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
