#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
char line_buffer[BUFFER_SIZE] = {0};
int buffer_index = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the UART
int init_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                              // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read non-blocking
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART with timeout
int read_uart(int fd, char *buffer, int max_len) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("Error in select()");
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        ssize_t bytes_read = read(fd, buffer, max_len - 1);
        if (bytes_read == -1) {
            perror("Error reading from UART");
            return -1;
        } else {
            buffer[bytes_read] = '\0';
            return bytes_read;
        }
    }
}

// Function to parse the line buffer for range data
int parse_range_data(const char *line, float *range) {
    char *token;
    char *rest = strdup(line); // Duplicate the string for strtok

    if (rest == NULL) {
        perror("strdup failed");
        return -1;
    }

    token = strtok_r(rest, ",", &rest);
    if (token != NULL) {
        long timestamp_sec;
        if (sscanf(token, "%ld", &timestamp_sec) == 1) {
            token = strtok_r(NULL, ",", &rest);
            if (token != NULL) {
                if (sscanf(token, "%f", range) == 1) {
                    free(rest);
                    return 0; // Success
                } else {
                    fprintf(stderr, "Error parsing range value\n");
                }
            } else {
                fprintf(stderr, "Missing range value\n");
            }
        } else {
            fprintf(stderr, "Error parsing timestamp\n");
        }
    } else {
        fprintf(stderr, "Missing timestamp\n");
    }

    free(rest);
    return -1; // Failure
}

// Function to log the range data with timestamp
void log_range_data(long timestamp_sec, float range) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp_sec);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return 1;
    }

    printf("UART initialized on %s at %d baud\n", UART_DEVICE, BAUD_RATE);

    // Main loop
    while (program_running) {
        int bytes_read = read_uart(uart_fd, line_buffer + buffer_index, BUFFER_SIZE - buffer_index - 1);
        if (bytes_read > 0) {
            buffer_index += bytes_read;

            // Check for newline character
            if (buffer_index > 0 && line_buffer[buffer_index - 1] == '\n') {
                line_buffer[buffer_index - 1] = '\0'; // Null-terminate the line

                float range;
                if (parse_range_data(line_buffer, &range) == 0) {
                    long timestamp_sec = time(NULL);
                    log_range_data(timestamp_sec, range);
                } else {
                    fprintf(stderr, "Invalid range data: %s\n", line_buffer);
                }

                buffer_index = 0; // Reset buffer index
            } else if (buffer_index >= BUFFER_SIZE - 1) {
                fprintf(stderr, "Line buffer overflow\n");
                buffer_index = 0; // Reset buffer index
            }
        } else if (bytes_read < 0) {
            // Error reading from UART, check for UART error
            struct termios tty;
            if (tcgetattr(uart_fd, &tty) != 0) {
                perror("Error getting termios attributes");
                break;
            }

            if (tty.c_cflag & (CERROR | CBREAK)) {
                fprintf(stderr, "UART error: %s\n", strerror(errno));
                break;
            }
        }

        usleep(10000); // Small delay to avoid busy-waiting
    }

    // Close UART
    if (uart_fd != -1) {
        close(uart_fd);
    }

    printf("UART closed\n");

    return 0;
}

