#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define the serial port
#define SERIAL_PORT "/dev/ttyAMA0"

// Define the baud rate
#define BAUD_RATE 115200

// Global variables for serial port and pigpio
int serial_handle = -1;
int pigpio_initialized = 0;

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_data(int left_state, int middle_state, int right_state);
void send_emergency_stop_message(void);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close the serial port if it's open
    if (serial_handle != -1) {
        serialClose(serial_handle);
        printf("Serial port closed.\n");
    }

    // Terminate pigpio if it's initialized
    if (pigpio_initialized) {
        gpioTerminate();
        printf("pigpio terminated.\n");
    }

    exit(0);
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log sensor data to the console
void log_sensor_data(int left_state, int middle_state, int right_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Left: %d, Middle: %d, Right: %d\n", timestamp, left_state, middle_state, right_state);
}

// Function to send the emergency stop message over the serial port
void send_emergency_stop_message(void) {
    char message[] = "EMERGENCY STOP!\n";
    int bytes_written = serialWrite(serial_handle, message, strlen(message));

    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to serial port: %d\n", bytes_written);
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Open the serial port
    serial_handle = serialOpen(SERIAL_PORT, BAUD_RATE, 0); // 0 for no flow control
    if (serial_handle < 0) {
        fprintf(stderr, "Error opening serial port: %d\n", serial_handle);
        gpioTerminate();
        return 1;
    }
    printf("Serial port opened successfully.\n");

    // Main loop
    while (1) {
        // Read sensor values
        int left_state = read_sensor(LEFT_SENSOR_PIN);
        int middle_state = read_sensor(MIDDLE_SENSOR_PIN);
        int right_state = read_sensor(RIGHT_SENSOR_PIN);

        // Check for errors during sensor reading
        if (left_state == -1 || middle_state == -1 || right_state == -1) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log sensor data
        log_sensor_data(left_state, middle_state, right_state);

        // Check if all sensors are simultaneously low
        if (left_state == 0 && middle_state == 0 && right_state == 0) {
            send_emergency_stop_message();
        }

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness and to avoid compiler warnings.
    serialClose(serial_handle);
    gpioTerminate();
    return 0;
}

